import { ZONES, type ZoneDef } from '../data/zones.ts';

/** Depth of the Challenger Deep, the bottom of the game. */
export const MAX_DEPTH_M = 10_900;

/** Depth (positive, metres) of a point at height `y`, where sea level is y = 0. */
export const depthAtY = (y: number): number => Math.max(0, -y);

/** Absolute pressure in atmospheres: 1 atm at the surface plus 1 atm per 10 m. */
export const pressureAtm = (depthM: number): number => 1 + Math.max(0, depthM) / 10;

/** Water temperature in °C: warm on top, close to 2 °C below the thermocline. */
export const temperatureC = (depthM: number): number => 2 + 20 * Math.exp(-Math.max(0, depthM) / 350);

/**
 * Share of sunlight that reaches a given depth (1 at the surface, ~1 % at 250 m).
 * Drives ambient light, water colour and which animals can see you.
 */
export const sunlightAt = (depthM: number): number => Math.exp(-Math.max(0, depthM) / 55);

export function zoneAt(depthM: number): ZoneDef {
  return ZONES.findLast((zone) => depthM >= zone.fromM) ?? ZONES[0];
}

export function zoneIndexAt(depthM: number): number {
  return ZONES.findLastIndex((zone) => depthM >= zone.fromM);
}
