import {
  AdditiveBlending,
  BufferAttribute,
  BufferGeometry,
  Points,
  ShaderMaterial,
} from 'three';
import { mulberry32 } from '../core/random.ts';
import { COMMON_UNIFORMS } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

const BOX = 90;

const vertexShader = /* glsl */ `
uniform float uTime;
uniform vec3 uCamPos;
uniform float uPixelRatio;
uniform float uBox;
uniform vec3 uBeamPos;
uniform vec3 uBeamDir;
uniform vec3 uBeamParams;
varying float vAlpha;
varying float vDist;
varying float vGlint;

void main() {
  vec3 p = position * uBox;
  p.y -= uTime * (0.25 + 0.5 * position.x);
  p.x += sin(uTime * 0.3 + position.z * 40.0) * 0.7;
  p.z += cos(uTime * 0.25 + position.x * 40.0) * 0.7;

  vec3 rel = mod(p - uCamPos + 0.5 * uBox, uBox) - 0.5 * uBox;
  vec3 wp = uCamPos + rel;
  vec4 mv = viewMatrix * vec4(wp, 1.0);
  // Particles inside the headlight cone catch the light.
  vec3 fromLamp = wp - uBeamPos;
  float lampDist = length(fromLamp);
  float inCone = smoothstep(uBeamParams.y, uBeamParams.y + 0.05, dot(fromLamp / max(lampDist, 0.01), uBeamDir));
  vGlint = uBeamParams.z * inCone * (1.0 - smoothstep(0.4 * uBeamParams.x, uBeamParams.x, lampDist)) * 0.25;
  gl_Position = projectionMatrix * mv;

  vDist = length(rel);
  float depthSize = 0.5 + position.y;
  gl_PointSize = clamp(34.0 * depthSize / max(-mv.z, 0.5), 1.0, 8.0) * (1.0 + vGlint * 0.4) * uPixelRatio;
  vAlpha = (1.0 - smoothstep(0.28 * uBox, 0.5 * uBox, vDist)) * (0.25 + 0.75 * fract(position.x * 91.7));
}
`;

const fragmentShader = /* glsl */ `
${COMMON_UNIFORMS}
varying float vAlpha;
varying float vDist;
varying float vGlint;

void main() {
  float d = length(gl_PointCoord - 0.5);
  float soft = 1.0 - smoothstep(0.05, 0.5, d);
  // Pale detritus in lit water, teal bioluminescent plankton in the dark.
  float bio = 1.0 - smoothstep(0.0, 0.25, uSunlight);
  vec3 pale = vec3(0.75, 0.88, 0.95) * (0.15 + 0.85 * uSunlight);
  vec3 glow = vec3(0.37, 0.95, 0.83) * 1.6;
  vec3 col = mix(pale, glow, bio);
  float a = soft * (vAlpha * exp(-uFogDensity * vDist * 0.6) * mix(0.35, 0.9, bio) + vGlint * 0.5);
  col = mix(col, vec3(0.85, 0.96, 1.0) * 1.4, clamp(vGlint, 0.0, 1.0));
  if (!(a >= 0.0) || a > 100.0) discard;
  gl_FragColor = vec4(col * a, a);
}
`;

/** Drifting particles in a box around the camera; wrapping and animation run on the GPU. */
export class MarineSnow {
  readonly points: Points;
  private readonly boxUniform = { value: BOX };

  constructor(uniforms: SceneUniforms, count: number) {
    const rng = mulberry32(2024);
    const seeds = new Float32Array(count * 3);
    for (let i = 0; i < seeds.length; i++) seeds[i] = rng();
    const geometry = new BufferGeometry();
    geometry.setAttribute('position', new BufferAttribute(seeds, 3));

    const material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
        uBox: this.boxUniform,
        uBeamPos: uniforms.uBeamPos,
        uBeamDir: uniforms.uBeamDir,
        uBeamParams: uniforms.uBeamParams,
      },
      vertexShader,
      fragmentShader,
      blending: AdditiveBlending,
      transparent: true,
      depthWrite: false,
      fog: false,
    });
    this.points = new Points(geometry, material);
    this.points.frustumCulled = false;
  }

  dispose(): void {
    this.points.geometry.dispose();
    (this.points.material as ShaderMaterial).dispose();
  }
}
