import { t } from '../i18n/index.ts';
import type { Account } from '../net/account.ts';
import type { SyncStatus } from '../net/sync.ts';

type Mode = 'login' | 'register' | 'reset';

const statusText = (status: SyncStatus): string => t(`account.sync.${status}`);

function el<K extends keyof HTMLElementTagNameMap>(tag: K, className?: string, text?: string): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function field(label: string, type: string, autocomplete: string, name: string): { row: HTMLElement; input: HTMLInputElement } {
  const row = el('label', 'field');
  const input = el('input');
  input.type = type;
  input.name = name;
  input.setAttribute('autocomplete', autocomplete);
  input.required = true;
  input.spellcheck = false;
  row.append(el('span', undefined, label), input);
  return { row, input };
}

/** Short text for the menu item: the player's name or "Account". */
export function accountLabel(account: Account): string {
  return account.session ? account.session.user.username : t('menu.account');
}

function passwordForm(account: Account, open: boolean): HTMLElement {
  const box = el('div', 'account-password');
  const toggle = el('button', 'ghost', t('account.changePassword'));
  toggle.type = 'button';
  const form = el('form', 'account-form');
  form.noValidate = true;
  const pass = field(t('account.newPassword'), 'password', 'new-password', 'new-password');
  const error = el('p', 'form-error');
  error.setAttribute('role', 'alert');
  const info = el('p', 'form-info');
  const save = el('button', 'primary-btn', t('account.savePassword'));
  save.type = 'submit';
  form.append(pass.row, error, info, save);
  form.hidden = !open;
  toggle.hidden = open;
  toggle.addEventListener('click', () => {
    form.hidden = false;
    toggle.hidden = true;
    pass.input.focus();
  });
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    error.textContent = '';
    info.textContent = '';
    save.disabled = true;
    void account.changePassword(pass.input.value).then((r) => {
      save.disabled = false;
      if (r.ok) {
        pass.input.value = '';
        info.textContent = t('account.passwordChanged');
      } else {
        error.textContent = r.message;
      }
    });
  });
  box.append(toggle, form);
  return box;
}

/** The sign-in / registration / account sheet. `rerender` is called when the view must be rebuilt. */
export function createAccountView(account: Account, rerender: () => void, close: () => void): HTMLElement {
  const root = el('div', 'account');

  if (!account.enabled) {
    root.append(
      el('h3', undefined, t('account.off.title')),
      el('p', 'account-note', t('account.off.text1')),
      el('p', 'account-note', t('account.off.text2')),
    );
    return root;
  }

  const notice = account.notice;
  const banner = (): HTMLElement | null => (notice ? el('p', notice.kind === 'error' ? 'form-error' : 'form-info', notice.message) : null);

  const session = account.session;
  if (session) {
    const top = banner();
    if (top) root.append(top);
    root.append(el('h3', undefined, session.user.username), el('p', 'account-note', session.user.email));
    const status = el('p', `sync sync-${account.status}`, statusText(account.status));
    const actions = el('div', 'account-actions');
    const save = el('button', 'ghost', t('account.saveNow'));
    save.type = 'button';
    save.addEventListener('click', () => void account.saveNow());
    actions.append(save);
    if (account.status === 'error') {
      const retry = el('button', 'ghost', t('account.retry'));
      retry.type = 'button';
      retry.addEventListener('click', () => account.retry());
      actions.append(retry);
    }
    const out = el('button', 'ghost danger', t('account.signOut'));
    out.type = 'button';
    out.addEventListener('click', () => {
      out.disabled = true;
      void account.signOut().then(rerender);
    });
    actions.append(out);
    root.append(status, actions, passwordForm(account, notice?.kind === 'recovery'));
    return root;
  }

  let mode: Mode = 'login';
  const tabs = el('div', 'tabs');
  const form = el('form', 'account-form');
  form.noValidate = true;
  const email = field(t('account.email'), 'email', 'email', 'email');
  const username = field(t('account.username'), 'text', 'nickname', 'username');
  const password = field(t('account.password'), 'password', 'current-password', 'password');
  const error = el('p', 'form-error');
  error.setAttribute('role', 'alert');
  const info = el('p', 'form-info');
  const submit = el('button', 'primary-btn', t('account.submit.login'));
  submit.type = 'submit';
  const forgot = el('button', 'link-btn', t('account.forgot'));
  forgot.type = 'button';
  forgot.addEventListener('click', () => {
    mode = 'reset';
    paint();
  });
  const resend = el('button', 'ghost', t('account.resend'));
  resend.type = 'button';
  resend.hidden = true;
  resend.addEventListener('click', () => {
    resend.disabled = true;
    void account.resendConfirmation(email.input.value.trim()).then((r) => {
      resend.disabled = false;
      error.textContent = r.ok ? '' : r.message;
      info.textContent = r.ok ? t('account.resent') : '';
    });
  });
  const guest = el('button', 'ghost', t('account.guest'));
  guest.type = 'button';
  guest.addEventListener('click', close);

  const paint = (): void => {
    for (const t of tabs.querySelectorAll('button')) t.classList.toggle('active', t.dataset.mode === mode);
    username.row.hidden = mode !== 'register';
    username.input.required = mode === 'register';
    password.row.hidden = mode === 'reset';
    password.input.required = mode !== 'reset';
    forgot.hidden = mode !== 'login';
    resend.hidden = true;
    password.input.setAttribute('autocomplete', mode === 'login' ? 'current-password' : 'new-password');
    submit.textContent = mode === 'login' ? t('account.submit.login') : mode === 'register' ? t('account.submit.register') : t('account.submit.reset');
    error.textContent = '';
    info.textContent = '';
  };
  for (const [m, label] of [['login', t('account.tab.login')], ['register', t('account.tab.register')]] as const) {
    const b = el('button', 'tab', label);
    b.type = 'button';
    b.dataset.mode = m;
    b.setAttribute('role', 'tab');
    b.addEventListener('click', () => {
      mode = m;
      paint();
    });
    tabs.append(b);
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    error.textContent = '';
    info.textContent = '';
    submit.disabled = true;
    const old = submit.textContent;
    submit.textContent = t('account.wait');
    if (mode === 'reset') {
      void account.resetPassword(email.input.value.trim()).then((r) => {
        submit.disabled = false;
        submit.textContent = old;
        if (r.ok) info.textContent = t('account.resetSent');
        else error.textContent = r.message;
      });
      return;
    }
    const run =
      mode === 'login'
        ? account.signIn(email.input.value.trim(), password.input.value)
        : account.signUp(email.input.value.trim(), password.input.value, username.input.value.trim());
    void run.then((result) => {
      submit.disabled = false;
      submit.textContent = old;
      if (!result.ok) {
        error.textContent = result.message;
        resend.hidden = result.code !== 'email_not_confirmed';
      } else if (result.session === null) {
        info.textContent = t('account.created');
        mode = 'login';
        for (const t of tabs.querySelectorAll('button')) t.classList.toggle('active', t.dataset.mode === mode);
        username.row.hidden = true;
        submit.textContent = t('account.submit.login');
        resend.hidden = false;
        forgot.hidden = false;
      } else {
        rerender();
      }
    });
  });

  form.append(email.row, username.row, password.row, error, info, submit, forgot, resend);
  const top = banner();
  if (top) root.append(top);
  root.append(
    tabs,
    form,
    el('p', 'account-note', t('account.why')),
    guest,
  );
  paint();
  return root;
}
