export interface BackendConfig {
  readonly url: string;
  readonly anonKey: string;
}

/** Reads the backend settings from Vite's env; null means the game runs offline, as a guest. */
export function readConfig(env: Readonly<Record<string, unknown>>): BackendConfig | null {
  const url = typeof env.VITE_SUPABASE_URL === 'string' ? env.VITE_SUPABASE_URL.trim().replace(/\/+$/, '') : '';
  const anonKey = typeof env.VITE_SUPABASE_ANON_KEY === 'string' ? env.VITE_SUPABASE_ANON_KEY.trim() : '';
  if (!/^https?:\/\//.test(url) || anonKey.length < 20) return null;
  return { url, anonKey };
}
