import { MISSIONS, type MissionDef } from '../data/missions.ts';
import { SPECIES, type SpeciesDef } from '../data/species.ts';
import type { ProgressData } from './progress.ts';

/** A photo that was just taken: what, how good, and how deep. */
export interface PhotoEvent {
  species: SpeciesDef;
  score: number;
  depth: number;
}

const species = SPECIES as readonly SpeciesDef[];

/** How far a state-based mission has got, as [done, needed]. Photo missions have no counter. */
export function missionProgress(mission: MissionDef, data: Readonly<ProgressData>): [number, number] | null {
  const goal = mission.goal;
  switch (goal.kind) {
    case 'depth':
      return [Math.min(goal.metres, Math.floor(data.maxDepth)), goal.metres];
    case 'discover': {
      const n = species.filter((s) => (data.discovered[s.id] ?? 0) > 0 && (goal.archetype === undefined || s.archetype === goal.archetype)).length;
      return [Math.min(goal.count, n), goal.count];
    }
    case 'portfolio': {
      const n = Object.values(data.photos).filter((p) => p.best >= goal.minScore).length;
      return [Math.min(goal.count, n), goal.count];
    }
    case 'pois':
      return [Math.min(goal.count, data.poisFound.length), goal.count];
    default:
      return null;
  }
}

/** Is the mission fulfilled by the saved state or, for photo missions, by the photo just taken? */
export function isMissionMet(mission: MissionDef, data: Readonly<ProgressData>, photo?: PhotoEvent): boolean {
  const goal = mission.goal;
  if (goal.kind === 'photo') {
    if (!photo) return false;
    if (goal.species !== undefined && photo.species.id !== goal.species) return false;
    if (goal.archetype !== undefined && photo.species.archetype !== goal.archetype) return false;
    if (goal.minDepth !== undefined && photo.depth < goal.minDepth) return false;
    if (goal.minScore !== undefined && photo.score < goal.minScore) return false;
    return true;
  }
  const p = missionProgress(mission, data);
  return p !== null && p[0] >= p[1];
}

/** Missions not done yet that the state (and the photo, if any) now fulfils. */
export function newlyMet(data: Readonly<ProgressData>, photo?: PhotoEvent): MissionDef[] {
  return MISSIONS.filter((m) => !data.missionsDone.includes(m.id) && isMissionMet(m, data, photo));
}

/** Credits paid out for every finished mission. */
export const missionCredits = (done: readonly string[]): number =>
  MISSIONS.reduce((sum, m) => sum + (done.includes(m.id) ? m.reward : 0), 0);
