import { BufferAttribute, BufferGeometry } from 'three';
import type { Archetype } from '../data/species.ts';

type V3 = readonly [number, number, number];

class Parts {
  private readonly pos: number[] = [];
  private readonly idx: number[] = [];
  private readonly marks: number[] = [];
  private current = 0;

  mark(value: number): this {
    this.current = value;
    return this;
  }

  private vertex(x: number, y: number, z: number): number {
    this.pos.push(x, y, z);
    this.marks.push(this.current);
    return this.pos.length / 3 - 1;
  }

  loft(rings: ReadonlyArray<readonly [number, number, number, number?, number?]>, sides = 10): this {
    const first = this.pos.length / 3;
    for (const [z, rx, ry, cy = 0, cx = 0] of rings) {
      for (let s = 0; s < sides; s++) {
        const a = (s / sides) * Math.PI * 2;
        this.vertex(cx + Math.cos(a) * rx, cy + Math.sin(a) * ry, z);
      }
    }
    for (let r = 0; r < rings.length - 1; r++) {
      for (let s = 0; s < sides; s++) {
        const a = first + r * sides + s;
        const b = first + r * sides + ((s + 1) % sides);
        this.idx.push(a, a + sides, b, b, a + sides, b + sides);
      }
    }
    return this;
  }

  spindle(z0: number, z1: number, rx: number, ry: number, n = 12, pow = 0.7, sides = 10, cy = 0): this {
    const rings: Array<[number, number, number, number]> = [];
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      const e = Math.max(0.02, Math.sin(Math.PI * t ** pow) ** 0.8);
      rings.push([z0 + (z1 - z0) * t, rx * e, ry * e, cy]);
    }
    return this.loft(rings, sides);
  }

  ball(x: number, y: number, z: number, r: number): this {
    const rings: Array<[number, number, number, number, number]> = [];
    for (let i = 0; i <= 6; i++) {
      const a = (i / 6) * Math.PI;
      rings.push([z - Math.cos(a) * r, Math.max(0.001, Math.sin(a) * r), Math.max(0.001, Math.sin(a) * r), y, x]);
    }
    return this.loft(rings, 8);
  }

  tube(path: readonly V3[], r0: number, r1: number, sides = 5): this {
    const first = this.pos.length / 3;
    path.forEach(([x, y, z], i) => {
      const t = i / Math.max(1, path.length - 1);
      const r = r0 + (r1 - r0) * t;
      const next = path[Math.min(path.length - 1, i + 1)] ?? [x, y, z];
      const prev = path[Math.max(0, i - 1)] ?? [x, y, z];
      let dx = next[0] - prev[0];
      let dy = next[1] - prev[1];
      let dz = next[2] - prev[2];
      const len = Math.hypot(dx, dy, dz) || 1;
      dx /= len;
      dy /= len;
      dz /= len;
      const ux = Math.abs(dy) < 0.9 ? 0 : 1;
      const uy = Math.abs(dy) < 0.9 ? 1 : 0;
      let ax = uy * dz - 0 * dy;
      let ay = 0 * dx - ux * dz;
      let az = ux * dy - uy * dx;
      const al = Math.hypot(ax, ay, az) || 1;
      ax /= al;
      ay /= al;
      az /= al;
      const bx = dy * az - dz * ay;
      const by = dz * ax - dx * az;
      const bz = dx * ay - dy * ax;
      for (let s = 0; s < sides; s++) {
        const a = (s / sides) * Math.PI * 2;
        const c = Math.cos(a) * r;
        const sn = Math.sin(a) * r;
        this.vertex(x + ax * c + bx * sn, y + ay * c + by * sn, z + az * c + bz * sn);
      }
    });
    for (let r = 0; r < path.length - 1; r++) {
      for (let s = 0; s < sides; s++) {
        const a = first + r * sides + s;
        const b = first + r * sides + ((s + 1) % sides);
        this.idx.push(a, a + sides, b, b, a + sides, b + sides);
      }
    }
    return this;
  }

  poly(points: readonly V3[]): this {
    const first = this.pos.length / 3;
    for (const [x, y, z] of points) this.vertex(x, y, z);
    for (let i = 1; i < points.length - 1; i++) this.idx.push(first, first + i, first + i + 1);
    return this;
  }

  pair(points: readonly V3[]): this {
    this.poly(points);
    return this.poly(points.map(([x, y, z]) => [-x, y, z] as const));
  }

  build(): BufferGeometry {
    const g = new BufferGeometry();
    g.setAttribute('position', new BufferAttribute(new Float32Array(this.pos), 3));
    g.setAttribute('mark', new BufferAttribute(new Float32Array(this.marks), 1));
    g.setIndex(this.idx);
    g.computeVertexNormals();
    return g;
  }
}

function fish(): BufferGeometry {
  const p = new Parts().spindle(-0.5, 0.34, 0.07, 0.14, 16, 0.7, 12);
  p.mark(3)
    .loft([[-0.27, 0.0705, 0.1, 0.0], [-0.255, 0.0715, 0.103, 0.0], [-0.24, 0.0705, 0.1, 0.0]], 12)
    .ball(0, -0.012, -0.495, 0.018);
  p.mark(1).ball(0.052, 0.035, -0.37, 0.024).ball(-0.052, 0.035, -0.37, 0.024);
  p.mark(2)
    .poly([[0, 0, 0.3], [0, 0.035, 0.3], [0, 0.14, 0.4], [0, 0.25, 0.5], [0, 0.13, 0.45], [0, 0, 0.405], [0, -0.13, 0.45], [0, -0.25, 0.5], [0, -0.14, 0.4], [0, -0.035, 0.3]])
    .poly([[0, 0.11, 0.0], [0, 0.125, -0.15], [0, 0.2, -0.12], [0, 0.27, -0.02], [0, 0.22, 0.07], [0, 0.12, 0.15]])
    .poly([[0, -0.1, 0.12], [0, -0.115, 0.04], [0, -0.19, 0.14], [0, -0.1, 0.2]])
    .pair([[0.03, -0.1, -0.12], [0.05, -0.17, -0.06], [0.04, -0.18, -0.02], [0.03, -0.1, -0.02]])
    .pair([[0.07, -0.01, -0.22], [0.12, -0.04, -0.2], [0.2, -0.1, -0.1], [0.16, -0.09, -0.07], [0.08, -0.04, -0.12]]);
  return p.build();
}

function shark(): BufferGeometry {
  return new Parts()
    .spindle(-0.5, 0.3, 0.085, 0.1, 14, 0.62)
    .tube([[0, 0, 0.26], [0, 0.01, 0.4]], 0.04, 0.02)
    .mark(1)
    .ball(0.067, 0.03, -0.4, 0.02)
    .ball(-0.067, 0.03, -0.4, 0.02)
    .mark(3)
    .loft([[-0.31, 0.0852, 0.1, 0.0], [-0.3, 0.0858, 0.102, 0.0], [-0.29, 0.0852, 0.1, 0.0]], 12)
    .loft([[-0.27, 0.0858, 0.103, 0.0], [-0.26, 0.0862, 0.104, 0.0], [-0.25, 0.0858, 0.103, 0.0]], 12)
    .mark(2)
    .poly([[0, 0.03, 0.34], [0, 0.3, 0.52], [0, 0.04, 0.46]])
    .poly([[0, -0.02, 0.36], [0, -0.15, 0.48], [0, -0.01, 0.44]])
    .poly([[0, 0.09, -0.15], [0, 0.3, 0.02], [0, 0.09, 0.06]])
    .pair([[0.07, -0.05, -0.2], [0.34, -0.14, 0.0], [0.08, -0.05, 0.02]])
    .pair([[0.04, -0.06, 0.18], [0.12, -0.09, 0.26], [0.04, -0.05, 0.26]])
    .build();
}

