  return new Parts()
    .spindle(-0.5, 0.32, 0.115, 0.13, 14, 0.55, 12)
    .tube([[0, 0, 0.3], [0, 0.01, 0.42]], 0.05, 0.025)
    .mark(1)
    .ball(0.1, -0.01, -0.36, 0.012)
    .ball(-0.1, -0.01, -0.36, 0.012)
    .mark(2)
