function ray(): BufferGeometry {
  return new Parts()
    .spindle(-0.4, 0.25, 0.62, 0.05, 14, 0.9, 12)
    .pair([[0.0, 0.0, -0.46], [0.07, 0.0, -0.4], [0.02, 0.0, -0.3]])
    .tube([[0, 0, 0.22], [0, 0, 0.5]], 0.025, 0.006)
    .build();
}

function turtle(): BufferGeometry {
  return new Parts()
    .spindle(-0.3, 0.3, 0.24, 0.13, 10, 0.7, 12, 0.02)
    .spindle(-0.5, -0.28, 0.06, 0.06, 6, 0.8, 8)
    .pair([[0.16, -0.02, -0.18], [0.55, 0.0, -0.3], [0.2, -0.02, -0.04]])
    .pair([[0.12, -0.02, 0.18], [0.24, 0.0, 0.34], [0.08, -0.02, 0.28]])
    .build();
}

function squid(): BufferGeometry {
  const p = new Parts().spindle(-0.12, 0.5, 0.08, 0.08, 12, 1.0, 10).spindle(-0.3, -0.1, 0.06, 0.06, 6, 0.8, 8);
  for (const [i, angle] of Array.from({ length: 8 }, (_, k) => [k, (k / 8) * Math.PI * 2] as const)) {
    const sx = Math.cos(angle) * 0.05;
    const sy = Math.sin(angle) * 0.05;
    p.tube([[sx, sy, -0.28], [sx * 1.6, sy * 1.6, -0.4 - (i % 2) * 0.03], [sx * 1.9, sy * 1.9, -0.5]], 0.012, 0.004, 4);
  }
  p.tube([[0.02, 0, -0.3], [0.03, 0.03, -0.6], [0.04, 0.0, -0.8]], 0.008, 0.012, 4);
  p.tube([[-0.02, 0, -0.3], [-0.03, 0.03, -0.6], [-0.04, 0.0, -0.8]], 0.008, 0.012, 4);
  p.pair([[0.05, 0, 0.24], [0.22, 0, 0.4], [0.04, 0, 0.5]]);
  return p.build();
}

function octopus(): BufferGeometry {
  const p = new Parts().spindle(-0.05, 0.5, 0.2, 0.22, 10, 0.8, 12, 0.03);
  for (const [i, angle] of Array.from({ length: 8 }, (_, k) => [k, (k / 8) * Math.PI * 2] as const)) {
    const sx = Math.cos(angle);
    const sy = Math.sin(angle);
    p.tube(
      [[sx * 0.05, sy * 0.05 - 0.04, 0.0], [sx * 0.2, sy * 0.1 - 0.12, -0.25], [sx * 0.34, -0.2 + sy * 0.04, -0.4 - (i % 3) * 0.04]],
      0.035,
      0.006,
      5,
    );
  }
  return p.build();
}

function jelly(): BufferGeometry {
  const p = new Parts();
  const rings: Array<[number, number, number, number]> = [];
  const n = 9;
  const first: V3[] = [];
  void first;
  const parts = p as unknown as { pos: number[]; idx: number[] };
  void rings;
  const sides = 14;
  const base = parts.pos.length / 3;
  for (let r = 0; r <= n; r++) {
    const phi = (r / n) * (Math.PI / 2);
    const radius = Math.cos(phi) * 0.4;
    const y = Math.sin(phi) * 0.28;
    for (let s = 0; s < sides; s++) {
      const a = (s / sides) * Math.PI * 2;
      parts.pos.push(Math.cos(a) * Math.max(0.005, radius), y, Math.sin(a) * Math.max(0.005, radius));
      (parts as unknown as { marks: number[] }).marks.push(0);
    }
  }
  for (let r = 0; r < n; r++) {
    for (let s = 0; s < sides; s++) {
      const a = base + r * sides + s;
      const b = base + r * sides + ((s + 1) % sides);
      parts.idx.push(a, b, a + sides, b, b + sides, a + sides);
    }
  }
  for (const [i, angle] of Array.from({ length: 10 }, (_, k) => [k, (k / 10) * Math.PI * 2] as const)) {
    const cx = Math.cos(angle) * 0.3;
    const cz = Math.sin(angle) * 0.3;
    const len = 0.7 + (i % 3) * 0.15;
    p.tube([[cx, 0, cz], [cx * 0.8, -len * 0.5, cz * 0.8], [cx * 0.6 + 0.02, -len, cz * 0.6]], 0.012, 0.003, 4);
  }
  p.tube([[0, 0, 0], [0.04, -0.3, 0], [0, -0.6, 0.04]], 0.07, 0.02, 6);
  return p.build();
}

function crustacean(): BufferGeometry {
  const p = new Parts().spindle(-0.4, 0.5, 0.2, 0.13, 10, 0.85, 8, 0.0);
  for (const side of [-1, 1] as const) {
    for (let i = 0; i < 6; i++) {
      const z = -0.25 + i * 0.12;
      p.tube([[side * 0.12, -0.06, z], [side * 0.3, -0.12, z + 0.04], [side * 0.36, -0.28, z + 0.07]], 0.015, 0.006, 3);
    }
    p.tube([[side * 0.05, 0.04, -0.42], [side * 0.12, 0.1, -0.62], [side * 0.2, 0.08, -0.85]], 0.01, 0.003, 3);
  }
  return p.build();
}

function cucumber(): BufferGeometry {
  const p = new Parts().spindle(-0.5, 0.5, 0.1, 0.1, 10, 0.5, 8, 0.0);
  for (const side of [-1, 1] as const) {
    for (const z of [-0.3, -0.1, 0.1]) {
      p.tube([[side * 0.07, -0.07, z], [side * 0.14, -0.15, z], [side * 0.16, -0.22, z]], 0.02, 0.01, 3);
    }
  }
  p.tube([[0, 0.08, -0.46], [0, 0.18, -0.55], [0, 0.22, -0.6]], 0.02, 0.01, 3);
  return p.build();
}

function eel(): BufferGeometry {
  const rings: Array<[number, number, number]> = [];
  for (let i = 0; i <= 28; i++) {
    const t = i / 28;
    const e = Math.max(0.12, Math.sin(Math.PI * t ** 0.35) ** 0.9);
    rings.push([-0.5 + t, 0.016 * e, 0.032 * e]);
  }
  const p = new Parts().loft(rings, 8);
  const strip: V3[] = [];
  for (let i = 0; i <= 8; i++) strip.push([0, 0.03 + 0.012 * Math.sin(i * 0.9), -0.3 + i * 0.1]);
  const under = strip.map(([x, , z]) => [x, 0.0, z] as const);
  p.poly([...strip, ...under.reverse()]);
  return p.build();
}

export const ARCHETYPE_GEOMETRY: Record<Archetype, () => BufferGeometry> = {
  fish,
  shark,
  whale,
  ray,
  turtle,
  squid,
  octopus,
  jelly,
  crustacean,
  cucumber,
  eel,
};

