import {
  Color,
  DoubleSide,
  InstancedBufferAttribute,
  InstancedBufferGeometry,
  Mesh,
  ShaderMaterial,
} from 'three';
import type { Archetype } from '../data/species.ts';
import { type Creature, visualSize } from '../domain/creature.ts';
import { ARCHETYPE_GEOMETRY } from './creature-geometry.ts';
import { CREATURE_FRAGMENT } from './fish-school.ts';
import type { SceneUniforms } from './uniforms.ts';

const CAPACITY = 14;
interface Motion {
  readonly mode: 0 | 1 | 2;
  readonly wave: readonly [number, number, number, number];
  readonly rate: (speed: number) => number;
}

const MOTION: Record<Archetype, Motion> = {
  fish: { mode: 0, wave: [0.07, 7, 0, 0], rate: (v) => 6 + v * 1.2 },
  shark: { mode: 0, wave: [0.05, 6, 0, 0], rate: (v) => 2.5 + v * 0.8 },
  whale: { mode: 0, wave: [0.05, 4, 1, 0], rate: (v) => 1.2 + v * 0.3 },
  ray: { mode: 1, wave: [0.4, 0, 0, 0], rate: (v) => 1.4 + v * 0.3 },
  turtle: { mode: 1, wave: [0.7, 0, 0, 0], rate: (v) => 1.6 + v * 0.6 },
  squid: { mode: 0, wave: [0.05, 6, 0, 0], rate: (v) => 2.5 + v * 0.6 },
  octopus: { mode: 2, wave: [0.12, 0, 0, 0], rate: () => 1.6 },
  jelly: { mode: 2, wave: [0.18, 0, 0, 0], rate: () => 1.8 },
  crustacean: { mode: 0, wave: [0.04, 8, 0, 0], rate: () => 6 },
  cucumber: { mode: 0, wave: [0.03, 4, 0, 1], rate: () => 1 },
  eel: { mode: 0, wave: [0.1, 10, 0, 1], rate: (v) => 3 + v * 0.8 },
};

const PATTERN: Readonly<Record<string, number>> = {
  'tiger-shark': 1,
  clownfish: 1,
  lionfish: 1,
  sailfish: 1,
  'whale-shark': 2,
  pufferfish: 2,
  moray: 2,
  coelacanth: 2,
  octopus: 2,
  manta: 3,
  orca: 3,
  dolphin: 3,
  'great-white': 3,
  humpback: 3,
  'green-turtle': 2,
};

const TRANSLUCENT: ReadonlySet<Archetype> = new Set<Archetype>(['jelly']);

const vertexShader = /* glsl */ `
uniform float uTime;
uniform float uMode;
uniform vec4 uWave;
attribute vec3 iPos;
attribute vec3 iDir;
attribute vec4 iData; // x = size, y = phase, z = rate
attribute vec3 iShape; // width, height, length multipliers
attribute vec3 iBody;
attribute vec3 iBack;
attribute vec3 iGlow;
attribute float mark;
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying vec3 vBody;
varying vec3 vBack;
varying vec3 vGlow;
varying float vUp;
varying vec3 vLocal;
varying float vPattern;
varying float vMark;

void main() {
  vec3 f = normalize(iDir);
  vec3 r = cross(f, vec3(0.0, 1.0, 0.0));
  if (dot(r, r) < 1e-4) r = vec3(1.0, 0.0, 0.0);
  r = normalize(r);
  vec3 u = cross(r, f);
  mat3 basis = mat3(r, u, -f);

  vec3 p = position;
  float t = uTime * iData.z + iData.y * 6.2831853;
  if (uMode < 0.5) {
    float w = mix(smoothstep(-0.25, 0.5, p.z), 1.0, uWave.w);
    float s = sin(t - p.z * uWave.y) * uWave.x * w;
    if (uWave.z > 0.5) p.y += s; else p.x += s;
  } else if (uMode < 1.5) {
    p.y += sin(t) * uWave.x * abs(p.x);
  } else {
    float k = sin(t);
    p.xz *= 1.0 + uWave.x * 0.5 * k * smoothstep(-0.5, 0.2, p.y);
    p.y *= 1.0 - uWave.x * 0.3 * k;
    p.x += sin(t * 0.7 + p.y * 6.0) * 0.03 * smoothstep(0.1, -0.6, p.y);
  }

  vWorldPos = iPos + basis * (p * iShape * iData.x);
  vNormalW = basis * normal;
  vBody = iBody;
  vBack = iBack;
  vGlow = iGlow;
  vUp = normal.y;
  vLocal = position;
  vPattern = iData.w;
  vMark = mark;
  gl_Position = projectionMatrix * viewMatrix * vec4(vWorldPos, 1.0);
}
`;

class Batch {
  readonly mesh: Mesh;
  readonly geometry: InstancedBufferGeometry;
  readonly material: ShaderMaterial;
  readonly attrs: Record<'iPos' | 'iDir' | 'iData' | 'iShape' | 'iBody' | 'iBack' | 'iGlow', InstancedBufferAttribute>;
  count = 0;

  constructor(archetype: Archetype, uniforms: SceneUniforms) {
    const base = ARCHETYPE_GEOMETRY[archetype]();
    this.geometry = new InstancedBufferGeometry();
    this.geometry.index = base.index;
    this.geometry.setAttribute('position', base.getAttribute('position'));
    this.geometry.setAttribute('normal', base.getAttribute('normal'));
    this.geometry.setAttribute('mark', base.getAttribute('mark'));
    const make = (size: number): InstancedBufferAttribute => {
      const a = new InstancedBufferAttribute(new Float32Array(CAPACITY * size), size);
      a.setUsage(35048);
      return a;
    };
    this.attrs = { iPos: make(3), iDir: make(3), iData: make(4), iShape: make(3), iBody: make(3), iBack: make(3), iGlow: make(3) };
    for (const [name, a] of Object.entries(this.attrs)) this.geometry.setAttribute(name, a);
    this.geometry.instanceCount = 0;

    const motion = MOTION[archetype];
    this.material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
        uBeamPos: uniforms.uBeamPos,
        uBeamDir: uniforms.uBeamDir,
        uBeamParams: uniforms.uBeamParams,
        uAlpha: { value: TRANSLUCENT.has(archetype) ? 0.5 : 1 },
        uMode: { value: motion.mode },
        uWave: { value: { x: motion.wave[0], y: motion.wave[1], z: motion.wave[2], w: motion.wave[3] } },
      },
      vertexShader,
      fragmentShader: CREATURE_FRAGMENT,
      side: DoubleSide,
      transparent: TRANSLUCENT.has(archetype),
      depthWrite: !TRANSLUCENT.has(archetype),
      fog: false,
    });
    this.mesh = new Mesh(this.geometry, this.material);
    this.mesh.frustumCulled = false;
    if (TRANSLUCENT.has(archetype)) this.mesh.renderOrder = 3;
  }
}

/** Draws every solitary animal: one instanced mesh per body plan, animated in the vertex shader. */
export class Creatures {
  readonly group: Mesh[];
  private readonly batches = new Map<Archetype, Batch>();
  private readonly colour = new Color();

  constructor(uniforms: SceneUniforms) {
    for (const archetype of Object.keys(ARCHETYPE_GEOMETRY) as Archetype[]) {
      this.batches.set(archetype, new Batch(archetype, uniforms));
    }
    this.group = [...this.batches.values()].map((b) => b.mesh);
  }

  update(creatures: readonly Creature[]): void {
    for (const b of this.batches.values()) b.count = 0;
    for (const c of creatures) {
      const sp = c.species;
      const batch = this.batches.get(sp.archetype);
      if (!batch || batch.count >= CAPACITY) continue;
      const n = batch.count++;
      const a = batch.attrs;
      const f = c.forward();
      const upright = sp.archetype === 'jelly' || sp.archetype === 'octopus' || sp.archetype === 'crustacean' || sp.archetype === 'cucumber';
      const len = Math.hypot(f.x, upright ? 0 : f.y, f.z) || 1;
      const motion = MOTION[sp.archetype];
      const size = visualSize(sp);
      a.iPos.setXYZ(n, c.position.x, c.position.y, c.position.z);
      a.iDir.setXYZ(n, f.x / len, upright ? 0 : f.y / len, f.z / len);
      a.iData.setXYZW(n, size, c.phase, motion.rate(sp.speed) * (1 + 0.8 * c.alarm), PATTERN[sp.id] ?? 0);
      const shape = sp.shape;
      const siph = sp.id === 'siphonophore';
      a.iShape.setXYZ(n, (shape?.width ?? 1) * (siph ? 0.15 : 1), shape?.height ?? 1, (shape?.length ?? 1) * (siph ? 0.15 : 1));
      this.colour.setHex(sp.body);
      a.iBody.setXYZ(n, this.colour.r, this.colour.g, this.colour.b);
      this.colour.setHex(sp.accent);
      a.iBack.setXYZ(n, this.colour.r, this.colour.g, this.colour.b);
      if (sp.glow !== undefined) {
        this.colour.setHex(sp.glow);
        a.iGlow.setXYZ(n, this.colour.r, this.colour.g, this.colour.b);
      } else {
        a.iGlow.setXYZ(n, 0, 0, 0);
      }
    }
    for (const b of this.batches.values()) {
      b.geometry.instanceCount = b.count;
      for (const attr of Object.values(b.attrs)) attr.needsUpdate = true;
    }
  }

  dispose(): void {
    for (const b of this.batches.values()) {
      b.geometry.dispose();
      b.material.dispose();
    }
  }
}
