import {
  BufferAttribute,
  BufferGeometry,
  Color,
  DoubleSide,
  IcosahedronGeometry,
  InstancedBufferAttribute,
  InstancedBufferGeometry,
  Mesh,
  ShaderMaterial,
} from 'three';
import {
  buildBranchCoral,
  buildBrainCoral,
  buildFanCoral,
  buildTableCoral,
} from './coral-geometry.ts';
import { CELL, type FloraItem, type FloraKind, scatterCell } from '../domain/scatter.ts';
import type { WorldQuery } from '../domain/world.ts';
import { COMMON_UNIFORMS, LIGHTING_GLSL } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

/** Cells generated per frame, so arriving in a new area never causes a stutter. */
const CELLS_PER_FRAME = 10;

interface KindStyle {
  readonly capacity: number;
  readonly sway: number;
  readonly colourA: number;
  readonly colourB: number;
  readonly boost?: number;
}

const STYLE: Record<FloraKind, KindStyle> = {
  rock: { capacity: 450, sway: 0, colourA: 0x4a4640, colourB: 0x7a7261 },
  grass: { capacity: 1400, sway: 0.35, colourA: 0x4f7f33, colourB: 0xb5cf55 },
  kelp: { capacity: 420, sway: 1, colourA: 0x76862a, colourB: 0xd0b445 },
  coralBranch: { capacity: 700, sway: 0.05, colourA: 0xd84ad0, colourB: 0x4ad8e8, boost: 3 },
  coralTable: { capacity: 260, sway: 0, colourA: 0x35e0b8, colourB: 0xa070f0, boost: 3 },
  coralBrain: { capacity: 380, sway: 0, colourA: 0xe0d060, colourB: 0x70e090, boost: 2.8 },
  coralFan: { capacity: 260, sway: 0.18, colourA: 0xf04aa0, colourB: 0xf0e040, boost: 3 },
};

const hash3 = (x: number, y: number, z: number): number => {
  const s = Math.sin(x * 127.1 + y * 311.7 + z * 74.7) * 43758.5453;
  return s - Math.floor(s);
};

function buildRock(): BufferGeometry {
  const geometry = new IcosahedronGeometry(1, 2);
  const p = geometry.getAttribute('position') as BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const y = p.getY(i);
    const z = p.getZ(i);
    const k = 0.72 + 0.5 * hash3(Math.round(x * 6), Math.round(y * 6), Math.round(z * 6));
    p.setXYZ(i, x * k * 1.15, Math.max(y * k, -0.35), z * k);
  }
  geometry.computeVertexNormals();
  return geometry;
}

interface Blade {
  angle: number;
  offset: number;
  bend: number;
  width: number;
  twist: number;
}

function buildBlades(blades: Blade[], segments: number): BufferGeometry {
  const positions: number[] = [];
  const indices: number[] = [];
  for (const blade of blades) {
    const base = positions.length / 3;
    const dx = Math.cos(blade.angle);
    const dz = Math.sin(blade.angle);
    const ox = Math.cos(blade.angle * 2.7) * blade.offset;
    const oz = Math.sin(blade.angle * 2.7) * blade.offset;
    for (let s = 0; s <= segments; s++) {
      const t = s / segments;
      const half = blade.width * (1 - 0.85 * t) * 0.5;
      const bend = blade.bend * t * t + Math.sin(t * 6 + blade.twist) * 0.04 * t;
      const cx = ox + dx * bend;
      const cz = oz + dz * bend;
      positions.push(cx - dz * half, t, cz + dx * half, cx + dz * half, t, cz - dx * half);
    }
    for (let s = 0; s < segments; s++) {
      const a = base + s * 2;
      indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
  }
  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

const makeGrass = (): BufferGeometry =>
  buildBlades(
    Array.from({ length: 9 }, (_, i) => ({
      angle: i * 2.4,
      offset: 0.05 + (i % 3) * 0.05,
      bend: 0.15 + (i % 4) * 0.07,
      width: 0.1,
      twist: i,
    })),
    3,
  );

const makeKelp = (): BufferGeometry =>
  buildBlades(
    Array.from({ length: 3 }, (_, i) => ({
      angle: i * 2.1 + 0.4,
      offset: 0.08,
      bend: 0.08 + i * 0.03,
      width: 0.3,
      twist: i * 2,
    })),
    10,
  );

const vertexShader = /* glsl */ `
uniform float uTime;
uniform float uSway;
attribute vec4 iPos;   // xyz = base position, w = yaw
attribute vec4 iSize;  // x = width, y = height, z = tint
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying float vTint;
varying float vHeight;

void main() {
  float c = cos(iPos.w);
  float s = sin(iPos.w);
  mat3 yaw = mat3(c, 0.0, -s, 0.0, 1.0, 0.0, s, 0.0, c);

  vec3 p = position * vec3(iSize.x, iSize.y, iSize.x);
  float h = clamp(position.y, 0.0, 1.0);
  float phase = iPos.x * 0.37 + iPos.z * 0.29;
  float sway = uSway * h * h * (0.35 + 0.1 * iSize.y);
  p.x += sin(uTime * 1.1 + phase) * sway;
  p.z += cos(uTime * 0.9 + phase * 1.3) * sway * 0.7;

  vWorldPos = iPos.xyz + yaw * p;
  vNormalW = yaw * normal;
  vTint = iSize.z;
  vHeight = h;
  gl_Position = projectionMatrix * viewMatrix * vec4(vWorldPos, 1.0);
}
`;

const fragmentShader = /* glsl */ `
${COMMON_UNIFORMS}
${LIGHTING_GLSL}
uniform vec3 uColA;
uniform vec3 uColB;
uniform float uPlant;
uniform float uBoost;
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying float vTint;
varying float vHeight;

void main() {
  vec3 N = safeNormalize(vNormalW, vec3(0.0, 1.0, 0.0));
  if (!gl_FrontFacing) N = -N;
  // Thin leaves let light through: lean their normals up so they catch the sun.
  N = safeNormalize(mix(N, vec3(0.0, 1.0, 0.0), 0.65 * uPlant), vec3(0.0, 1.0, 0.0));
  vec3 albedo = mix(uColA, uColB, vTint);
  // Plants are lighter towards the tips; rocks get a little vertical grime.
  albedo *= mix(0.8 + 0.2 * N.y, 0.65 + 0.7 * vHeight, uPlant) * uBoost;
  gl_FragColor = vec4(shadeUnderwater(albedo, N, vWorldPos), 1.0);
}
`;

interface Layer {
  readonly mesh: Mesh;
  readonly geometry: InstancedBufferGeometry;
  readonly material: ShaderMaterial;
  readonly pos: InstancedBufferAttribute;
  readonly size: InstancedBufferAttribute;
  readonly capacity: number;
}

/**
 * Rocks, seagrass and kelp scattered over the seabed around the camera. Cells are generated
 * lazily and cached; instance buffers are refilled whenever the set of nearby cells changes.
 */
export class Flora {
  readonly group: Mesh[] = [];
  private readonly layers = new Map<FloraKind, Layer>();
  private readonly cache = new Map<number, readonly FloraItem[]>();
  private readonly world: WorldQuery;
  private readonly radiusCells: number;
  private cellX = Number.NaN;
  private cellZ = Number.NaN;
  private dirty = true;
  private wanted: { key: number; cx: number; cz: number }[] = [];

  constructor(world: WorldQuery, uniforms: SceneUniforms, radius: number) {
    this.world = world;
    this.radiusCells = Math.ceil(radius / CELL);
    const scale = Math.min(1, radius / 90);
    const geometries: Record<FloraKind, BufferGeometry> = {
      rock: buildRock(),
      grass: makeGrass(),
      kelp: makeKelp(),
      coralBranch: buildBranchCoral(),
      coralTable: buildTableCoral(),
      coralBrain: buildBrainCoral(),
      coralFan: buildFanCoral(),
    };
    for (const kind of Object.keys(STYLE) as FloraKind[]) {
      const style = STYLE[kind];
      const layer = this.createLayer(
        geometries[kind],
        uniforms,
        style,
        Math.max(40, Math.round(style.capacity * scale)),
        kind === 'grass' || kind === 'kelp' ? 1 : 0,
      );
      this.layers.set(kind, layer);
      this.group.push(layer.mesh);
    }
  }

  update(camX: number, camZ: number): void {
    const cx = Math.floor(camX / CELL);
    const cz = Math.floor(camZ / CELL);
    if (cx !== this.cellX || cz !== this.cellZ) {
      this.cellX = cx;
      this.cellZ = cz;
      this.wanted = this.cellsAround(cx, cz);
      this.dirty = true;
      this.evict();
    }

    let generated = 0;
    for (const cell of this.wanted) {
      if (generated >= CELLS_PER_FRAME) break;
      if (this.cache.has(cell.key)) continue;
      this.cache.set(cell.key, scatterCell(cell.cx, cell.cz, this.world));
      generated++;
      this.dirty = true;
    }
    if (this.dirty && generated < CELLS_PER_FRAME) {
      this.rebuild();
      this.dirty = false;
    }
  }

  dispose(): void {
    for (const layer of this.layers.values()) {
      layer.geometry.dispose();
      layer.material.dispose();
    }
  }

  private cellsAround(cx: number, cz: number): { key: number; cx: number; cz: number }[] {
    const r = this.radiusCells;
    const cells: { key: number; cx: number; cz: number; d: number }[] = [];
    for (let dz = -r; dz <= r; dz++) {
      for (let dx = -r; dx <= r; dx++) {
        const d = dx * dx + dz * dz;
        if (d > r * r) continue;
        cells.push({ key: cellKey(cx + dx, cz + dz), cx: cx + dx, cz: cz + dz, d });
      }
    }
    cells.sort((a, b) => a.d - b.d);
    return cells;
  }

  private evict(): void {
    if (this.cache.size < this.wanted.length * 3) return;
    const keep = new Set(this.wanted.map((c) => c.key));
    for (const key of this.cache.keys()) if (!keep.has(key)) this.cache.delete(key);
  }

  private rebuild(): void {
    const counts = new Map<FloraKind, number>();
    for (const cell of this.wanted) {
      const items = this.cache.get(cell.key);
      if (!items) continue;
      for (const item of items) {
        const layer = this.layers.get(item.kind);
        if (!layer) continue;
        const n = counts.get(item.kind) ?? 0;
        if (n >= layer.capacity) continue;
        const lift = item.kind === 'rock' ? item.height * 0.25 : -0.03;
        layer.pos.setXYZW(n, item.x, item.y + lift, item.z, item.yaw);
        layer.size.setXYZW(n, item.width, item.height, item.tint, 0);
        counts.set(item.kind, n + 1);
      }
    }
    for (const [kind, layer] of this.layers) {
      layer.geometry.instanceCount = counts.get(kind) ?? 0;
      layer.pos.needsUpdate = true;
      layer.size.needsUpdate = true;
    }
  }

  private createLayer(
    base: BufferGeometry,
    uniforms: SceneUniforms,
    style: KindStyle,
    capacity: number,
    plant: number,
  ): Layer {
    const geometry = new InstancedBufferGeometry();
    geometry.index = base.index;
    geometry.setAttribute('position', base.getAttribute('position'));
    geometry.setAttribute('normal', base.getAttribute('normal'));
    const make = (): InstancedBufferAttribute => {
      const a = new InstancedBufferAttribute(new Float32Array(capacity * 4), 4);
      a.setUsage(35048);
      return a;
    };
    const pos = make();
    const size = make();
    geometry.setAttribute('iPos', pos);
    geometry.setAttribute('iSize', size);
    geometry.instanceCount = 0;

    const material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
        uBeamPos: uniforms.uBeamPos,
        uBeamDir: uniforms.uBeamDir,
        uBeamParams: uniforms.uBeamParams,
        uSway: { value: style.sway },
        uPlant: { value: plant },
        uBoost: { value: style.boost ?? 1 },
        uColA: { value: new Color(style.colourA) },
        uColB: { value: new Color(style.colourB) },
      },
      vertexShader,
      fragmentShader,
      side: DoubleSide,
      fog: false,
    });
    const mesh = new Mesh(geometry, material);
    mesh.frustumCulled = false;
    return { mesh, geometry, material, pos, size, capacity };
  }
}

const cellKey = (cx: number, cz: number): number => (cx + 32768) * 65536 + (cz + 32768);
