import { SUB } from '../data/balance.ts';
import { MAX_UPGRADE_LEVEL, STAT_TABLES, UPGRADE_IDS, type UpgradeId } from '../data/upgrades.ts';

export type UpgradeLevels = Record<UpgradeId, number>;

/** Immutable performance sheet of the submarine, derived from the installed upgrades. */
export interface SubSpec {
  readonly crushDepth: number;
  readonly batteryCapacity: number;
  readonly oxygenCapacity: number;
  readonly maxSpeed: number;
  readonly maxVertical: number;
  readonly turnRate: number;
  readonly agility: number;
  readonly beamRange: number;
  readonly sonarRange: number;
  readonly sonarCooldown: number;
  readonly sonarAnalysis: number;
  readonly photoBonus: number;
  readonly emergencySpeed: number;
}

export const createUpgradeLevels = (): UpgradeLevels => ({
  hull: 0,
  battery: 0,
  oxygen: 0,
  thrusters: 0,
  light: 0,
  sonar: 0,
  camera: 0,
});

export const clampLevel = (level: number): number =>
  Math.max(0, Math.min(MAX_UPGRADE_LEVEL, Math.floor(level)));

const stat = (table: readonly number[], level: number): number => table[clampLevel(level)] ?? 0;

export function deriveSubSpec(levels: Readonly<UpgradeLevels>): SubSpec {
  return {
    crushDepth: stat(STAT_TABLES.crushDepth, levels.hull),
    batteryCapacity: stat(STAT_TABLES.batteryCapacity, levels.battery),
    oxygenCapacity: stat(STAT_TABLES.oxygenCapacity, levels.oxygen),
    maxSpeed: stat(STAT_TABLES.maxSpeed, levels.thrusters),
    maxVertical: stat(STAT_TABLES.maxVertical, levels.thrusters),
    turnRate: 0.8 + 0.08 * clampLevel(levels.thrusters),
    agility: SUB.agility,
    beamRange: stat(STAT_TABLES.beamRange, levels.light),
    sonarRange: stat(STAT_TABLES.sonarRange, levels.sonar),
    sonarCooldown: stat(STAT_TABLES.sonarCooldown, levels.sonar),
    sonarAnalysis: stat(STAT_TABLES.sonarAnalysis, levels.sonar),
    photoBonus: stat(STAT_TABLES.photoBonus, levels.camera),
    emergencySpeed: SUB.emergencySpeed,
  };
}

export const isUpgradeId = (value: string): value is UpgradeId =>
  (UPGRADE_IDS as readonly string[]).includes(value);
