import {
  AdditiveBlending,
  DoubleSide,
  Group,
  Mesh,
  PlaneGeometry,
  ShaderMaterial,
  Vector3,
} from 'three';
import { mulberry32 } from '../core/random.ts';
import { COMMON_UNIFORMS, NOISE_GLSL } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

const vertexShader = /* glsl */ `
varying vec2 vUv;
varying vec3 vWorld;
void main() {
  vUv = uv;
  vec4 w = modelMatrix * vec4(position, 1.0);
  vWorld = w.xyz;
  gl_Position = projectionMatrix * viewMatrix * w;
}
`;

const fragmentShader = /* glsl */ `
${COMMON_UNIFORMS}
${NOISE_GLSL}
uniform float uStrength;
uniform float uSeed;
varying vec2 vUv;
varying vec3 vWorld;

void main() {
  float across = 1.0 - abs(vUv.x * 2.0 - 1.0);
  across = smoothstep(0.0, 0.7, across);
  float along = pow(clamp(vUv.y, 0.0, 1.0), 1.4);
  float shimmer = 0.55 + 0.45 * vnoise(vec2(vUv.y * 6.0 + uSeed, uTime * 0.6 + uSeed * 3.0));
  float dist = length(vWorld - uCamPos);
  float a = across * along * shimmer * uStrength * exp(-uFogDensity * dist * 0.5);
  if (!(a >= 0.0) || a > 100.0) discard;
  gl_FragColor = vec4(uSunColor * vec3(0.9, 1.1, 1.2) * a, a);
}
`;

/**
 * Crepuscular rays: tall translucent planes hanging from the surface along the sun direction.
 * They follow the camera and fade out as sunlight is absorbed with depth.
 */
export class LightShafts {
  readonly group = new Group();
  private readonly materials: ShaderMaterial[] = [];
  private readonly baseOffsets: Vector3[] = [];
  private readonly sunlight: SceneUniforms['uSunlight'];

  constructor(uniforms: SceneUniforms, count: number) {
    this.sunlight = uniforms.uSunlight;
    const rng = mulberry32(77);
    for (let i = 0; i < count; i++) {
      const strength = { value: 0 };
      const material = new ShaderMaterial({
        uniforms: {
          uTime: uniforms.uTime,
          uSunDir: uniforms.uSunDir,
          uSunColor: uniforms.uSunColor,
          uFogColor: uniforms.uFogColor,
          uFogDensity: uniforms.uFogDensity,
          uCamPos: uniforms.uCamPos,
          uSunlight: uniforms.uSunlight,
          uPixelRatio: uniforms.uPixelRatio,
          uStrength: strength,
          uSeed: { value: rng() * 10 },
        },
        vertexShader,
        fragmentShader,
        blending: AdditiveBlending,
        transparent: true,
        depthWrite: false,
        side: DoubleSide,
        fog: false,
      });
      const width = 8 + rng() * 16;
      const height = 220;
      const mesh = new Mesh(new PlaneGeometry(width, height, 1, 1), material);
      mesh.frustumCulled = false;
      mesh.geometry.translate(0, -height / 2, 0);
      mesh.rotation.y = rng() * Math.PI;
      this.baseOffsets.push(new Vector3((rng() - 0.5) * 160, 0, (rng() - 0.5) * 160));
      this.materials.push(material);
      this.group.add(mesh);
    }
  }

  update(cameraX: number, cameraZ: number, sunDir: Vector3, underwater: boolean): void {
    const strengthBase = underwater ? 0.5 : 0;
    const tiltX = (-sunDir.x / Math.max(sunDir.y, 0.2)) * 0.75;
    const tiltZ = (-sunDir.z / Math.max(sunDir.y, 0.2)) * 0.75;
    const snap = 40;
    const cx = Math.round(cameraX / snap) * snap;
    const cz = Math.round(cameraZ / snap) * snap;
    this.group.visible = underwater;
    for (let i = 0; i < this.group.children.length; i++) {
      const mesh = this.group.children[i];
      const offset = this.baseOffsets[i];
      const material = this.materials[i];
      if (!mesh || !offset || !material) continue;
      mesh.position.set(cx + offset.x, 0, cz + offset.z);
      mesh.rotation.x = tiltZ * 0.2;
      mesh.rotation.z = tiltX * 0.2;
      const strength = material.uniforms.uStrength;
      if (strength) strength.value = strengthBase * this.sunlight.value;
    }
  }

  dispose(): void {
    for (const child of this.group.children) {
      if (child instanceof Mesh) child.geometry.dispose();
    }
    for (const material of this.materials) material.dispose();
  }
}
