export type PortTheme = 'temperate' | 'tropical' | 'arctic' | 'volcanic';

/** What the harbour's crew does for the submarine while it floats at the surface (multipliers on the stock rates). */
export interface PortService {
  readonly oxygen: number;
  readonly battery: number;
  readonly hull: number;
}

export interface PortDef {
  readonly id: string;
  readonly z: number;
  readonly price: number;
  readonly theme: PortTheme;
  readonly service: PortService;
}

export const HOME_PORT_ID = 'neptune';

/** Harbours along the coast. Ids are stored in saves: never rename. */
export const PORTS: readonly PortDef[] = [
  { id: 'neptune', z: 0, price: 0, theme: 'temperate', service: { oxygen: 1, battery: 1, hull: 0 } },
  { id: 'coral-bay', z: 1100, price: 2500, theme: 'tropical', service: { oxygen: 2, battery: 1, hull: 0 } },
  { id: 'frost-point', z: -1500, price: 6500, theme: 'arctic', service: { oxygen: 1, battery: 2, hull: 0 } },
  { id: 'ember-cove', z: 2400, price: 15000, theme: 'volcanic', service: { oxygen: 1.5, battery: 1.5, hull: 1.2 } },
];

export const PORT_IDS: ReadonlySet<string> = new Set(PORTS.map((p) => p.id));

export const getPort = (id: string): PortDef => PORTS.find((p) => p.id === id) ?? (PORTS[0] as PortDef);
