import { BALANCE } from '../data/balance.ts';
import { HOME_PORT_ID, PORT_IDS, PORTS } from '../data/ports.ts';
import { POIS } from '../data/sites.ts';
import { SPECIES, type SpeciesDef } from '../data/species.ts';
import { MAX_UPGRADE_LEVEL, UPGRADES, UPGRADE_IDS, type UpgradeId } from '../data/upgrades.ts';
import { ZONES } from '../data/zones.ts';
import { MISSION_IDS, type MissionDef } from '../data/missions.ts';
import { missionCredits, newlyMet, type PhotoEvent } from './missions.ts';
import { type PhotoHistory, photoReward } from './photo.ts';
import { clampLevel, createUpgradeLevels, type UpgradeLevels } from './spec.ts';

const DISCOVERY_RARITY: Record<SpeciesDef['rarity'], number> = {
  common: 1,
  uncommon: 1.5,
  rare: 2,
  legendary: 2.5,
};
const ZONE_COMPLETE_BONUS = 1000;
const STARTING_CREDITS = 100;

export interface ProgressData {
  credits: number;
  levels: UpgradeLevels;
  discovered: Record<string, number>;
  maxDepth: number;
  zonesDone: string[];
  photos: Record<string, PhotoHistory>;
  photoEarned: number;
  missionsDone: string[];
  poisFound: string[];
  ports: string[];
  homePort: string;
  /** When the state was last changed, ms since the epoch; breaks ties when merging. */
  savedAt: number;
}

export const createProgress = (): ProgressData => ({
  credits: STARTING_CREDITS,
  levels: createUpgradeLevels(),
  discovered: {},
  maxDepth: 0,
  zonesDone: [],
  photos: {},
  photoEarned: 0,
  missionsDone: [],
  poisFound: [],
  ports: [],
  homePort: HOME_PORT_ID,
  savedAt: 0,
});

const asCount = (v: unknown): number =>
  typeof v === 'number' && Number.isFinite(v) ? Math.max(0, Math.floor(v)) : 0;

/** Turns anything read from storage into a valid state. */
export function sanitizeProgress(raw: unknown): ProgressData {
  const base = createProgress();
  if (typeof raw !== 'object' || raw === null) return base;
  const r = raw as Record<string, unknown>;
  const knownSpecies = new Set((SPECIES as readonly SpeciesDef[]).map((s) => s.id));
  const discovered: Record<string, number> = {};
  if (typeof r.discovered === 'object' && r.discovered !== null) {
    for (const [id, n] of Object.entries(r.discovered)) {
      if (knownSpecies.has(id) && asCount(n) > 0) discovered[id] = asCount(n);
    }
  }
  const levels = createUpgradeLevels();
  if (typeof r.levels === 'object' && r.levels !== null) {
    const source = r.levels as Record<string, unknown>;
    for (const id of UPGRADE_IDS) levels[id] = clampLevel(asCount(source[id]));
  }
  const photos: Record<string, PhotoHistory> = {};
  if (typeof r.photos === 'object' && r.photos !== null) {
    for (const [id, h] of Object.entries(r.photos)) {
      const x = h as Record<string, unknown> | null;
      if (knownSpecies.has(id) && x && asCount(x.count) > 0) photos[id] = { best: Math.min(100, asCount(x.best)), count: asCount(x.count) };
    }
  }
  const ports = Array.isArray(r.ports) ? [...new Set(r.ports.filter((m): m is string => typeof m === 'string' && PORT_IDS.has(m) && m !== HOME_PORT_ID))] : [];
  const zoneIds = new Set(ZONES.map((z) => z.id as string));
  const zonesDone = Array.isArray(r.zonesDone)
    ? r.zonesDone.filter((z): z is string => typeof z === 'string' && zoneIds.has(z))
    : [];
  return {
    credits: typeof r.credits === 'number' && Number.isFinite(r.credits) ? Math.max(0, Math.floor(r.credits)) : base.credits,
    levels,
    discovered,
    maxDepth: asCount(r.maxDepth),
    zonesDone,
    photos,
    photoEarned: asCount(r.photoEarned),
    missionsDone: Array.isArray(r.missionsDone) ? [...new Set(r.missionsDone.filter((m): m is string => typeof m === 'string' && MISSION_IDS.has(m)))] : [],
    poisFound: Array.isArray(r.poisFound) ? [...new Set(r.poisFound.filter((m): m is string => typeof m === 'string' && POIS.some((p) => p.id === m)))] : [],
    ports,
    homePort: typeof r.homePort === 'string' && (r.homePort === HOME_PORT_ID || ports.includes(r.homePort)) ? r.homePort : HOME_PORT_ID,
    savedAt: asCount(r.savedAt),
  };
}

/** How far a save has progressed; the merge keeps the one that is further along. */
export function progressWeight(p: Readonly<ProgressData>): number {
  let levels = 0;
  for (const id of UPGRADE_IDS) levels += p.levels[id];
  return Object.keys(p.discovered).length * 10 + Object.keys(p.photos).length * 2 + levels * 25 + Math.floor(p.maxDepth / 100) + p.zonesDone.length * 30 + p.missionsDone.length * 20 + p.poisFound.length * 15 + p.ports.length * 40;
}


export const discoveryReward = (species: SpeciesDef): number =>
  Math.round(species.value * DISCOVERY_RARITY[species.rarity] * BALANCE.photo.discoveryMultiplier);

export const zoneOfSpecies = (species: SpeciesDef) =>
  ZONES.find((z) => species.depth[0] < z.toM) ?? ZONES[ZONES.length - 1];

export const zoneBonus = (zoneIndex: number): number => ZONE_COMPLETE_BONUS * (zoneIndex + 1);

function mergePhotos(a: Record<string, PhotoHistory>, b: Record<string, PhotoHistory>): Record<string, PhotoHistory> {
  const out: Record<string, PhotoHistory> = { ...a };
  for (const [id, h] of Object.entries(b)) {
    const mine = out[id];
    out[id] = mine ? { best: Math.max(mine.best, h.best), count: Math.max(mine.count, h.count) } : { ...h };
  }
  return out;
}

/** What the credits should be if only the game's own rules had ever changed them. */
export function ruleCredits(p: Readonly<ProgressData>): number {
  let total = STARTING_CREDITS;
  for (const id of Object.keys(p.discovered)) {
    const species = (SPECIES as readonly SpeciesDef[]).find((s) => s.id === id);
    if (species) total += discoveryReward(species);
  }
  for (const zoneId of p.zonesDone) {
    const index = ZONES.findIndex((z) => z.id === zoneId);
    if (index >= 0) total += zoneBonus(index);
  }
  total += p.photoEarned;
  total += missionCredits(p.missionsDone);
  for (const port of PORTS) if (p.ports.includes(port.id)) total -= port.price;
  for (const poi of POIS) if (p.poisFound.includes(poi.id)) total += poi.reward;
  total += Math.floor(p.maxDepth / BALANCE.depthRecord.stepM) * Math.round(BALANCE.depthRecord.stepM * BALANCE.depthRecord.creditsPerMetre * 10);
  for (const id of UPGRADE_IDS) {
    for (let level = 0; level < p.levels[id]; level++) total -= UPGRADES[id].costs[level] ?? 0;
  }
  return total;
}

/**
 * Combines two saves of the same player (this device and the cloud). Discoveries, depth record
 * and the best level of every upgrade are kept from both, and the credits are recomputed from
 * those, so nothing earned on either side is lost and nothing is paid for twice.
 */
export function mergeProgress(a: Readonly<ProgressData>, b: Readonly<ProgressData>): ProgressData {
  const wa = progressWeight(a);
  const wb = progressWeight(b);
  const base = wa > wb || (wa === wb && a.savedAt >= b.savedAt) ? a : b;
  const discovered: Record<string, number> = { ...a.discovered };
  for (const [id, n] of Object.entries(b.discovered)) discovered[id] = Math.max(n, discovered[id] ?? 0);
  const levels = createUpgradeLevels();
  for (const id of UPGRADE_IDS) levels[id] = Math.max(a.levels[id], b.levels[id]);
  const merged: ProgressData = {
    credits: 0,
    levels,
    discovered,
    maxDepth: Math.max(a.maxDepth, b.maxDepth),
    zonesDone: [...new Set([...a.zonesDone, ...b.zonesDone])],
    photos: mergePhotos(a.photos, b.photos),
    photoEarned: Math.max(a.photoEarned, b.photoEarned),
    missionsDone: [...new Set([...a.missionsDone, ...b.missionsDone])],
    poisFound: [...new Set([...a.poisFound, ...b.poisFound])],
    ports: [...new Set([...a.ports, ...b.ports])],
    homePort: [...a.ports, ...b.ports].includes(base.homePort) || base.homePort === HOME_PORT_ID ? base.homePort : HOME_PORT_ID,
    savedAt: Math.max(a.savedAt, b.savedAt),
  };
  const outside = base.credits - ruleCredits(base);
  merged.credits = Math.max(0, ruleCredits(merged) + outside);
  return merged;
}


export interface DiscoveryResult {
  species: SpeciesDef;
  isNew: boolean;
  credits: number;
  zoneCompleted: { id: string; bonus: number } | null;
}

export interface UpgradeOffer {
  id: UpgradeId;
  level: number;
  cost: number | null;
  affordable: boolean;
}

type Listener = (data: Readonly<ProgressData>) => void;
type Discovery = (result: DiscoveryResult) => void;
type MissionListener = (mission: MissionDef) => void;

export interface ProgressStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export const STORAGE_KEY = 'luminara.progress';

/** Player progression: bestiary discoveries, credits, bought upgrades and depth record. */
export class ProgressStore {
  private data: ProgressData;
  private readonly storage: ProgressStorage | null;
  private key: string;
  private readonly listeners = new Set<Listener>();
  private readonly discoverListeners = new Set<Discovery>();
  private readonly missionListeners = new Set<MissionListener>();

  constructor(storage: ProgressStorage | null = null, key: string = STORAGE_KEY) {
    this.storage = storage;
    this.key = key;
    this.data = sanitizeProgress(this.load());
  }

  get currentKey(): string {
    return this.key;
  }

  get value(): Readonly<ProgressData> {
    return this.data;
  }

  get levels(): Readonly<UpgradeLevels> {
    return this.data.levels;
  }

  isDiscovered(id: string): boolean {
    return (this.data.discovered[id] ?? 0) > 0;
  }

  discoveredCount(): number {
    return Object.keys(this.data.discovered).length;
  }

  discover(species: SpeciesDef): DiscoveryResult {
    const seen = this.data.discovered[species.id] ?? 0;
    this.data.discovered[species.id] = seen + 1;
    if (seen > 0) {
      this.save();
      return { species, isNew: false, credits: 0, zoneCompleted: null };
    }
    let credits = discoveryReward(species);
    let zoneCompleted: DiscoveryResult['zoneCompleted'] = null;
    const zone = zoneOfSpecies(species);
    if (zone && !this.data.zonesDone.includes(zone.id)) {
      const members = (SPECIES as readonly SpeciesDef[]).filter((s) => zoneOfSpecies(s)?.id === zone.id);
      if (members.every((s) => this.isDiscovered(s.id))) {
        const bonus = zoneBonus(ZONES.indexOf(zone));
        this.data.zonesDone.push(zone.id);
        credits += bonus;
        zoneCompleted = { id: zone.id, bonus };
      }
    }
    this.data.credits += credits;
    const result = { species, isNew: true, credits, zoneCompleted };
    this.save();
    this.emit();
    for (const l of this.discoverListeners) l(result);
    this.settleMissions();
    return result;
  }

  recordDepth(depth: number): number {
    const { stepM, creditsPerMetre } = BALANCE.depthRecord;
    const steps = Math.floor(depth / stepM) - Math.floor(this.data.maxDepth / stepM);
    this.data.maxDepth = Math.max(this.data.maxDepth, Math.floor(depth));
    if (steps <= 0) return 0;
    const earned = Math.round(steps * stepM * creditsPerMetre * 10);
    this.data.credits += earned;
    this.save();
    this.emit();
    this.settleMissions();
    return earned;
  }

  recordPhoto(species: SpeciesDef, score: number, depth = 0): { reward: number; first: boolean; newBest: boolean } {
    const before = this.data.photos[species.id];
    const reward = photoReward(species, score, before);
    const first = before === undefined;
    const newBest = before === undefined || score > before.best;
    this.data.photos[species.id] = { best: Math.max(score, before?.best ?? 0), count: (before?.count ?? 0) + 1 };
    this.data.credits += reward;
    this.data.photoEarned += reward;
    this.save();
    this.emit();
    this.settleMissions({ species, score, depth });
    return { reward, first, newBest };
  }

  private settleMissions(photo?: PhotoEvent): void {
    const met = newlyMet(this.data, photo);
    if (met.length === 0) return;
    for (const m of met) {
      this.data.missionsDone.push(m.id);
      this.data.credits += m.reward;
    }
    this.save();
    this.emit();
    for (const m of met) for (const l of this.missionListeners) l(m);
  }

  ownsPort(id: string): boolean {
    return id === HOME_PORT_ID || this.data.ports.includes(id);
  }

  /** Buys a harbour; false when it is already owned, unknown or too expensive. */
  buyPort(id: string): boolean {
    const port = PORTS.find((p) => p.id === id);
    if (!port || this.ownsPort(id) || this.data.credits < port.price) return false;
    this.data.credits -= port.price;
    this.data.ports.push(id);
    this.save();
    this.emit();
    return true;
  }

  setHomePort(id: string): boolean {
    if (!this.ownsPort(id)) return false;
    this.data.homePort = id;
    this.save();
    this.emit();
    return true;
  }

  isPoiFound(id: string): boolean {
    return this.data.poisFound.includes(id);
  }

  discoverPoi(id: string): { id: string; reward: number } | null {
    const poi = POIS.find((p) => p.id === id);
    if (!poi || this.isPoiFound(id)) return null;
    this.data.poisFound.push(id);
    this.data.credits += poi.reward;
    this.save();
    this.emit();
    this.settleMissions();
    return { id: poi.id, reward: poi.reward };
  }

  isMissionDone(id: string): boolean {
    return this.data.missionsDone.includes(id);
  }

  onMission(listener: MissionListener): () => void {
    this.missionListeners.add(listener);
    return () => this.missionListeners.delete(listener);
  }

  offer(id: UpgradeId): UpgradeOffer {
    const level = this.data.levels[id];
    const cost = level >= MAX_UPGRADE_LEVEL ? null : (UPGRADES[id].costs[level] ?? null);
    return { id, level, cost, affordable: cost !== null && this.data.credits >= cost };
  }

  /** Buys the next level of an upgrade; false when maxed out or too expensive. */
  purchase(id: UpgradeId): boolean {
    const offer = this.offer(id);
    if (offer.cost === null || !offer.affordable) return false;
    this.data.credits -= offer.cost;
    this.data.levels[id] = offer.level + 1;
    this.save();
    this.emit();
    return true;
  }

  switchKey(key: string): void {
    this.key = key;
    this.data = sanitizeProgress(this.load());
    this.emit();
  }

  replace(data: ProgressData): void {
    this.data = sanitizeProgress(data);
    this.save();
    this.emit();
  }

  snapshot(): ProgressData {
    return sanitizeProgress(JSON.parse(JSON.stringify(this.data)));
  }

  addCredits(amount: number): void {
    this.data.credits = Math.max(0, this.data.credits + Math.round(amount));
    this.save();
    this.emit();
  }

  reset(): void {
    this.data = createProgress();
    this.save();
    this.emit();
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  onDiscover(listener: Discovery): () => void {
    this.discoverListeners.add(listener);
    return () => this.discoverListeners.delete(listener);
  }

  private emit(): void {
    for (const l of this.listeners) l(this.data);
  }

  private load(): unknown {
    try {
      const text = this.storage?.getItem(this.key);
      return text ? JSON.parse(text) : null;
    } catch {
      return null;
    }
  }

  private save(): void {
    try {
      this.data.savedAt = Date.now();
      this.storage?.setItem(this.key, JSON.stringify(this.data));
    } catch {
    }
  }
}
