import {
  BufferAttribute,
  type BufferGeometry,
  Color,
  CylinderGeometry,
  Euler,
  Matrix4,
  Quaternion,
  ShaderMaterial,
  Vector3,
} from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { COMMON_UNIFORMS, LIGHTING_GLSL, NOISE_GLSL } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

export interface PartOptions {
  pos?: readonly [number, number, number];
  rot?: readonly [number, number, number];
  scale?: readonly [number, number, number] | number;
  emit?: number;
  slime?: number;
  jitter?: number;
}

/** Adds a cylinder running between two points (branches, bones, masts...). */
export function addLimb(b: PropBuilder, a: Vector3, c: Vector3, r0: number, r1: number, color: number): void {
  const dir = new Vector3().subVectors(c, a);
  const len = dir.length();
  if (len < 1e-4) return;
  const q = new Quaternion().setFromUnitVectors(new Vector3(0, 1, 0), dir.normalize());
  const e = new Euler().setFromQuaternion(q);
  const mid = new Vector3().addVectors(a, c).multiplyScalar(0.5);
  b.add(new CylinderGeometry(r1, r0, len, 7), color, { pos: [mid.x, mid.y, mid.z], rot: [e.x, e.y, e.z], jitter: 0.08 });
}

const hash = (n: number): number => {
  const s = Math.sin(n * 12.9898) * 43758.5453;
  return s - Math.floor(s);
};

/** Collects primitives into one vertex-coloured mesh so a whole landmark is a single draw call. */
export class PropBuilder {
  private readonly parts: BufferGeometry[] = [];
  private counter = 0;

  add(geometry: BufferGeometry, color: number, options: PartOptions = {}): this {
    const g = geometry.index ? geometry.toNonIndexed() : geometry.clone();
    g.deleteAttribute('uv');
    const s = options.scale ?? 1;
    const scale = typeof s === 'number' ? new Vector3(s, s, s) : new Vector3(s[0], s[1], s[2]);
    const rot = options.rot ?? [0, 0, 0];
    const pos = options.pos ?? [0, 0, 0];
    const m = new Matrix4().compose(
      new Vector3(pos[0], pos[1], pos[2]),
      new Quaternion().setFromEuler(new Euler(rot[0], rot[1], rot[2])),
      scale,
    );
    g.applyMatrix4(m);
    const n = g.getAttribute('position').count;
    const c = new Color(color);
    const j = 1 + ((hash(++this.counter) - 0.5) * 2 * (options.jitter ?? 0.12));
    const colors = new Float32Array(n * 3);
    const emit = new Float32Array(n);
    const slime = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      colors[i * 3] = c.r * j;
      colors[i * 3 + 1] = c.g * j;
      colors[i * 3 + 2] = c.b * j;
      emit[i] = options.emit ?? 0;
      slime[i] = options.slime ?? 0;
    }
    g.setAttribute('color', new BufferAttribute(colors, 3));
    g.setAttribute('emit', new BufferAttribute(emit, 1));
    g.setAttribute('slime', new BufferAttribute(slime, 1));
    this.parts.push(g);
    return this;
  }

  addRaw(geometry: BufferGeometry, color: number, options: PartOptions = {}): this {
    return this.add(geometry, color, options);
  }

  build(): BufferGeometry {
    const merged = mergeGeometries(this.parts, false);
    if (!merged) throw new Error('PropBuilder: nothing to merge');
    for (const p of this.parts) p.dispose();
    merged.computeBoundingSphere();
    return merged;
  }
}

const vertexShader = /* glsl */ `
attribute vec3 color;
attribute float emit;
attribute float slime;
varying float vSlime;
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying vec3 vColor;
varying float vEmit;

void main() {
  vec4 wp = modelMatrix * vec4(position, 1.0);
  vWorldPos = wp.xyz;
  vNormalW = normalize(mat3(modelMatrix) * normal);
  vColor = color;
  vEmit = emit;
  vSlime = slime;
  gl_Position = projectionMatrix * viewMatrix * wp;
}
`;

const fragmentShader = /* glsl */ `
${COMMON_UNIFORMS}
${NOISE_GLSL}
${LIGHTING_GLSL}
uniform float uGrowth;
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying vec3 vColor;
varying float vEmit;
varying float vSlime;

void main() {
  vec3 N = safeNormalize(vNormalW, vec3(0.0, 1.0, 0.0));
  if (!gl_FrontFacing) N = -N;
  float n = fbm(vWorldPos.xz * 0.55 + vWorldPos.y * 0.9);
  float fine = vnoise(vWorldPos.xz * 3.1 + vWorldPos.y * 2.3);
  vec3 albedo = vColor * (0.55 + 0.7 * n) * (0.85 + 0.3 * fine);
  // Algae and silt settle on upward-facing surfaces.
  float growth = smoothstep(0.25, 0.9, N.y) * smoothstep(0.35, 0.7, n) * uGrowth;
  albedo = mix(albedo, vec3(0.24, 0.3, 0.17), growth * 0.7);
  // Wet wood and steel are darker; algae and barnacles cling to everything near and below the waterline.
  float wet = smoothstep(0.9, -0.2, vWorldPos.y);
  albedo *= 1.0 - 0.22 * wet;
  float slimeAmt = vSlime * smoothstep(1.3, -0.3, vWorldPos.y) * (1.0 - 0.55 * smoothstep(-2.0, -14.0, vWorldPos.y));
  vec3 algae = vec3(0.12, 0.26, 0.1) * (0.6 + 1.0 * fbm(vWorldPos.xz * 1.6 + vWorldPos.y * 2.0));
  albedo = mix(albedo, algae, clamp(slimeAmt, 0.0, 1.0) * 0.8);
  float barnacle = step(0.72, vnoise(vWorldPos.xz * 8.0 + vWorldPos.y * 6.0)) * slimeAmt;
  albedo = mix(albedo, vec3(0.55, 0.55, 0.5), barnacle * 0.7);
  vec3 col = shadeUnderwater(albedo, N, vWorldPos);
  float dist = length(vWorldPos - uCamPos);
  // Above the water the sky fills in the shadows that the low sun leaves dark.
  vec3 sky = vec3(0.17, 0.2, 0.27) * smoothstep(-1.0, 0.6, vWorldPos.y) * (0.45 + 0.55 * N.y);
  col += albedo * sky * exp(-uFogDensity * dist);
  vec3 glow = vColor * vEmit * 2.2;
  col += mix(vec3(0.0), glow, exp(-uFogDensity * dist * 0.5));
  gl_FragColor = vec4(sanitize(col, uFogColor), 1.0);
}
`;

/** Material for landmarks: vertex colours, mottled rust/silt, headlight and fog like the seabed. */
export function createPropMaterial(uniforms: SceneUniforms, growth = 1): ShaderMaterial {
  return new ShaderMaterial({
    uniforms: {
      uTime: uniforms.uTime,
      uSunDir: uniforms.uSunDir,
      uSunColor: uniforms.uSunColor,
      uFogColor: uniforms.uFogColor,
      uFogDensity: uniforms.uFogDensity,
      uCamPos: uniforms.uCamPos,
      uSunlight: uniforms.uSunlight,
      uPixelRatio: uniforms.uPixelRatio,
      uBeamPos: uniforms.uBeamPos,
      uBeamDir: uniforms.uBeamDir,
      uBeamParams: uniforms.uBeamParams,
      uGrowth: { value: growth },
    },
    vertexShader,
    fragmentShader,
    fog: false,
  });
}
