import { createMonotoneCurve } from '../core/curve.ts';
import { smoothstep } from '../core/math.ts';
import { fbm2 } from '../core/noise.ts';
import { PORTS, type PortDef } from '../data/ports.ts';

export const WORLD_BOUNDS = { minX: -1200, maxX: 17000, minZ: -3000, maxZ: 3000 } as const;

/** Where the Challenger-style trench cuts across the plain. */
export const TRENCH_CENTER_X = 14500;
const TRENCH_HALF_WIDTH = 3200;
const TRENCH_DEPTH = 5900;
const SEED = 1337;

const PROFILE = createMonotoneCurve([
  [-1200, 60],
  [-700, 32],
  [-313, 0],
  [-240, -12],
  [-100, -30],
  [200, -52],
  [600, -80],
  [1000, -110],
  [1400, -150],
  [1700, -260],
  [2200, -520],
  [2800, -900],
  [3600, -1500],
  [4600, -2300],
  [5800, -3200],
  [7000, -3900],
  [8200, -4400],
  [9500, -4750],
  [11000, -4950],
  [14000, -5000],
  [17000, -5000],
]);

/** The levelled harbour platform: a flat quay at deck height, cut into the hillside. */
export const HARBOUR = { x0: -340, x1: -298, z0: -40, z1: 40, level: 2.4 } as const;

function coastShift(z: number): number {
  return (fbm2(z * 0.0035, 0.5, 3, SEED) - 0.5) * 240 * smoothstep(0, 500, Math.abs(z));
}

/** Where a port sits in the world: its levelled platform is the home harbour moved along the coast. */
export interface PortPlacement {
  readonly port: PortDef;
  readonly dx: number;
  readonly dz: number;
}

export const PORT_PLACEMENTS: readonly PortPlacement[] = PORTS.map((port) => ({ port, dx: -coastShift(port.z), dz: port.z }));

export const placementOf = (id: string): PortPlacement => PORT_PLACEMENTS.find((p) => p.port.id === id) ?? (PORT_PLACEMENTS[0] as PortPlacement);

function applyHarbours(x: number, z: number, height: number): number {
  let h = height;
  for (const p of PORT_PLACEMENTS) {
    if (Math.abs(z - p.dz) > 80 || x < p.dx - 420 || x > p.dx + 60) continue;
    h = applyHarbour(x - p.dx, z - p.dz, h);
  }
  return h;
}

function applyHarbour(x: number, z: number, height: number): number {
  const { x0, x1, z0, z1, level } = HARBOUR;
  const seaward = x > x1;
  const dx = x < x0 ? x0 - x : seaward ? x - x1 : 0;
  const dz = z < z0 ? z0 - z : z > z1 ? z - z1 : 0;
  const wx = 1 - smoothstep(0, seaward ? 1.2 : 26, dx);
  const wz = 1 - smoothstep(0, 16, dz);
  const w = wx * wz;
  return height + (level - height) * w;
}

/** Anything that can answer "how high is the seabed here?". */
export interface WorldQuery {
  seabedY(x: number, z: number): number;
}

export function seabedY(x: number, z: number): number {
  const coast = coastShift(z);
  const xs = x + coast;

  const base = PROFILE(xs);
  const trench = 1 - smoothstep(0, TRENCH_HALF_WIDTH, Math.abs(x - TRENCH_CENTER_X));
  let height = base - TRENCH_DEPTH * trench;

  const inland = smoothstep(-5, 10, base);
  height += inland * fbm2(x * 0.004, z * 0.004, 4, SEED + 3) * 42;

  const underwater = 1 - inland;
  const reefBelt = Math.exp(-(((x - 600) / 700) ** 2));
  const slopeRough = smoothstep(1500, 7000, x) * (1 - 0.85 * trench);
  const amplitude = 1.2 + 14 * reefBelt + 34 * slopeRough;
  const coarse = fbm2(x * 0.011, z * 0.011, 4, SEED + 7) - 0.5;
  const fine = fbm2(x * 0.05, z * 0.05, 2, SEED + 11) - 0.5;
  height += underwater * (coarse * 2 * amplitude + fine * 0.3 * amplitude);

  return applyHarbours(x, z, height);
}

export const world: WorldQuery = { seabedY };

/** Slope angle (radians) of the seabed around a point, sampled with central differences. */
export function seabedSlope(x: number, z: number, step = 4): number {
  const dx = (seabedY(x + step, z) - seabedY(x - step, z)) / (2 * step);
  const dz = (seabedY(x, z + step) - seabedY(x, z - step)) / (2 * step);
  return Math.atan(Math.hypot(dx, dz));
}
