import { BufferAttribute, type BufferGeometry, Mesh, ShaderMaterial } from 'three';
import { clamp, smoothstep } from '../core/math.ts';
import { fbm2 } from '../core/noise.ts';
import type { WorldQuery } from '../domain/world.ts';
import { createPolarGrid, type PolarGrid } from './polar-grid.ts';
import { CAUSTICS_GLSL, COMMON_UNIFORMS, NOISE_GLSL, SAFE_GLSL } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

const vertexShader = /* glsl */ `
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying vec3 vColor;

void main() {
  vWorldPos = position;
  vNormalW = normal;
  vColor = color;
  gl_Position = projectionMatrix * viewMatrix * vec4(position, 1.0);
}
`;

const fragmentShader = /* glsl */ `
${COMMON_UNIFORMS}
${NOISE_GLSL}
${CAUSTICS_GLSL}
${SAFE_GLSL}
uniform vec3 uBeamPos;
uniform vec3 uBeamDir;
uniform vec3 uBeamParams;
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying vec3 vColor;

/** Micro relief: sand ripples on gentle slopes, grit and pebbles everywhere. */
float detailHeight(vec2 p, float sandy) {
  vec2 w = p + vec2(vnoise(p * 0.35), vnoise(p * 0.35 + 7.0)) * 2.6;
  float crest = 1.0 - abs(sin(dot(w, vec2(0.92, 0.39)) * 2.3));
  crest *= crest;
  float grit = vnoise(p * 6.5) * 0.6 + vnoise(p * 17.0) * 0.4;
  float pebbles = smoothstep(0.62, 0.9, vnoise(p * 3.1 + 11.0));
  return mix(grit * 0.5 + pebbles * 0.8, crest * 0.55 + grit * 0.2, sandy);
}

void main() {
  vec3 N = safeNormalize(vNormalW, vec3(0.0, 1.0, 0.0));
  float depth = max(0.0, -vWorldPos.y);
  float camDist = length(vWorldPos - uCamPos);

  // Ripples live on gentle sandy slopes; steep or deep ground stays rough and muddy.
  float sandy = smoothstep(0.75, 0.95, N.y) * (1.0 - smoothstep(250.0, 1400.0, depth));
  float fade = 1.0 - smoothstep(35.0, 150.0, camDist);
  vec2 q = vWorldPos.xz;
  float e = 0.1;
  float h0 = detailHeight(q, sandy);
  float hx = detailHeight(q + vec2(e, 0.0), sandy);
  float hz = detailHeight(q + vec2(0.0, e), sandy);
  vec3 bump = vec3(-(hx - h0), 0.0, -(hz - h0)) / e;
  N = safeNormalize(N + bump * 0.32 * fade, vec3(0.0, 1.0, 0.0));

  float detail = vnoise(vWorldPos.xz * 0.6) * 0.5 + vnoise(vWorldPos.xz * 2.3) * 0.5;
  vec3 albedo = vColor * (0.78 + 0.44 * detail);
  albedo *= mix(1.0, 0.72 + 0.55 * h0, fade);
  float speck = step(0.9, vnoise(q * 21.0)) * fade;
  albedo = mix(albedo, albedo * vec3(1.35, 1.3, 1.2), speck * 0.5);

  vec3 absorb = exp(-vec3(0.28, 0.06, 0.033) * depth);

  float sunDiff = max(dot(N, uSunDir), 0.0);
  vec3 sun = uSunColor * sunDiff * absorb;
  float underwater = step(vWorldPos.y, 0.0);
  float caust = caustics(vWorldPos.xz * 0.28, uTime);
  sun *= 1.0 + caust * 2.4 * underwater * exp(-depth * 0.035);

  vec3 ambient = vec3(0.10, 0.16, 0.24) * absorb * (0.55 + 0.45 * N.y) + vec3(0.0015, 0.003, 0.005);

  // Headlight cone.
  vec3 fromLamp = vWorldPos - uBeamPos;
  float lampDist = length(fromLamp);
  vec3 L = fromLamp / max(lampDist, 0.001);
  float cone = smoothstep(uBeamParams.y, uBeamParams.y + 0.1, dot(L, uBeamDir));
  float reach = 1.0 - smoothstep(uBeamParams.x * 0.3, uBeamParams.x, lampDist);
  float falloff = 1.0 / (1.0 + 0.0012 * lampDist * lampDist);
  vec3 beam = vec3(0.85, 0.96, 1.0) * uBeamParams.z * cone * reach * falloff * max(dot(N, -L), 0.0);

  vec3 lit = albedo * (sun + ambient + beam);

  float dist = length(vWorldPos - uCamPos);
  vec3 col = mix(uFogColor, lit, exp(-uFogDensity * dist));
  gl_FragColor = vec4(sanitize(col, uFogColor), 1.0);
}
`;

/** Linear-space colour of the ground for a given height, slope (normal.y) and noise sample. */
export function seabedColor(
  height: number,
  normalY: number,
  noise: number,
  out: [number, number, number],
): void {
  const rock = clamp((0.82 - normalY) * 4);
  let r: number;
  let g: number;
  let b: number;

  if (height > 1) {
    const grass = smoothstep(2, 14, height);
    r = 0.55 + (0.09 - 0.55) * grass;
    g = 0.45 + (0.17 - 0.45) * grass;
    b = 0.28 + (0.06 - 0.28) * grass;
  } else {
    const depth = -height;
    const mud = smoothstep(120, 900, depth);
    const abyss = smoothstep(900, 4500, depth);
    r = 0.42 + (0.15 - 0.42) * mud + (0.075 - 0.15) * abyss;
    g = 0.36 + (0.14 - 0.36) * mud + (0.072 - 0.14) * abyss;
    b = 0.24 + (0.12 - 0.24) * mud + (0.075 - 0.12) * abyss;
  }

  const shade = 0.82 + 0.36 * noise;
  r = (r + (0.14 - r) * rock * 0.8) * shade;
  g = (g + (0.13 - g) * rock * 0.8) * shade;
  b = (b + (0.12 - b) * rock * 0.8) * shade;
  out[0] = r;
  out[1] = g;
  out[2] = b;
}

const SLICE = 1024;

interface RebuildJob {
  readonly cx: number;
  readonly cz: number;
  next: number;
}

/**
 * The seafloor and the island: a polar-grid mesh re-sampled from the world function around
 * the camera. Once the focus has drifted far enough that the dense inner rings are no longer
 * under the player, new heights are computed in the background over several frames (within a
 * small per-frame time budget) and swapped in at once, so travelling never stutters.
 */
export class Seabed {
  readonly mesh: Mesh;
  private readonly world: WorldQuery;
  private readonly grid: PolarGrid;
  private readonly geometry: BufferGeometry;
  private readonly staging: Float32Array;
  private centerX = Number.NaN;
  private centerZ = Number.NaN;
  private job: RebuildJob | null = null;

  constructor(world: WorldQuery, uniforms: SceneUniforms, rings: number) {
    this.world = world;
    this.grid = createPolarGrid({
      rings,
      segments: Math.round(rings * 2.4),
      radius: 4500,
      growth: 6.5,
    });
    this.geometry = this.grid.geometry;
    this.staging = new Float32Array(this.grid.vertexCount);
    this.geometry.setAttribute(
      'normal',
      new BufferAttribute(new Float32Array(this.grid.vertexCount * 3), 3),
    );
    this.geometry.setAttribute(
      'color',
      new BufferAttribute(new Float32Array(this.grid.vertexCount * 3), 3),
    );

    const material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
        uBeamPos: uniforms.uBeamPos,
        uBeamDir: uniforms.uBeamDir,
        uBeamParams: uniforms.uBeamParams,
      },
      vertexShader,
      fragmentShader,
      vertexColors: true,
      fog: false,
    });
    this.mesh = new Mesh(this.geometry, material);
    this.mesh.frustumCulled = false;
  }

  update(x: number, z: number, threshold = 50, budgetMs = 3): void {
    if (!Number.isFinite(this.centerX)) {
      this.job = { cx: x, cz: z, next: 0 };
      this.advance(Number.POSITIVE_INFINITY);
      return;
    }
    if (!this.job && Math.hypot(x - this.centerX, z - this.centerZ) >= threshold) {
      this.job = { cx: x, cz: z, next: 0 };
    }
    if (this.job) this.advance(budgetMs);
  }

  private advance(budgetMs: number): void {
    const job = this.job;
    if (!job) return;
    const { offsets, vertexCount } = this.grid;
    const start = performance.now();
    while (job.next < vertexCount) {
      const end = Math.min(vertexCount, job.next + SLICE);
      for (let v = job.next; v < end; v++) {
        this.staging[v] = this.world.seabedY(
          job.cx + (offsets[v * 2] ?? 0),
          job.cz + (offsets[v * 2 + 1] ?? 0),
        );
      }
      job.next = end;
      if (performance.now() - start > budgetMs) return;
    }
    this.commit(job);
    this.job = null;
  }

  private commit(job: RebuildJob): void {
    this.centerX = job.cx;
    this.centerZ = job.cz;
    const position = this.geometry.getAttribute('position') as BufferAttribute;
    const color = this.geometry.getAttribute('color') as BufferAttribute;
    const { offsets, vertexCount } = this.grid;

    for (let v = 0; v < vertexCount; v++) {
      position.setXYZ(
        v,
        job.cx + (offsets[v * 2] ?? 0),
        this.staging[v] ?? 0,
        job.cz + (offsets[v * 2 + 1] ?? 0),
      );
    }
    position.needsUpdate = true;
    this.geometry.computeVertexNormals();

    const normal = this.geometry.getAttribute('normal') as BufferAttribute;
    // Degenerate triangles (e.g. at the grid centre) can leave a non-finite normal behind;
    // a single NaN would turn into a black square once bloom smears it.
    for (let v = 0; v < vertexCount; v++) {
      if (
        !Number.isFinite(normal.getX(v)) ||
        !Number.isFinite(normal.getY(v)) ||
        !Number.isFinite(normal.getZ(v))
      ) {
        normal.setXYZ(v, 0, 1, 0);
      }
    }
    const rgb: [number, number, number] = [0, 0, 0];
    for (let v = 0; v < vertexCount; v++) {
      const wx = job.cx + (offsets[v * 2] ?? 0);
      const wz = job.cz + (offsets[v * 2 + 1] ?? 0);
      seabedColor(this.staging[v] ?? 0, normal.getY(v), fbm2(wx * 0.02, wz * 0.02, 2, 91), rgb);
      const finite = Number.isFinite(rgb[0] + rgb[1] + rgb[2]);
      color.setXYZ(v, finite ? rgb[0] : 0.3, finite ? rgb[1] : 0.3, finite ? rgb[2] : 0.25);
    }
    color.needsUpdate = true;
  }

  dispose(): void {
    this.geometry.dispose();
    (this.mesh.material as ShaderMaterial).dispose();
  }
}
