import { content as contentEn } from './content-en.ts';
import { content as contentRu } from './content-ru.ts';
import { content as contentUk } from './content-uk.ts';
import { en, type UiKey } from './en.ts';
import { ru } from './ru.ts';
import { uk } from './uk.ts';

export type Lang = 'en' | 'ru' | 'uk';
export type { UiKey };

export const LANGS: ReadonlyArray<{ readonly id: Lang; readonly label: string }> = [
  { id: 'en', label: 'English' },
  { id: 'ru', label: 'Русский' },
  { id: 'uk', label: 'Українська' },
];

export const DEFAULT_LANG: Lang = 'en';

const UI: Record<Lang, Readonly<Record<string, string>>> = { en, ru, uk };
const CONTENT: Record<Lang, Readonly<Record<string, string>>> = { en: contentEn, ru: contentRu, uk: contentUk };
const NUMBER_LOCALE: Record<Lang, string> = { en: 'en-US', ru: 'ru-RU', uk: 'uk-UA' };

let current: Lang = DEFAULT_LANG;
const listeners = new Set<(lang: Lang) => void>();

export const isLang = (value: unknown): value is Lang => value === 'en' || value === 'ru' || value === 'uk';

export const getLang = (): Lang => current;

export function setLang(lang: Lang): void {
  if (lang === current) return;
  current = lang;
  if (typeof document !== 'undefined') document.documentElement.lang = lang;
  for (const l of listeners) l(lang);
}

/** Calls `listener` whenever the language changes. Returns an unsubscribe function. */
export function onLangChange(listener: (lang: Lang) => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function fill(text: string, vars?: Readonly<Record<string, string | number>>): string {
  if (!vars) return text;
  return text.replace(/\{(\w+)\}/g, (whole, name: string) => {
    const v = vars[name];
    return v === undefined ? whole : String(v);
  });
}

/** Interface text; `{name}` placeholders are filled from `vars`. */
export function t(key: UiKey, vars?: Readonly<Record<string, string | number>>): string {
  return fill(UI[current][key] ?? en[key] ?? key, vars);
}

/** Text of game content (species, zones, upgrades, ...), looked up by a dotted key such as `species.tuna.name`. */
export function content(key: string): string {
  return CONTENT[current][key] ?? contentEn[key] ?? key;
}

/** Formats a number with the thousands separators of the current language. */
export function num(value: number, digits = 0): string {
  return value.toLocaleString(NUMBER_LOCALE[current], { maximumFractionDigits: digits, minimumFractionDigits: digits });
}
