import { mergeProgress, type ProgressData, type ProgressStore, STORAGE_KEY } from '../domain/progress.ts';
import type { AuthClient, Session } from './auth.ts';
import { type CloudProgress, CloudRejected } from './cloud.ts';

export type SyncStatus = 'guest' | 'syncing' | 'saved' | 'error' | 'rejected';

type Listener = (status: SyncStatus) => void;

/** Local save slot of each account, so two accounts on one browser never mix. */
export const userKey = (userId: string): string => `${STORAGE_KEY}.${userId}`;

const RETRY_MS = 20_000;

export interface SyncTimers {
  set(fn: () => void, ms: number): unknown;
  clear(handle: unknown): void;
}

const REAL_TIMERS: SyncTimers = {
  set: (fn, ms) => setTimeout(fn, ms),
  clear: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
};

/**
 * Keeps the local progress and the cloud save in step. Signed out, the game uses the guest slot.
 * Signing in merges this browser's cache of the account with the cloud copy; every change is
 * sent to the cloud a few seconds later (or at once when the tab is hidden).
 */
export class ProgressSync {
  private current: SyncStatus = 'guest';
  private readonly listeners = new Set<Listener>();
  private pending: unknown = null;
  private dirty = false;
  private generation = 0;
  private loading = false;
  private synced = false;
  private retryHandle: unknown = null;
  private activeUser: string | null = null;
  private readonly progress: ProgressStore;
  private readonly auth: AuthClient;
  private readonly cloud: CloudProgress;
  private readonly debounceMs: number;
  private readonly timers: SyncTimers;

  constructor(
    progress: ProgressStore,
    auth: AuthClient,
    cloud: CloudProgress,
    debounceMs = 4000,
    timers: SyncTimers = REAL_TIMERS,
  ) {
    this.progress = progress;
    this.auth = auth;
    this.cloud = cloud;
    this.debounceMs = debounceMs;
    this.timers = timers;
  }

  get status(): SyncStatus {
    return this.current;
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  start(): void {
    this.auth.subscribe((session) => {
      if ((session?.user.id ?? null) === this.activeUser) return;
      void this.onSession(session);
    });
    this.progress.subscribe(() => this.onLocalChange());
    void this.onSession(this.auth.session);
  }

  retry(): void {
    void this.onSession(this.auth.session);
  }

  async flush(keepalive = false): Promise<void> {
    if (this.pending !== null) {
      this.timers.clear(this.pending);
      this.pending = null;
    }
    if (!this.auth.session || !this.synced || !this.dirty) return;
    await this.push(keepalive);
  }

  private async onSession(session: Session | null): Promise<void> {
    const generation = ++this.generation;
    this.activeUser = session?.user.id ?? null;
    this.loading = session !== null;
    this.synced = false;
    if (this.retryHandle !== null) {
      this.timers.clear(this.retryHandle);
      this.retryHandle = null;
    }
    if (this.pending !== null) {
      this.timers.clear(this.pending);
      this.pending = null;
    }
    this.dirty = false;
    if (!session) {
      this.progress.switchKey(STORAGE_KEY);
      this.setStatus('guest');
      return;
    }
    const guest = this.progress.snapshot();
    const hadGuestSlot = this.progress.currentKey === STORAGE_KEY;
    this.progress.switchKey(userKey(session.user.id));
    this.setStatus('syncing');
    try {
      const remote = await this.cloud.load();
      if (generation !== this.generation) return;
      const local = this.progress.snapshot();
      let next: ProgressData;
      if (remote) next = mergeProgress(local, remote);
      else if (hadGuestSlot) next = mergeProgress(local, guest);
      else next = local;
      this.progress.replace(next);
      this.synced = true;
      this.loading = false;
      this.dirty = true;
      await this.push(false);
    } catch {
      if (generation === this.generation) {
        this.setStatus('error');
        this.retryHandle = this.timers.set(() => void this.onSession(this.auth.session), RETRY_MS);
      }
    } finally {
      if (generation === this.generation) this.loading = false;
    }
  }

  private onLocalChange(): void {
    if (!this.auth.session || this.loading || !this.synced) return;
    this.dirty = true;
    if (this.pending !== null) this.timers.clear(this.pending);
    this.pending = this.timers.set(() => {
      this.pending = null;
      void this.push(false);
    }, this.debounceMs);
  }

  private async push(keepalive: boolean): Promise<void> {
    const generation = this.generation;
    this.setStatus('syncing');
    this.dirty = false;
    try {
      await this.cloud.save(this.progress.snapshot(), keepalive);
      if (generation === this.generation) this.setStatus(this.dirty ? 'syncing' : 'saved');
    } catch (error) {
      if (error instanceof CloudRejected) {
        // Retrying the same data cannot succeed; the next change will try again.
        if (generation === this.generation) this.setStatus('rejected');
        return;
      }
      this.dirty = true;
      if (generation === this.generation) {
        this.setStatus('error');
        if (this.retryHandle === null) {
          this.retryHandle = this.timers.set(() => {
            this.retryHandle = null;
            if (this.auth.session && this.synced) void this.push(false);
          }, RETRY_MS);
        }
      }
    }
  }

  private setStatus(status: SyncStatus): void {
    if (status === this.current) return;
    this.current = status;
    for (const l of this.listeners) l(status);
  }
}
