export type Archetype =
  | 'fish'
  | 'ray'
  | 'turtle'
  | 'whale'
  | 'squid'
  | 'jelly'
  | 'crustacean'
  | 'octopus'
  | 'shark'
  | 'eel'
  | 'cucumber';

export type Rarity = 'common' | 'uncommon' | 'rare' | 'legendary';
export type Temperament = 'skittish' | 'neutral' | 'curious';
/** Pelagic animals roam the open water, benthic ones stay near the seabed. */
export type Habitat = 'pelagic' | 'benthic';

/** Optional body-shape knobs for the procedural fish builder. All are multipliers or flags. */
export interface FishShape {
  readonly length?: number;
  readonly height?: number;
  readonly width?: number;
  readonly tail?: 'fork' | 'lunate' | 'taper' | 'shark';
  readonly dorsal?: boolean;
  readonly bigMouth?: boolean;
  readonly lure?: boolean;
}

export interface SpeciesDef {
  readonly id: string;
  readonly latin: string;
  readonly archetype: Archetype;
  readonly rarity: Rarity;
  readonly habitat: Habitat;
  readonly depth: readonly [number, number];
  readonly prefer: number;
  readonly sizeM: number;
  readonly speed: number;
  readonly temperament: Temperament;
  readonly body: number;
  readonly accent: number;
  readonly glow?: number;
  readonly opacity?: number;
  readonly school?: { readonly min: number; readonly max: number };
  readonly shape?: FishShape;
  readonly value: number;
  readonly catchable?: { readonly difficulty: number; readonly kg: readonly [number, number] };
  readonly extinct?: boolean;
}

