export type SpeciesId = (typeof SPECIES)[number]['id'];

const BY_ID: ReadonlyMap<string, SpeciesDef> = new Map(SPECIES.map((s) => [s.id, s]));

export function isSpeciesId(value: string): value is SpeciesId {
  return BY_ID.has(value);
}

export function getSpecies(id: string): SpeciesDef {
  const species = BY_ID.get(id);
  if (!species) throw new Error(`Unknown species: ${id}`);
  return species;
}

export const SPECIES_COUNT = SPECIES.length;
