import { num, t } from '../i18n/index.ts';
import type { Account } from '../net/account.ts';
import type { Board, BoardData, BoardRow } from '../net/leaderboard.ts';

const BOARDS: readonly Board[] = ['score', 'species', 'depth'];

const fmt = (n: number): string => num(Math.round(n));

function el<K extends keyof HTMLElementTagNameMap>(tag: K, className?: string, text?: string): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function value(row: BoardRow, board: Board): string {
  return board === 'score' ? fmt(row.score) : board === 'species' ? fmt(row.species) : `${fmt(row.depth)} ${t('hud.m')}`;
}

function line(row: BoardRow, board: Board, extra = ''): HTMLElement {
  const tr = el('div', `lb-row${row.isMe ? ' me' : ''}${extra}`);
  tr.append(el('span', 'lb-rank', row.rank > 0 ? String(row.rank) : '–'), el('span', 'lb-name', row.username), el('span', 'lb-value', value(row, board)));
  return tr;
}

/** The ranking sheet: three boards, my own place pinned under the table. Open to guests, too. */
export function createLeaderboardView(account: Account): HTMLElement {
  const root = el('div', 'leaderboard');
  let board: Board = 'score';
  let token = 0;

  const tabs = el('div', 'tabs');
  const table = el('div', 'lb-table');
  const foot = el('p', 'account-note');
  const refresh = el('button', 'ghost', t('lb.refresh'));
  refresh.type = 'button';

  const paintTabs = (): void => {
    for (const t of tabs.querySelectorAll('button')) t.classList.toggle('active', t.dataset.board === board);
  };

  const draw = (data: BoardData): void => {
    const head = el('div', 'lb-row lb-head');
    head.append(el('span', 'lb-rank', '#'), el('span', 'lb-name', t('lb.player')), el('span', 'lb-value', t(`lb.head.${board}`)));
    const rows = data.rows.map((r) => line(r, board));
    if (data.rows.length === 0) {
      table.replaceChildren(el('p', 'account-note', t('lb.empty')));
    } else {
      table.replaceChildren(head, ...rows);
    }
    if (data.me && !data.rows.some((r) => r.isMe)) {
      table.append(el('div', 'lb-gap', '···'), line(data.me, board));
    }
    foot.textContent = account.session
      ? data.me
        ? t('lb.mine', { rank: data.me.rank > 0 ? data.me.rank : '–' })
        : t('lb.notRanked')
      : t('lb.signIn');
  };

  const load = (): void => {
    const mine = ++token;
    table.replaceChildren(el('p', 'account-note', t('lb.loading')));
    refresh.disabled = true;
    account
      .leaderboard(board)
      .then((data) => {
        if (mine === token) draw(data);
      })
      .catch(() => {
        if (mine === token) table.replaceChildren(el('p', 'form-error', t('lb.failed')));
      })
      .finally(() => {
        if (mine === token) refresh.disabled = false;
      });
  };

  if (!account.enabled) {
    root.append(el('h3', undefined, t('lb.offline.title')), el('p', 'account-note', t('lb.offline.text')));
    return root;
  }

  for (const id of BOARDS) {
    const label = t(`lb.tab.${id}`);
    const b = el('button', 'tab', label);
    b.type = 'button';
    b.dataset.board = id;
    b.setAttribute('role', 'tab');
    b.addEventListener('click', () => {
      board = id;
      paintTabs();
      load();
    });
    tabs.append(b);
  }
  refresh.addEventListener('click', load);
  const bar = el('div', 'lb-bar');
  bar.append(tabs, refresh);
  root.append(bar, table, foot);
  paintTabs();
  load();
  return root;
}
