import { clamp } from '../core/math.ts';
import { DIVE_SITES } from '../data/sites.ts';
import { ZONES } from '../data/zones.ts';
import { MAX_DEPTH_M, pressureAtm, temperatureC, zoneAt } from '../domain/ocean.ts';
import { num, t } from '../i18n/index.ts';
import { zoneAlias, zoneName } from '../i18n/names.ts';

export interface HudData {
  depth: number;
  maxDepth: number;
  crushDepth: number;
  speed: number;
  heading: number;
  oxygen: number;
  battery: number;
  hull: number;
  submerged: boolean;
  lightOn: boolean;
  emergency: boolean;
  emergencyHold: number;
}

export type ToastKind = 'info' | 'warn' | 'danger' | 'good';

const SVG = 'http://www.w3.org/2000/svg';
const RING_RADIUS = 21;
const RING_LENGTH = 2 * Math.PI * RING_RADIUS;
const DEPTH_CURVE = 1.6;
const TAPE_SCALE = 3.2;

const rulerPosition = (depth: number): number => (clamp(depth / MAX_DEPTH_M) ** (1 / DEPTH_CURVE)) * 100;

function el<K extends keyof HTMLElementTagNameMap>(tag: K, className?: string, text?: string): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

interface Ring {
  root: HTMLElement;
  arc: SVGCircleElement;
  value: HTMLElement;
}

function ring(label: string): Ring {
  const root = el('div', 'ring');
  const svg = document.createElementNS(SVG, 'svg');
  svg.setAttribute('viewBox', '0 0 52 52');
  const track = document.createElementNS(SVG, 'circle');
  const arc = document.createElementNS(SVG, 'circle');
  for (const c of [track, arc]) {
    c.setAttribute('cx', '26');
    c.setAttribute('cy', '26');
    c.setAttribute('r', String(RING_RADIUS));
    c.setAttribute('fill', 'none');
  }
  track.setAttribute('class', 'ring-track');
  arc.setAttribute('class', 'ring-arc');
  arc.setAttribute('stroke-dasharray', String(RING_LENGTH));
  arc.setAttribute('stroke-dashoffset', '0');
  svg.append(track, arc);
  const value = el('b', 'ring-value');
  const face = el('div', 'ring-face');
  face.append(svg, value);
  root.append(face, el('span', 'ring-label', label));
  return { root, arc, value };
}

/** Heads-up display built from plain DOM; updates only what changed. */
export class Hud {
  private readonly root: HTMLElement;
  private readonly layer = el('div', 'hud-layer');
  private readonly toasts = el('div', 'toasts');
  private readonly flashEl = el('div', 'flash');
  private readonly cache = new Map<string, string>();
  private hintsVisible = true;

  private zoneAliasEl = el('span');
  private zoneNameEl = el('span');
  private banner = el('div');
  private depthValue = el('span');
  private pressure = el('dd');
  private temperature = el('dd');
  private speed = el('dd');
  private headingValue = el('span');
  private tape: HTMLElement = el('div') as HTMLElement;
  private oxygen = ring('');
  private battery = ring('');
  private hull = ring('');
  private marker = el('i');
  private crushMark = el('em');
  private recordMark = el('em');
  private emergencyBar = el('div');
  private emergencyFill = el('div');
  private surfaceTag = el('div');
  private lightTag = el('span');
  private hintsPanel: HTMLElement = el('div') as HTMLElement;
  private readonly tipEl = el('div', 'hud-tip');
  private tipText = '';

  constructor(root: HTMLElement) {
    this.root = root;
    this.tipEl.hidden = true;
    this.tipEl.setAttribute('role', 'status');
    root.replaceChildren(this.layer, this.toasts, this.tipEl, this.flashEl);
    this.build();
  }

  retranslate(): void {
    this.build();
  }

  private build(): void {
    this.cache.clear();

    this.zoneAliasEl = el('span', 'zone-alias');
    this.zoneNameEl = el('span', 'zone-name');
    this.banner = el('div', 'zone-banner');
    this.banner.append(this.zoneAliasEl, this.zoneNameEl);

    this.lightTag = el('span', 'pill', t('hud.light'));
    const top = el('div', 'hud-topright');
    top.append(this.lightTag);
    this.hintsPanel = this.buildHints();
    this.hintsPanel.hidden = !this.hintsVisible;
    top.append(this.hintsPanel);

    const depth = el('section', 'hud-depth');
    this.depthValue = el('span', 'depth-number', '0');
    const big = el('div', 'depth-big');
    big.append(this.depthValue, el('i', undefined, t('hud.m')));
    const caption = el('div', 'depth-caption', t('hud.depth'));
    this.pressure = el('dd');
    this.temperature = el('dd');
    this.speed = el('dd');
    const stats = el('dl', 'depth-stats');
    const stat = (label: string, value: HTMLElement): void => {
      const wrap = el('div');
      wrap.append(el('dt', undefined, label), value);
      stats.append(wrap);
    };
    stat(t('hud.pressure'), this.pressure);
    stat(t('hud.temperature'), this.temperature);
    stat(t('hud.speed'), this.speed);
    depth.append(caption, big, stats);

    const compass = el('div', 'compass');
    this.headingValue = el('span', 'compass-value');
    const view = el('div', 'compass-window');
    this.tape = this.buildTape();
    view.append(this.tape, el('i', 'compass-caret'));
    compass.append(this.headingValue, view);

    this.oxygen = ring(t('hud.air'));
    this.battery = ring(t('hud.power'));
    this.hull = ring(t('hud.hull'));
    const rings = el('div', 'rings');
    rings.append(this.oxygen.root, this.battery.root, this.hull.root);

    const ruler = el('div', 'ruler');
    ruler.append(el('i', 'ruler-line'));
    for (const zone of ZONES) {
      const tick = el('b', undefined, t('unit.m', { n: num(zone.fromM) }));
      tick.style.top = `${rulerPosition(zone.fromM)}%`;
      ruler.append(tick);
    }
    const end = el('b', undefined, t('unit.m', { n: num(MAX_DEPTH_M) }));
    end.style.top = '100%';
    this.marker = el('i', 'ruler-marker');
    this.crushMark = el('em', 'crush');
    this.recordMark = el('em', 'record');
    ruler.append(end, this.recordMark, this.crushMark, this.marker);

    this.emergencyFill = el('div', 'emergency-fill');
    this.emergencyBar = el('div', 'emergency');
    this.emergencyBar.append(el('span', undefined, t('hud.emergency')), this.emergencyFill);
    this.emergencyBar.hidden = true;

    this.surfaceTag = el('div', 'surface-tag', t('hud.surface'));
    this.surfaceTag.hidden = true;

    const reticle = el('div', 'reticle');
    this.layer.replaceChildren(this.banner, top, ruler, depth, compass, rings, this.emergencyBar, this.surfaceTag, reticle);
  }

  private buildHints(): HTMLElement {
    const panel = el('div', 'hints');
    const rows: ReadonlyArray<readonly [string, string]> = [
      ['W S', t('hud.hint.move')],
      ['A D', t('hud.hint.turn')],
      [t('key.space'), t('hud.hint.rise')],
      ['Shift', t('hud.hint.dive')],
      ['L', t('hud.hint.light')],
      ['F', t('hud.hint.sonar')],
      ['P', t('hud.hint.photo')],
      ['X', t('hud.hint.emergency')],
      [`1–${DIVE_SITES.length}`, t('hud.hint.sites')],
    ];
    for (const [keys, label] of rows) {
      const row = el('div', 'hint');
      const caps = el('span', 'caps');
      for (const k of keys.split(' ')) caps.append(el('kbd', undefined, k));
      row.append(caps, el('span', undefined, label));
      panel.append(row);
    }
    return panel;
  }

  private buildTape(): HTMLElement {
    const tape = el('div', 'compass-tape');
    const cardinal: Record<number, string> = { 0: t('compass.n'), 90: t('compass.e'), 180: t('compass.s'), 270: t('compass.w') };
    for (let deg = 0; deg < 1080; deg += 5) {
      const angle = deg % 360;
      const major = angle % 90 === 0;
      const mid = angle % 30 === 0;
      const tick = el('i', major ? 'tick major' : mid ? 'tick mid' : 'tick');
      tick.style.left = `${deg * TAPE_SCALE}px`;
      tape.append(tick);
      if (mid) {
        const label = el('span', major ? 'tick-label major' : 'tick-label', major ? (cardinal[angle] ?? '') : String(angle));
        label.style.left = `${deg * TAPE_SCALE}px`;
        tape.append(label);
      }
    }
    return tape;
  }

  /** Shows a single beginner tip above the compass; null hides it. */
  setTip(text: string | null): void {
    if (text === this.tipText) return;
    this.tipText = text ?? '';
    this.tipEl.hidden = text === null;
    if (text !== null) {
      this.tipEl.textContent = text;
      this.tipEl.classList.remove('in');
      void this.tipEl.offsetWidth;
      this.tipEl.classList.add('in');
    }
  }

  setHints(visible: boolean): void {
    this.hintsVisible = visible;
    this.hintsPanel.hidden = !visible;
  }

  update(d: HudData): void {
    const zone = zoneAt(d.depth);
    this.set('zone', zone.id, () => {
      this.zoneNameEl.textContent = zoneName(zone.id);
      this.zoneAliasEl.textContent = zoneAlias(zone.id);
      this.banner.classList.remove('shift');
      void this.banner.offsetWidth;
      this.banner.classList.add('shift');
    });
    const depth = num(Math.max(0, d.depth));
    this.set('depth', depth, () => {
      this.depthValue.textContent = depth;
    });
    const pressure = t('hud.atm');
    this.set('pressure', `${num(pressureAtm(d.depth))}|${pressure}`, () => {
      this.pressure.textContent = `${num(pressureAtm(d.depth))} ${pressure}`;
    });
    const temp = num(temperatureC(d.depth), d.depth < 1500 ? 0 : 1);
    this.set('temp', temp, () => {
      this.temperature.textContent = t('unit.celsius', { n: temp });
    });
    const speed = num(d.speed);
    this.set('speed', speed, () => {
      this.speed.textContent = t('unit.mps', { n: speed });
    });
    const heading = Math.round(d.heading) % 360;
    this.set('heading', String(heading), () => {
      this.headingValue.textContent = `${String(heading).padStart(3, '0')}°`;
      this.tape.style.transform = `translateX(${-(heading + 360) * TAPE_SCALE}px)`;
    });

    this.setRing('oxygen', this.oxygen, d.oxygen, 0.2);
    this.setRing('battery', this.battery, d.battery, 0.2);
    this.setRing('hull', this.hull, d.hull, 0.3);

    this.marker.style.top = `${rulerPosition(d.depth)}%`;
    this.crushMark.style.top = `${rulerPosition(d.crushDepth)}%`;
    this.recordMark.style.top = `${rulerPosition(d.maxDepth)}%`;
    this.crushMark.hidden = d.crushDepth >= MAX_DEPTH_M;
    this.lightTag.classList.toggle('on', d.lightOn);

    this.surfaceTag.hidden = d.submerged;
    this.emergencyBar.hidden = d.emergencyHold <= 0 && !d.emergency;
    this.emergencyBar.classList.toggle('active', d.emergency);
    this.emergencyFill.style.width = `${(d.emergency ? 1 : d.emergencyHold) * 100}%`;
  }

  flash(): void {
    this.flashEl.classList.remove('go');
    void this.flashEl.offsetWidth;
    this.flashEl.classList.add('go');
  }

  toast(text: string, kind: ToastKind = 'info', ms = 4200): void {
    const node = el('div', `toast ${kind}`, '');
    node.textContent = text;
    this.toasts.prepend(node);
    while (this.toasts.children.length > 4) this.toasts.lastElementChild?.remove();
    window.setTimeout(() => {
      node.classList.add('out');
      window.setTimeout(() => node.remove(), 500);
    }, ms);
  }

  setVisible(visible: boolean): void {
    this.root.hidden = !visible;
  }

  private set(key: string, value: string, apply: () => void): void {
    if (this.cache.get(key) === value) return;
    this.cache.set(key, value);
    apply();
  }

  private setRing(key: string, r: Ring, share: number, low: number): void {
    const pct = Math.round(clamp(share) * 100);
    this.set(`ring-${key}`, String(pct), () => {
      r.arc.setAttribute('stroke-dashoffset', String(RING_LENGTH * (1 - clamp(share))));
      r.value.textContent = String(pct);
      r.root.classList.toggle('low', share < low);
      r.root.classList.toggle('critical', share < low / 2);
    });
  }
}
