import {
  BoxGeometry,
  type BufferGeometry,
  ConeGeometry,
  CylinderGeometry,
  IcosahedronGeometry,
  Vector3,
} from 'three';
import { fbm2 } from '../core/noise.ts';
import { createRng, type Rng } from '../core/random.ts';
import { seabedSlope, type WorldQuery } from '../domain/world.ts';
import { addLimb, PropBuilder } from './props.ts';

function palm(b: PropBuilder, rng: Rng, x: number, y: number, z: number, h: number): void {
  const a = rng.range(0, 6.28);
  const lean = rng.range(0.15, 0.4) * h;
  let prev = new Vector3(x, y, z);
  const steps = 5;
  for (let s = 1; s <= steps; s++) {
    const t = s / steps;
    const p = new Vector3(x + Math.cos(a) * lean * t * t, y + h * t, z + Math.sin(a) * lean * t * t);
    addLimb(b, prev, p, 0.3 - 0.1 * (s - 1) / steps, 0.3 - 0.1 * s / steps, 0x6a5238);
    prev = p;
  }
  const frond = new BoxGeometry(4.4, 0.05, 1, 1, 1, 1);
  frond.translate(2.2, 0, 0);
  for (let i = 0; i < 8; i++) {
    b.add(frond, 0x3f7a2c, {
      pos: [prev.x, prev.y, prev.z],
      rot: [0, (i / 8) * Math.PI * 2 + rng.range(-0.2, 0.2), -rng.range(0.35, 0.75)],
      scale: [rng.range(0.85, 1.2), 1, 1],
      jitter: 0.25,
    });
  }
  b.add(new IcosahedronGeometry(0.28, 0), 0x5a3a20, { pos: [prev.x, prev.y - 0.3, prev.z] });
}

function pine(b: PropBuilder, rng: Rng, x: number, y: number, z: number, h: number): void {
  b.add(new CylinderGeometry(0.2, 0.35, h * 0.4, 6), 0x4a3828, { pos: [x, y + h * 0.2, z] });
  const tiers = 4;
  for (let i = 0; i < tiers; i++) {
    const t = i / tiers;
    const r = (1 - t * 0.7) * h * 0.26;
    b.add(new ConeGeometry(r, h * 0.36, 8), 0x234a2a, {
      pos: [x, y + h * (0.28 + t * 0.62), z],
      rot: [0, rng.range(0, 3), 0],
      jitter: 0.3,
    });
  }
}

function broadleaf(b: PropBuilder, rng: Rng, x: number, y: number, z: number, h: number): void {
  b.add(new CylinderGeometry(0.22, 0.4, h * 0.55, 6), 0x5a4430, { pos: [x, y + h * 0.27, z] });
  for (let i = 0; i < 4; i++) {
    const r = h * rng.range(0.22, 0.34);
    b.add(new IcosahedronGeometry(1, 1), i % 2 ? 0x4a7a2e : 0x35602a, {
      pos: [x + rng.range(-0.28, 0.28) * h, y + h * (0.55 + rng.range(0, 0.3)), z + rng.range(-0.28, 0.28) * h],
      scale: [r, r * 0.8, r],
      jitter: 0.3,
    });
  }
}

function lighthouse(b: PropBuilder, x: number, y: number, z: number): void {
  const stripes = [0xe8e4da, 0xb02a24, 0xe8e4da, 0xb02a24];
  stripes.forEach((c, i) => {
    const r0 = 2.7 - i * 0.28;
    b.add(new CylinderGeometry(r0 - 0.28, r0, 5, 14), c, { pos: [x, y + 2.5 + i * 5, z], jitter: 0.05 });
  });
  b.add(new CylinderGeometry(2.3, 2.3, 0.4, 14), 0x2a2e30, { pos: [x, y + 20.2, z] });
  b.add(new CylinderGeometry(1.2, 1.2, 2.4, 12), 0xfff2c0, { pos: [x, y + 21.6, z], emit: 1 });
  b.add(new ConeGeometry(1.7, 1.6, 12), 0xb02a24, { pos: [x, y + 23.6, z] });
  b.add(new BoxGeometry(2.4, 3, 2.4), 0xd6d2c6, { pos: [x + 5, y + 1.5, z] });
  b.add(new BoxGeometry(2.8, 0.4, 2.8), 0x6a3028, { pos: [x + 5, y + 3.1, z] });
}

/** Palms along the beach, pines and broadleaf groves on the hills, a lighthouse, shore boulders. */
export function buildTrees(world: WorldQuery): BufferGeometry {
  const rng = createRng(7777);
  const b = new PropBuilder();
  let count = 0;
  for (let i = 0; i < 7000 && count < 460; i++) {
    const x = rng.range(-1150, -310);
    const z = rng.range(-1200, 1200);
    const h = world.seabedY(x, z);
    if (h < 1.1 || h > 55) continue;
    if (x > -400 && Math.abs(z) < 70) continue;
    if (Math.hypot(x + 380, z + 70) < 12) continue;
    if (seabedSlope(x, z, 3) > 0.5) continue;
    const grove = fbm2(x * 0.012, z * 0.012, 3, 515);
    if (h > 7 && grove < 0.44) continue;
    count++;
    const size = rng.range(0.8, 1.3);
    if (h < 7) palm(b, rng, x, h - 0.2, z, rng.range(6, 10) * size);
    else if (grove > 0.55 && rng.chance(0.55)) pine(b, rng, x, h - 0.3, z, rng.range(8, 15) * size);
    else broadleaf(b, rng, x, h - 0.3, z, rng.range(5, 9) * size);
  }
  const lx = -380;
  const lz = -70;
  lighthouse(b, lx, Math.max(world.seabedY(lx, lz), 1) - 0.3, lz);

  for (let i = 0; i < 1200 && i < 1200; i++) {
    const x = rng.range(-340, -285);
    const z = rng.range(-500, 500);
    const h = world.seabedY(x, z);
    if (h < -0.5 || h > 1.5 || (x > -380 && Math.abs(z) < 24)) continue;
    if (rng.next() > 0.08) continue;
    const r = rng.range(0.6, 2);
    b.add(new IcosahedronGeometry(1, 1), 0x6a665c, { pos: [x, h + r * 0.2, z], scale: [r * 1.2, r * 0.7, r], jitter: 0.2 });
  }
  return b.build();
}
