import { DoubleSide, Mesh, ShaderMaterial, type Texture, Vector2, Vector4 } from 'three';
import { WAVES } from '../domain/waves.ts';
import { createPolarGrid } from './polar-grid.ts';
import { SHORE_REGION, type ShoreRegion } from './shore-mask.ts';
import { CAUSTICS_GLSL, COMMON_UNIFORMS, NOISE_GLSL, SAFE_GLSL, SKY_GLSL } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

const vertexShader = /* glsl */ `
uniform float uTime;
uniform vec4 uWaves[4];
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying float vFoam;

void main() {
  vec3 p = (modelMatrix * vec4(position, 1.0)).xyz;
  vec3 disp = vec3(0.0);
  vec3 n = vec3(0.0, 1.0, 0.0);
  float jxx = 0.0;
  float jzz = 0.0;
  float jxz = 0.0;

  for (int i = 0; i < 4; i++) {
    vec2 d = uWaves[i].xy;
    float s = uWaves[i].z;
    float k = 6.28318530718 / uWaves[i].w;
    float amp = s / k;
    float w = sqrt(9.81 * k);
    float th = k * dot(d, p.xz) - w * uTime;
    float c = cos(th);
    float sn = sin(th);
    disp.x += d.x * amp * c;
    disp.z += d.y * amp * c;
    disp.y += amp * sn;
    n.x -= d.x * s * c;
    n.z -= d.y * s * c;
    n.y -= s * sn;
    jxx += s * d.x * d.x * sn;
    jzz += s * d.y * d.y * sn;
    jxz += s * d.x * d.y * sn;
  }

  float jac = (1.0 - jxx) * (1.0 - jzz) - jxz * jxz;
  vFoam = clamp((0.78 - jac) * 3.0, 0.0, 1.0);
  vNormalW = normalize(n);
  vWorldPos = p + disp;
  gl_Position = projectionMatrix * viewMatrix * vec4(vWorldPos, 1.0);
}
`;

const fragmentShader = /* glsl */ `
${COMMON_UNIFORMS}
${SAFE_GLSL}
${NOISE_GLSL}
${SKY_GLSL}
${CAUSTICS_GLSL}
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying float vFoam;
uniform sampler2D uShore;
uniform vec4 uShoreRegion;
uniform vec2 uPiles[48];
uniform int uPileCount;
uniform vec4 uPierBox;

void main() {
  vec3 toCam = uCamPos - vWorldPos;
  float dist = length(toCam);
  vec3 V = toCam / max(dist, 0.001);

  // Fine ripples on top of the Gerstner normal.
  vec2 uv = vWorldPos.xz;
  float e = 0.25;
  float h0 = fbm(uv * 0.9 + vec2(uTime * 0.07, uTime * 0.04));
  float hx = fbm((uv + vec2(e, 0.0)) * 0.9 + vec2(uTime * 0.07, uTime * 0.04));
  float hz = fbm((uv + vec2(0.0, e)) * 0.9 + vec2(uTime * 0.07, uTime * 0.04));
  float ripple = 0.35 * (1.0 - smoothstep(60.0, 400.0, dist));
  vec3 N = normalize(vNormalW + vec3(h0 - hx, 0.0, h0 - hz) * ripple * 3.0);

  vec3 col;
  if (gl_FrontFacing) {
    float cosV = clamp(dot(N, V), 0.0, 1.0);
    float fres = 0.02 + 0.98 * pow(1.0 - cosV, 5.0);
    vec3 R = reflect(-V, N);
    R.y = abs(R.y);
    vec3 refl = skyColor(R);

    vec3 deepCol = vec3(0.004, 0.045, 0.085);
    vec3 shallowCol = vec3(0.03, 0.26, 0.31);
    float crest = smoothstep(-0.6, 1.8, vWorldPos.y);
    vec3 water = mix(deepCol, shallowCol, crest * 0.8 + 0.1);
    col = mix(water, refl, fres);

    vec3 H = normalize(uSunDir + V);
    float spec = pow(max(dot(N, H), 0.0), 260.0);
    col += uSunColor * spec * 4.0;

    float foamNoise = fbm(uv * 1.7 + uTime * 0.1);
    float foam = clamp(vFoam * (0.5 + foamNoise), 0.0, 1.0);

    // Surf where the water gets shallow near the port.
    float shore = 0.0;
    vec2 suv = (vWorldPos.xz - uShoreRegion.xy) / uShoreRegion.zw;
    if (suv.x > 0.0 && suv.x < 1.0 && suv.y > 0.0 && suv.y < 1.0) {
      float wd = -(texture2D(uShore, suv).r * 20.0 - 10.0);
      float band = smoothstep(-0.1, 0.3, wd) * (1.0 - smoothstep(0.4, 2.2, wd));
      float lines = 0.5 + 0.5 * sin(wd * 3.4 - uTime * 0.9 + foamNoise * 3.0);
      shore = band * (0.3 + 0.7 * smoothstep(0.35, 0.9, lines)) * (0.5 + 0.9 * foamNoise);
    }
    // Foam rings around the pier piles.
    float rings = 0.0;
    if (vWorldPos.x > uPierBox.x && vWorldPos.x < uPierBox.z && vWorldPos.z > uPierBox.y && vWorldPos.z < uPierBox.w) {
      for (int i = 0; i < 48; i++) {
        if (i >= uPileCount) break;
        float d = length(vWorldPos.xz - uPiles[i]);
        rings = max(rings, smoothstep(0.2, 0.3, d) * (1.0 - smoothstep(0.45, 1.3, d)));
      }
      rings *= 0.45 + 0.9 * fbm(uv * 3.0 - uTime * 0.3);
    }
    foam = clamp(foam + shore + rings, 0.0, 1.0);
    col = mix(col, vec3(0.92, 0.95, 1.0) * (0.4 + 0.6 * uSunColor), foam * 0.8);
  } else {
    // Seen from below: Snell's window to the sky, mirror of the deep water outside it.
    vec3 rd = -V;
    float cosI = dot(rd, N);
    // The critical angle of water is about 48.6 degrees (cos = 0.66); beyond it light reflects back down.
    float window = smoothstep(0.62, 0.74, cosI);
    vec3 mirror = uFogColor * 1.4;
    vec3 T = refract(rd, -N, 1.33);
    vec3 through = dot(T, T) > 0.0001 ? skyColor(normalize(T)) * 0.7 : mirror;
    col = mix(mirror, through, window);
    float caust = caustics(vWorldPos.xz * 0.3, uTime);
    col += uSunColor * caust * 0.06 * uSunlight;
  }

  float transmittance = exp(-uFogDensity * dist);
  col = mix(uFogColor, col, transmittance);
  gl_FragColor = vec4(sanitize(col, uFogColor), 1.0);
}
`;

/** The sea surface: Gerstner waves, sky reflections, foam, and a Snell's window seen from below. */
export class OceanSurface {
  readonly mesh: Mesh;

  constructor(
    uniforms: SceneUniforms,
    rings: number,
    shore: Texture,
    piles: readonly { x: number; z: number }[],
  ) {
    const grid = createPolarGrid({
      rings,
      segments: Math.round(rings * 2.6),
      radius: 7000,
      growth: 6.8,
    });
    const material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
        uWaves: { value: WAVES.map((w) => new Vector4(w.dirX, w.dirZ, w.steepness, w.wavelength)) },
        uShore: { value: shore },
        uShoreRegion: {
          value: new Vector4(SHORE_REGION.minX, SHORE_REGION.minZ, SHORE_REGION.sizeX, SHORE_REGION.sizeZ),
        },
        uPiles: { value: Array.from({ length: 48 }, (_, i) => new Vector2(piles[i]?.x ?? 0, piles[i]?.z ?? 0)) },
        uPileCount: { value: Math.min(48, piles.length) },
        uPierBox: { value: pierBox(piles) },
      },
      vertexShader,
      fragmentShader,
      side: DoubleSide,
      fog: false,
    });
    this.mesh = new Mesh(grid.geometry, material);
    this.mesh.frustumCulled = false;
  }

  setHarbour(region: ShoreRegion, piles: readonly { x: number; z: number }[]): void {
    const u = (this.mesh.material as ShaderMaterial).uniforms;
    (u.uShoreRegion?.value as Vector4).set(region.minX, region.minZ, region.sizeX, region.sizeZ);
    const list = u.uPiles?.value as Vector2[];
    list.forEach((v, i) => v.set(piles[i]?.x ?? 0, piles[i]?.z ?? 0));
    (u.uPileCount as { value: number }).value = Math.min(48, piles.length);
    (u.uPierBox?.value as Vector4).copy(pierBox(piles));
  }

  follow(x: number, z: number): void {
    this.mesh.position.set(x, 0, z);
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    (this.mesh.material as ShaderMaterial).dispose();
  }
}

function pierBox(piles: readonly { x: number; z: number }[]): Vector4 {
  if (piles.length === 0) return new Vector4(1, 1, -1, -1);
  let minX = Number.POSITIVE_INFINITY;
  let minZ = Number.POSITIVE_INFINITY;
  let maxX = Number.NEGATIVE_INFINITY;
  let maxZ = Number.NEGATIVE_INFINITY;
  for (const p of piles) {
    minX = Math.min(minX, p.x);
    minZ = Math.min(minZ, p.z);
    maxX = Math.max(maxX, p.x);
    maxZ = Math.max(maxZ, p.z);
  }
  return new Vector4(minX - 1.5, minZ - 1.5, maxX + 1.5, maxZ + 1.5);
}
