import { GameApp } from './app/game-app.ts';
import { QUALITY_TIERS, type QualityTier } from './core/quality.ts';
import { SettingsStore } from './core/settings.ts';
import { PhotoAlbum } from './domain/photo-album.ts';
import { ProgressStore } from './domain/progress.ts';
import { type Account, createAccount, OFFLINE_ACCOUNT } from './net/account.ts';
import { AuthClient } from './net/auth.ts';
import { CloudProgress } from './net/cloud.ts';
import { readConfig } from './net/config.ts';
import { ProgressSync } from './net/sync.ts';
import { onLangChange, setLang, t, type UiKey } from './i18n/index.ts';
import { Menu } from './ui/menu.ts';
import './ui/styles.css';

function must<T extends HTMLElement>(selector: string): T {
  const node = document.querySelector<T>(selector);
  if (!node) throw new Error(`Missing element: ${selector}`);
  return node;
}

function supportsWebGL2(): boolean {
  try {
    return document.createElement('canvas').getContext('webgl2') !== null;
  } catch {
    return false;
  }
}

function translateStatic(): void {
  for (const node of document.querySelectorAll<HTMLElement>('[data-i18n]')) {
    node.textContent = t(node.dataset.i18n as UiKey);
  }
}

function boot(): void {
  const early = new SettingsStore(storageOrNull());
  setLang(early.value.language);
  translateStatic();
  onLangChange(translateStatic);
  if (!supportsWebGL2()) {
    must('#fatal').hidden = false;
    must('#title').hidden = true;
    return;
  }

  const params = new URLSearchParams(location.search);
  const settings = early;
  settings.subscribe((value, changed) => {
    if (changed === 'language' || changed === null) setLang(value.language);
  });
  const storage = storageOrNull();
  const progress = new ProgressStore(storage);
  const account = connectAccount(progress, storage);
  const album = new PhotoAlbum(storage, () => progress.currentKey);
  const forced = params.get('quality');
  const forcedTier =
    forced && (QUALITY_TIERS as readonly string[]).includes(forced) ? (forced as QualityTier) : null;
  const choice = settings.value.quality;
  const startTier: QualityTier = forcedTier ?? (choice === 'auto' ? 'high' : choice);

  const title = must('#title');
  const pause = must('#pause');
  let menu: Menu | null = null;

  const app = new GameApp({
    canvas: must<HTMLCanvasElement>('#scene'),
    hudRoot: must('#hud'),
    tier: startTier,
    settings,
    progress,
    album,
    autoQuality: forcedTier === null && choice === 'auto',
    onModeChange: (mode) => {
      title.hidden = mode !== 'title';
      pause.hidden = mode !== 'paused';
      menu?.setMode(mode);
    },
  });

  menu = new Menu(must('#main-menu'), must('#pause-menu'), settings, progress, account, album, {
    begin: () => app.begin(),
    resume: () => app.togglePause(),
    exitToTitle: () => app.exitToTitle(),
  });
  menu.setMode('title');
  app.start();
  if (/access_token=|error_code=|error=/.test(location.hash)) {
    const hash = location.hash;
    history.replaceState(null, '', location.pathname + location.search);
    void account.consumeLink(hash);
  }

  if (params.has('debug')) {
    (window as unknown as Record<string, unknown>).__luminara = app;
  }
}

function connectAccount(progress: ProgressStore, storage: Storage | null): Account {
  const config = readConfig((import.meta as { env?: Record<string, unknown> }).env ?? {});
  if (!config) return OFFLINE_ACCOUNT;
  const auth = new AuthClient(config, storage);
  auth.redirectTo = `${location.origin}${location.pathname}`;
  const sync = new ProgressSync(progress, auth, new CloudProgress(config, auth));
  sync.start();
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') void sync.flush(true);
  });
  window.addEventListener('pagehide', () => void sync.flush(true));
  return createAccount(config, auth, sync);
}

function storageOrNull(): Storage | null {
  try {
    return localStorage;
  } catch {
    return null;
  }
}

console.info(
  '%cLUMINARA%c  a game by %cXpain',
  'color:#5ff2d4;font-weight:700;letter-spacing:0.2em',
  'color:#86aab5',
  'color:#2bff7e;font-weight:700',
);

boot();
