import { CanvasTexture, RepeatWrapping, SRGBColorSpace } from 'three';
import { createRng } from '../core/random.ts';

const SIZE = 1024;

export interface HullTextures {
  map: CanvasTexture;
  bump: CanvasTexture;
  roughness: CanvasTexture;
}

type Ctx = CanvasRenderingContext2D;

function makeCanvas(): { canvas: HTMLCanvasElement; ctx: Ctx } {
  const canvas = document.createElement('canvas');
  canvas.width = SIZE;
  canvas.height = SIZE;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('2D canvas is not available');
  return { canvas, ctx };
}

const px = (u: number): number => u * SIZE;
const py = (v: number): number => (1 - v) * SIZE;

const PANEL_COLUMNS = 12;
const PANEL_ROWS = [0.1, 0.28, 0.5, 0.56, 0.72, 0.88] as const;

function drawSeams(ctx: Ctx, line: string, width: number, rivet: string, rivetHighlight: string | null): void {
  ctx.strokeStyle = line;
  ctx.lineWidth = width;
  for (let k = 0; k <= PANEL_COLUMNS; k++) {
    const x = px(k / PANEL_COLUMNS);
    ctx.beginPath();
    ctx.moveTo(x, py(0.03));
    ctx.lineTo(x, py(0.97));
    ctx.stroke();
  }
  for (const v of PANEL_ROWS) {
    ctx.beginPath();
    ctx.moveTo(0, py(v));
    ctx.lineTo(SIZE, py(v));
    ctx.stroke();
  }
  // Rivets along every seam.
  ctx.fillStyle = rivet;
  for (let k = 0; k <= PANEL_COLUMNS; k++) {
    for (let v = 0.05; v < 0.96; v += 0.032) {
      ctx.beginPath();
      ctx.arc(px(k / PANEL_COLUMNS) + 7, py(v), 2.4, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  for (const v of PANEL_ROWS) {
    for (let u = 0.01; u < 1; u += 0.02) {
      ctx.beginPath();
      ctx.arc(px(u), py(v) + 7, 2.4, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  if (rivetHighlight) {
    ctx.fillStyle = rivetHighlight;
    for (let k = 0; k <= PANEL_COLUMNS; k++) {
      for (let v = 0.05; v < 0.96; v += 0.032) {
        ctx.beginPath();
        ctx.arc(px(k / PANEL_COLUMNS) + 6.4, py(v) - 0.6, 0.9, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
}

function drawWear(ctx: Ctx, colour: (alpha: number) => string, seed: number, count: number): void {
  const rng = createRng(seed);
  for (let i = 0; i < count; i++) {
    const underside = rng.chance(0.65);
    const u = underside ? (rng.chance(0.5) ? rng.range(0, 0.1) : rng.range(0.9, 1)) : rng.next();
    const v = rng.range(0.04, 0.96);
    const length = rng.range(5, 34);
    const angle = rng.range(0, Math.PI);
    ctx.strokeStyle = colour(rng.range(0.1, 0.38));
    ctx.lineWidth = rng.range(0.8, 2.2);
    ctx.beginPath();
    ctx.moveTo(px(u), py(v));
    ctx.lineTo(px(u) + Math.cos(angle) * length, py(v) + Math.sin(angle) * length);
    ctx.stroke();
  }
}

/**
 * Painted-hull textures generated on a canvas: yellow paint with a white and red livery band,
 * panel seams with rivets, scuffs and underside grime. The map is wrapped around the hull
 * with u around (0 = keel, 0.25 = starboard) and v from the nose to the tail.
 */
export function createHullTextures(): HullTextures {
  const colour = makeCanvas();
  const c = colour.ctx;
  c.fillStyle = '#f1b400';
  c.fillRect(0, 0, SIZE, SIZE);

  const rng = createRng(77);
  for (let i = 0; i < 46; i++) {
    c.fillStyle = rng.chance(0.5) ? 'rgba(255,255,255,0.035)' : 'rgba(80,40,0,0.045)';
    c.beginPath();
    c.arc(rng.range(0, SIZE), rng.range(0, SIZE), rng.range(50, 170), 0, Math.PI * 2);
    c.fill();
  }

  c.fillStyle = '#f4f0e3';
  c.fillRect(0, py(0.56), SIZE, py(0.5) - py(0.56));
  c.fillStyle = '#c8372a';
  c.fillRect(0, py(0.575), SIZE, py(0.565) - py(0.575));
  c.fillStyle = '#1e252b';
  c.fillRect(0, py(0.97), SIZE, py(0.88) - py(0.97));

  drawSeams(c, 'rgba(95,62,0,0.6)', 2, 'rgba(80,50,0,0.75)', 'rgba(255,230,150,0.7)');
  drawWear(c, (a) => `rgba(45,32,14,${a})`, 5, 320);

  for (const [x0, x1] of [
    [0, px(0.13)],
    [px(0.87), SIZE],
  ] as const) {
    const grad = c.createLinearGradient(x0, 0, x1, 0);
    const edgeFirst = x0 === 0;
    grad.addColorStop(0, edgeFirst ? 'rgba(25,35,30,0.45)' : 'rgba(25,35,30,0)');
    grad.addColorStop(1, edgeFirst ? 'rgba(25,35,30,0)' : 'rgba(25,35,30,0.45)');
    c.fillStyle = grad;
    c.fillRect(x0, 0, x1 - x0, SIZE);
  }

  const bumpCanvas = makeCanvas();
  const b = bumpCanvas.ctx;
  b.fillStyle = '#808080';
  b.fillRect(0, 0, SIZE, SIZE);
  drawSeams(b, '#4a4a4a', 3, '#d8d8d8', null);
  drawWear(b, (a) => `rgba(200,200,200,${a})`, 9, 200);

  const roughCanvas = makeCanvas();
  const r = roughCanvas.ctx;
  r.fillStyle = '#4c4c4c';
  r.fillRect(0, 0, SIZE, SIZE);
  drawSeams(r, '#9a9a9a', 3, '#8a8a8a', null);
  drawWear(r, (a) => `rgba(190,190,190,${a})`, 5, 320);

  const finish = (canvas: HTMLCanvasElement, srgb: boolean): CanvasTexture => {
    const texture = new CanvasTexture(canvas);
    texture.wrapS = RepeatWrapping;
    texture.anisotropy = 8;
    if (srgb) texture.colorSpace = SRGBColorSpace;
    return texture;
  };
  return {
    map: finish(colour.canvas, true),
    bump: finish(bumpCanvas.canvas, false),
    roughness: finish(roughCanvas.canvas, false),
  };
}

/** Transparent texture with a single line of lettering, for hull decals. */
export function createLabelTexture(text: string, width: number, height: number, colour: string): CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('2D canvas is not available');
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = colour;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `800 ${Math.floor(height * 0.78)}px "Arial Black", Impact, "Helvetica Neue", Arial, sans-serif`;
  ctx.fillText(text.split('').join(' '), width / 2, height / 2 + height * 0.03, width * 0.96);
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  texture.anisotropy = 8;
  return texture;
}

/** A small instrument screen: grid, sweep arcs and a few blips. */
export function createScreenTexture(): CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('2D canvas is not available');
  ctx.fillStyle = '#021a1c';
  ctx.fillRect(0, 0, 256, 128);
  ctx.strokeStyle = 'rgba(80,255,220,0.35)';
  ctx.lineWidth = 1;
  for (let x = 0; x <= 256; x += 32) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, 128);
    ctx.stroke();
  }
  for (let y = 0; y <= 128; y += 32) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(256, y);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(120,255,230,0.8)';
  ctx.lineWidth = 2;
  for (const radius of [30, 60, 90]) {
    ctx.beginPath();
    ctx.arc(128, 128, radius, Math.PI, 0);
    ctx.stroke();
  }
  ctx.fillStyle = '#9fffe8';
  for (const [x, y] of [
    [90, 70],
    [150, 52],
    [176, 88],
    [116, 34],
  ] as const) {
    ctx.beginPath();
    ctx.arc(x, y, 3.5, 0, Math.PI * 2);
    ctx.fill();
  }
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  return texture;
}
