export type TipId = 'dive' | 'light' | 'photo';

export interface TipContext {
  depth: number;
  lightOn: boolean;
  photos: number;
}

interface Step {
  readonly id: TipId;
  readonly ready: (c: TipContext) => boolean;
  readonly done: (c: TipContext) => boolean;
}

const STEPS: readonly Step[] = [
  { id: 'dive', ready: () => true, done: (c) => c.depth >= 15 },
  { id: 'light', ready: (c) => c.depth >= 30, done: (c) => c.lightOn },
  { id: 'photo', ready: (c) => c.depth >= 30, done: (c) => c.photos > 0 },
];

export interface TipStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

const KEY = 'luminara.tutorial';

/** Three one-time tips for new players: dive, switch the light on, take a photo. */
export class Tutorial {
  private readonly finished = new Set<TipId>();
  private readonly storage: TipStorage | null;

  constructor(storage: TipStorage | null = null) {
    this.storage = storage;
    try {
      const raw: unknown = JSON.parse(storage?.getItem(KEY) ?? '[]');
      if (Array.isArray(raw)) for (const s of STEPS) if (raw.includes(s.id)) this.finished.add(s.id);
    } catch {
      this.finished.clear();
    }
  }

  /** The tip to show right now, or null. Finished steps are remembered. */
  update(c: TipContext): TipId | null {
    for (const step of STEPS) {
      if (this.finished.has(step.id)) continue;
      if (step.done(c)) {
        this.finished.add(step.id);
        this.save();
        continue;
      }
      return step.ready(c) ? step.id : null;
    }
    return null;
  }

  reset(): void {
    this.finished.clear();
    this.save();
  }

  private save(): void {
    try {
      this.storage?.setItem(KEY, JSON.stringify([...this.finished]));
    } catch {
    }
  }
}
