import {
  BackSide,
  Color,
  Mesh,
  MeshBasicMaterial,
  PlaneGeometry,
  PMREMGenerator,
  Scene,
  ShaderMaterial,
  SphereGeometry,
  type Texture,
  type WebGLRenderer,
} from 'three';

const sunDirection = { x: 0.9, y: 0.2, z: 0.25 };

/**
 * A tiny studio-style environment (sunset sky, bright sun and sky panels, dark teal below)
 * pre-filtered into a PMREM texture. Glossy paint and acrylic on the submarine reflect it.
 */
export function createEnvironmentMap(renderer: WebGLRenderer): Texture {
  const scene = new Scene();
  const disposables: { dispose(): void }[] = [];

  const skyMaterial = new ShaderMaterial({
    side: BackSide,
    depthWrite: false,
    uniforms: {},
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vec3 d = normalize(vDir);
        vec3 sun = normalize(vec3(${sunDirection.x}, ${sunDirection.y}, ${sunDirection.z}));
        vec3 below = vec3(0.01, 0.07, 0.1);
        vec3 horizon = vec3(1.1, 0.55, 0.3);
        vec3 top = vec3(0.35, 0.5, 0.95);
        vec3 col = mix(below, horizon, smoothstep(-0.35, 0.04, d.y));
        col = mix(col, top, smoothstep(0.02, 0.8, d.y));
        col += vec3(0.8, 0.4, 0.2) * pow(max(dot(d, sun), 0.0), 6.0);
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const skyGeometry = new SphereGeometry(50, 32, 16);
  scene.add(new Mesh(skyGeometry, skyMaterial));
  disposables.push(skyMaterial, skyGeometry);

  const panel = (colour: Color, size: [number, number], position: [number, number, number]): void => {
    const geometry = new PlaneGeometry(size[0], size[1]);
    const material = new MeshBasicMaterial({ color: colour, toneMapped: false });
    const mesh = new Mesh(geometry, material);
    mesh.position.set(...position);
    mesh.lookAt(0, 0, 0);
    scene.add(mesh);
    disposables.push(geometry, material);
  };
  panel(new Color(5, 3.8, 2.8), [26, 9], [sunDirection.x * 40, sunDirection.y * 40 + 4, sunDirection.z * 40]);
  panel(new Color(1.2, 1.8, 2.8), [40, 40], [0, 42, 0]);
  panel(new Color(0.8, 1.3, 1.8), [30, 8], [-38, 10, -20]);


  const generator = new PMREMGenerator(renderer);
  const target = generator.fromScene(scene, 0.03);
  generator.dispose();
  for (const item of disposables) item.dispose();
  return target.texture;
}
