import { NOISE_GLSL } from './shaders/common.ts';
import { AdditiveBlending, Color, CylinderGeometry, DoubleSide, Mesh, ShaderMaterial } from 'three';

const vertexShader = /* glsl */ `
varying vec2 vUv;
varying vec3 vNormalV;
varying vec3 vViewPos;
void main() {
  vUv = uv;
  vNormalV = normalize(normalMatrix * normal);
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  vViewPos = mv.xyz;
  gl_Position = projectionMatrix * mv;
}
`;

const fragmentShader = /* glsl */ `
${NOISE_GLSL}
uniform float uTime;
uniform float uIntensity;
uniform vec3 uColor;
varying vec2 vUv;
varying vec3 vNormalV;
varying vec3 vViewPos;
void main() {
  float along = clamp(vUv.y, 0.0, 1.0);
  float t = 1.0 - along; // 0 at the lamp, 1 at the far end of the beam
  float facing = clamp(abs(dot(normalize(vNormalV), normalize(-vViewPos))), 0.0, 1.0);
  // pow() of a value that rounding pushed just below zero is NaN on real GPUs, and bloom
  // smears a single NaN into a black block; keep every base non-negative.
  float body = pow(facing, 1.3);
  // Particles drifting through the cone make slow shimmering streaks along it.
  float streak = fbm(vec2(vUv.x * 14.0, along * 5.0 - uTime * 0.35));
  float shimmer = 0.65 + 0.7 * streak;
  float a = uIntensity * body * shimmer * pow(along, 1.5) * smoothstep(0.0, 0.05, t) * 0.5;
  if (!(a >= 0.0) || a > 100.0) discard;
  gl_FragColor = vec4(uColor * a, a);
}
`;

/**
 * Volumetric-looking headlight cone: an open additive cone that is brightest along its axis
 * and fades with distance. It points along local -Z and is sized with `setShape`.
 */
export class VolumetricBeam {
  readonly mesh: Mesh<CylinderGeometry, ShaderMaterial>;
  private readonly intensity = { value: 0 };
  private readonly time = { value: 0 };

  constructor() {
    const geometry = new CylinderGeometry(0.03, 1, 1, 32, 1, true);
    geometry.translate(0, -0.5, 0);
    geometry.rotateX(Math.PI / 2);
    const material = new ShaderMaterial({
      uniforms: {
        uIntensity: this.intensity,
        uTime: this.time,
        uColor: { value: new Color(0.7, 0.9, 1.0) },
      },
      vertexShader,
      fragmentShader,
      blending: AdditiveBlending,
      transparent: true,
      depthWrite: false,
      side: DoubleSide,
      fog: false,
    });
    this.mesh = new Mesh(geometry, material);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 5;
  }

  setShape(length: number, halfAngle: number): void {
    const radius = Math.tan(halfAngle) * length;
    this.mesh.scale.set(radius, radius, length);
  }

  setTime(seconds: number): void {
    this.time.value = seconds;
  }

  setIntensity(value: number): void {
    this.intensity.value = value;
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    this.mesh.material.dispose();
  }
}
