import {
  BufferAttribute,
  type BufferGeometry,
  CylinderGeometry,
  IcosahedronGeometry,
  Vector3,
} from 'three';
import { createRng, type Rng } from '../core/random.ts';
import { seabedSlope, type WorldQuery } from '../domain/world.ts';
import { PropBuilder } from './props.ts';

const ROCK_COLOURS = [0x5a5650, 0x6e6558, 0x4c4c50, 0x7a705e, 0x564a40];

function roughen(g: BufferGeometry, amount: number, scale: number, seed: number): void {
  const p = g.getAttribute('position') as BufferAttribute;
  const n = g.getAttribute('normal') as BufferAttribute | undefined;
  const key = (x: number, y: number, z: number): number => {
    const s = Math.sin(Math.round(x * scale) * 12.9898 + Math.round(y * scale) * 78.233 + Math.round(z * scale) * 37.719 + seed) * 43758.5453;
    return s - Math.floor(s);
  };
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const y = p.getY(i);
    const z = p.getZ(i);
    const k = (key(x, y, z) - 0.5) * 2 * amount;
    const dir = n ? new Vector3(n.getX(i), n.getY(i), n.getZ(i)) : new Vector3(x, y, z).normalize();
    p.setXYZ(i, x + dir.x * k, y + dir.y * k * 0.6, z + dir.z * k);
  }
  g.computeVertexNormals();
}

function boulder(b: PropBuilder, rng: Rng, x: number, y: number, z: number, r: number): void {
  const g = new IcosahedronGeometry(1, 2);
  roughen(g, 0.28, 4, rng.range(0, 99));
  const colour = ROCK_COLOURS[Math.floor(rng.next() * ROCK_COLOURS.length)] ?? 0x5a5650;
  b.add(g, colour, {
    pos: [x, y + r * 0.3, z],
    scale: [r * rng.range(0.9, 1.4), r * rng.range(0.55, 1), r * rng.range(0.9, 1.3)],
    rot: [0, rng.range(0, 6.28), 0],
    jitter: 0.18,
  });
}

function spire(b: PropBuilder, rng: Rng, x: number, y: number, z: number, height: number, r: number): void {
  const g = new CylinderGeometry(r * 0.18, r, height, 8, 7, false);
  const p = g.getAttribute('position') as BufferAttribute;
  const lean = rng.range(-0.25, 0.25);
  const lean2 = rng.range(-0.25, 0.25);
  for (let i = 0; i < p.count; i++) {
    const t = (p.getY(i) + height / 2) / height;
    p.setXYZ(i, p.getX(i) + lean * height * t * t, p.getY(i) + height / 2, p.getZ(i) + lean2 * height * t * t);
  }
  g.computeVertexNormals();
  roughen(g, r * 0.22, 1.5, rng.range(0, 99));
  const colour = ROCK_COLOURS[Math.floor(rng.next() * ROCK_COLOURS.length)] ?? 0x5a5650;
  b.add(g, colour, { pos: [x, y - 0.6, z], jitter: 0.2 });
}

/**
 * Big rock formations (spire clusters, boulder piles, arches and mesas) scattered across the shelf
 * and upper slope, denser where the ground is steep. All baked into one mesh.
 */
export function buildFormations(world: WorldQuery): BufferGeometry {
  const rng = createRng(90210);
  const b = new PropBuilder();
  const ground = (x: number, z: number): number => world.seabedY(x, z);
  let placed = 0;
  for (let attempt = 0; attempt < 900 && placed < 95; attempt++) {
    const cx = rng.range(-210, 3800);
    const cz = rng.range(-1600, 1600);
    const gy = ground(cx, cz);
    const depth = -gy;
    if (depth < 5 || depth > 1500) continue;
    if (Math.abs(cx + 290) < 140 && Math.abs(cz) < 50) continue;
    if (Math.hypot(cx - 1350, cz - 250) < 130) continue;
    const slope = seabedSlope(cx, cz, 4);
    if (rng.next() > 0.18 + slope * 1.6) continue;
    placed++;

    const roll = rng.next();
    const near = (spread: number): [number, number, number] => {
      const x = cx + rng.range(-spread, spread);
      const z = cz + rng.range(-spread, spread);
      return [x, z, ground(x, z)];
    };
    if (roll < 0.35) {
      const n = 3 + Math.floor(rng.next() * 4);
      const tall = rng.range(7, 30);
      for (let i = 0; i < n; i++) {
        const [x, z, y] = near(6);
        spire(b, rng, x, y, z, tall * rng.range(0.35, 1), rng.range(1.4, 3.6));
      }
      for (let i = 0; i < 3; i++) {
        const [x, z, y] = near(8);
        boulder(b, rng, x, y, z, rng.range(1, 2.6));
      }
    } else if (roll < 0.75) {
      const n = 5 + Math.floor(rng.next() * 6);
      for (let i = 0; i < n; i++) {
        const [x, z, y] = near(7);
        boulder(b, rng, x, y, z, rng.range(1.4, 5));
      }
    } else if (roll < 0.87) {
      const span = rng.range(8, 13);
      const a = rng.range(0, Math.PI);
      const dx = Math.cos(a) * span * 0.5;
      const dz = Math.sin(a) * span * 0.5;
      const h = rng.range(7, 11);
      const [x1, z1] = [cx + dx, cz + dz];
      const [x2, z2] = [cx - dx, cz - dz];
      spire(b, rng, x1, ground(x1, z1), z1, h, 3);
      spire(b, rng, x2, ground(x2, z2), z2, h, 3);
      const lintel = new IcosahedronGeometry(1, 2);
      roughen(lintel, 0.2, 4, rng.range(0, 99));
      b.add(lintel, ROCK_COLOURS[1] ?? 0x6e6558, {
        pos: [cx, Math.max(ground(x1, z1), ground(x2, z2)) + h * 0.93, cz],
        scale: [span * 0.62, 1.7, 2.6],
        rot: [0, -a, 0],
      });
    } else {
      const r = rng.range(7, 15);
      const h = rng.range(4, 10);
      const g = new CylinderGeometry(r * 0.8, r, h, 12, 3, false);
      const p = g.getAttribute('position') as BufferAttribute;
      for (let i = 0; i < p.count; i++) p.setY(i, p.getY(i) + h / 2);
      g.computeVertexNormals();
      roughen(g, r * 0.12, 0.8, rng.range(0, 99));
      b.add(g, ROCK_COLOURS[3] ?? 0x7a705e, { pos: [cx, gy - 1, cz], jitter: 0.15 });
      for (let i = 0; i < 5; i++) {
        const [x, z, y] = near(r * 1.3);
        boulder(b, rng, x, y, z, rng.range(0.8, 2.4));
      }
    }
  }
  return b.build();
}
