import { ClampToEdgeWrapping, DataTexture, LinearFilter, RedFormat, UnsignedByteType } from 'three';
import { clamp } from '../core/math.ts';
import type { WorldQuery } from '../domain/world.ts';

/** The patch of coast around the port that gets surf foam. */
export const SHORE_REGION = { minX: -760, minZ: -300, sizeX: 700, sizeZ: 600 } as const;

export interface ShoreRegion {
  minX: number;
  minZ: number;
  sizeX: number;
  sizeZ: number;
}
const WIDTH = 384;
const HEIGHT = 384;
const RANGE = 10;

/**
 * Seabed height around the port baked into a small texture, so the water shader can draw
 * surf foam where it is shallow. The bake runs over several frames within a time budget.
 */
export class ShoreMask {
  readonly texture: DataTexture;
  private readonly data = new Uint8Array(WIDTH * HEIGHT);
  private readonly world: WorldQuery;
  readonly region: ShoreRegion = { ...SHORE_REGION };
  private row = 0;

  constructor(world: WorldQuery) {
    this.world = world;
    this.data.fill(0);
    this.texture = new DataTexture(this.data, WIDTH, HEIGHT, RedFormat, UnsignedByteType);
    this.texture.minFilter = LinearFilter;
    this.texture.magFilter = LinearFilter;
    this.texture.wrapS = ClampToEdgeWrapping;
    this.texture.wrapT = ClampToEdgeWrapping;
    this.texture.generateMipmaps = false;
    this.texture.needsUpdate = true;
  }

  retarget(dx: number, dz: number): void {
    this.region.minX = SHORE_REGION.minX + dx;
    this.region.minZ = SHORE_REGION.minZ + dz;
    this.data.fill(0);
    this.row = 0;
  }

  get done(): boolean {
    return this.row >= HEIGHT;
  }

  update(budgetMs: number): void {
    if (this.done) return;
    const start = performance.now();
    while (this.row < HEIGHT && performance.now() - start < budgetMs) {
      const z = this.region.minZ + ((this.row + 0.5) / HEIGHT) * this.region.sizeZ;
      for (let i = 0; i < WIDTH; i++) {
        const x = this.region.minX + ((i + 0.5) / WIDTH) * this.region.sizeX;
        const h = this.world.seabedY(x, z);
        this.data[this.row * WIDTH + i] = Math.round(clamp((h + RANGE) / (2 * RANGE)) * 255);
      }
      this.row++;
    }
    this.texture.needsUpdate = true;
  }

  dispose(): void {
    this.texture.dispose();
  }
}
