import { type ProgressData, sanitizeProgress } from '../domain/progress.ts';
import type { AuthClient } from './auth.ts';
import type { BackendConfig } from './config.ts';

type Fetch = typeof fetch;

export class CloudError extends Error {}

/** The server understood the save and refused it: it breaks the game's rules. Retrying will not help. */
export class CloudRejected extends CloudError {}

/** Reads and writes the player's save in the `progress` table (one row per account). */
export class CloudProgress {
  private readonly config: BackendConfig;
  private readonly auth: AuthClient;
  private readonly http: Fetch;

  constructor(config: BackendConfig, auth: AuthClient, http: Fetch = (...args) => fetch(...args)) {
    this.config = config;
    this.auth = auth;
    this.http = http;
  }

  /** The saved progress, or null when the account has none yet. Throws CloudError when the server cannot be reached. */
  async load(): Promise<ProgressData | null> {
    const session = this.auth.session;
    const token = await this.auth.accessToken();
    if (!session || !token) throw new CloudError('not signed in');
    const url = `${this.config.url}/rest/v1/progress?select=data&user_id=eq.${encodeURIComponent(session.user.id)}`;
    let res: Response;
    try {
      res = await this.http(url, { headers: this.auth.headers(token) });
    } catch {
      throw new CloudError('network');
    }
    if (!res.ok) throw new CloudError(`load failed: ${res.status}`);
    const rows: unknown = await res.json();
    const first = Array.isArray(rows) ? (rows[0] as { data?: unknown } | undefined) : undefined;
    return first?.data ? sanitizeProgress(first.data) : null;
  }

  async save(data: ProgressData, keepalive = false): Promise<void> {
    const session = this.auth.session;
    const token = await this.auth.accessToken();
    if (!session || !token) throw new CloudError('not signed in');
    let res: Response;
    try {
      res = await this.http(`${this.config.url}/rest/v1/progress?on_conflict=user_id`, {
        method: 'POST',
        headers: { ...this.auth.headers(token), Prefer: 'resolution=merge-duplicates,return=minimal' },
        body: JSON.stringify({ user_id: session.user.id, data }),
        keepalive,
      });
    } catch {
      throw new CloudError('network');
    }
    if (!res.ok) {
      const text = await res.text().catch(() => '');
      if (res.status >= 400 && res.status < 500 && text.includes('progress_invalid')) throw new CloudRejected(text);
      throw new CloudError(`save failed: ${res.status}`);
    }
  }
}
