import { num, t } from '../i18n/index.ts';
import { speciesFact, speciesName, zoneName } from '../i18n/names.ts';
import { SPECIES, type SpeciesDef } from '../data/species.ts';
import { ZONES } from '../data/zones.ts';
import type { PhotoAlbum } from '../domain/photo-album.ts';
import { discoveryReward, type ProgressStore } from '../domain/progress.ts';
import { createSilhouette } from './silhouettes.ts';

const SUB_LENGTH_M = 5;

const fmt = (n: number): string => num(n);

function length(m: number): string {
  if (m < 1) return t('unit.cm', { n: Math.round(m * 100) });
  return t('unit.m', { n: num(m, m % 1 === 0 ? 0 : 1) });
}

function depthText(s: SpeciesDef): string {
  return t('unit.m', { n: `${fmt(s.depth[0])}–${fmt(s.depth[1])}` });
}

function zoneScale(depth: number): number {
  const last = ZONES.length - 1;
  for (let i = 0; i <= last; i++) {
    const z = ZONES[i];
    if (!z) continue;
    if (depth <= z.toM || i === last) {
      const t = Math.min(1, Math.max(0, (depth - z.fromM) / (z.toM - z.fromM)));
      return (i + t) / ZONES.length;
    }
  }
  return 1;
}

function el<K extends keyof HTMLElementTagNameMap>(tag: K, className?: string, text?: string): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

/** The species catalogue: filter by ocean zone, search, and read about each animal. */
export function createBestiary(progress: ProgressStore, album: PhotoAlbum): HTMLElement {
  const all = [...SPECIES].sort((a, b) => a.prefer - b.prefer) as SpeciesDef[];
  let zoneIndex = -1;
  let query = '';
  let selected: SpeciesDef | undefined = all[0];

  const root = el('div', 'bestiary');
  const bar = el('div', 'best-bar');
  const chips = el('div', 'chips');
  const search = el('input', 'search');
  search.type = 'search';
  search.placeholder = t('bestiary.search');
  search.setAttribute('aria-label', t('bestiary.search'));
  const grid = el('div', 'best-grid');
  const detail = el('aside', 'best-detail');
  const count = el('span', 'best-count');

  const visible = (): SpeciesDef[] => {
    const zone = zoneIndex >= 0 ? ZONES[zoneIndex] : undefined;
    const q = query.trim().toLowerCase();
    return all.filter((s) => {
      if (zone && (s.depth[1] < zone.fromM || s.depth[0] > zone.toM)) return false;
      if (!progress.isDiscovered(s.id)) return !q;
      return !q || speciesName(s.id).toLowerCase().includes(q) || s.latin.toLowerCase().includes(q);
    });
  };

  const drawChips = (): void => {
    const names: Array<[number, string]> = [[-1, t('bestiary.all')], ...ZONES.map((z, i): [number, string] => [i, zoneName(z.id)])];
    chips.replaceChildren(
      ...names.map(([i, name]) => {
        const b = el('button', i === zoneIndex ? 'chip active' : 'chip', name);
        b.type = 'button';
        b.addEventListener('click', () => {
          zoneIndex = i;
          drawChips();
          drawGrid();
        });
        return b;
      }),
    );
  };

  const drawGrid = (): void => {
    const list = visible();
    count.textContent = t('bestiary.found', { found: progress.discoveredCount(), total: all.length });
    if (list.length === 0) {
      grid.replaceChildren(el('p', 'best-empty', t('bestiary.none')));
      return;
    }
    if (!selected || !list.includes(selected)) selected = list[0];
    grid.replaceChildren(
      ...list.map((s) => {
        const found = progress.isDiscovered(s.id);
        const card = el(
          'button',
          `${s === selected ? `card r-${s.rarity} active` : `card r-${s.rarity}`}${found ? '' : ' locked'}`,
        );
        card.type = 'button';
        card.title = found ? s.latin : t('bestiary.unknown.card');
        card.append(
          createSilhouette(s),
          el('span', 'card-name', found ? speciesName(s.id) : '???'),
          el('span', 'card-depth', found ? depthText(s) : depthText(s)),
        );
        card.addEventListener('click', () => {
          selected = s;
          for (const n of grid.querySelectorAll('.card.active')) n.classList.remove('active');
          card.classList.add('active');
          drawDetail();
        });
        return card;
      }),
    );
    drawDetail();
  };

  const drawDetail = (): void => {
    const s = selected;
    if (!s) {
      detail.replaceChildren();
      return;
    }
    if (!progress.isDiscovered(s.id)) {
      const art = el('div', 'detail-art locked');
      art.append(createSilhouette(s));
      const hint = el('div', 'locked-note');
      hint.append(
        el('h3', undefined, t('bestiary.unknown.title')),
        el('p', undefined, t('bestiary.unknown.text', { depth: depthText(s) })),
        el('p', 'reward', t('bestiary.unknown.reward', { reward: fmt(discoveryReward(s)) })),
      );
      detail.replaceChildren(art, hint);
      detail.scrollTop = 0;
      return;
    }
    const head = el('div', 'detail-art');
    head.append(createSilhouette(s));

    const title = el('div', 'detail-title');
    title.append(el('h3', undefined, speciesName(s.id)), el('p', 'latin', s.latin));

    const tags = el('div', 'tags');
    tags.append(el('span', `tag r-${s.rarity}`, t(`bestiary.rarity.${s.rarity}`)));
    tags.append(el('span', 'tag', s.habitat === 'benthic' ? t('bestiary.benthic') : t('bestiary.pelagic')));
    if (s.glow !== undefined) tags.append(el('span', 'tag glowtag', t('bestiary.glows')));
    if (s.extinct) tags.append(el('span', 'tag extinct', t('bestiary.extinct')));

    const stats = el('dl', 'stats');
    const stat = (k: string, v: string): void => {
      stats.append(el('dt', undefined, k), el('dd', undefined, v));
    };
    stat(t('bestiary.stat.length'), length(s.sizeM));
    stat(t('bestiary.stat.speed'), t('unit.mps', { n: num(s.speed, s.speed % 1 === 0 ? 0 : 1) }));
    stat(t('bestiary.stat.temper'), t(`bestiary.temper.${s.temperament}`));
    stat(t('bestiary.stat.common'), t('unit.m', { n: fmt(s.prefer) }));
    stat(t('bestiary.stat.reward'), t('credits', { n: fmt(discoveryReward(s)) }));
    const shot = progress.value.photos[s.id];
    stat(t('bestiary.stat.bestShot'), shot ? t('bestiary.shotStat', { best: shot.best, count: shot.count }) : t('bestiary.noShot'));

    const depth = el('div', 'depth-scale');
    const track = el('div', 'depth-track');
    ZONES.forEach((z, i) => {
      const seg = el('i');
      seg.style.left = `${(i / ZONES.length) * 100}%`;
      seg.title = zoneName(z.id);
      track.append(seg);
    });
    const from = zoneScale(s.depth[0]);
    const to = zoneScale(s.depth[1]);
    const range = el('b', 'depth-range');
    range.style.left = `${from * 100}%`;
    range.style.width = `${Math.max(1.5, (to - from) * 100)}%`;
    const pref = el('em', 'depth-pref');
    pref.style.left = `${zoneScale(s.prefer) * 100}%`;
    track.append(range, pref);
    const labels = el('div', 'depth-labels');
    for (const z of ZONES) labels.append(el('span', undefined, zoneName(z.id).slice(0, 5)));
    depth.append(el('p', 'depth-caption', t('bestiary.habitat', { depth: depthText(s) })), track, labels);

    const size = el('div', 'size-compare');
    const ratio = Math.min(1, s.sizeM / 30);
    const sub = el('i', 'size-sub');
    sub.style.width = `${(SUB_LENGTH_M / 30) * 100}%`;
    const beast = el('b', 'size-beast');
    beast.style.width = `${Math.max(0.8, ratio * 100)}%`;
    size.append(
      el('p', 'depth-caption', t('bestiary.size', { length: SUB_LENGTH_M })),
      el('div', 'size-row', undefined),
    );
    size.querySelector('.size-row')?.append(sub, beast);

    const photo = album.get(s.id);
    const figure = photo ? el('figure', 'shot') : null;
    if (figure && photo) {
      const img = el('img');
      img.src = photo.image;
      img.alt = t('bestiary.photoAlt', { name: speciesName(s.id) });
      figure.append(img, el('figcaption', undefined, t('bestiary.photoCaption', { score: photo.score })));
    }
    detail.replaceChildren(head, title, tags, ...(figure ? [figure] : []), stats, depth, size, el('p', 'fact', speciesFact(s.id)));
    detail.scrollTop = 0;
  };

  search.addEventListener('input', () => {
    query = search.value;
    drawGrid();
  });

  bar.append(chips, el('div', 'best-search', undefined));
  bar.querySelector('.best-search')?.append(search, count);
  const body = el('div', 'best-body');
  body.append(grid, detail);
  root.append(bar, body);
  drawChips();
  drawGrid();
  return root;
}
