import {
  InstancedBufferAttribute,
  InstancedBufferGeometry,
  Mesh,
  PlaneGeometry,
  ShaderMaterial,
  Vector4,
} from 'three';
import { clamp } from '../core/math.ts';
import { createRng } from '../core/random.ts';
import type { SubState } from '../domain/submarine.ts';
import { WAVES } from '../domain/waves.ts';
import { COMMON_UNIFORMS, NOISE_GLSL } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

interface Puff {
  x: number;
  z: number;
  vx: number;
  vz: number;
  age: number;
  life: number;
  size0: number;
  size1: number;
  alpha: number;
  seed: number;
}

const vertexShader = /* glsl */ `
uniform float uTime;
uniform vec4 uWaves[4];
attribute vec4 iPos;   // x, z, size, seed
attribute vec4 iData;  // age (0..1), alpha
varying vec2 vUv;
varying float vAge;
varying float vAlpha;
varying float vSeed;
varying vec3 vWorldPos;

float surfaceHeight(vec2 p) {
  float h = 0.0;
  for (int i = 0; i < 4; i++) {
    float k = 6.28318530718 / uWaves[i].w;
    float amp = uWaves[i].z / k;
    h += amp * sin(k * dot(uWaves[i].xy, p) - sqrt(9.81 * k) * uTime);
  }
  return h;
}

void main() {
  float a = iPos.w * 6.28318530718;
  vec2 local = position.xy * iPos.z;
  vec2 rotated = vec2(local.x * cos(a) - local.y * sin(a), local.x * sin(a) + local.y * cos(a));
  vec2 xz = iPos.xy + rotated;
  vWorldPos = vec3(xz.x, surfaceHeight(xz) + 0.06, xz.y);
  vUv = position.xy + 0.5;
  vAge = iData.x;
  vAlpha = iData.y;
  vSeed = iPos.w;
  gl_Position = projectionMatrix * viewMatrix * vec4(vWorldPos, 1.0);
}
`;

const fragmentShader = /* glsl */ `
${COMMON_UNIFORMS}
${NOISE_GLSL}
varying vec2 vUv;
varying float vAge;
varying float vAlpha;
varying float vSeed;
varying vec3 vWorldPos;

void main() {
  float n = fbm(vUv * 6.0 + vSeed * 30.0 + uTime * 0.05);
  float r = length(vUv - 0.5) * 2.0;
  float shape = 1.0 - smoothstep(0.3, 1.0, r);
  // Foam breaks up into lacy patches as it ages.
  float cut = 0.3 + 0.35 * vAge;
  float a = shape * smoothstep(cut, cut + 0.25, n * 0.85 + shape * 0.5);
  a *= vAlpha * (1.0 - vAge) * smoothstep(0.0, 0.06, vAge + 0.02);
  if (!(a > 0.01)) discard;
  vec3 col = vec3(0.93, 0.96, 1.0) * (0.55 + 0.45 * uSunlight) + uSunColor * 0.12;
  float dist = length(vWorldPos - uCamPos);
  col = mix(uFogColor, col, exp(-uFogDensity * dist));
  gl_FragColor = vec4(col, min(a, 1.0));
}
`;

const SPAWN_REACH = 2.4;

/**
 * White foam patches that ride on the waves: a trail behind the propeller, a bow wave and a
 * slow ring of foam around the hull while the boat is on the surface.
 */
export class SurfaceFoam {
  readonly mesh: Mesh;
  private readonly capacity: number;
  private readonly puffs: Puff[] = [];
  private readonly geometry: InstancedBufferGeometry;
  private readonly material: ShaderMaterial;
  private readonly iPos: InstancedBufferAttribute;
  private readonly iData: InstancedBufferAttribute;
  private readonly rng = createRng(31415);
  private sternDebt = 0;
  private bowDebt = 0;
  private hullDebt = 0;

  constructor(uniforms: SceneUniforms, capacity: number) {
    this.capacity = capacity;
    const base = new PlaneGeometry(1, 1, 5, 5);
    this.geometry = new InstancedBufferGeometry();
    this.geometry.index = base.index;
    this.geometry.setAttribute('position', base.getAttribute('position'));
    this.iPos = new InstancedBufferAttribute(new Float32Array(capacity * 4), 4);
    this.iData = new InstancedBufferAttribute(new Float32Array(capacity * 4), 4);
    this.iPos.setUsage(35048);
    this.iData.setUsage(35048);
    this.geometry.setAttribute('iPos', this.iPos);
    this.geometry.setAttribute('iData', this.iData);
    this.geometry.instanceCount = 0;

    this.material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
        uWaves: { value: WAVES.map((w) => new Vector4(w.dirX, w.dirZ, w.steepness, w.wavelength)) },
      },
      vertexShader,
      fragmentShader,
      transparent: true,
      depthWrite: false,
      fog: false,
    });
    this.mesh = new Mesh(this.geometry, this.material);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 2;
  }

  update(dt: number, time: number, sub: SubState, thrust: number, underwater: boolean): void {
    this.mesh.visible = !underwater;
    this.age(dt);

    const surface = Math.abs(sub.position.y - waveAt(sub.position.x, sub.position.z, time)) < SPAWN_REACH;
    if (surface && dt > 0) this.emit(dt, sub, thrust);
    this.upload();
  }

  dispose(): void {
    this.geometry.dispose();
    this.material.dispose();
  }

  private age(dt: number): void {
    for (let i = this.puffs.length - 1; i >= 0; i--) {
      const p = this.puffs[i];
      if (!p) continue;
      p.age += dt / p.life;
      p.x += p.vx * dt;
      p.z += p.vz * dt;
      if (p.age >= 1) this.puffs.splice(i, 1);
    }
  }

  private emit(dt: number, sub: SubState, thrust: number): void {
    const speed = Math.hypot(sub.velocity.x, sub.velocity.z);
    const fx = -Math.sin(sub.yaw);
    const fz = -Math.cos(sub.yaw);
    const rx = Math.cos(sub.yaw);
    const rz = -Math.sin(sub.yaw);
    const at = (lateral: number, ahead: number): [number, number] => [
      sub.position.x + rx * lateral + fx * ahead,
      sub.position.z + rz * lateral + fz * ahead,
    ];

    this.sternDebt += dt * (1.5 + Math.abs(thrust) * 22 + speed * 3);
    while (this.sternDebt >= 1) {
      this.sternDebt -= 1;
      const [x, z] = at(this.rng.range(-0.6, 0.6), -3.9);
      this.push(x, z, -fx * speed * 0.15, -fz * speed * 0.15, this.rng.range(1.0, 1.8), this.rng.range(3.4, 5.4), this.rng.range(3.5, 5.5), 0.62);
    }
    if (speed > 1) {
      this.bowDebt += dt * speed * 3;
      while (this.bowDebt >= 1) {
        this.bowDebt -= 1;
        const side = this.rng.chance(0.5) ? 1 : -1;
        const [x, z] = at(side * 1.0, 2.8);
        this.push(x, z, rx * side * 0.5, rz * side * 0.5, 0.7, 1.8, this.rng.range(1.4, 2.2), 0.5);
      }
    }
    this.hullDebt += dt * 4;
    while (this.hullDebt >= 1) {
      this.hullDebt -= 1;
      const side = this.rng.chance(0.5) ? 1 : -1;
      const [x, z] = at(side * this.rng.range(0.9, 1.15), this.rng.range(-2.3, 2.6));
      this.push(x, z, rx * side * 0.12, rz * side * 0.12, 0.7, 1.9, this.rng.range(2.2, 3.4), 0.34);
    }
  }

  private push(x: number, z: number, vx: number, vz: number, size0: number, size1: number, life: number, alpha: number): void {
    if (this.puffs.length >= this.capacity) this.puffs.shift();
    this.puffs.push({ x, z, vx, vz, age: 0, life, size0, size1, alpha, seed: this.rng.next() });
  }

  private upload(): void {
    this.puffs.forEach((p, i) => {
      const grow = 1 - (1 - clamp(p.age)) ** 2;
      this.iPos.setXYZW(i, p.x, p.z, p.size0 + (p.size1 - p.size0) * grow, p.seed);
      this.iData.setXYZW(i, p.age, p.alpha, 0, 0);
    });
    this.geometry.instanceCount = this.puffs.length;
    this.iPos.needsUpdate = true;
    this.iData.needsUpdate = true;
  }
}

function waveAt(x: number, z: number, t: number): number {
  let h = 0;
  for (const w of WAVES) {
    const k = (2 * Math.PI) / w.wavelength;
    h += (w.steepness / k) * Math.sin(k * (w.dirX * x + w.dirZ * z) - Math.sqrt(9.81 * k) * t);
  }
  return h;
}
