import type { AuthClient } from './auth.ts';
import type { BackendConfig } from './config.ts';

export type Board = 'score' | 'species' | 'depth';

export interface BoardRow {
  readonly rank: number;
  readonly username: string;
  readonly species: number;
  readonly depth: number;
  readonly score: number;
  readonly isMe: boolean;
}

export interface BoardData {
  readonly rows: readonly BoardRow[];
  readonly me: BoardRow | null;
}

const COLUMN: Record<Board, string> = { score: 'score', species: 'species_count', depth: 'max_depth' };
export const TOP = 50;

type Fetch = typeof fetch;

interface RawProfile {
  username?: unknown;
  species_count?: unknown;
  max_depth?: unknown;
  score?: unknown;
}

const num = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : 0);

function toRow(raw: RawProfile, rank: number, isMe: boolean): BoardRow {
  return {
    rank,
    username: typeof raw.username === 'string' ? raw.username : '—',
    species: num(raw.species_count),
    depth: num(raw.max_depth),
    score: num(raw.score),
    isMe,
  };
}

/** Reads the public ranking. Works for guests too; signed-in players also get their own place. */
export async function fetchLeaderboard(
  config: BackendConfig,
  auth: AuthClient,
  board: Board,
  http: Fetch = (...args) => fetch(...args),
): Promise<BoardData> {
  const column = COLUMN[board];
  const select = 'username,species_count,max_depth,score';
  const get = (query: string, extra: Record<string, string> = {}, token?: string): Promise<Response> =>
    http(`${config.url}/rest/v1/profiles?${query}`, { headers: { ...auth.headers(token), ...extra } });

  const topRes = await get(`select=${select}&${column}=gt.0&order=${column}.desc,created_at.asc&limit=${TOP}`);
  if (!topRes.ok) throw new Error(`leaderboard failed: ${topRes.status}`);
  const topRaw: unknown = await topRes.json();
  const list = Array.isArray(topRaw) ? (topRaw as RawProfile[]) : [];

  const session = auth.session;
  let me: BoardRow | null = null;
  if (session) {
    const token = await auth.accessToken();
    const mineRes = await get(`select=${select}&user_id=eq.${encodeURIComponent(session.user.id)}`, {}, token ?? undefined);
    if (mineRes.ok) {
      const mine = ((await mineRes.json()) as RawProfile[])[0];
      if (mine) {
        const myValue = num(mine[column as keyof RawProfile]);
        const aheadRes = await get(`select=username&${column}=gt.${myValue}&limit=1`, { Prefer: 'count=exact' });
        const range = aheadRes.headers.get('content-range') ?? '';
        const ahead = Number(range.split('/')[1]);
        me = toRow(mine, Number.isFinite(ahead) ? ahead + 1 : 0, true);
      }
    }
  }

  const rows = list.map((p, i) => toRow(p, i + 1, me !== null && p.username === me.username));
  return { rows, me };
}
