import type { Archetype } from './species.ts';

/** What has to happen for a mission to be done. */
export type MissionGoal =
  | {
      readonly kind: 'photo';
      readonly species?: string;
      readonly archetype?: Archetype;
      readonly minDepth?: number;
      readonly minScore?: number;
    }
  | { readonly kind: 'discover'; readonly count: number; readonly archetype?: Archetype }
  | { readonly kind: 'depth'; readonly metres: number }
  | { readonly kind: 'portfolio'; readonly count: number; readonly minScore: number }
  | { readonly kind: 'pois'; readonly count: number };

export interface MissionDef {
  readonly id: string;
  readonly reward: number;
  readonly goal: MissionGoal;
}

