export interface LookDelta {
  dx: number;
  dy: number;
  zoom: number;
}

/** A finger drag turns the camera a little faster than a mouse drag of the same length. */
const TOUCH_LOOK = 1.3;

const BLOCKED_KEYS = new Set([
  'Space',
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'Tab',
]);

/** Keyboard and pointer state, polled once per frame. */
export class Input {
  private readonly down = new Set<string>();
  private readonly pressed = new Set<string>();
  private readonly virtual = new Set<string>();
  private readonly fingers = new Map<number, { x: number; y: number }>();
  private dragging = false;
  private dx = 0;
  private dy = 0;
  private wheel = 0;
  private readonly target: HTMLElement;
  private readonly cleanup: Array<() => void> = [];

  constructor(target: HTMLElement) {
    this.target = target;
    this.listen(window, 'keydown', (e) => this.onKeyDown(e as KeyboardEvent));
    this.listen(window, 'keyup', (e) => this.down.delete((e as KeyboardEvent).code));
    this.listen(window, 'blur', () => this.down.clear());
    this.listen(target, 'pointerdown', (e) => this.onPointerDown(e as PointerEvent));
    this.listen(window, 'pointermove', (e) => this.onPointerMove(e as PointerEvent));
    this.listen(window, 'pointerup', (e) => this.onPointerEnd(e as PointerEvent));
    this.listen(window, 'pointercancel', (e) => this.onPointerEnd(e as PointerEvent));
    this.listen(
      target,
      'wheel',
      (e) => {
        e.preventDefault();
        this.wheel += (e as WheelEvent).deltaY;
      },
      { passive: false },
    );
  }

  /** On-screen buttons act like keys: held while pressed, "pressed" on the frame they go down. */
  setVirtual(code: string, on: boolean): void {
    if (on) {
      if (!this.virtual.has(code)) this.pressed.add(code);
      this.virtual.add(code);
    } else {
      this.virtual.delete(code);
    }
  }

  isDown(...codes: string[]): boolean {
    return codes.some((code) => this.down.has(code) || this.virtual.has(code));
  }

  wasPressed(...codes: string[]): boolean {
    return codes.some((code) => this.pressed.has(code));
  }

  consumeLook(): LookDelta {
    const delta = { dx: this.dx, dy: this.dy, zoom: this.wheel };
    this.dx = 0;
    this.dy = 0;
    this.wheel = 0;
    return delta;
  }

  endFrame(): void {
    this.pressed.clear();
  }

  dispose(): void {
    for (const off of this.cleanup) off();
    this.cleanup.length = 0;
  }

  private onKeyDown(e: KeyboardEvent): void {
    // Typing in a form field (sign-in, search) must not move the submarine or be swallowed.
    if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (BLOCKED_KEYS.has(e.code)) e.preventDefault();
    if (!e.repeat) this.pressed.add(e.code);
    this.down.add(e.code);
  }

  private onPointerDown(e: PointerEvent): void {
    if (e.pointerType === 'touch') this.fingers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    else this.dragging = true;
    try {
      this.target.setPointerCapture(e.pointerId);
    } catch {
    }
  }

  private onPointerEnd(e: PointerEvent): void {
    this.fingers.delete(e.pointerId);
    if (e.pointerType !== 'touch') this.dragging = false;
  }

  private onPointerMove(e: PointerEvent): void {
    const last = this.fingers.get(e.pointerId);
    if (last) {
      if (this.fingers.size >= 2) {
        const others = [...this.fingers.entries()].filter(([id]) => id !== e.pointerId);
        const other = others[0]?.[1];
        if (other) {
          const before = Math.hypot(last.x - other.x, last.y - other.y);
          const after = Math.hypot(e.clientX - other.x, e.clientY - other.y);
          this.wheel -= (after - before) * 3;
        }
      } else {
        this.dx += (e.clientX - last.x) * TOUCH_LOOK;
        this.dy += (e.clientY - last.y) * TOUCH_LOOK;
      }
      last.x = e.clientX;
      last.y = e.clientY;
      return;
    }
    if (!this.dragging) return;
    this.dx += e.movementX;
    this.dy += e.movementY;
  }

  private listen(
    target: EventTarget,
    type: string,
    handler: (e: Event) => void,
    options?: AddEventListenerOptions,
  ): void {
    target.addEventListener(type, handler, options);
    this.cleanup.push(() => target.removeEventListener(type, handler, options));
  }
}
