import { BufferAttribute, BufferGeometry } from 'three';

export interface PolarGridOptions {
  rings: number;
  segments: number;
  radius: number;
  growth?: number;
}

export interface PolarGrid {
  readonly geometry: BufferGeometry;
  readonly offsets: Float32Array;
  readonly vertexCount: number;
}

/**
 * A disc made of concentric rings whose spacing grows exponentially with radius:
 * dense mesh where the camera looks closely, sparse where fog or distance hide it.
 * Positions are created flat (y = 0); callers displace them on the CPU or in a shader.
 */
export function createPolarGrid({ rings, segments, radius, growth = 6.5 }: PolarGridOptions): PolarGrid {
  const vertexCount = (rings + 1) * segments;
  const positions = new Float32Array(vertexCount * 3);
  const offsets = new Float32Array(vertexCount * 2);
  const scale = radius / (Math.exp(growth) - 1);

  for (let i = 0; i <= rings; i++) {
    const r = scale * (Math.exp((growth * i) / rings) - 1);
    for (let j = 0; j < segments; j++) {
      const a = (j / segments) * Math.PI * 2;
      const v = i * segments + j;
      const x = Math.cos(a) * r;
      const z = Math.sin(a) * r;
      positions[v * 3] = x;
      positions[v * 3 + 2] = z;
      offsets[v * 2] = x;
      offsets[v * 2 + 1] = z;
    }
  }

  const indices = new Uint32Array(rings * segments * 6);
  let k = 0;
  for (let i = 0; i < rings; i++) {
    for (let j = 0; j < segments; j++) {
      const j2 = (j + 1) % segments;
      const a = i * segments + j;
      const b = i * segments + j2;
      const c = (i + 1) * segments + j;
      const d = (i + 1) * segments + j2;
      indices[k++] = a;
      indices[k++] = b;
      indices[k++] = c;
      indices[k++] = b;
      indices[k++] = d;
      indices[k++] = c;
    }
  }

  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new BufferAttribute(positions, 3));
  geometry.setIndex(new BufferAttribute(indices, 1));
  return { geometry, offsets, vertexCount };
}
