import { t, type UiKey } from '../i18n/index.ts';
import type { BackendConfig } from './config.ts';

export interface AuthUser {
  readonly id: string;
  readonly email: string;
  readonly username: string;
}

export interface Session {
  readonly accessToken: string;
  readonly refreshToken: string;
  /** ms since the epoch. */
  readonly expiresAt: number;
  readonly user: AuthUser;
}

export type AuthResult =
  | { readonly ok: true; readonly session: Session }
  | { readonly ok: true; readonly session: null; readonly needsConfirmation: true }
  | { readonly ok: false; readonly message: string; readonly code?: string };

/** What the player came back with from a link in an e-mail. */
export interface LinkNotice {
  readonly kind: 'confirmed' | 'recovery' | 'error';
  readonly message: string;
}

export type SimpleResult = { readonly ok: true } | { readonly ok: false; readonly message: string };

export interface AuthStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

type Fetch = typeof fetch;
type Listener = (session: Session | null) => void;

const SESSION_KEY = 'luminara.session';
const REFRESH_MARGIN = 60_000;

const ERROR_KEYS: Readonly<Record<string, UiKey>> = {
  invalid_credentials: 'auth.invalid_credentials',
  user_already_exists: 'auth.user_already_exists',
  email_exists: 'auth.user_already_exists',
  weak_password: 'auth.weak_password',
  email_not_confirmed: 'auth.email_not_confirmed',
  over_request_rate_limit: 'auth.over_request_rate_limit',
  over_email_send_rate_limit: 'auth.over_email_send_rate_limit',
  signup_disabled: 'auth.signup_disabled',
  otp_expired: 'auth.otp_expired',
  same_password: 'auth.same_password',
  validation_failed: 'auth.validation_failed',
};

const errorText = (code: string): string | null => {
  const key = ERROR_KEYS[code];
  return key ? t(key) : null;
};

/** Checks a registration form; returns an error text or null when everything is fine. */
export function validateCredentials(email: string, password: string, username: string | null): string | null {
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return t('auth.badEmail');
  if (password.length < 8) return t('auth.shortPassword');
  if (username !== null && !/^[\p{L}\p{N}_-]{3,20}$/u.test(username)) {
    return t('auth.badName');
  }
  return null;
}

function parseUser(raw: unknown): AuthUser | null {
  if (typeof raw !== 'object' || raw === null) return null;
  const u = raw as Record<string, unknown>;
  if (typeof u.id !== 'string') return null;
  const meta = typeof u.user_metadata === 'object' && u.user_metadata !== null ? (u.user_metadata as Record<string, unknown>) : {};
  const email = typeof u.email === 'string' ? u.email : '';
  const username = typeof meta.username === 'string' && meta.username ? meta.username : email.split('@')[0] || t('auth.defaultName');
  return { id: u.id, email, username };
}

function parseSession(raw: unknown, now: number): Session | null {
  if (typeof raw !== 'object' || raw === null) return null;
  const r = raw as Record<string, unknown>;
  const user = parseUser(r.user);
  if (!user || typeof r.access_token !== 'string' || typeof r.refresh_token !== 'string') return null;
  const expiresIn = typeof r.expires_in === 'number' ? r.expires_in : 3600;
  const expiresAt = typeof r.expires_at === 'number' ? r.expires_at * 1000 : now + expiresIn * 1000;
  return { accessToken: r.access_token, refreshToken: r.refresh_token, expiresAt, user };
}

function errorInfo(body: unknown): { message: string; code?: string } {
  if (typeof body === 'object' && body !== null) {
    const b = body as Record<string, unknown>;
    const code = typeof b.error_code === 'string' ? b.error_code : typeof b.code === 'string' ? b.code : '';
    const known = errorText(code);
    if (known) return { message: known, code };
    const text = [b.msg, b.message, b.error_description].find((v): v is string => typeof v === 'string');
    if (text && /already registered|already exists/i.test(text)) return { message: t('auth.user_already_exists'), code: 'user_already_exists' };
    if (text && /invalid login/i.test(text)) return { message: t('auth.invalid_credentials'), code: 'invalid_credentials' };
    if (text) return { message: t('auth.server', { text }) };
  }
  return { message: t('auth.unknown') };
}

/** Email + password accounts over Supabase's GoTrue HTTP API (no SDK needed). */
export class AuthClient {
  private current: Session | null = null;
  private readonly listeners = new Set<Listener>();
  private refreshing: Promise<Session | null> | null = null;
  /** Where links in e-mails lead back to (this page). Must be listed in Supabase's Redirect URLs. */
  redirectTo: string | null = null;

  private readonly config: BackendConfig;
  private readonly storage: AuthStorage | null;
  private readonly http: Fetch;
  private readonly now: () => number;

  constructor(
    config: BackendConfig,
    storage: AuthStorage | null = null,
    http: Fetch = (...args) => fetch(...args),
    now: () => number = Date.now,
  ) {
    this.config = config;
    this.storage = storage;
    this.http = http;
    this.now = now;
    this.current = this.restore();
  }

  get session(): Session | null {
    return this.current;
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  async signUp(email: string, password: string, username: string): Promise<AuthResult> {
    const problem = validateCredentials(email, password, username);
    if (problem) return { ok: false, message: problem };
    const reply = await this.post(`/auth/v1/signup${this.redirectQuery('?')}`, { email, password, data: { username } });
    if (!reply.ok) return { ok: false, message: reply.message, ...(reply.code ? { code: reply.code } : {}) };
    const session = parseSession(reply.body, this.now());
    if (!session) return { ok: true, session: null, needsConfirmation: true };
    this.set(session);
    return { ok: true, session };
  }

  async signIn(email: string, password: string): Promise<AuthResult> {
    const problem = validateCredentials(email, password, null);
    if (problem) return { ok: false, message: problem };
    const reply = await this.post('/auth/v1/token?grant_type=password', { email, password });
    if (!reply.ok) return { ok: false, message: reply.message, ...(reply.code ? { code: reply.code } : {}) };
    const session = parseSession(reply.body, this.now());
    if (!session) return { ok: false, message: t('auth.unexpected') };
    this.set(session);
    return { ok: true, session };
  }

  async resetPassword(email: string): Promise<SimpleResult> {
    if (validateCredentials(email, 'x'.repeat(8), null)) return { ok: false, message: t('auth.badEmail') };
    const reply = await this.post(`/auth/v1/recover${this.redirectQuery('?')}`, { email });
    return reply.ok ? { ok: true } : { ok: false, message: reply.message };
  }

  async resendConfirmation(email: string): Promise<SimpleResult> {
    if (validateCredentials(email, 'x'.repeat(8), null)) return { ok: false, message: t('auth.badEmail') };
    const reply = await this.post(`/auth/v1/resend${this.redirectQuery('?')}`, { type: 'signup', email });
    return reply.ok ? { ok: true } : { ok: false, message: reply.message };
  }

  async updatePassword(password: string): Promise<SimpleResult> {
    if (password.length < 8) return { ok: false, message: t('auth.shortPassword') };
    const token = await this.accessToken();
    if (!token) return { ok: false, message: t('auth.signInFirst') };
    const reply = await this.post('/auth/v1/user', { password }, 'PUT', token);
    return reply.ok ? { ok: true } : { ok: false, message: reply.message };
  }

  async consumeRedirect(hash: string): Promise<LinkNotice | null> {
    const params = new URLSearchParams(hash.replace(/^#/, ''));
    const failure = params.get('error_code') ?? params.get('error');
    if (failure) {
      return { kind: 'error', message: errorText(failure) ?? t('auth.linkFailed') };
    }
    const access = params.get('access_token');
    const refresh = params.get('refresh_token');
    if (!access || !refresh) return null;
    const reply = await this.post('/auth/v1/user', undefined, 'GET', access);
    const user = reply.ok ? parseUser(reply.body) : null;
    if (!user) return { kind: 'error', message: reply.ok ? t('auth.unexpected') : reply.message };
    const expiresIn = Number(params.get('expires_in')) || 3600;
    this.set({ accessToken: access, refreshToken: refresh, expiresAt: this.now() + expiresIn * 1000, user });
    return params.get('type') === 'recovery'
      ? { kind: 'recovery', message: t('auth.recovery') }
      : { kind: 'confirmed', message: t('auth.confirmed') };
  }

  private redirectQuery(prefix: string): string {
    return this.redirectTo ? `${prefix}redirect_to=${encodeURIComponent(this.redirectTo)}` : '';
  }

  async signOut(): Promise<void> {
    const session = this.current;
    this.set(null);
    if (!session) return;
    try {
      await this.http(`${this.config.url}/auth/v1/logout`, {
        method: 'POST',
        headers: this.headers(session.accessToken),
      });
    } catch {
    }
  }

  async accessToken(): Promise<string | null> {
    const session = this.current;
    if (!session) return null;
    if (session.expiresAt - REFRESH_MARGIN > this.now()) return session.accessToken;
    const fresh = await this.refresh();
    return fresh?.accessToken ?? null;
  }

  refresh(): Promise<Session | null> {
    if (this.refreshing) return this.refreshing;
    const session = this.current;
    if (!session) return Promise.resolve(null);
    this.refreshing = (async () => {
      const reply = await this.post('/auth/v1/token?grant_type=refresh_token', { refresh_token: session.refreshToken });
      if (reply.ok) {
        const next = parseSession(reply.body, this.now());
        if (next) {
          this.set(next);
          return next;
        }
      } else if (reply.status >= 400 && reply.status < 500) {
        this.set(null);
        return null;
      }
      return session;
    })().finally(() => {
      this.refreshing = null;
    });
    return this.refreshing;
  }

  headers(token?: string): Record<string, string> {
    const headers: Record<string, string> = { apikey: this.config.anonKey, 'Content-Type': 'application/json' };
    if (token) headers.Authorization = `Bearer ${token}`;
    return headers;
  }

  private async post(
    path: string,
    body: unknown,
    method: 'POST' | 'PUT' | 'GET' = 'POST',
    token?: string,
  ): Promise<{ ok: true; body: unknown } | { ok: false; message: string; code?: string; status: number }> {
    try {
      const init: RequestInit = { method, headers: this.headers(token) };
      if (body !== undefined) init.body = JSON.stringify(body);
      const res = await this.http(`${this.config.url}${path}`, init);
      let json: unknown = null;
      try {
        json = await res.json();
      } catch {
        json = null;
      }
      if (!res.ok) return { ok: false, ...errorInfo(json), status: res.status };
      return { ok: true, body: json };
    } catch {
      return { ok: false, message: t('auth.network'), status: 0 };
    }
  }

  private set(session: Session | null): void {
    this.current = session;
    try {
      if (session) this.storage?.setItem(SESSION_KEY, JSON.stringify(session));
      else this.storage?.removeItem(SESSION_KEY);
    } catch {
    }
    for (const l of this.listeners) l(session);
  }

  private restore(): Session | null {
    try {
      const text = this.storage?.getItem(SESSION_KEY);
      if (!text) return null;
      const r = JSON.parse(text) as Record<string, unknown>;
      const u = r.user as Record<string, unknown> | undefined;
      if (
        typeof r.accessToken !== 'string' ||
        typeof r.refreshToken !== 'string' ||
        typeof r.expiresAt !== 'number' ||
        typeof u?.id !== 'string' ||
        typeof u.email !== 'string' ||
        typeof u.username !== 'string'
      ) {
        return null;
      }
      return {
        accessToken: r.accessToken,
        refreshToken: r.refreshToken,
        expiresAt: r.expiresAt,
        user: { id: u.id, email: u.email, username: u.username },
      };
    } catch {
      return null;
    }
  }
}
