import { clamp, damp, wrapPi } from '../core/math.ts';
import { forwardFromAngles, type Vec3 } from '../core/vec3.ts';
import { BALANCE, SUB } from '../data/balance.ts';
import type { PortService } from '../data/ports.ts';
import type { SubSpec } from './spec.ts';
import { WORLD_BOUNDS } from './world.ts';

export interface SubControls {
  thrust: number;
  turn: number;
  lift: number;
  emergency: boolean;
}

export const IDLE_CONTROLS: Readonly<SubControls> = {
  thrust: 0,
  turn: 0,
  lift: 0,
  emergency: false,
};

export type EmergencyReason = 'manual' | 'oxygen' | 'battery' | 'hull';

export interface SubState {
  position: Vec3;
  velocity: Vec3;
  yaw: number;
  pitch: number;
  roll: number;
  yawRate: number;
  oxygen: number;
  battery: number;
  hull: number;
  lightOn: boolean;
  submerged: boolean;
  emergency: EmergencyReason | null;
}

export type WarningKind = 'oxygen' | 'battery' | 'hull' | 'pressure';

export type SubEvent =
  | { type: 'submerged' }
  | { type: 'surfaced' }
  | { type: 'emergency'; reason: EmergencyReason }
  | { type: 'rescued'; reason: EmergencyReason }
  | { type: 'impact'; speed: number; damage: number }
  | { type: 'warning'; kind: WarningKind }
  | { type: 'boundary' };

/** What the submarine needs to know about the world around it. */
export interface SubEnvironment {
  seabedY(x: number, z: number): number;
  surfaceY(x: number, z: number): number;
}

export interface Spawn {
  x: number;
  z: number;
  yaw: number;
}

export class Submarine {
  readonly state: SubState;
  private spec: SubSpec;
  private service: PortService = { oxygen: 1, battery: 1, hull: 0 };
  private readonly armed = new Set<WarningKind>();

  constructor(spec: SubSpec, spawn: Spawn) {
    this.spec = spec;
    this.state = {
      position: { x: spawn.x, y: -SUB.draft, z: spawn.z },
      velocity: { x: 0, y: 0, z: 0 },
      yaw: spawn.yaw,
      pitch: 0,
      roll: 0,
      yawRate: 0,
      oxygen: spec.oxygenCapacity,
      battery: spec.batteryCapacity,
      hull: 100,
      lightOn: true,
      submerged: false,
      emergency: null,
    };
  }

  get depth(): number {
    return Math.max(0, -this.state.position.y);
  }

  get lightActive(): boolean {
    return this.state.lightOn && this.state.battery > 0;
  }

  get currentSpec(): SubSpec {
    return this.spec;
  }

  /** Installs new hardware. Reserves scale so an upgrade never leaves tanks half-empty. */
  setService(service: PortService): void {
    this.service = service;
  }

  setSpec(spec: SubSpec): void {
    const s = this.state;
    const oxygenShare = this.spec.oxygenCapacity > 0 ? s.oxygen / this.spec.oxygenCapacity : 1;
    const batteryShare = this.spec.batteryCapacity > 0 ? s.battery / this.spec.batteryCapacity : 1;
    this.spec = spec;
    s.oxygen = spec.oxygenCapacity * clamp(oxygenShare);
    s.battery = spec.batteryCapacity * clamp(batteryShare);
  }

  /** Fully recharges and repairs, as the port crew would. */
  restoreAll(): void {
    const s = this.state;
    s.oxygen = this.spec.oxygenCapacity;
    s.battery = this.spec.batteryCapacity;
    s.hull = 100;
    s.emergency = null;
    this.armed.clear();
  }

  placeAtSurface(spawn: Spawn, env: SubEnvironment): void {
    const s = this.state;
    s.position.x = spawn.x;
    s.position.z = spawn.z;
    s.position.y = env.surfaceY(spawn.x, spawn.z) - SUB.draft;
    s.velocity.x = 0;
    s.velocity.y = 0;
    s.velocity.z = 0;
    s.yaw = spawn.yaw;
    s.pitch = 0;
    s.roll = 0;
    s.yawRate = 0;
    s.submerged = false;
    s.emergency = null;
  }

  consumeBattery(amount: number): void {
    this.state.battery = Math.max(0, this.state.battery - amount);
  }

  spendBattery(amount: number): boolean {
    if (this.state.battery < amount) return false;
    this.state.battery -= amount;
    return true;
  }

  bump(nx: number, ny: number, nz: number, overlap: number, bodyVelocity: Vec3, mass: number): number {
    const s = this.state;
    s.position.x += nx * overlap;
    s.position.y += ny * overlap;
    s.position.z += nz * overlap;
    const rvx = s.velocity.x - bodyVelocity.x;
    const rvy = s.velocity.y - bodyVelocity.y;
    const rvz = s.velocity.z - bodyVelocity.z;
    const closing = -(rvx * nx + rvy * ny + rvz * nz);
    if (closing <= 0) return 0;
    const bounce = closing * 1.3;
    s.velocity.x += nx * bounce;
    s.velocity.y += ny * bounce;
    s.velocity.z += nz * bounce;
    const damage = Math.max(0, closing - BALANCE.hull.bumpThreshold) * BALANCE.hull.bumpDamagePerMs * mass;
    s.hull = Math.max(0, s.hull - damage);
    return damage;
  }

  toggleLight(): boolean {
    this.state.lightOn = !this.state.lightOn;
    return this.state.lightOn;
  }

  rescue(): void {
    const s = this.state;
    s.battery = Math.max(s.battery, this.spec.batteryCapacity * BALANCE.rescue.batteryAfter);
    s.hull = Math.max(s.hull, BALANCE.rescue.hullAfter);
    s.oxygen = this.spec.oxygenCapacity;
    this.armed.clear();
  }

  update(dt: number, controls: Readonly<SubControls>, env: SubEnvironment): SubEvent[] {
    const events: SubEvent[] = [];
    const s = this.state;
    const spec = this.spec;

    this.checkEmergency(controls, events);

    const emergency = s.emergency !== null;
    const powered = s.battery > 0;
    const thrust = emergency || !powered ? 0 : clamp(controls.thrust, -1, 1);
    const lift = emergency || !powered ? 0 : clamp(controls.lift, -1, 1);
    const turn = powered ? clamp(controls.turn, -1, 1) : 0;

    s.yawRate = damp(s.yawRate, turn * spec.turnRate, 3, dt);
    s.yaw = wrapPi(s.yaw + s.yawRate * dt);

    const forward = forwardFromAngles(s.yaw, 0);
    const speedTarget =
      thrust >= 0 ? thrust * spec.maxSpeed : thrust * spec.maxSpeed * SUB.reverseFactor;
    const verticalTarget = emergency ? spec.emergencySpeed : lift * spec.maxVertical;
    s.velocity.x = damp(s.velocity.x, forward.x * speedTarget, spec.agility, dt);
    s.velocity.z = damp(s.velocity.z, forward.z * speedTarget, spec.agility, dt);
    s.velocity.y = damp(s.velocity.y, verticalTarget, spec.agility * 0.8, dt);

    const prevX = s.position.x;
    const prevZ = s.position.z;
    s.position.x += s.velocity.x * dt;
    s.position.y += s.velocity.y * dt;
    s.position.z += s.velocity.z * dt;

    this.applyBounds(events);
    this.applySeabed(prevX, prevZ, events, env);
    this.applySurface(dt, env);
    this.updateAttitude(dt);

    const below = env.surfaceY(s.position.x, s.position.z) - s.position.y;
    if (!s.submerged && below > SUB.submergedBelow) {
      s.submerged = true;
      events.push({ type: 'submerged' });
    } else if (s.submerged && below < SUB.surfacedBelow) {
      s.submerged = false;
      events.push({ type: 'surfaced' });
      if (s.emergency !== null) {
        events.push({ type: 'rescued', reason: s.emergency });
        s.emergency = null;
      }
    }

    this.updateResources(dt, thrust, lift, powered);
    this.updateHullPressure(dt);
    this.updateWarnings(events);

    return events;
  }

  private checkEmergency(controls: Readonly<SubControls>, events: SubEvent[]): void {
    const s = this.state;
    if (s.emergency !== null || !s.submerged) return;
    let reason: EmergencyReason | null = null;
    if (s.oxygen <= 0) reason = 'oxygen';
    else if (s.hull <= 0) reason = 'hull';
    else if (s.battery <= 0) reason = 'battery';
    else if (controls.emergency) reason = 'manual';
    if (reason !== null) {
      s.emergency = reason;
      events.push({ type: 'emergency', reason });
    }
  }

  private applyBounds(events: SubEvent[]): void {
    const p = this.state.position;
    const v = this.state.velocity;
    let hit = false;
    if (p.x < WORLD_BOUNDS.minX || p.x > WORLD_BOUNDS.maxX) {
      p.x = clamp(p.x, WORLD_BOUNDS.minX, WORLD_BOUNDS.maxX);
      v.x = 0;
      hit = true;
    }
    if (p.z < WORLD_BOUNDS.minZ || p.z > WORLD_BOUNDS.maxZ) {
      p.z = clamp(p.z, WORLD_BOUNDS.minZ, WORLD_BOUNDS.maxZ);
      v.z = 0;
      hit = true;
    }
    if (hit) events.push({ type: 'boundary' });
  }

  private applySeabed(prevX: number, prevZ: number, events: SubEvent[], env: SubEnvironment): void {
    const s = this.state;
    const floor = env.seabedY(s.position.x, s.position.z) + SUB.radius;
    if (s.position.y >= floor) return;

    if (floor > -SUB.submergedBelow) {
      s.position.x = prevX;
      s.position.z = prevZ;
      s.velocity.x = 0;
      s.velocity.z = 0;
      const safeFloor = env.seabedY(s.position.x, s.position.z) + SUB.radius;
      if (s.position.y < safeFloor) s.position.y = safeFloor;
      return;
    }

    const impact = Math.max(0, -s.velocity.y);
    s.position.y = floor;
    if (s.velocity.y < 0) s.velocity.y = 0;
    if (impact > BALANCE.hull.impactThreshold) {
      const damage = (impact - BALANCE.hull.impactThreshold) * BALANCE.hull.impactDamagePerMs;
      s.hull = Math.max(0, s.hull - damage);
      events.push({ type: 'impact', speed: impact, damage });
    }
  }

  private applySurface(dt: number, env: SubEnvironment): void {
    const s = this.state;
    const ceiling = env.surfaceY(s.position.x, s.position.z) - SUB.draft;
    if (s.position.y > ceiling) {
      s.position.y = damp(s.position.y, ceiling, 12, dt);
      if (s.velocity.y > 0) s.velocity.y = 0;
    }
  }

  private updateAttitude(dt: number): void {
    const s = this.state;
    const horizontal = Math.hypot(s.velocity.x, s.velocity.z);
    const targetPitch = clamp(Math.atan2(s.velocity.y, Math.max(2, horizontal)), -0.6, 0.6);
    s.pitch = damp(s.pitch, targetPitch, 3, dt);
    s.roll = damp(s.roll, clamp(s.yawRate * 0.45, -0.4, 0.4), 3, dt);
  }

  private updateResources(dt: number, thrust: number, lift: number, powered: boolean): void {
    const s = this.state;
    const spec = this.spec;
    if (s.submerged) {
      s.oxygen = Math.max(0, s.oxygen - BALANCE.oxygen.consumption * dt);
      const load =
        BALANCE.battery.systems +
        (this.lightActive ? BALANCE.battery.light : 0) +
        (powered ? Math.abs(thrust) * BALANCE.battery.thrust + Math.abs(lift) * BALANCE.battery.lift : 0);
      s.battery = Math.max(0, s.battery - load * dt);
    } else {
      const service = this.service;
      s.oxygen = Math.min(spec.oxygenCapacity, s.oxygen + BALANCE.oxygen.surfaceRecovery * service.oxygen * dt);
      s.battery = Math.min(spec.batteryCapacity, s.battery + BALANCE.battery.surfaceRecharge * service.battery * dt);
      if (service.hull > 0) s.hull = Math.min(100, s.hull + service.hull * dt);
    }
  }

  private updateHullPressure(dt: number): void {
    const s = this.state;
    const excess = this.depth - this.spec.crushDepth;
    if (excess <= 0) return;
    const damage = (BALANCE.hull.crushBase + BALANCE.hull.crushPerMetre * excess) * dt;
    s.hull = Math.max(0, s.hull - damage);
  }

  private updateWarnings(events: SubEvent[]): void {
    const s = this.state;
    const spec = this.spec;
    this.warn('oxygen', s.submerged && s.oxygen < spec.oxygenCapacity * 0.2, events);
    this.warn('battery', s.submerged && s.battery < spec.batteryCapacity * 0.2, events);
    this.warn('hull', s.hull < BALANCE.hull.warnBelow, events);
    this.warn('pressure', this.depth > spec.crushDepth * 0.9, events);
  }

  private warn(kind: WarningKind, active: boolean, events: SubEvent[]): void {
    if (active) {
      if (!this.armed.has(kind)) {
        this.armed.add(kind);
        events.push({ type: 'warning', kind });
      }
    } else {
      this.armed.delete(kind);
    }
  }
}
