import { fbm2 } from '../core/noise.ts';
import { createRng } from '../core/random.ts';
import { hashInts } from '../core/random.ts';
import { seabedSlope, type WorldQuery } from './world.ts';

export type FloraKind =
  | 'rock'
  | 'kelp'
  | 'grass'
  | 'coralBranch'
  | 'coralTable'
  | 'coralBrain'
  | 'coralFan';

const CORAL_KINDS = ['coralBranch', 'coralTable', 'coralBrain', 'coralFan', 'coralBranch', 'coralBrain'] as const;

export interface FloraItem {
  readonly kind: FloraKind;
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly yaw: number;
  readonly width: number;
  readonly height: number;
  readonly tint: number;
}

/** Side of one scatter cell, metres. */
export const CELL = 10;
const ATTEMPTS = 10;
const SEED = 4242;

/**
 * Deterministic seabed decoration for one cell: the same cell always yields the same items,
 * so plants and rocks stay put as the camera travels and can be generated lazily.
 */
export function scatterCell(cx: number, cz: number, world: WorldQuery): FloraItem[] {
  const rng = createRng(hashInts(cx, cz, SEED));
  const items: FloraItem[] = [];
  for (let i = 0; i < ATTEMPTS; i++) {
    const x = (cx + rng.next()) * CELL;
    const z = (cz + rng.next()) * CELL;
    const y = world.seabedY(x, z);
    const depth = -y;
    if (depth < 0.6) continue;

    const slope = seabedSlope(x, z, 2);
    const patch = fbm2(x * 0.018, z * 0.018, 3, SEED + 1);
    const roll = rng.next();
    const tint = rng.next();
    const yaw = rng.range(0, Math.PI * 2);

    const reef = Math.exp(-(((x + 20) / 330) ** 2));
    if (reef > 0.15 && depth >= 3 && depth <= 62 && slope < 0.7) {
      const colony = fbm2(x * 0.03 + 40, z * 0.03 - 17, 3, SEED + 7);
      if (colony > 0.46 && roll < 0.2 + 0.7 * reef * Math.min(1, (colony - 0.46) * 8)) {
        const kind = CORAL_KINDS[Math.floor(rng.next() * CORAL_KINDS.length)] ?? 'coralBranch';
        const size = rng.range(0.7, 1.6) * (kind === 'coralTable' ? 1.4 : 1);
        items.push({ kind, x, y, z, yaw, width: size, height: size * rng.range(0.7, 1.2), tint });
        continue;
      }
    }
    if (depth >= 3 && depth <= 50 && slope < 0.55 && patch > 0.52 && roll < 0.35) {
      items.push({ kind: 'kelp', x, y, z, yaw, width: rng.range(0.9, 1.5), height: rng.range(3, 8), tint });
      continue;
    }
    if (depth >= 1.5 && depth <= 90 && slope < 0.4 && patch > 0.4 && roll < 0.8) {
      items.push({ kind: 'grass', x, y, z, yaw, width: rng.range(0.7, 1.3), height: rng.range(0.4, 1.1), tint });
      continue;
    }
    const rockChance = 0.05 + slope * 0.7 + (patch > 0.6 ? 0.1 : 0);
    if (depth < 4200 && rng.next() < rockChance) {
      const size = rng.range(0.35, 1.2) * (rng.chance(0.12) ? 3 : 1);
      items.push({ kind: 'rock', x, y, z, yaw, width: size, height: size * rng.range(0.55, 1), tint });
    }
  }
  return items;
}
