import {
  BufferAttribute,
  BufferGeometry,
  Color,
  DoubleSide,
  InstancedBufferAttribute,
  InstancedBufferGeometry,
  Mesh,
  ShaderMaterial,
} from 'three';
import { getSpecies } from '../data/species.ts';
import type { School } from '../domain/school.ts';
import { COMMON_UNIFORMS, SAFE_GLSL } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

const RINGS = 14;
const SIDES = 8;
const VISUAL_SCALE = 3.8;
const MIN_VISUAL_SIZE = 0.6;

function buildFishGeometry(): BufferGeometry {
  const positions: number[] = [];
  const indices: number[] = [];
  for (let r = 0; r <= RINGS; r++) {
    const t = r / RINGS;
    const z = t - 0.5;
    let rx: number;
    let ry: number;
    if (t < 0.8) {
      const e = Math.sin(Math.PI * t ** 0.7) ** 0.8;
      rx = 0.085 * e;
      ry = 0.15 * e;
    } else {
      const f = (t - 0.8) / 0.2;
      rx = 0.012;
      ry = 0.07 + f * 0.15;
    }
    for (let s = 0; s < SIDES; s++) {
      const a = (s / SIDES) * Math.PI * 2;
      positions.push(Math.cos(a) * rx, Math.sin(a) * ry, z);
    }
  }
  for (let r = 0; r < RINGS; r++) {
    for (let s = 0; s < SIDES; s++) {
      const a = r * SIDES + s;
      const b = r * SIDES + ((s + 1) % SIDES);
      const c = a + SIDES;
      const d = b + SIDES;
      indices.push(a, c, b, b, c, d);
    }
  }
  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

const vertexShader = /* glsl */ `
uniform float uTime;
attribute vec3 iPos;
attribute vec3 iDir;
attribute vec4 iData; // x = size, y = phase, z = tail-beat rate
attribute vec3 iBody;
attribute vec3 iBack;
attribute vec3 iGlow;
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying vec3 vBody;
varying vec3 vBack;
varying vec3 vGlow;
varying float vUp;
varying vec3 vLocal;
varying float vPattern;
varying float vMark;

void main() {
  float size = iData.x;
  vec3 f = normalize(iDir);
  vec3 r = cross(f, vec3(0.0, 1.0, 0.0));
  if (dot(r, r) < 1e-4) r = vec3(1.0, 0.0, 0.0);
  r = normalize(r);
  vec3 u = cross(r, f);
  mat3 basis = mat3(r, u, -f);

  vec3 p = position;
  // Body wave that grows towards the tail.
  float tail = smoothstep(-0.25, 0.5, p.z);
  p.x += sin(uTime * iData.z + iData.y * 6.2831 - p.z * 7.0) * 0.07 * tail;

  vWorldPos = iPos + basis * (p * size);
  vNormalW = basis * normal;
  vBody = iBody;
  vBack = iBack;
  vGlow = iGlow;
  vUp = position.y / 0.15;
  vLocal = position;
  vPattern = 0.0;
  vMark = 0.0;
  gl_Position = projectionMatrix * viewMatrix * vec4(vWorldPos, 1.0);
}
`;

export const CREATURE_FRAGMENT = /* glsl */ `
${COMMON_UNIFORMS}
${SAFE_GLSL}
uniform vec3 uBeamPos;
uniform vec3 uBeamDir;
uniform vec3 uBeamParams;
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying vec3 vBody;
varying vec3 vBack;
varying vec3 vGlow;
varying float vUp;
varying vec3 vLocal;
varying float vPattern;
varying float vMark;
uniform float uAlpha;

void main() {
  vec3 N = safeNormalize(vNormalW, vec3(0.0, 1.0, 0.0));
  if (!gl_FrontFacing) N = -N;
  float depth = max(0.0, -vWorldPos.y);

  // Darker back, silvery belly.
  vec3 albedo = mix(vBody, vBack, smoothstep(0.15, 0.85, vUp));
  albedo = mix(albedo, vec3(0.85, 0.9, 0.95), smoothstep(-0.2, -0.95, vUp) * 0.5);
  if (vPattern > 0.5 && vPattern < 1.5) {
    // Vertical bands along the body.
    float band = smoothstep(0.35, 0.5, abs(fract(vLocal.z * 5.0) - 0.5) * 2.0 - 0.1);
    albedo = mix(albedo, vBack * 0.3, band * smoothstep(-0.5, 0.2, vUp));
  } else if (vPattern > 1.5 && vPattern < 2.5) {
    // Pale spots.
    float sp = sin(vLocal.x * 38.0) * sin(vLocal.z * 31.0) * sin(vLocal.y * 38.0 + 1.0);
    albedo = mix(albedo, vec3(0.9, 0.92, 0.85), smoothstep(0.35, 0.5, sp) * 0.85);
  } else if (vPattern > 2.5) {
    // Sharp dark back, white belly.
    albedo = mix(vec3(0.94, 0.95, 0.96), vBody * 0.45, smoothstep(-0.12, 0.08, vUp));
  }

  vec3 absorb = exp(-vec3(0.14, 0.045, 0.028) * depth);
  vec3 sun = uSunColor * (0.25 + 0.95 * max(dot(N, uSunDir), 0.0)) * absorb;
  vec3 ambient = vec3(0.22, 0.32, 0.44) * absorb * (0.55 + 0.45 * N.y) + vec3(0.002, 0.004, 0.006);

  vec3 fromLamp = vWorldPos - uBeamPos;
  float lampDist = length(fromLamp);
  vec3 L = fromLamp / max(lampDist, 0.001);
  float cone = smoothstep(uBeamParams.y, uBeamParams.y + 0.1, dot(L, uBeamDir));
  float reach = 1.0 - smoothstep(uBeamParams.x * 0.3, uBeamParams.x, lampDist);
  float falloff = 1.0 / (1.0 + 0.0012 * lampDist * lampDist);
  vec3 beam = vec3(0.85, 0.96, 1.0) * uBeamParams.z * cone * reach * falloff * (0.35 + 0.65 * max(dot(N, -L), 0.0));

  float markEye = step(0.5, vMark) * (1.0 - step(1.5, vMark));
  float markFin = step(1.5, vMark) * (1.0 - step(2.5, vMark));
  float markDark = step(2.5, vMark);
  albedo = mix(albedo, vec3(0.012), markEye);
  albedo = mix(albedo, mix(vBody, vBack, 0.5) * 1.2 + 0.05, markFin);
  albedo = mix(albedo, albedo * 0.22, markDark);

  float camDist = length(vWorldPos - uCamPos);
  vec3 V = (uCamPos - vWorldPos) / max(camDist, 0.001);
  // Fine scale sheen, faded out with distance so it never aliases.
  float scales = sin(vLocal.z * 210.0 + vLocal.y * 90.0) * sin(vLocal.y * 240.0 - vLocal.z * 70.0);
  albedo *= 1.0 + 0.1 * scales * (1.0 - smoothstep(4.0, 16.0, camDist)) * (1.0 - markEye - markFin);

  vec3 lit = albedo * (sun + ambient + beam);
  // Glossy highlights from the sun and the headlight; eyes are the shiniest.
  float gloss = 0.12 + 1.6 * markEye + 0.05 * markFin;
  vec3 H1 = normalize(uSunDir + V);
  lit += uSunColor * absorb * pow(max(dot(N, H1), 0.0), 36.0) * gloss;
  vec3 H2 = normalize(-L + V);
  lit += vec3(0.85, 0.96, 1.0) * uBeamParams.z * cone * reach * falloff * pow(max(dot(N, H2), 0.0), 30.0) * gloss * 2.0;
  // Soft rim light so bodies keep their outline in the blue.
  float rim = pow(1.0 - max(dot(N, V), 0.0), 3.0);
  lit += vec3(0.1, 0.22, 0.3) * absorb * rim * (0.5 + 0.5 * uSunlight);
  // Photophores glow on the underside, more visible in the dark.
  lit += vGlow * smoothstep(0.1, -0.7, vUp) * (1.0 - 0.8 * uSunlight) * 2.5;

  float dist = length(vWorldPos - uCamPos);
  vec3 col = mix(uFogColor, lit, exp(-uFogDensity * dist));
  gl_FragColor = vec4(sanitize(col, uFogColor), uAlpha);
}
`;

/** Draws every school as one instanced mesh; positions come from the simulation each frame. */
export class FishSchools {
  readonly mesh: Mesh;
  private capacity: number;
  private readonly geometry: InstancedBufferGeometry;
  private readonly material: ShaderMaterial;
  private readonly iPos: InstancedBufferAttribute;
  private readonly iDir: InstancedBufferAttribute;
  private readonly iData: InstancedBufferAttribute;
  private readonly iBody: InstancedBufferAttribute;
  private readonly iBack: InstancedBufferAttribute;
  private readonly iGlow: InstancedBufferAttribute;
  private readonly colour = new Color();

  constructor(uniforms: SceneUniforms, capacity: number) {
    this.capacity = capacity;
    const base = buildFishGeometry();
    this.geometry = new InstancedBufferGeometry();
    this.geometry.index = base.index;
    this.geometry.setAttribute('position', base.getAttribute('position'));
    this.geometry.setAttribute('normal', base.getAttribute('normal'));

    const make = (itemSize: number): InstancedBufferAttribute => {
      const attribute = new InstancedBufferAttribute(new Float32Array(capacity * itemSize), itemSize);
      attribute.setUsage(35048);
      return attribute;
    };
    this.iPos = make(3);
    this.iDir = make(3);
    this.iData = make(4);
    this.iBody = make(3);
    this.iBack = make(3);
    this.iGlow = make(3);
    this.geometry.setAttribute('iPos', this.iPos);
    this.geometry.setAttribute('iDir', this.iDir);
    this.geometry.setAttribute('iData', this.iData);
    this.geometry.setAttribute('iBody', this.iBody);
    this.geometry.setAttribute('iBack', this.iBack);
    this.geometry.setAttribute('iGlow', this.iGlow);
    this.geometry.instanceCount = 0;

    this.material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
        uBeamPos: uniforms.uBeamPos,
        uBeamDir: uniforms.uBeamDir,
        uBeamParams: uniforms.uBeamParams,
        uAlpha: { value: 1 },
      },
      vertexShader,
      fragmentShader: CREATURE_FRAGMENT,
      side: DoubleSide,
      fog: false,
    });
    this.mesh = new Mesh(this.geometry, this.material);
    this.mesh.frustumCulled = false;
  }

  update(schools: readonly School[]): void {
    let n = 0;
    for (const school of schools) {
      const species = getSpecies(school.speciesId);
      const size = Math.max(species.sizeM * VISUAL_SCALE, MIN_VISUAL_SIZE);
      const beat = 7 + species.speed * 1.2;
      const glowing = species.glow !== undefined;

      for (let i = 0; i < school.count && n < this.capacity; i++, n++) {
        const k = i * 3;
        const vx = school.velocity[k] ?? 0;
        const vy = school.velocity[k + 1] ?? 0;
        const vz = school.velocity[k + 2] ?? 0;
        const len = Math.hypot(vx, vy, vz) || 1;

        this.iPos.setXYZ(n, school.position[k] ?? 0, school.position[k + 1] ?? 0, school.position[k + 2] ?? 0);
        this.iDir.setXYZ(n, vx / len, vy / len, vz / len);
        const rate = beat * (1 + 0.35 * school.panic);
        this.iData.setXYZW(n, size * (0.85 + 0.3 * (school.phase[i] ?? 0)), school.phase[i] ?? 0, rate, 0);

        this.colour.setHex(species.body);
        this.iBody.setXYZ(n, this.colour.r, this.colour.g, this.colour.b);
        this.colour.setHex(species.accent);
        this.iBack.setXYZ(n, this.colour.r, this.colour.g, this.colour.b);
        if (glowing && species.glow !== undefined) {
          this.colour.setHex(species.glow);
          this.iGlow.setXYZ(n, this.colour.r, this.colour.g, this.colour.b);
        } else {
          this.iGlow.setXYZ(n, 0, 0, 0);
        }
      }
    }
    this.geometry.instanceCount = n;
    for (const a of [this.iPos, this.iDir, this.iData, this.iBody, this.iBack, this.iGlow]) a.needsUpdate = true;
  }

  dispose(): void {
    this.geometry.dispose();
    this.material.dispose();
  }
}
