import { DEFAULT_LANG, isLang, type Lang } from '../i18n/index.ts';
import { QUALITY_TIERS, type QualityTier } from './quality.ts';

/** Everything the player can change in the settings menu. */
export interface Settings {
  quality: QualityTier | 'auto';
  renderScale: number;
  fov: number;
  bloom: boolean;
  filmGrain: boolean;
  vignette: boolean;
  chromaticAberration: boolean;
  sensitivity: number;
  invertY: boolean;
  cameraAutoReturn: boolean;
  showHints: boolean;
  showTips: boolean;
  language: Lang;
  volumeMaster: number;
  volumeEffects: number;
  volumeAmbient: number;
  volumeMusic: number;
}

export const DEFAULT_SETTINGS: Readonly<Settings> = {
  quality: 'auto',
  renderScale: 1,
  fov: 62,
  bloom: true,
  filmGrain: true,
  vignette: true,
  chromaticAberration: true,
  sensitivity: 1,
  invertY: false,
  cameraAutoReturn: true,
  showHints: true,
  showTips: true,
  language: DEFAULT_LANG,
  volumeMaster: 0.8,
  volumeEffects: 1,
  volumeAmbient: 0.8,
  volumeMusic: 0.5,
};

export const SETTING_LIMITS = {
  renderScale: { min: 0.5, max: 1, step: 0.05 },
  fov: { min: 50, max: 95, step: 1 },
  sensitivity: { min: 0.3, max: 2.5, step: 0.05 },
  volume: { min: 0, max: 1, step: 0.05 },
} as const;

const clampNumber = (value: unknown, min: number, max: number, fallback: number): number =>
  typeof value === 'number' && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;

const asBoolean = (value: unknown, fallback: boolean): boolean =>
  typeof value === 'boolean' ? value : fallback;

/** Turns untrusted data (saved JSON) into a complete, valid Settings object. */
export function sanitizeSettings(raw: unknown): Settings {
  const d = DEFAULT_SETTINGS;
  const r = (typeof raw === 'object' && raw !== null ? raw : {}) as Record<string, unknown>;
  const quality =
    r.quality === 'auto' || (QUALITY_TIERS as readonly unknown[]).includes(r.quality)
      ? (r.quality as Settings['quality'])
      : d.quality;
  const L = SETTING_LIMITS;
  return {
    quality,
    renderScale: clampNumber(r.renderScale, L.renderScale.min, L.renderScale.max, d.renderScale),
    fov: clampNumber(r.fov, L.fov.min, L.fov.max, d.fov),
    bloom: asBoolean(r.bloom, d.bloom),
    filmGrain: asBoolean(r.filmGrain, d.filmGrain),
    vignette: asBoolean(r.vignette, d.vignette),
    chromaticAberration: asBoolean(r.chromaticAberration, d.chromaticAberration),
    sensitivity: clampNumber(r.sensitivity, L.sensitivity.min, L.sensitivity.max, d.sensitivity),
    invertY: asBoolean(r.invertY, d.invertY),
    cameraAutoReturn: asBoolean(r.cameraAutoReturn, d.cameraAutoReturn),
    showHints: asBoolean(r.showHints, d.showHints),
    showTips: asBoolean(r.showTips, d.showTips),
    language: isLang(r.language) ? r.language : d.language,
    volumeMaster: clampNumber(r.volumeMaster, 0, 1, d.volumeMaster),
    volumeEffects: clampNumber(r.volumeEffects, 0, 1, d.volumeEffects),
    volumeAmbient: clampNumber(r.volumeAmbient, 0, 1, d.volumeAmbient),
    volumeMusic: clampNumber(r.volumeMusic, 0, 1, d.volumeMusic),
  };
}

export interface SettingsStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

type Listener = (settings: Readonly<Settings>, changed: keyof Settings | null) => void;

const STORAGE_KEY = 'luminara.settings';

/** Holds the current settings, saves them, and tells listeners about changes. */
export class SettingsStore {
  private current: Settings;
  private readonly listeners = new Set<Listener>();
  private readonly storage: SettingsStorage | null;

  constructor(storage: SettingsStorage | null = null) {
    this.storage = storage;
    this.current = sanitizeSettings(this.load());
  }

  get value(): Readonly<Settings> {
    return this.current;
  }

  set<K extends keyof Settings>(key: K, value: Settings[K]): void {
    const next = sanitizeSettings({ ...this.current, [key]: value });
    if (next[key] === this.current[key]) return;
    this.current = next;
    this.save();
    this.emit(key);
  }

  reset(): void {
    this.current = { ...DEFAULT_SETTINGS };
    this.save();
    this.emit(null);
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private emit(changed: keyof Settings | null): void {
    for (const listener of this.listeners) listener(this.current, changed);
  }

  private load(): unknown {
    try {
      const text = this.storage?.getItem(STORAGE_KEY);
      return text ? JSON.parse(text) : null;
    } catch {
      return null;
    }
  }

  private save(): void {
    try {
      this.storage?.setItem(STORAGE_KEY, JSON.stringify(this.current));
    } catch {
    }
  }
}
