export interface AlbumStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

interface Entry {
  score: number;
  image: string;
}

/**
 * The best photo of every species, kept on this device (images are too big for the cloud save).
 * `key` is asked every time so the album follows the active account.
 */
export class PhotoAlbum {
  private readonly storage: AlbumStorage | null;
  private readonly keyOf: () => string;
  private cache: { key: string; entries: Record<string, Entry> } | null = null;

  constructor(storage: AlbumStorage | null, keyOf: () => string) {
    this.storage = storage;
    this.keyOf = keyOf;
  }

  get(speciesId: string): Entry | null {
    return this.entries()[speciesId] ?? null;
  }

  save(speciesId: string, score: number, image: string): boolean {
    const entries = this.entries();
    const old = entries[speciesId];
    if (old && old.score >= score) return false;
    entries[speciesId] = { score, image };
    try {
      this.storage?.setItem(this.fullKey(), JSON.stringify(entries));
    } catch {
    }
    return true;
  }

  private fullKey(): string {
    return `${this.keyOf()}.album`;
  }

  private entries(): Record<string, Entry> {
    const key = this.fullKey();
    if (this.cache?.key === key) return this.cache.entries;
    let entries: Record<string, Entry> = {};
    try {
      const parsed: unknown = JSON.parse(this.storage?.getItem(key) ?? 'null');
      if (typeof parsed === 'object' && parsed !== null) {
        for (const [id, v] of Object.entries(parsed)) {
          const e = v as Partial<Entry> | null;
          if (e && typeof e.score === 'number' && typeof e.image === 'string' && e.image.startsWith('data:image/')) {
            entries[id] = { score: e.score, image: e.image };
          }
        }
      }
    } catch {
      entries = {};
    }
    this.cache = { key, entries };
    return entries;
  }
}
