import { t } from '../i18n/index.ts';
import { speciesName } from '../i18n/names.ts';
import { type Contact, Sonar } from '../domain/sonar.ts';

const SIZE = 184;
const COLOUR: Record<Contact['status'], string> = {
  unknown: '170, 235, 245',
  known: '95, 242, 212',
  new: '255, 200, 87',
};

/** A round, heading-up radar that shows the contacts of the last sonar ping and fades them out. */
export class SonarDisplay {
  readonly root = document.createElement('div');
  private readonly canvas = document.createElement('canvas');
  private readonly ctx: CanvasRenderingContext2D | null;
  private readonly label = document.createElement('div');
  private readonly ratio = Math.min(2, globalThis.devicePixelRatio || 1);

  constructor() {
    this.root.className = 'sonar';
    this.root.hidden = true;
    this.canvas.width = SIZE * this.ratio;
    this.canvas.height = SIZE * this.ratio;
    this.canvas.style.width = `${SIZE}px`;
    this.canvas.style.height = `${SIZE}px`;
    this.ctx = this.canvas.getContext('2d');
    this.label.className = 'sonar-label';
    this.root.append(this.canvas, this.label);
  }

  setVisible(visible: boolean): void {
    this.root.hidden = !visible;
  }

  draw(time: number, sonar: Sonar, sub: { x: number; y: number; z: number; yaw: number }, range: number, cooldown: number): void {
    const ctx = this.ctx;
    if (!ctx) return;
    const r = this.ratio;
    const c = (SIZE * r) / 2;
    const radius = c - 6 * r;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, SIZE * r, SIZE * r);

    ctx.beginPath();
    ctx.arc(c, c, radius, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(2, 18, 24, 0.55)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(95, 242, 212, 0.45)';
    ctx.lineWidth = 1.5 * r;
    ctx.stroke();
    ctx.strokeStyle = 'rgba(95, 242, 212, 0.16)';
    ctx.lineWidth = r;
    for (const k of [1 / 3, 2 / 3]) {
      ctx.beginPath();
      ctx.arc(c, c, radius * k, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(c, c - radius);
    ctx.lineTo(c, c + radius);
    ctx.moveTo(c - radius, c);
    ctx.lineTo(c + radius, c);
    ctx.stroke();

    const age = sonar.age(time);
    if (age < 1.6) {
      const t = age / 1.6;
      ctx.beginPath();
      ctx.arc(c, c, radius * t, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(95, 242, 212, ${0.7 * (1 - t)})`;
      ctx.lineWidth = 2 * r;
      ctx.stroke();
    }

    ctx.beginPath();
    ctx.moveTo(c, c - 6 * r);
    ctx.lineTo(c + 4 * r, c + 5 * r);
    ctx.lineTo(c - 4 * r, c + 5 * r);
    ctx.closePath();
    ctx.fillStyle = '#e7f5f7';
    ctx.fill();

    const fx = -Math.sin(sub.yaw);
    const fz = -Math.cos(sub.yaw);
    const rx = Math.cos(sub.yaw);
    const rz = -Math.sin(sub.yaw);
    const fade = Math.max(0, 1 - age / Sonar.HOLD);
    ctx.font = `${10 * r}px ui-monospace, Menlo, Consolas, monospace`;
    ctx.textBaseline = 'middle';
    if (fade > 0) {
      for (const contact of sonar.contacts) {
        const dx = contact.x - sub.x;
        const dz = contact.z - sub.z;
        const right = dx * rx + dz * rz;
        const ahead = dx * fx + dz * fz;
        const dist = Math.hypot(right, ahead);
        if (dist / range > Math.min(1, age / 1.6)) continue;
        const scale = dist > range ? range / dist : 1;
        const px = c + ((right * scale) / range) * radius;
        const py = c - ((ahead * scale) / range) * radius;
        const dot = (3 + Math.min(4, Math.log2(1 + contact.size))) * r;
        ctx.fillStyle = `rgba(${COLOUR[contact.status]}, ${fade})`;
        ctx.beginPath();
        if (contact.kind === 'school') {
          ctx.arc(px, py, dot, 0, Math.PI * 2);
        } else {
          ctx.rect(px - dot * 0.8, py - dot * 0.8, dot * 1.6, dot * 1.6);
        }
        ctx.fill();
        const name = contact.speciesId ? speciesName(contact.speciesId) : contact.status === 'new' ? '?' : '';
        if (name) ctx.fillText(name, px + dot + 3 * r, py);
      }
    }

    const left = sonar.cooldownLeft(time, cooldown);
    const text = t('sonar.label', { range: Math.round(range), state: left > 0 ? t('unit.s', { n: left.toFixed(1) }) : t('sonar.ready') });
    if (this.label.textContent !== text) this.label.textContent = text;
  }
}
