const WHITE = 0xf4f8fb;

type Pt = readonly [number, number, number];

function box(b: PropBuilder, w: number, h: number, d: number, pos: Pt, color: number, extra: { emit?: number; slime?: number; jitter?: number; rot?: Pt } = {}): void {
  b.add(new BoxGeometry(w, h, d), color, { pos, ...extra });
}

function cyl(b: PropBuilder, r0: number, r1: number, h: number, pos: Pt, color: number, extra: { emit?: number; slime?: number; jitter?: number; rot?: Pt; sides?: number } = {}): void {
  b.add(new CylinderGeometry(r1, r0, h, extra.sides ?? 10), color, { pos, ...extra });
}


function buildPier(b: PropBuilder, world: WorldQuery, rng: Rng, piles: { x: number; z: number }[]): void {
  const { x0, x1, z, width } = PIER;
  const length = x1 - x0;
  const cx = (x0 + x1) / 2;

  const pitch = 0.4;
  const planks = Math.floor(length / pitch);
  for (let i = 0; i < planks; i++) {
    box(b, pitch - 0.04, 0.14, width, [x0 + (i + 0.5) * pitch, DECK - 0.07, z], 0x8a6238, { jitter: 0.3, slime: 0.15 });
  }
  for (const side of [-1, 1]) {
    box(b, length, 0.34, 0.3, [cx, DECK - 0.3, z + side * (width / 2 - 0.3)], 0x4a3a2a, { slime: 0.9, jitter: 0.1 });
  }
  const spots: { x: number; zz: number; bottom: number }[] = [];
  for (let x = x0 + 1; x <= x1; x += 5) {
    box(b, 0.32, 0.3, width, [x, DECK - 0.58, z], 0x4a3a2a, { slime: 0.9, jitter: 0.1 });
    for (const side of [-1, 1]) {
      const zz = z + side * (width / 2 - 0.3);
      const bottom = world.seabedY(x, zz) - 0.7;
      if (bottom < DECK - 0.6) {
        spots.push({ x, zz, bottom });
        if (world.seabedY(x, zz) < -0.2) piles.push({ x, z: zz });
      }
    }
  }
  for (const s of spots) {
    const h = DECK - s.bottom;
    b.add(new CylinderGeometry(0.24, 0.3, h, 10), 0x74654f, { pos: [s.x, s.bottom + h / 2, s.zz], slime: 1, jitter: 0.12 });
    cyl(b, 0.31, 0.31, 0.12, [s.x, DECK - 0.7, s.zz], 0x30363a);
  }
  for (let i = 0; i + 1 < spots.length; i++) {
    const a = spots[i];
    const c = spots[i + 1];
    if (!a || !c || Math.abs(a.x - c.x) > 0.01) continue;
    const mid = Math.max(a.bottom, c.bottom) + 1.2;
    const top = DECK - 1.0;
    addLimb(b, new Vector3(a.x, mid, a.zz), new Vector3(c.x, top, c.zz), 0.07, 0.07, 0x5a4a38);
    addLimb(b, new Vector3(a.x, top, a.zz), new Vector3(c.x, mid, c.zz), 0.07, 0.07, 0x5a4a38);
    b.add(new BoxGeometry(0.2, 0.2, width), 0x5a4a38, { pos: [a.x, mid, z], slime: 1, jitter: 0.1 });
  }

  for (const side of [-1, 1]) {
    const zz = z + side * (width / 2 - 0.1);
    const end = side === -1 ? x1 - 22 : x1;
    for (let x = x0 + 0.5; x <= end; x += 3) cyl(b, 0.05, 0.05, 1.05, [x, DECK + 0.52, zz], 0x2e363b, { sides: 6 });
    box(b, end - x0, 0.07, 0.07, [(x0 + end) / 2 + 0.25, DECK + 1.04, zz], 0x2e363b);
    box(b, end - x0, 0.05, 0.05, [(x0 + end) / 2 + 0.25, DECK + 0.55, zz], 0x2e363b);
  }
  const berthZ = z - width / 2 + 0.45;
  for (const x of [x1 - 14, x1 - 8, x1 - 2.5]) {
    cyl(b, 0.16, 0.2, 0.42, [x, DECK + 0.21, berthZ], 0x1d2226);
    b.add(new TorusGeometry(0.17, 0.05, 6, 12), 0x1d2226, { pos: [x, DECK + 0.42, berthZ], rot: [Math.PI / 2, 0, 0] });
  }
  for (let x = x1 - 28; x <= x1 - 1; x += 3) {
    b.add(new TorusGeometry(0.36, 0.15, 8, 14), 0x15171a, { pos: [x, 0.35, z - width / 2 - 0.1], rot: [0, 0, 0], slime: 0.5 });
    addLimb(b, new Vector3(x, DECK - 0.1, z - width / 2 + 0.2), new Vector3(x, 0.7, z - width / 2 - 0.1), 0.025, 0.025, 0x8a7a5a);
  }
  for (const x of [x1 - 14, x1 - 8]) {
    addLimb(b, new Vector3(x, DECK + 0.4, berthZ), new Vector3(x + 1.2, 0.5, berthZ - 1.6), 0.04, 0.04, 0xb8a37a);
  }
  for (const dz of [-0.35, 0.35]) {
    box(b, 0.06, 3.2, 0.06, [x1 - 0.05, DECK - 1.2, z + width / 2 + 0.05 + dz * 0.0 + (dz > 0 ? 0.35 : 0)], 0x2e363b, { slime: 0.6 });
  }
  for (let i = 0; i < 8; i++) box(b, 0.05, 0.05, 0.9, [x1 - 0.05, DECK - 2.6 + i * 0.4, z + width / 2 + 0.4], 0x2e363b, { slime: 0.6 });

  for (const x of [x0 + 8, (x0 + x1) / 2, x1 - 6]) lamp(b, x, DECK, z + width / 2 - 0.25, -1);

  const sx = x0 + 18;
  for (const dx of [-1.6, 1.6]) for (const dz of [-1.1, 1.1]) cyl(b, 0.07, 0.07, 2.6, [sx + dx, DECK + 1.3, z + dz], 0x3a2e24, { sides: 6 });
  box(b, 4.4, 0.18, 3.2, [sx, DECK + 2.7, z], 0x7a3a2c, { jitter: 0.1 });
  box(b, 3.4, 0.12, 0.5, [sx, DECK + 0.5, z - 1.1], 0x6a4a2c);
  b.add(new TorusGeometry(0.4, 0.08, 6, 14), 0xb8a37a, { pos: [x1 - 20, DECK + 0.1, z + 1.2], rot: [Math.PI / 2, 0, 0] });
  b.add(new TorusGeometry(0.28, 0.1, 8, 16), 0xe05a1c, { pos: [x0 + 30, DECK + 0.8, z + width / 2 - 0.2], rot: [0, 0, 0], emit: 0.04 });
  void rng;
}

function lamp(b: PropBuilder, x: number, y: number, z: number, armDir: number): void {
  cyl(b, 0.08, 0.1, 4.0, [x, y + 2.0, z], 0x1d2226, { sides: 8 });
  addLimb(b, new Vector3(x, y + 4.0, z), new Vector3(x, y + 4.35, z + armDir * 0.9), 0.05, 0.05, 0x1d2226);
  box(b, 0.5, 0.12, 0.5, [x, y + 4.4, z + armDir * 1.0], 0x1d2226);
  b.add(new SphereGeometry(0.2, 10, 8), WARM, { pos: [x, y + 4.22, z + armDir * 1.0], emit: 1.7, scale: [1, 0.9, 1] });
}


function buildQuay(b: PropBuilder, world: WorldQuery, rng: Rng, pal: Palette): void {
  const { x0, x1, z0, z1 } = HARBOUR;
  const wx = (x0 + x1) / 2;
  const wz = (z0 + z1) / 2;
  box(b, x1 - x0, 0.3, z1 - z0, [wx, QUAY - 0.12, wz], pal.apron, { jitter: 0.06 });
  box(b, 2.2, 13, z1 - z0, [x1 + 0.7, QUAY - 6.7, wz], 0x8a8b86, { slime: 1, jitter: 0.08 });
  box(b, 2.8, 0.45, z1 - z0 + 0.4, [x1 + 0.5, QUAY - 0.05, wz], 0xa4a49a, { slime: 0.2 });
  box(b, 0.25, 0.02, z1 - z0 - 1, [x1 - 1.0, QUAY + 0.04, wz], 0xe0b92a, { emit: 0.03 });
  for (let z = z0 + 4; z < z1 - 2; z += 4.2) box(b, 7, 0.02, 0.14, [x1 - 8, QUAY + 0.04, z], 0xdad8d0);
  for (let z = z0 + 4; z <= z1 - 3; z += 8) {
    if (Math.abs(z - PIER.z) < 3) continue;
    cyl(b, 0.2, 0.26, 0.5, [x1 - 0.4, QUAY + 0.2, z], 0x1d2226);
    b.add(new TorusGeometry(0.34, 0.14, 8, 14), 0x15171a, { pos: [x1 + 0.2, 0.3, z], rot: [0, Math.PI / 2, 0], slime: 0.6 });
  }
  for (const z of [-32, -16, 16, 32]) lamp(b, x1 - 3, QUAY, z, 1);

  const ox = -324;
  const oz = -25;
  box(b, 7, 3.0, 5.4, [ox, QUAY + 1.5, oz], pal.wall, { jitter: 0.04 });
  box(b, 6.2, 2.8, 4.8, [ox, QUAY + 4.4, oz], pal.wall2, { jitter: 0.04 });
  b.add(new ConeGeometry(4.9, 2.2, 4), pal.roof, { pos: [ox, QUAY + 6.9, oz], rot: [0, Math.PI / 4, 0], scale: [1.18, 1, 1] });
  for (let i = 0; i < 3; i++) {
    for (const f of [0, 1]) {
      const lit = rng.chance(0.6);
      box(b, 0.12, 1.1, 1.2, [ox + 3.55 - f * 0.4, QUAY + 1.4 + f * 2.9, oz - 1.8 + i * 1.8], lit ? 0xffd48a : 0x1a2a38, { emit: lit ? 0.85 : 0 });
    }
  }
  box(b, 0.14, 2.0, 1.3, [ox + 3.56, QUAY + 1.0, oz + 0.0], 0x2b3a46);
  box(b, 0.2, 0.7, 4.0, [ox + 3.62, QUAY + 3.1, oz], 0x0f4a52, { emit: 0.25 });
  const wxp = -327;
  const wzp = 24;
  box(b, 16, 5.4, 11, [wxp, QUAY + 2.7, wzp], pal.shed, { jitter: 0.05 });
  for (const s of [-1, 1]) {
    box(b, 16.6, 0.22, 6.2, [wxp, QUAY + 6.2, wzp + s * 2.6], pal.shedRoof, { rot: [s * -0.33, 0, 0], jitter: 0.06 });
  }
  box(b, 0.2, 4.2, 5.6, [wxp + 8.05, QUAY + 2.1, wzp], 0x2c4452);
  for (let i = 0; i < 4; i++) box(b, 0.1, 0.5, 1.6, [wxp + 8.05, QUAY + 4.8, wzp - 4 + i * 2.7], 0xffd48a, { emit: 0.6 });
  for (const z of [-33, -26]) {
    const tx = -336;
    cyl(b, 3.1, 3.1, 5.4, [tx, QUAY + 2.7, z], pal.tank, { sides: 24, jitter: 0.04 });
    cyl(b, 3.2, 3.2, 0.3, [tx, QUAY + 5.5, z], 0x8a8f95, { sides: 24 });
    box(b, 0.1, 5.2, 0.5, [tx + 3.12, QUAY + 2.8, z], 0x3a4146);
  }
  addLimb(b, new Vector3(-333, QUAY + 0.6, -33), new Vector3(-310, QUAY + 0.6, -33), 0.14, 0.14, 0x5a6a72);
  const stacks: Array<[number, number, number]> = [[-336, -12, 2], [-336, -9.4, 2], [-336, -6.8, 1], [-322, -8, 2], [-322, -5.4, 1], [-312, 12, 1]];
  stacks.forEach(([x, z, n], k) => {
    for (let level = 0; level < n; level++) {
      const c = pal.containers[(k * 3 + level) % pal.containers.length] ?? 0x8c2f23;
      box(b, 6.1, 2.5, 2.4, [x, QUAY + 1.25 + level * 2.5, z], c, { jitter: 0.12, rot: [0, level * 0.03, 0] });
    }
  });
  for (let i = 0; i < 14; i++) {
    const bx = -318 + rng.range(-4, 4);
    const bz = 13 + rng.range(-3.5, 3.5);
    cyl(b, 0.36, 0.36, 0.9, [bx, QUAY + 0.45, bz], [0x2a5a8c, 0xa32a22, 0xc7952a, 0x3a3f44][i % 4] ?? 0x2a5a8c, { jitter: 0.15, sides: 10 });
  }
  for (let i = 0; i < 9; i++) box(b, 1, 1, 1, [-312 + rng.range(-2, 2), QUAY + 0.5 + (i % 3 === 0 ? 1 : 0), -2 + rng.range(-5, 5)], 0x8a6a3c, { jitter: 0.2, rot: [0, rng.range(0, 1), 0] });
  cyl(b, 0.1, 0.18, 15, [x1 - 3.5, QUAY + 7.5, -37], 0xcfd3d0, { sides: 8 });
  box(b, 3.0, 1.8, 0.04, [x1 - 5.1, QUAY + 13.6, -37], 0x14a89a, { emit: 0.12 });
  box(b, 3.0, 0.5, 0.05, [x1 - 5.1, QUAY + 13.0, -37], 0xfafafa);
  b.add(new SphereGeometry(0.28, 10, 8), 0xff3a2a, { pos: [x1 - 3.5, QUAY + 15.2, -37], emit: 1.6 });
  const kx = x1 - 6;
  const kz = 20;
  for (const dx of [-3, 3]) for (const dz of [-2.4, 2.4]) box(b, 0.5, 8, 0.5, [kx + dx, QUAY + 4, kz + dz], 0xb43a2a, { jitter: 0.06 });
  box(b, 7, 0.9, 5.6, [kx, QUAY + 8.4, kz], 0xb43a2a);
  box(b, 24, 0.7, 0.9, [kx + 9, QUAY + 9.1, kz], 0xe8e4da);
  addLimb(b, new Vector3(kx + 3, QUAY + 8.6, kz), new Vector3(kx + 19, QUAY + 9.2, kz), 0.12, 0.12, 0x3a4146);
  box(b, 2.2, 2.0, 2.0, [kx - 1.5, QUAY + 9.9, kz + 2.6], 0xe8e4da);
  box(b, 0.05, 0.9, 1.4, [kx - 0.35, QUAY + 10.1, kz + 2.6], 0x9fd8ee, { emit: 0.3 });
  addLimb(b, new Vector3(kx + 14, QUAY + 8.7, kz), new Vector3(kx + 14, QUAY + 1.5, kz), 0.04, 0.04, 0x20262b);
  b.add(new TorusGeometry(0.3, 0.09, 6, 10), 0xe0b92a, { pos: [kx + 14, QUAY + 1.2, kz], rot: [0, Math.PI / 2, 0] });
  void world;
}



function palm(b: PropBuilder, x: number, z: number, lean: number, height: number): void {
  const top = new Vector3(x + lean, QUAY + height, z + lean * 0.4);
  const mid = new Vector3(x + lean * 0.35, QUAY + height * 0.55, z + lean * 0.12);
  addLimb(b, new Vector3(x, QUAY, z), mid, 0.3, 0.22, 0x7a5a38);
  addLimb(b, mid, top, 0.22, 0.14, 0x7a5a38);
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * Math.PI * 2;
    const tip = new Vector3(top.x + Math.cos(a) * 3.6, top.y - 1.6, top.z + Math.sin(a) * 3.6);
    const knee = new Vector3(top.x + Math.cos(a) * 1.8, top.y + 0.5, top.z + Math.sin(a) * 1.8);
    addLimb(b, top, knee, 0.1, 0.07, 0x2f8a3a);
    addLimb(b, knee, tip, 0.07, 0.02, 0x3fa24a);
  }
  b.add(new SphereGeometry(0.28, 8, 6), 0x5a3a1c, { pos: [top.x + 0.3, top.y - 0.3, top.z], scale: [1, 1, 1] });
}

function dressTemperate(b: PropBuilder, rng: Rng): void {
  for (let i = 0; i < 6; i++) {
    const x = -338 + rng.range(-1, 1);
    const z = -3 + i * 3.2;
    b.add(new ConeGeometry(1.1, 3.4, 7), 0x2e5a3a, { pos: [x, QUAY + 2.2, z], jitter: 0.1 });
  }
}

function dressTropical(b: PropBuilder, rng: Rng): void {
  const spots: Array<[number, number]> = [[-334, -38], [-330, -2], [-338, 6], [-322, 36], [-336, 38], [-314, -30], [-318, 2]];
  spots.forEach(([x, z], i) => palm(b, x, z, rng.range(-1.6, 1.6), 7 + (i % 3) * 1.4));
  for (const z of [-18, 6]) {
    const ux = -312;
    cyl(b, 0.05, 0.05, 2.6, [ux, QUAY + 1.3, z], 0xe8e4da, { sides: 6 });
    b.add(new ConeGeometry(2.1, 0.7, 8), z < 0 ? 0xe0553a : 0xf2b630, { pos: [ux, QUAY + 2.8, z] });
    box(b, 1.6, 0.08, 0.7, [ux + 0.2, QUAY + 0.5, z + 1.7], 0xf4efe0);
  }
}

function dressArctic(b: PropBuilder, rng: Rng): void {
  const { x0, x1, z0, z1 } = HARBOUR;
  for (let i = 0; i < 22; i++) {
    const x = rng.range(x0 + 4, x1 - 4);
    const z = rng.range(z0 + 3, z1 - 3);
    b.add(new IcosahedronGeometry(rng.range(0.9, 2.4), 1), WHITE, { pos: [x, QUAY + 0.05, z], scale: [1.7, 0.32, 1.2], jitter: 0.05 });
  }
  box(b, 7.4, 0.3, 5.8, [-324, QUAY + 5.6, -25], WHITE);
  box(b, 16.8, 0.24, 11.4, [-327, QUAY + 5.5, 24], WHITE, { jitter: 0.04 });
  for (const [x, z] of [[-336, -12], [-336, -9.4], [-322, -8]] as const) box(b, 6.2, 0.2, 2.5, [x, QUAY + 5.1, z], WHITE);
  for (let x = PIER.x0 + 2; x < PIER.x1 - 6; x += 7.5) box(b, 3.6, 0.1, PIER.width - 0.6, [x, DECK + 0.03, PIER.z], WHITE, { jitter: 0.03 });
  for (let i = 0; i < 9; i++) {
    const x = -300 + rng.range(-4, 6);
    const z = rng.range(-36, 36);
    b.add(new ConeGeometry(0.8, 4, 5), 0xcfe4f2, { pos: [x, QUAY + 1.6, z], jitter: 0.1, emit: 0.05 });
  }
}

function dressVolcanic(b: PropBuilder, rng: Rng): void {
  const { x0, x1, z0, z1 } = HARBOUR;
  for (let i = 0; i < 18; i++) {
    const x = rng.range(x0 + 4, x1 - 5);
    const z = rng.range(z0 + 3, z1 - 3);
    const r = rng.range(1.2, 3.4);
    b.add(new IcosahedronGeometry(r, 1), 0x2a2725, { pos: [x, QUAY + r * 0.35, z], scale: [1, 0.7, 1.1], jitter: 0.2 });
    if (i % 2 === 0) b.add(new IcosahedronGeometry(r * 0.32, 0), 0xff6a1c, { pos: [x + r * 0.5, QUAY + r * 0.55, z], emit: 1.6 });
  }
  for (let i = 0; i < 10; i++) {
    const x = rng.range(x0 + 6, x1 - 6);
    const z = rng.range(z0 + 4, z1 - 4);
    box(b, rng.range(3, 7), 0.04, 0.3, [x, QUAY + 0.06, z], 0xff5a14, { emit: 1.4, rot: [0, rng.range(0, 3), 0] });
  }
  for (const z of [-30, 30]) {
    cyl(b, 0.8, 1.6, 4.5, [-318, QUAY + 2.2, z], 0x2a2725, { sides: 9, jitter: 0.12 });
    b.add(new SphereGeometry(0.9, 10, 8), 0xff6a1c, { pos: [-318, QUAY + 4.6, z], emit: 1.5, scale: [1, 0.5, 1] });
  }
}

const DRESS: Record<PortTheme, (b: PropBuilder, rng: Rng) => void> = {
  temperate: dressTemperate,
  tropical: dressTropical,
  arctic: dressArctic,
  volcanic: dressVolcanic,
};


function hullGeometry(len: number, h: number, beam: number): BufferGeometry {
  const g = new BoxGeometry(len, h, beam, 12, 3, 5);
  const p = g.getAttribute('position');
  for (let i = 0; i < p.count; i++) {
    const t = (p.getX(i) + len / 2) / len;
    const yn = (p.getY(i) + h / 2) / h;
    let w = 0.5 + 0.5 * Math.min(1, yn * 1.5);
    if (t > 0.55) w *= 1 - ((t - 0.55) / 0.45) ** 1.5 * 0.94;
    p.setXYZ(i, p.getX(i), p.getY(i) + t ** 3 * h * 0.32 * yn, p.getZ(i) * w);
  }
  g.computeVertexNormals();
  return g;
}

interface Boat {
  readonly mesh: Mesh;
  readonly x: number;
  readonly z: number;
  readonly phase: number;
}

function trawler(): BufferGeometry {
  const b = new PropBuilder();
  b.add(hullGeometry(13, 2.6, 4.4), 0x24526e, { pos: [0, 0.1, 0], slime: 0.4 });
  b.add(hullGeometry(13.06, 0.7, 4.46), 0x7a2a24, { pos: [0, -0.9, 0], slime: 0.8 });
  box(b, 12.2, 0.12, 3.9, [0, 1.34, 0], 0x8a6a42, { jitter: 0.1 });
  box(b, 3.4, 2.4, 3.0, [-2.2, 2.6, 0], 0xe8e4da, { jitter: 0.03 });
  box(b, 3.8, 0.2, 3.4, [-2.2, 3.9, 0], 0x24526e);
  for (const z of [-1, 1]) box(b, 0.1, 0.8, 1.0, [-0.5, 2.8, z * 0.95], 0xffd48a, { emit: 0.7 });
  box(b, 0.1, 0.9, 2.2, [-0.48, 2.8, 0], 0x1a2a38);
  cyl(b, 0.12, 0.14, 7, [1.6, 4.5, 0], 0x4a4f54, { sides: 8 });
  addLimb(b, new Vector3(1.6, 5.2, 0), new Vector3(5.8, 2.2, 0), 0.07, 0.07, 0x4a4f54);
  cyl(b, 0.8, 0.8, 1.1, [3.3, 1.9, 0], 0xb8651f, { rot: [Math.PI / 2, 0, 0], sides: 14 });
  for (let i = 0; i < 4; i++) cyl(b, 0.2, 0.2, 0.6, [-4.6 + i * 0.4, 1.6, 1.1], 0xc7952a, { sides: 8 });
  b.add(new SphereGeometry(0.15, 8, 6), 0xff3a2a, { pos: [-2.2, 4.1, 0], emit: 0.9 });
  b.add(new TorusGeometry(0.22, 0.07, 6, 10), 0x15171a, { pos: [-1.2, 0.55, 2.3], slime: 0.2 });
  return b.build();
}

function skiff(): BufferGeometry {
  const b = new PropBuilder();
  b.add(hullGeometry(7, 1.2, 2.5), 0xe8e4da, { pos: [0, 0.1, 0], slime: 0.3 });
  b.add(hullGeometry(7.04, 0.35, 2.54), 0xc9541c, { pos: [0, -0.4, 0], slime: 0.8 });
  box(b, 1.4, 0.3, 2.0, [0.4, 0.75, 0], 0x7a5a38);
  box(b, 0.7, 0.9, 0.5, [-3.6, 0.8, 0], 0x1d2226);
  cyl(b, 0.05, 0.05, 1, [-3.6, -0.1, 0], 0x1d2226, { sides: 6 });
  return b.build();
}

function sailboat(): BufferGeometry {
  const b = new PropBuilder();
  b.add(hullGeometry(9.6, 1.5, 3.1), 0xf0eee6, { pos: [0, 0.1, 0], slime: 0.3 });
  b.add(hullGeometry(9.64, 0.4, 3.14), 0x1b3d6a, { pos: [0, -0.55, 0], slime: 0.8 });
  box(b, 3.2, 0.6, 2.0, [-0.4, 1.1, 0], 0xf0eee6);
  box(b, 3.0, 0.1, 1.9, [-0.4, 1.45, 0], 0x6a4a2c);
  cyl(b, 0.06, 0.09, 13, [1.0, 7.0, 0], 0xb8bcc0, { sides: 8 });
  box(b, 3.6, 0.07, 0.07, [-0.6, 2.2, 0], 0xb8bcc0);
  box(b, 3.4, 5.4, 0.04, [0.2, 4.2, 0.12], 0xf4f0e6, { jitter: 0.04, rot: [0, 0, -0.1] });
  box(b, 0.12, 2.2, 0.8, [0, -1.8, 0], 0x23272b, { slime: 0.9 });
  return b.build();
}


function buildSeabedJunk(b: PropBuilder, world: WorldQuery, rng: Rng): void {
  const place = (x: number, z: number): number => world.seabedY(x, z);
  for (let i = 0; i < 16; i++) {
    const x = rng.range(PIER.x0 + 6, PIER.x1 - 4);
    const z = PIER.z + rng.range(-9, 9);
    const y = place(x, z);
    if (y > -1.2) continue;
    const kind = i % 4;
    if (kind === 0) cyl(b, 0.36, 0.36, 0.9, [x, y + 0.3, z], 0x6a5a3a, { rot: [rng.range(1.2, 1.7), rng.range(0, 6), 0], slime: 1, jitter: 0.2, sides: 10 });
    else if (kind === 1) b.add(new TorusGeometry(0.36, 0.15, 8, 14), 0x15171a, { pos: [x, y + 0.2, z], rot: [Math.PI / 2 + rng.range(-0.3, 0.3), 0, rng.range(0, 3)], slime: 1 });
    else if (kind === 2) box(b, 0.9, 0.5, 0.6, [x, y + 0.2, z], 0x7a6a4a, { slime: 1, rot: [0, rng.range(0, 3), 0] });
    else b.add(new IcosahedronGeometry(0.5, 1), 0x6a665c, { pos: [x, y + 0.1, z], scale: [1.4, 0.7, 1], slime: 1 });
  }
  const ax = PIER.x1 - 12;
  const az = PIER.z - 5.5;
  const ay = place(ax, az);
  b.add(new CylinderGeometry(0.08, 0.08, 2.2, 6), 0x4a3f33, { pos: [ax, ay + 0.9, az], rot: [0.2, 0, 0.35], slime: 1 });
  b.add(new TorusGeometry(0.9, 0.08, 6, 14, Math.PI), 0x4a3f33, { pos: [ax, ay + 0.2, az], rot: [0, 0.6, Math.PI], slime: 1 });
  for (let i = 0; i < 12; i++) {
    b.add(new TorusGeometry(0.1, 0.03, 4, 8), 0x4a3f33, { pos: [ax + 0.5 + i * 0.22, place(ax + 0.5 + i * 0.22, az + i * 0.18) + 0.06, az + i * 0.18], rot: [i % 2 ? Math.PI / 2 : 0, 0, 0], slime: 1 });
  }
}

/**
 * The home port: levelled quay with an office, warehouse, tanks, containers and a crane, a plank
 * pier on slimy piles with fenders and lamps, boats that bob on the waves, and the odd lost thing on
 * the seabed. Everything uses the landmark material, so it picks up the headlight and fog at depth.
 */
export class Harbour {
  readonly group = new Group();
  readonly piles: { x: number; z: number }[] = [];
  private readonly material: ShaderMaterial;
  private readonly geometries: BufferGeometry[] = [];
  private readonly boats: Boat[] = [];
  private readonly dx: number;
  private readonly dz: number;

  constructor(world: WorldQuery, uniforms: SceneUniforms, placement: PortPlacement) {
    this.material = createPropMaterial(uniforms, 0.6);
    this.dx = placement.dx;
    this.dz = placement.dz;
    this.group.position.set(this.dx, 0, this.dz);
    const local: WorldQuery = { ...world, seabedY: (x, z) => world.seabedY(x + this.dx, z + this.dz) };
    const theme = placement.port.theme;
    const rng = createRng(4711 + placement.port.z);
    const fixed = new PropBuilder();
    buildPier(fixed, local, rng, this.piles);
    buildQuay(fixed, local, rng, PALETTES[theme]);
    DRESS[theme](fixed, rng);
    buildSeabedJunk(fixed, local, rng);
    this.add(fixed.build());
    for (const p of this.piles) {
      p.x += this.dx;
      p.z += this.dz;
    }

    const berthZ = PIER.z + PIER.width / 2 + 2.9;
    this.addBoat(trawler(), PIER.x1 - 20, berthZ + 0.4, 0.0);
    this.addBoat(skiff(), PIER.x1 - 38, berthZ - 0.4, 1.7);
    this.addBoat(sailboat(), PIER.x1 - 54, berthZ + 0.1, 3.3);
  }

  update(time: number): void {
    for (const boat of this.boats) {
      const { x, z, phase, mesh } = boat;
      const wx = x + this.dx;
      const wz = z + this.dz;
      const y = waveHeight(wx, wz, time);
      const fore = waveHeight(wx + 2.5, wz, time);
      const aft = waveHeight(wx - 2.5, wz, time);
      const left = waveHeight(wx, wz - 1.4, time);
      const right = waveHeight(wx, wz + 1.4, time);
      mesh.position.set(x, y * 0.9 + 0.1 + Math.sin(time * 1.3 + phase) * 0.03, z);
      mesh.rotation.set(((left - right) / 2.8) * 0.5, 0, ((fore - aft) / 5) * 0.45, 'YXZ');
    }
  }

  dispose(): void {
    for (const g of this.geometries) g.dispose();
    this.material.dispose();
  }

  private add(geometry: BufferGeometry): Mesh {
    this.geometries.push(geometry);
    const mesh = new Mesh(geometry, this.material);
    this.group.add(mesh);
    return mesh;
  }

  private addBoat(geometry: BufferGeometry, x: number, z: number, phase: number): void {
    const mesh = this.add(geometry);
    mesh.position.set(x, 0, z);
    this.boats.push({ mesh, x, z, phase });
  }
}

