export interface WaveDef {
  readonly dirX: number;
  readonly dirZ: number;
  /** Peak steepness k·A in (0, 1); the sum over all waves must stay below 1. */
  readonly steepness: number;
  readonly wavelength: number;
}

const wave = (angleDeg: number, wavelength: number, steepness: number): WaveDef => {
  const a = (angleDeg * Math.PI) / 180;
  return { dirX: Math.cos(a), dirZ: Math.sin(a), steepness, wavelength };
};

/** Gerstner wave set shared by the CPU (floating physics) and the GPU (ocean shader). */
export const WAVES: readonly [WaveDef, WaveDef, WaveDef, WaveDef] = [
  wave(12, 64, 0.15),
  wave(-28, 34, 0.11),
  wave(55, 18, 0.08),
  wave(-75, 9.5, 0.05),
];

const GRAVITY = 9.81;

/** Surface height at (x, z) and time t, using the same Gerstner sum as the shader. */
export function waveHeight(x: number, z: number, t: number): number {
  let h = 0;
  for (const w of WAVES) {
    const k = (2 * Math.PI) / w.wavelength;
    const amplitude = w.steepness / k;
    const omega = Math.sqrt(GRAVITY * k);
    h += amplitude * Math.sin(k * (w.dirX * x + w.dirZ * z) - omega * t);
  }
  return h;
}

/** Angular frequency of a wave, shared with the shader uniform setup. */
export const waveOmega = (wavelength: number): number =>
  Math.sqrt((GRAVITY * 2 * Math.PI) / wavelength);
