import type { Input } from '../core/input.ts';
import { t, type UiKey } from '../i18n/index.ts';

interface Pad {
  readonly code: string;
  readonly icon: string;
  readonly label: UiKey;
  readonly cls: string;
}

const PADS: readonly Pad[] = [
  { code: 'Space', icon: '▲', label: 'touch.rise', cls: 'rise' },
  { code: 'ShiftLeft', icon: '▼', label: 'touch.dive', cls: 'dive' },
  { code: 'KeyL', icon: '☀', label: 'touch.light', cls: 'light' },
  { code: 'KeyF', icon: '◎', label: 'touch.sonar', cls: 'ping' },
  { code: 'KeyP', icon: '◉', label: 'touch.photo', cls: 'photo' },
  { code: 'KeyX', icon: '⇈', label: 'touch.emergency', cls: 'escape' },
];

const STICK_RADIUS = 56;
const DEAD_ZONE = 0.28;

/** On-screen stick and buttons for phones; they feed the same Input the keyboard uses. */
export class TouchControls {
  readonly root = document.createElement('div');
  private readonly input: Input;
  private readonly knob = document.createElement('i');
  private readonly labels: Array<[HTMLElement, UiKey]> = [];
  private stickId: number | null = null;
  private held: string[] = [];

  constructor(input: Input, onPause: () => void) {
    this.input = input;
    this.root.className = 'touch';
    this.root.hidden = true;
    this.root.append(this.buildStick(), this.buildPads(), this.buildPause(onPause));
  }

  mount(parent: HTMLElement): void {
    parent.append(this.root);
  }

  setVisible(visible: boolean): void {
    this.root.hidden = !visible;
    if (!visible) this.releaseAll();
  }

  retranslate(): void {
    for (const [node, key] of this.labels) node.textContent = t(key);
  }

  private label(node: HTMLElement, key: UiKey): void {
    node.textContent = t(key);
    this.labels.push([node, key]);
  }

  private buildStick(): HTMLElement {
    const base = document.createElement('div');
    base.className = 'touch-stick';
    base.append(this.knob);
    const move = (e: PointerEvent): void => {
      const box = base.getBoundingClientRect();
      let dx = e.clientX - (box.left + box.width / 2);
      let dy = e.clientY - (box.top + box.height / 2);
      const len = Math.hypot(dx, dy);
      if (len > STICK_RADIUS) {
        dx = (dx / len) * STICK_RADIUS;
        dy = (dy / len) * STICK_RADIUS;
      }
      this.knob.style.transform = `translate(${dx}px, ${dy}px)`;
      const nx = dx / STICK_RADIUS;
      const ny = dy / STICK_RADIUS;
      this.input.setVirtual('KeyW', ny < -DEAD_ZONE);
      this.input.setVirtual('KeyS', ny > DEAD_ZONE);
      this.input.setVirtual('KeyA', nx < -DEAD_ZONE);
      this.input.setVirtual('KeyD', nx > DEAD_ZONE);
    };
    const end = (e: PointerEvent): void => {
      if (e.pointerId !== this.stickId) return;
      this.stickId = null;
      this.knob.style.transform = '';
      for (const code of ['KeyW', 'KeyS', 'KeyA', 'KeyD']) this.input.setVirtual(code, false);
    };
    base.addEventListener('pointerdown', (e) => {
      if (this.stickId !== null) return;
      e.preventDefault();
      this.stickId = e.pointerId;
      try {
        base.setPointerCapture(e.pointerId);
      } catch {
      }
      move(e);
    });
    base.addEventListener('pointermove', (e) => {
      if (e.pointerId === this.stickId) move(e);
    });
    base.addEventListener('pointerup', end);
    base.addEventListener('pointercancel', end);
    return base;
  }

  private buildPads(): HTMLElement {
    const cluster = document.createElement('div');
    cluster.className = 'touch-pads';
    for (const pad of PADS) {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = `touch-pad ${pad.cls}`;
      const icon = document.createElement('span');
      icon.textContent = pad.icon;
      const caption = document.createElement('small');
      this.label(caption, pad.label);
      b.append(icon, caption);
      const release = (): void => {
        b.classList.remove('on');
        this.input.setVirtual(pad.code, false);
        this.held = this.held.filter((c) => c !== pad.code);
      };
      b.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        try {
          b.setPointerCapture(e.pointerId);
        } catch {
        }
        b.classList.add('on');
        this.held.push(pad.code);
        this.input.setVirtual(pad.code, true);
      });
      b.addEventListener('pointerup', release);
      b.addEventListener('pointercancel', release);
      b.addEventListener('contextmenu', (e) => e.preventDefault());
      cluster.append(b);
    }
    return cluster;
  }

  private buildPause(onPause: () => void): HTMLElement {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'touch-pause';
    b.textContent = '❚❚';
    b.addEventListener('click', onPause);
    return b;
  }

  private releaseAll(): void {
    for (const code of [...this.held, 'KeyW', 'KeyS', 'KeyA', 'KeyD']) this.input.setVirtual(code, false);
    this.held = [];
    this.stickId = null;
    this.knob.style.transform = '';
  }
}
