import { BufferAttribute, BufferGeometry, IcosahedronGeometry, LatheGeometry, Vector2 } from 'three';


class Builder {
  readonly positions: number[] = [];
  readonly indices: number[] = [];

  tube(
    ax: number,
    ay: number,
    az: number,
    bx: number,
    by: number,
    bz: number,
    ra: number,
    rb: number,
    sides = 6,
  ): void {
    const dx = bx - ax;
    const dy = by - ay;
    const dz = bz - az;
    const len = Math.hypot(dx, dy, dz) || 1;
    const ux = dx / len;
    const uy = dy / len;
    const uz = dz / len;
    const wx = Math.abs(uy) > 0.9 ? 1 : 0;
    const wy = Math.abs(uy) > 0.9 ? 0 : 1;
    let px = uy * 0 - uz * wy;
    let py = uz * wx - ux * 0;
    let pz = ux * wy - uy * wx;
    const pl = Math.hypot(px, py, pz) || 1;
    px /= pl;
    py /= pl;
    pz /= pl;
    const qx = uy * pz - uz * py;
    const qy = uz * px - ux * pz;
    const qz = ux * py - uy * px;
    const base = this.positions.length / 3;
    for (let ring = 0; ring < 2; ring++) {
      const r = ring === 0 ? ra : rb;
      const cx = ring === 0 ? ax : bx;
      const cy = ring === 0 ? ay : by;
      const cz = ring === 0 ? az : bz;
      for (let s = 0; s < sides; s++) {
        const a = (s / sides) * Math.PI * 2;
        const c = Math.cos(a) * r;
        const n = Math.sin(a) * r;
        this.positions.push(cx + px * c + qx * n, cy + py * c + qy * n, cz + pz * c + qz * n);
      }
    }
    for (let s = 0; s < sides; s++) {
      const n = (s + 1) % sides;
      const a = base + s;
      const b = base + n;
      this.indices.push(a, b, a + sides, b, b + sides, a + sides);
    }
  }

  strip(ax: number, ay: number, bx: number, by: number, w: number): void {
    const dx = bx - ax;
    const dy = by - ay;
    const len = Math.hypot(dx, dy) || 1;
    const nx = (-dy / len) * w * 0.5;
    const ny = (dx / len) * w * 0.5;
    const base = this.positions.length / 3;
    this.positions.push(ax - nx, ay - ny, 0, ax + nx, ay + ny, 0, bx - nx, by - ny, 0, bx + nx, by + ny, 0);
    this.indices.push(base, base + 1, base + 2, base + 1, base + 3, base + 2);
  }

  build(): BufferGeometry {
    const g = new BufferGeometry();
    g.setAttribute('position', new BufferAttribute(new Float32Array(this.positions), 3));
    g.setIndex(this.indices);
    g.computeVertexNormals();
    return g;
  }
}

const rnd = (n: number): number => {
  const s = Math.sin(n * 91.3458) * 47453.5453;
  return s - Math.floor(s);
};

/** Staghorn-style branching coral. */
export function buildBranchCoral(): BufferGeometry {
  const b = new Builder();
  let seed = 1;
  const grow = (x: number, y: number, z: number, dirx: number, diry: number, dirz: number, len: number, r: number, depth: number): void => {
    const nx = x + dirx * len;
    const ny = y + diry * len;
    const nz = z + dirz * len;
    b.tube(x, y, z, nx, ny, nz, r, r * 0.62);
    if (depth === 0) return;
    const kids = depth === 3 ? 4 : 3;
    for (let i = 0; i < kids; i++) {
      seed++;
      const a = rnd(seed) * Math.PI * 2;
      const spread = 0.45 + rnd(seed + 50) * 0.5;
      let kx = dirx + Math.cos(a) * spread;
      let kz = dirz + Math.sin(a) * spread;
      let ky = diry * 0.9 + 0.35;
      const l = Math.hypot(kx, ky, kz) || 1;
      kx /= l;
      ky /= l;
      kz /= l;
      grow(nx, ny, nz, kx, ky, kz, len * (0.72 + rnd(seed + 9) * 0.2), r * 0.66, depth - 1);
    }
  };
  grow(0, 0, 0, 0, 1, 0, 0.3, 0.06, 3);
  return b.build();
}

/** Table coral: a thin stem under a wide, slightly drooping plate. */
export function buildTableCoral(): BufferGeometry {
  const profile = [
    new Vector2(0.0, 0.0),
    new Vector2(0.09, 0.0),
    new Vector2(0.07, 0.3),
    new Vector2(0.18, 0.46),
    new Vector2(0.52, 0.5),
    new Vector2(0.54, 0.54),
    new Vector2(0.3, 0.6),
    new Vector2(0.0, 0.62),
  ];
  const g = new LatheGeometry(profile, 14);
  const p = g.getAttribute('position') as BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const z = p.getZ(i);
    const r = Math.hypot(x, z);
    if (r > 0.3) p.setY(i, p.getY(i) + Math.sin(Math.atan2(z, x) * 7) * 0.03 * (r - 0.3));
  }
  g.computeVertexNormals();
  return g;
}

/** Brain coral: a grooved dome. */
export function buildBrainCoral(): BufferGeometry {
  const g = new IcosahedronGeometry(0.5, 3);
  const p = g.getAttribute('position') as BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const y = p.getY(i);
    const z = p.getZ(i);
    const groove = 1 + 0.07 * Math.sin(x * 38 + Math.sin(z * 17) * 2.2) * Math.sin(z * 31 + y * 9);
    p.setXYZ(i, x * groove * 1.05, Math.max(y * groove, -0.08) + 0.08, z * groove);
  }
  g.computeVertexNormals();
  return g;
}

/** Sea fan: a lattice of ribs and rings standing in the XY plane. */
export function buildFanCoral(): BufferGeometry {
  const b = new Builder();
  const ribs = 9;
  const rings = 5;
  const spread = 1.25;
  const point = (rib: number, r: number): [number, number] => {
    const a = (rib / (ribs - 1) - 0.5) * spread * 2;
    return [Math.sin(a) * r * 0.5, 0.12 + Math.cos(a) * r * 0.88];
  };
  for (let rib = 0; rib < ribs; rib++) {
    const [x0, y0] = point(rib, 0.05);
    const [x1, y1] = point(rib, 1);
    b.strip(x0, y0, x1, y1, 0.035);
  }
  for (let ring = 1; ring <= rings; ring++) {
    const r = ring / rings;
    for (let rib = 0; rib < ribs - 1; rib++) {
      const [ax, ay] = point(rib, r);
      const [bx, by] = point(rib + 1, r);
      b.strip(ax, ay, bx, by, 0.02);
    }
  }
  b.strip(0, 0, 0, 0.14, 0.07);
  return b.build();
}
