import { clamp, TAU, wrapPi } from '../core/math.ts';
import type { Rng } from '../core/random.ts';
import type { SpeciesDef } from '../data/species.ts';
import type { Point3, SchoolEnv } from './school.ts';

/** Small animals are drawn larger than life; the same size is used for rendering and collisions. */
export const visualSize = (species: SpeciesDef): number =>
  species.sizeM >= 1 ? species.sizeM : Math.max(species.sizeM * 3.8, 0.6);

/** Animals shorter than this are harmless to bump into. */
export const SOLID_MIN_SIZE = 2;

const BODY_THICKNESS: Partial<Record<SpeciesDef['archetype'], number>> = {
  whale: 0.13,
  shark: 0.1,
  fish: 0.1,
  ray: 0.2,
  turtle: 0.22,
  squid: 0.08,
  jelly: 0.35,
  octopus: 0.2,
  eel: 0.04,
};

export interface BodyHit {
  nx: number;
  ny: number;
  nz: number;
  overlap: number;
}

const TOP_DEPTH = 2.5;
const LOOK_AHEAD_SECONDS = 5;
const FLEE_RADIUS = 30;
const CURIOUS_RANGE = 90;
const CURIOUS_KEEP = 14;

/** A single large animal: wanders, keeps its depth, avoids the seabed and reacts to the submarine. */
export class Creature {
  readonly speciesId: string;
  readonly species: SpeciesDef;
  readonly position: Point3;
  heading: number;
  pitch = 0;
  speed: number;
  readonly phase: number;
  alarm = 0;
  private readonly seed: number;
  private readonly turnSign: number;
  private readonly benthic: boolean;

  constructor(species: SpeciesDef, position: Point3, rng: Rng) {
    this.species = species;
    this.speciesId = species.id;
    this.position = { ...position };
    this.heading = rng.next() * TAU;
    this.speed = species.speed * 0.6;
    this.phase = rng.next();
    this.seed = rng.next() * 100;
    this.turnSign = rng.chance(0.5) ? 1 : -1;
    this.benthic = species.habitat === 'benthic';
  }

  forward(): Point3 {
    const c = Math.cos(this.pitch);
    return { x: Math.cos(this.heading) * c, y: Math.sin(this.pitch), z: Math.sin(this.heading) * c };
  }

  get solid(): boolean {
    return this.species.sizeM >= SOLID_MIN_SIZE;
  }

  velocity(): Point3 {
    const f = this.forward();
    return { x: f.x * this.speed, y: f.y * this.speed, z: f.z * this.speed };
  }

  bodyHit(point: Point3, radius: number): BodyHit | null {
    if (!this.solid) return null;
    const length = visualSize(this.species);
    const thickness = length * (BODY_THICKNESS[this.species.archetype] ?? 0.1);
    const half = Math.max(0, length * 0.5 - thickness);
    const f = this.forward();
    const px = point.x - this.position.x;
    const py = point.y - this.position.y;
    const pz = point.z - this.position.z;
    const along = clamp(px * f.x + py * f.y + pz * f.z, -half, half);
    const dx = px - f.x * along;
    const dy = py - f.y * along;
    const dz = pz - f.z * along;
    const d = Math.hypot(dx, dy, dz);
    const reach = thickness + radius;
    if (d >= reach) return null;
    if (d < 1e-4) return { nx: 0, ny: 1, nz: 0, overlap: reach };
    return { nx: dx / d, ny: dy / d, nz: dz / d, overlap: reach - d };
  }

  update(dt: number, time: number, env: SchoolEnv, sub: Point3): void {
    const sp = this.species;
    const p = this.position;
    const dx = sub.x - p.x;
    const dy = sub.y - p.y;
    const dz = sub.z - p.z;
    const dist = Math.hypot(dx, dy, dz);
    const toSub = Math.atan2(dz, dx);

    this.alarm = Math.max(0, this.alarm - dt * 0.35);
    let turn = 0.32 * Math.sin(time * 0.13 + this.seed) + 0.2 * Math.sin(time * 0.37 + this.seed * 2.3);
    let speedFactor = 0.6;

    if (sp.temperament === 'skittish' && dist < FLEE_RADIUS + sp.sizeM) {
      this.alarm = 1;
      turn += clamp(wrapPi(toSub + Math.PI - this.heading), -1, 1) * 2.5;
    } else if (sp.temperament === 'curious' && dist < CURIOUS_RANGE) {
      const want = dist > CURIOUS_KEEP + sp.sizeM ? toSub : toSub + Math.PI * 0.5 * this.turnSign;
      turn += clamp(wrapPi(want - this.heading), -1, 1) * 1.2;
      speedFactor = dist > CURIOUS_KEEP + sp.sizeM ? 0.9 : 0.5;
    } else if (dist < 6 + sp.sizeM * 0.5) {
      turn += clamp(wrapPi(toSub + Math.PI - this.heading), -1, 1) * 1.5;
    }
    speedFactor *= 1 + 2 * this.alarm;

    const lead = Math.max(14, this.speed * LOOK_AHEAD_SECONDS + sp.sizeM);
    const ahead = env.seabedY(p.x + Math.cos(this.heading) * lead, p.z + Math.sin(this.heading) * lead);
    const clearance = 3 + sp.sizeM * 0.6;
    if (!this.benthic && ahead > p.y - clearance) turn += this.turnSign * 1.6;
    if (this.benthic && ahead > p.y + 2) turn += this.turnSign * 1.6;

    this.heading += turn * dt;
    const target = this.speed + (sp.speed * speedFactor - this.speed) * Math.min(1, dt * 1.5);
    this.speed = target;

    const floor = env.seabedY(p.x, p.z);
    const top = -Math.max(TOP_DEPTH + sp.sizeM * 0.2, sp.depth[0]);
    let wantY: number;
    if (this.benthic) {
      wantY = floor + 0.4 + sp.sizeM * 0.4;
    } else {
      const bottom = Math.max(-sp.depth[1], floor + clearance);
      const preferred = -sp.prefer + Math.sin(time * 0.05 + this.seed) * Math.min(40, sp.prefer * 0.15);
      wantY = bottom > top ? top : clamp(preferred, bottom, top);
    }
    const pitchWant = clamp((wantY - p.y) * 0.06, -0.45, 0.45);
    this.pitch += (pitchWant - this.pitch) * Math.min(1, dt * 1.2);

    const horizontal = Math.cos(this.pitch);
    p.x += Math.cos(this.heading) * this.speed * horizontal * dt;
    p.z += Math.sin(this.heading) * this.speed * horizontal * dt;
    p.y += Math.sin(this.pitch) * this.speed * dt;
    const minY = floor + (this.benthic ? 0.2 : 1 + sp.sizeM * 0.3);
    p.y = clamp(p.y, minY, -TOP_DEPTH * 0.6);
  }
}
