import { BackSide, Mesh, ShaderMaterial, SphereGeometry } from 'three';
import { COMMON_UNIFORMS, NOISE_GLSL, SKY_GLSL } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

const vertexShader = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = position;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_Position.z = gl_Position.w; // always on the far plane
}
`;

const fragmentShader = /* glsl */ `
${COMMON_UNIFORMS}
${NOISE_GLSL}
${SKY_GLSL}
varying vec3 vDir;
void main() {
  gl_FragColor = vec4(skyColor(normalize(vDir)), 1.0);
}
`;

/** A sky dome that follows the camera. Hidden while the camera is underwater. */
export class SkyDome {
  readonly mesh: Mesh<SphereGeometry, ShaderMaterial>;

  constructor(uniforms: SceneUniforms) {
    const material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
      },
      vertexShader,
      fragmentShader,
      side: BackSide,
      depthWrite: false,
      fog: false,
    });
    this.mesh = new Mesh(new SphereGeometry(1000, 48, 24), material);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = -10;
  }

  follow(x: number, y: number, z: number): void {
    this.mesh.position.set(x, y, z);
  }
}
