import { t } from '../i18n/index.ts';
import { clamp } from '../core/math.ts';
import { BALANCE } from '../data/balance.ts';
import type { SpeciesDef } from '../data/species.ts';

/** One animal as seen through the lens. */
export interface PhotoSubject {
  species: SpeciesDef;
  distance: number;
  size: number;
  x: number;
  y: number;
  fov: number;
}

/** 0..100 quality of a shot: how well framed, how centred and how near the subject is. */
export function scorePhoto(s: PhotoSubject, cameraBonus: number): number {
  const angle = 2 * Math.atan(s.size / 2 / Math.max(s.distance, 0.5));
  const coverage = angle / s.fov;
  const framing = coverage < 0.4 ? clamp(coverage / 0.4) ** 0.8 : clamp(1 - (coverage - 0.4) / 0.9);
  const centring = 1 - clamp(Math.hypot(s.x * 0.8, s.y));
  const nearness = 1 - clamp((s.distance - 8) / 60);
  const quality = 0.5 * framing + 0.32 * centring + 0.18 * nearness;
  return Math.round(clamp(quality + cameraBonus) * 100);
}

export interface PhotoHistory {
  best: number;
  count: number;
}

/** Credits for a shot: a good first photo pays well, repeats pay a little and fade. */
export function photoReward(species: SpeciesDef, score: number, before: PhotoHistory | undefined): number {
  if (score < BALANCE.photo.minScore) return 0;
  const quality = score / 100;
  const share =
    before === undefined || before.count === 0
      ? BALANCE.photo.firstShare * BALANCE.photo.discoveryMultiplier
      : BALANCE.photo.repeatRate * BALANCE.photo.repeatDecay ** Math.min(before.count - 1, 6);
  return Math.max(1, Math.round(species.value * quality * quality * share));
}

export function ratingText(score: number): string {
  if (score >= 90) return t('rating.masterpiece');
  if (score >= 75) return t('rating.excellent');
  if (score >= 55) return t('rating.good');
  if (score >= BALANCE.photo.minScore) return t('rating.fair');
  return t('rating.poor');
}
