export type CurvePoint = readonly [x: number, y: number];

const at = (values: readonly number[], index: number): number => values[index] ?? 0;

/**
 * Builds a monotone cubic Hermite interpolant (Fritsch–Carlson) through the given points.
 * It never overshoots between control points, which is exactly what a seabed profile needs:
 * smooth slopes with no phantom bumps. Outside the range the curve is held flat.
 */
export function createMonotoneCurve(points: readonly CurvePoint[]): (x: number) => number {
  if (points.length < 2) throw new Error('A curve needs at least two points');
  const xs = points.map((p) => p[0]);
  const ys = points.map((p) => p[1]);
  for (let i = 1; i < xs.length; i++) {
    if (at(xs, i) <= at(xs, i - 1)) throw new Error('Curve x values must be strictly increasing');
  }

  const n = xs.length;
  const delta: number[] = [];
  for (let i = 0; i < n - 1; i++) {
    delta.push((at(ys, i + 1) - at(ys, i)) / (at(xs, i + 1) - at(xs, i)));
  }

  const tangent: number[] = new Array<number>(n).fill(0);
  tangent[0] = at(delta, 0);
  tangent[n - 1] = at(delta, n - 2);
  for (let i = 1; i < n - 1; i++) {
    const before = at(delta, i - 1);
    const after = at(delta, i);
    tangent[i] = before * after <= 0 ? 0 : (before + after) / 2;
  }

  for (let i = 0; i < n - 1; i++) {
    const d = at(delta, i);
    if (d === 0) {
      tangent[i] = 0;
      tangent[i + 1] = 0;
      continue;
    }
    const a = at(tangent, i) / d;
    const b = at(tangent, i + 1) / d;
    const s = a * a + b * b;
    if (s > 9) {
      const t = 3 / Math.sqrt(s);
      tangent[i] = t * a * d;
      tangent[i + 1] = t * b * d;
    }
  }

  return (x: number): number => {
    if (x <= at(xs, 0)) return at(ys, 0);
    if (x >= at(xs, n - 1)) return at(ys, n - 1);

    let lo = 0;
    let hi = n - 1;
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (at(xs, mid) <= x) lo = mid;
      else hi = mid;
    }

    const h = at(xs, hi) - at(xs, lo);
    const t = (x - at(xs, lo)) / h;
    const t2 = t * t;
    const t3 = t2 * t;
    return (
      (2 * t3 - 3 * t2 + 1) * at(ys, lo) +
      (t3 - 2 * t2 + t) * h * at(tangent, lo) +
      (-2 * t3 + 3 * t2) * at(ys, hi) +
      (t3 - t2) * h * at(tangent, hi)
    );
  };
}
