import { type SoundInput, soundParams, type VolumeSettings, busGain } from './mix.ts';

type Ctx = AudioContext;

const SCALE = [0, 3, 5, 7, 10, 12, 15];

/**
 * All sound of the game, synthesised on the fly (no audio files). Browsers only allow sound after a
 * click, so everything starts in `unlock()`; before that and without WebAudio every method does nothing.
 */
export class AudioEngine {
  private ctx: Ctx | null = null;
  private master: GainNode | null = null;
  private sfx: GainNode | null = null;
  private ambience: GainNode | null = null;
  private music: GainNode | null = null;
  private noise: AudioBuffer | null = null;
  private volumes: VolumeSettings = { volumeMaster: 0.8, volumeEffects: 1, volumeAmbient: 0.8, volumeMusic: 0.5 };
  private paused = false;

  private waveGain: GainNode | null = null;
  private waveFilter: BiquadFilterNode | null = null;
  private deepGain: GainNode | null = null;
  private deepOsc: OscillatorNode | null = null;
  private engineGain: GainNode | null = null;
  private engineOsc: OscillatorNode | null = null;
  private flowGain: GainNode | null = null;
  private flowFilter: BiquadFilterNode | null = null;
  private nextNote = 0;
  private padRoot = 55;

  unlock(): void {
    if (this.ctx) {
      void this.ctx.resume();
      return;
    }
    const Ctor: typeof AudioContext | undefined = typeof AudioContext === 'undefined' ? undefined : AudioContext;
    if (!Ctor) return;
    try {
      const ctx = new Ctor();
      this.ctx = ctx;
      this.master = ctx.createGain();
      this.master.connect(ctx.destination);
      this.sfx = this.bus(ctx);
      this.ambience = this.bus(ctx);
      this.music = this.bus(ctx);
      this.noise = this.makeNoise(ctx);
      this.buildAmbience(ctx);
      this.applyVolumes();
    } catch {
      this.ctx = null;
    }
  }

  setVolumes(v: VolumeSettings): void {
    this.volumes = v;
    this.applyVolumes();
  }

  setPaused(paused: boolean): void {
    this.paused = paused;
    this.applyVolumes();
  }

  update(input: SoundInput, dt: number): void {
    const ctx = this.ctx;
    if (!ctx || this.paused) return;
    const p = soundParams(input);
    const t = ctx.currentTime;
    const ease = 0.25;
    this.waveGain?.gain.setTargetAtTime(p.waveGain, t, ease);
    this.waveFilter?.frequency.setTargetAtTime(p.waveCutoff, t, ease);
    this.deepGain?.gain.setTargetAtTime(p.deepGain, t, 0.8);
    this.deepOsc?.frequency.setTargetAtTime(p.deepFreq, t, 0.8);
    this.engineGain?.gain.setTargetAtTime(p.engineGain, t, 0.15);
    this.engineOsc?.frequency.setTargetAtTime(p.engineFreq, t, 0.2);
    this.flowGain?.gain.setTargetAtTime(p.flowGain, t, 0.2);
    this.flowFilter?.frequency.setTargetAtTime(p.flowCutoff, t, 0.2);
    this.padRoot = 55 * 2 ** (-Math.min(1, Math.max(0, input.depth) / 6000) * 0.5);
    this.nextNote -= dt;
    if (this.nextNote <= 0) {
      this.nextNote = 4 + Math.random() * 6;
      this.pad();
    }
  }


  ping(): void {
    this.tone(1500, 900, 0.9, 0.3, 'sine');
    this.tone(1500, 900, 0.9, 0.12, 'sine', 0.28);
  }

  shutter(): void {
    this.burst(0.06, 4000, 0.35);
    this.tone(1800, 600, 0.08, 0.15, 'square', 0.02);
  }

  bump(strength: number): void {
    const s = Math.min(1, Math.max(0.15, strength));
    this.tone(120, 40, 0.5, 0.7 * s, 'sine');
    this.burst(0.25, 500, 0.5 * s);
  }

  chime(kind: 'discovery' | 'mission' | 'photo' = 'discovery'): void {
    const notes = kind === 'mission' ? [523, 659, 784, 1046] : kind === 'photo' ? [784, 1046] : [659, 880, 1175];
    notes.forEach((f, i) => this.tone(f, f, 0.9, 0.18, 'triangle', i * 0.11));
  }

  warning(): void {
    this.tone(880, 880, 0.14, 0.25, 'square');
    this.tone(880, 880, 0.14, 0.25, 'square', 0.22);
  }

  click(): void {
    this.tone(700, 500, 0.05, 0.12, 'triangle');
  }


  private bus(ctx: Ctx): GainNode {
    const g = ctx.createGain();
    if (this.master) g.connect(this.master);
    return g;
  }

  private applyVolumes(): void {
    const ctx = this.ctx;
    if (!ctx || !this.master || !this.sfx || !this.ambience || !this.music) return;
    const t = ctx.currentTime;
    const v = this.volumes;
    this.master.gain.setTargetAtTime(1, t, 0.05);
    this.sfx.gain.setTargetAtTime(busGain(v.volumeMaster, v.volumeEffects), t, 0.05);
    const live = this.paused ? 0.25 : 1;
    this.ambience.gain.setTargetAtTime(busGain(v.volumeMaster, v.volumeAmbient) * live, t, 0.1);
    this.music.gain.setTargetAtTime(busGain(v.volumeMaster, v.volumeMusic) * live, t, 0.1);
  }

  private makeNoise(ctx: Ctx): AudioBuffer {
    const length = ctx.sampleRate * 3;
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      last = (last + 0.02 * (Math.random() * 2 - 1)) / 1.02;
      data[i] = last * 3.5;
    }
    return buffer;
  }

  private noiseSource(ctx: Ctx): AudioBufferSourceNode {
    const src = ctx.createBufferSource();
    if (this.noise) src.buffer = this.noise;
    src.loop = true;
    return src;
  }

  private buildAmbience(ctx: Ctx): void {
    const out = this.ambience;
    if (!out) return;
    const waves = this.noiseSource(ctx);
    this.waveFilter = ctx.createBiquadFilter();
    this.waveFilter.type = 'lowpass';
    this.waveGain = ctx.createGain();
    const swell = ctx.createOscillator();
    swell.frequency.value = 0.13;
    const swellDepth = ctx.createGain();
    swellDepth.gain.value = 0.35;
    swell.connect(swellDepth).connect(this.waveGain.gain);
    waves.connect(this.waveFilter).connect(this.waveGain).connect(out);
    waves.start();
    swell.start();
    this.deepOsc = ctx.createOscillator();
    this.deepOsc.type = 'sine';
    this.deepOsc.frequency.value = 50;
    this.deepGain = ctx.createGain();
    this.deepGain.gain.value = 0;
    this.deepOsc.connect(this.deepGain).connect(out);
    this.deepOsc.start();
    this.engineOsc = ctx.createOscillator();
    this.engineOsc.type = 'sawtooth';
    this.engineOsc.frequency.value = 62;
    const engineFilter = ctx.createBiquadFilter();
    engineFilter.type = 'lowpass';
    engineFilter.frequency.value = 380;
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineOsc.connect(engineFilter).connect(this.engineGain).connect(out);
    this.engineOsc.start();
    const flow = this.noiseSource(ctx);
    this.flowFilter = ctx.createBiquadFilter();
    this.flowFilter.type = 'bandpass';
    this.flowFilter.frequency.value = 400;
    this.flowGain = ctx.createGain();
    this.flowGain.gain.value = 0;
    flow.connect(this.flowFilter).connect(this.flowGain).connect(out);
    flow.start();
  }

  private pad(): void {
    const ctx = this.ctx;
    const out = this.music;
    if (!ctx || !out) return;
    const step = SCALE[Math.floor(Math.random() * SCALE.length)] ?? 0;
    const f = this.padRoot * 2 ** (step / 12) * (Math.random() < 0.3 ? 2 : 1);
    const t = ctx.currentTime;
    for (const detune of [-6, 6]) {
      const o = ctx.createOscillator();
      o.type = 'sine';
      o.frequency.value = f;
      o.detune.value = detune;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(0.09, t + 3);
      g.gain.linearRampToValueAtTime(0, t + 9);
      o.connect(g).connect(out);
      o.start(t);
      o.stop(t + 9.2);
    }
  }

  private tone(from: number, to: number, length: number, gain: number, type: OscillatorType, delay = 0): void {
    const ctx = this.ctx;
    const out = this.sfx;
    if (!ctx || !out) return;
    const t = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(from, t);
    if (to !== from) o.frequency.exponentialRampToValueAtTime(Math.max(1, to), t + length);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + length);
    o.connect(g).connect(out);
    o.start(t);
    o.stop(t + length + 0.05);
  }

  private burst(length: number, cutoff: number, gain: number): void {
    const ctx = this.ctx;
    const out = this.sfx;
    if (!ctx || !out) return;
    const t = ctx.currentTime;
    const src = this.noiseSource(ctx);
    const f = ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = cutoff;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + length);
    src.connect(f).connect(g).connect(out);
    src.start(t);
    src.stop(t + length + 0.05);
  }
}
