import { t } from '../i18n/index.ts';
import type { AuthClient, AuthResult, LinkNotice, Session, SimpleResult } from './auth.ts';
import type { BackendConfig } from './config.ts';
import { type Board, type BoardData, fetchLeaderboard } from './leaderboard.ts';
import type { ProgressSync, SyncStatus } from './sync.ts';

type Listener = () => void;

/** What the menu needs from the online side. `enabled` is false when no backend is configured. */
export interface Account {
  readonly enabled: boolean;
  readonly session: Session | null;
  readonly status: SyncStatus;
  signIn(email: string, password: string): Promise<AuthResult>;
  signUp(email: string, password: string, username: string): Promise<AuthResult>;
  signOut(): Promise<void>;
  resetPassword(email: string): Promise<SimpleResult>;
  resendConfirmation(email: string): Promise<SimpleResult>;
  changePassword(password: string): Promise<SimpleResult>;
  readonly notice: LinkNotice | null;
  consumeLink(hash: string): Promise<LinkNotice | null>;
  clearNotice(): void;
  saveNow(): Promise<void>;
  retry(): void;
  /** The public ranking; rejects when the server cannot be reached. */
  leaderboard(board: Board): Promise<BoardData>;
  subscribe(listener: Listener): () => void;
}

/** Used when the game runs without a backend: everything is a guest session. */
export const OFFLINE_ACCOUNT: Account = {
  enabled: false,
  session: null,
  status: 'guest',
  signIn: async () => ({ ok: false, message: t('net.notConfigured') }),
  signUp: async () => ({ ok: false, message: t('net.notConfigured') }),
  signOut: async () => undefined,
  resetPassword: async () => ({ ok: false, message: t('net.notConfigured') }),
  resendConfirmation: async () => ({ ok: false, message: t('net.notConfigured') }),
  changePassword: async () => ({ ok: false, message: t('net.notConfigured') }),
  notice: null,
  consumeLink: async () => null,
  clearNotice: () => undefined,
  saveNow: async () => undefined,
  retry: () => undefined,
  leaderboard: () => Promise.reject(new Error('offline')),
  subscribe: () => () => undefined,
};

export function createAccount(config: BackendConfig, auth: AuthClient, sync: ProgressSync): Account {
  const listeners = new Set<Listener>();
  const notify = (): void => {
    for (const l of listeners) l();
  };
  auth.subscribe(notify);
  sync.subscribe(notify);
  let notice: LinkNotice | null = null;
  return {
    enabled: true,
    get session() {
      return auth.session;
    },
    get status() {
      return sync.status;
    },
    signIn: (email, password) => auth.signIn(email, password),
    signUp: (email, password, username) => auth.signUp(email, password, username),
    async signOut() {
      await sync.flush();
      await auth.signOut();
    },
    resetPassword: (email) => auth.resetPassword(email),
    resendConfirmation: (email) => auth.resendConfirmation(email),
    changePassword: (password) => auth.updatePassword(password),
    get notice() {
      return notice;
    },
    async consumeLink(hash) {
      notice = await auth.consumeRedirect(hash);
      if (notice) notify();
      return notice;
    },
    clearNotice() {
      notice = null;
    },
    saveNow: () => sync.flush(),
    retry: () => sync.retry(),
    leaderboard: (board) => fetchLeaderboard(config, auth, board),
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}
