import { hashInts } from './random.ts';

const fade = (t: number): number => t * t * t * (t * (t * 6 - 15) + 10);

const lattice = (ix: number, iz: number, seed: number): number =>
  hashInts(ix, iz, seed) / 4294967296;

/** Smooth 2D value noise in [0, 1]. */
export function valueNoise2(x: number, z: number, seed = 0): number {
  const ix = Math.floor(x);
  const iz = Math.floor(z);
  const fx = fade(x - ix);
  const fz = fade(z - iz);
  const a = lattice(ix, iz, seed);
  const b = lattice(ix + 1, iz, seed);
  const c = lattice(ix, iz + 1, seed);
  const d = lattice(ix + 1, iz + 1, seed);
  return a + (b - a) * fx + (c - a) * fz + (a - b - c + d) * fx * fz;
}

/** Fractal Brownian motion built from value noise, normalised to [0, 1]. */
export function fbm2(x: number, z: number, octaves = 4, seed = 0): number {
  let sum = 0;
  let amp = 0.5;
  let freq = 1;
  let norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += amp * valueNoise2(x * freq, z * freq, seed + i * 101);
    norm += amp;
    amp *= 0.5;
    freq *= 2;
  }
  return sum / norm;
}

/** Smooth 1D noise in [0, 1], handy for wandering headings. */
export const noise1 = (x: number, seed = 0): number => valueNoise2(x, seed * 17.13, seed);
