import type { SpeciesDef } from '../data/species.ts';


const NS = 'http://www.w3.org/2000/svg';

interface Part {
  d: string;
  line?: boolean;
  thick?: boolean;
  dark?: boolean;
}

function fishParts(s: SpeciesDef): Part[] {
  const L = clamp(s.shape?.length ?? 1, 0.55, 1.9);
  const H = clamp(s.shape?.height ?? 1, 0.45, 1.8);
  const cx = 60;
  const rx = Math.min(36, 25 * L);
  const ry = Math.min(24, 11 * H * (s.shape?.width ? 1 : 1));
  const nx = cx + rx;
  const tx = cx - rx * 0.8;
  const body = `M${nx},30 C${cx + rx * 0.5},${30 - ry * 1.5} ${cx - rx * 0.5},${30 - ry * 1.15} ${tx},30 C${cx - rx * 0.5},${30 + ry * 1.15} ${cx + rx * 0.5},${30 + ry * 1.5} ${nx},30 Z`;
  const parts: Part[] = [{ d: body }];
  const tail = s.shape?.tail ?? 'fork';
  const fy = Math.min(17, 10 + ry * 0.5);
  if (tail === 'fork') parts.push({ d: `M${tx + 2},30 L${tx - 15},${30 - fy} Q${tx - 9},30 ${tx - 15},${30 + fy} Z` });
  else if (tail === 'lunate') parts.push({ d: `M${tx + 2},30 Q${tx - 4},${30 - fy} ${tx - 14},${30 - fy - 3} Q${tx - 7},30 ${tx - 14},${30 + fy + 3} Q${tx - 4},${30 + fy} ${tx + 2},30 Z` });
  else if (tail === 'shark') parts.push({ d: `M${tx + 2},30 L${tx - 14},${30 - fy - 5} Q${tx - 8},30 ${tx - 11},${30 + fy - 2} Z` });
  else parts.push({ d: `M${tx + 2},30 Q${tx - 6},${30 - fy * 0.8} ${tx - 11},30 Q${tx - 6},${30 + fy * 0.8} ${tx + 2},30 Z` });
  if (s.shape?.dorsal) parts.push({ d: `M${cx + 6},${30 - ry * 1.25} L${cx - 4},${30 - ry * 1.25 - 11} L${cx - 14},${30 - ry * 1.05} Z` });
  parts.push({ d: `M${cx + 8},${30 + ry * 0.6} L${cx - 2},${30 + ry * 0.6 + 9} L${cx - 6},${30 + ry * 0.7} Z` });
  parts.push({ d: `M${nx - 9},${30 - 3} a1.8,1.8 0 1,0 0.01,0`, dark: true });
  if (s.shape?.bigMouth) parts.push({ d: `M${nx},30 L${nx - rx * 0.55},${30 + 3}`, line: true });
  if (s.shape?.lure) {
    parts.push({ d: `M${nx - 10},${30 - ry * 1.2} Q${nx - 4},${30 - ry * 1.2 - 14} ${nx + 6},${30 - ry * 1.2 - 12}`, line: true });
    parts.push({ d: `M${nx + 6},${30 - ry * 1.2 - 12} m-2.2,0 a2.2,2.2 0 1,0 4.4,0 a2.2,2.2 0 1,0 -4.4,0` });
  }
  return parts;
}

