function partsFor(s: SpeciesDef): Part[] {
  switch (s.archetype) {
    case 'shark':
      return SHARK;
    case 'whale':
      return WHALE;
    case 'ray':
      return RAY;
    case 'turtle':
      return TURTLE;
    case 'squid':
      return SQUID;
    case 'jelly':
      return JELLY;
    case 'crustacean':
      return CRUSTACEAN;
    case 'octopus':
      return OCTOPUS;
    case 'eel':
      return EEL;
    case 'cucumber':
      return CUCUMBER;
    default:
      return fishParts(s);
  }
}

const clamp = (v: number, a: number, b: number): number => Math.min(b, Math.max(a, v));

/** Lifts very dark colours so a silhouette never disappears against the dark UI. */
function css(hex: number, minLight: number): string {
  let r = (hex >> 16) & 255;
  let g = (hex >> 8) & 255;
  let b = hex & 255;
  const light = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
  if (light < minLight) {
    const t = (minLight - light) / (1 - light);
    r += (200 - r) * t * 0.9;
    g += (225 - g) * t * 0.9;
    b += (235 - b) * t * 0.9;
  }
  return `rgb(${Math.round(r)}, ${Math.round(g)}, ${Math.round(b)})`;
}

/** An SVG silhouette of the species, tinted with its own colours (and a halo if it glows). */
export function createSilhouette(species: SpeciesDef): SVGSVGElement {
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '-6 -4 132 68');
  svg.setAttribute('class', 'silhouette');
  svg.setAttribute('aria-hidden', 'true');
  svg.style.setProperty('--c', css(species.body, 0.36));
  svg.style.setProperty('--a', css(species.accent, 0.5));
  if (species.glow !== undefined) {
    svg.style.setProperty('--halo', css(species.glow, 0.6));
    svg.classList.add('glows');
  }
  if (species.opacity !== undefined) svg.style.opacity = String(Math.max(0.6, species.opacity));
  for (const part of partsFor(species)) {
    if (part.dark) {
      for (const m of part.d.matchAll(/M\s*(-?[\d.]+),(-?[\d.]+)\s*a\s*([\d.]+),/g)) {
        const eye = document.createElementNS(NS, 'circle');
        eye.setAttribute('cx', m[1] ?? '0');
        eye.setAttribute('cy', m[2] ?? '0');
        eye.setAttribute('r', m[3] ?? '1.5');
        eye.setAttribute('class', 'eye');
        svg.append(eye);
      }
      continue;
    }
    const path = document.createElementNS(NS, 'path');
    path.setAttribute('d', part.d);
    if (part.thick) path.setAttribute('class', 'line thick');
    else if (part.line) path.setAttribute('class', 'line');
    svg.append(path);
  }
  return svg;
}
