import type { Settings, SettingsStore } from '../core/settings.ts';
import { SETTING_LIMITS } from '../core/settings.ts';
import { isTouchDevice } from '../core/device.ts';
import { PORTS } from '../data/ports.ts';
import { MAX_UPGRADE_LEVEL, UPGRADE_IDS } from '../data/upgrades.ts';
import { LANGS, num, onLangChange, t, type UiKey } from '../i18n/index.ts';
import { missionDescription, missionTitle, portDescription, portName, portPerk, upgradeDescription, upgradeLevel, upgradeName } from '../i18n/names.ts';
import { isLang } from '../i18n/index.ts';
import type { PhotoAlbum } from '../domain/photo-album.ts';
import type { ProgressStore } from '../domain/progress.ts';
import type { Account } from '../net/account.ts';
import { accountLabel, createAccountView } from './account-view.ts';
import { MISSIONS } from '../data/missions.ts';
import { missionProgress } from '../domain/missions.ts';
import { createBestiary } from './bestiary.ts';
import { createLeaderboardView } from './leaderboard-view.ts';
import type { AppMode } from '../app/game-app.ts';

export interface MenuActions {
  begin(): void;
  resume(): void;
  exitToTitle(): void;
}

type SheetName = 'settings' | 'bestiary' | 'workshop' | 'harbours' | 'missions' | 'leaderboard' | 'account' | 'controls';
type TabName = 'graphics' | 'sound' | 'controls' | 'interface' | 'about';

const VERSION = '1.0';

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  className?: string,
  text?: string,
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function button(label: string, className: string, onClick: () => void): HTMLButtonElement {
  const b = el('button', className, label);
  b.type = 'button';
  b.addEventListener('click', onClick);
  return b;
}

const QUALITY_IDS: ReadonlyArray<Settings['quality']> = ['auto', 'low', 'medium', 'high', 'ultra'];

const keyGroups = (): ReadonlyArray<{ title: string; rows: ReadonlyArray<readonly [string[], string]> }> => [
  {
    title: t('keys.group.sub'),
    rows: [
      [['W', 'S'], t('keys.move')],
      [['A', 'D'], t('keys.turn')],
      [[t('key.space')], t('keys.rise')],
      [['Shift'], t('keys.dive')],
      [['L'], t('keys.light')],
      [['F'], t('keys.sonar')],
      [['P'], t('keys.photo')],
      [['X'], t('keys.emergency')],
    ],
  },
  {
    title: t('keys.group.camera'),
    rows: [
      [[t('key.mouse')], t('keys.look')],
      [[t('key.wheel')], t('keys.zoom')],
      [['1', '–', '5'], t('keys.sites')],
      [['Esc'], t('keys.pause')],
    ],
  },
];

/**
 * The title screen, pause menu and the settings / controls / about sheets. Everything is built
 * from the settings store, so changes apply and save instantly.
 */
export class Menu {
  private readonly sheet = el('div', 'sheet-backdrop');
  private readonly sheetBody = el('div', 'sheet');
  private opener: HTMLElement | null = null;
  private open: SheetName | null = null;
  private tab: TabName = 'graphics';
  private mode: AppMode = 'title';
  private readonly settings: SettingsStore;
  private readonly progress: ProgressStore;
  private readonly account: Account;
  private readonly album: PhotoAlbum;
  private readonly accountItems: HTMLElement[] = [];
  private readonly actions: MenuActions;
  private readonly titleNav: HTMLElement;
  private readonly pauseNav: HTMLElement;

  constructor(
    titleNav: HTMLElement,
    pauseNav: HTMLElement,
    settings: SettingsStore,
    progress: ProgressStore,
    account: Account,
    album: PhotoAlbum,
    actions: MenuActions,
  ) {
    this.album = album;
    this.settings = settings;
    this.progress = progress;
    this.account = account;
    this.actions = actions;

    this.titleNav = titleNav;
    this.pauseNav = pauseNav;
    this.buildNav();
    onLangChange(() => {
      this.buildNav();
      this.render();
    });

    this.sheet.hidden = true;
    this.sheet.append(this.sheetBody);
    this.sheet.addEventListener('pointerdown', (e) => {
      if (e.target === this.sheet) this.close();
    });
    document.body.append(this.sheet);

    window.addEventListener('keydown', this.onKey);
    settings.subscribe((_, changed) => {
      if (changed === null && this.open === 'settings') this.render();
    });
    account.subscribe(() => {
      this.paintAccountItems();
      if (account.notice && this.open !== 'account') this.show('account');
      if (this.open === 'account') this.render();
    });
    progress.subscribe(() => {
      if (this.open === 'missions' || this.open === 'harbours') this.render();
      if (this.open === 'workshop') {
        const scroll = this.sheetBody.querySelector('.shop')?.scrollTop ?? 0;
        this.render();
        const shop = this.sheetBody.querySelector('.shop');
        if (shop) shop.scrollTop = scroll;
      }
    });
  }

  setMode(mode: AppMode): void {
    this.mode = mode;
    this.close();
    if (mode === 'title') queueMicrotask(() => this.focusFirst(document.querySelector('#main-menu')));
    if (mode === 'paused') queueMicrotask(() => this.focusFirst(document.querySelector('#pause-menu')));
  }

  get isSheetOpen(): boolean {
    return this.open !== null;
  }

  private buildNav(): void {
    this.accountItems.length = 0;
    const common = (nav: HTMLElement, first: [string, () => void]): void => {
      nav.replaceChildren(
        this.item(first[0], first[1], true),
        this.item(t('menu.workshop'), () => this.show('workshop')),
        this.item(t('menu.harbours'), () => this.show('harbours')),
        this.item(t('menu.bestiary'), () => this.show('bestiary')),
        this.item(t('menu.missions'), () => this.show('missions')),
        this.item(t('menu.leaderboard'), () => this.show('leaderboard')),
        this.accountItem(),
        this.item(t('menu.settings'), () => this.show('settings')),
        this.item(t('menu.controls'), () => this.show('controls')),
      );
    };
    common(this.titleNav, [t('menu.begin'), () => this.actions.begin()]);
    common(this.pauseNav, [t('menu.resume'), () => this.actions.resume()]);
    this.pauseNav.append(this.item(t('menu.mainMenu'), () => this.actions.exitToTitle()));
  }

  private item(label: string, onClick: () => void, primary = false): HTMLButtonElement {
    const b = el('button', primary ? 'menu-item primary' : 'menu-item');
    b.type = 'button';
    b.append(el('span', 'menu-label', label), el('span', 'menu-arrow', '→'));
    b.addEventListener('click', () => {
      this.opener = b;
      onClick();
    });
    return b;
  }

  private accountItem(): HTMLButtonElement {
    const b = this.item(accountLabel(this.account), () => this.show('account'));
    this.accountItems.push(b);
    return b;
  }

  private paintAccountItems(): void {
    for (const b of this.accountItems) {
      const label = b.querySelector('.menu-label');
      if (label) label.textContent = accountLabel(this.account);
    }
  }

  private show(name: SheetName): void {
    this.open = name;
    this.sheet.hidden = false;
    this.render();
    queueMicrotask(() => this.focusFirst(this.sheetBody));
  }

  private close(): void {
    if (this.open === null) return;
    this.open = null;
    this.account.clearNotice();
    this.sheet.hidden = true;
    this.opener?.focus();
  }

  private readonly onKey = (e: KeyboardEvent): void => {
    if (e.key === 'Escape') {
      if (this.open !== null) {
        e.preventDefault();
        e.stopPropagation();
        this.close();
      } else if (this.mode === 'paused') {
        e.preventDefault();
        this.actions.resume();
      }
      return;
    }
    if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
    if (this.mode === 'play') return;
    const scope: ParentNode | null =
      this.open !== null
        ? this.sheetBody
        : document.querySelector(this.mode === 'paused' ? '#pause-menu' : '#main-menu');
    if (!scope) return;
    const items = [...scope.querySelectorAll<HTMLElement>('button, input, [role="tab"]')].filter(
      (n) => !n.hasAttribute('disabled'),
    );
    if (items.length === 0) return;
    const at = items.indexOf(document.activeElement as HTMLElement);
    const step = e.key === 'ArrowDown' ? 1 : -1;
    const next = items[(at + step + items.length) % items.length];
    if (next) {
      e.preventDefault();
      next.focus();
    }
  };

  private focusFirst(scope: ParentNode | null): void {
    scope?.querySelector<HTMLElement>('button, input')?.focus({ preventScroll: true });
  }


  private render(): void {
    if (this.open === null) return;
    const titles: Record<SheetName, UiKey> = {
      settings: 'menu.settings',
      bestiary: 'menu.bestiary',
      workshop: 'menu.workshop',
      harbours: 'menu.harbours',
      missions: 'menu.missions',
      leaderboard: 'menu.leaderboard',
      account: 'menu.account',
      controls: 'menu.controls',
    };
    const title = t(titles[this.open]);
    this.sheetBody.classList.toggle('wide', this.open === 'bestiary');
    const header = el('header', 'sheet-head');
    header.append(el('h2', undefined, title), button(t('menu.close'), 'ghost', () => this.close()));
    const body =
      this.open === 'settings'
        ? this.settingsView()
        : this.open === 'bestiary'
          ? createBestiary(this.progress, this.album)
          : this.open === 'workshop'
            ? this.workshopView()
            : this.open === 'missions'
              ? this.missionsView()
              : this.open === 'leaderboard'
              ? createLeaderboardView(this.account)
              : this.open === 'account'
              ? createAccountView(this.account, () => this.render(), () => this.close())
          : this.open === 'harbours'
            ? this.harboursView()
            : this.controlsView();
    this.sheetBody.setAttribute('role', 'dialog');
    this.sheetBody.setAttribute('aria-label', title);
    this.sheetBody.replaceChildren(header, body);
  }

  private missionsView(): HTMLElement {
    const wrap = el('div', 'missions');
    const data = this.progress.value;
    const done = MISSIONS.filter((m) => this.progress.isMissionDone(m.id)).length;
    wrap.append(el('p', 'shop-hint', t('missions.summary', { done, total: MISSIONS.length })));
    const list = el('div', 'mission-list');
    const ordered = [...MISSIONS].sort((a, b) => Number(this.progress.isMissionDone(a.id)) - Number(this.progress.isMissionDone(b.id)));
    for (const m of ordered) {
      const finished = this.progress.isMissionDone(m.id);
      const row = el('div', `mission${finished ? ' done' : ''}`);
      const text = el('div', 'mission-text');
      text.append(el('b', undefined, missionTitle(m.id)), el('span', undefined, missionDescription(m.id)));
      const prog = missionProgress(m, data);
      if (prog && !finished) {
        const bar = el('div', 'mission-bar');
        const fill = el('i');
        fill.style.width = `${Math.round((prog[0] / prog[1]) * 100)}%`;
        bar.append(fill);
        text.append(bar, el('small', undefined, `${num(prog[0])} / ${num(prog[1])}`));
      }
      row.append(text, el('div', 'mission-reward', finished ? t('missions.received') : `+${t('credits', { n: num(m.reward) })}`));
      list.append(row);
    }
    wrap.append(list);
    return wrap;
  }

  private workshopView(): HTMLElement {
    const wrap = el('div', 'shop');
    const p = this.progress;
    const top = el('div', 'shop-top');
    top.append(
      el('div', 'shop-credits', t('credits', { n: num(p.value.credits) })),
      el('p', 'shop-hint', t('workshop.hint')),
    );
    const list = el('div', 'shop-list');
    for (const id of UPGRADE_IDS) {
      const offer = p.offer(id);
      const row = el('div', 'shop-row');
      const text = el('div', 'shop-text');
      const pips = el('div', 'pips');
      for (let i = 0; i < MAX_UPGRADE_LEVEL; i++) pips.append(el('i', i < offer.level ? 'on' : ''));
      const now = upgradeLevel(id, offer.level);
      const next = offer.cost === null ? null : upgradeLevel(id, offer.level + 1);
      text.append(
        el('b', 'shop-name', upgradeName(id)),
        el('span', 'shop-desc', upgradeDescription(id)),
        pips,
        el('span', 'shop-now', next ? `${now} → ${next}` : t('workshop.maxed', { label: now })),
      );
      const buy = button(
        offer.cost === null ? t('workshop.max') : t('credits', { n: num(offer.cost) }),
        offer.affordable ? 'buy' : 'buy off',
        () => void p.purchase(id),
      );
      buy.disabled = !offer.affordable;
      row.append(text, buy);
      list.append(row);
    }
    wrap.append(top, list);
    return wrap;
  }

  private settingsView(): HTMLElement {
    const wrap = el('div', 'settings');
    const tabs = el('div', 'tabs');
    tabs.setAttribute('role', 'tablist');
    const names: ReadonlyArray<readonly [TabName, UiKey]> = [
      ['graphics', 'settings.tab.graphics'],
      ['sound', 'settings.tab.sound'],
      ['controls', 'settings.tab.controls'],
      ['interface', 'settings.tab.interface'],
      ['about', 'settings.tab.about'],
    ];
    for (const [name, key] of names) {
      const tab = button(t(key), name === this.tab ? 'tab active' : 'tab', () => {
        this.tab = name;
        this.render();
        queueMicrotask(() => this.sheetBody.querySelector<HTMLElement>('.tab.active')?.focus());
      });
      tab.setAttribute('role', 'tab');
      tab.setAttribute('aria-selected', String(name === this.tab));
      tabs.append(tab);
    }

    const rows = el('div', 'rows');
    const s = this.settings;
    const pct = (v: number): string => `${Math.round(v * 100)} %`;
    if (this.tab === 'graphics') {
      rows.append(
        this.choice(
          'settings.quality',
          'quality',
          QUALITY_IDS.map((id) => [id, t(`settings.quality.${id}` as UiKey)] as const),
        ),
        this.slider('settings.renderScale', 'renderScale', SETTING_LIMITS.renderScale, pct),
        this.slider('settings.fov', 'fov', SETTING_LIMITS.fov, (v) => `${Math.round(v)}°`),
        this.toggle('settings.bloom', 'bloom'),
        this.toggle('settings.filmGrain', 'filmGrain'),
        this.toggle('settings.vignette', 'vignette'),
        this.toggle('settings.chromaticAberration', 'chromaticAberration'),
      );
    } else if (this.tab === 'sound') {
      rows.append(
        this.slider('settings.volumeMaster', 'volumeMaster', SETTING_LIMITS.volume, pct),
        this.slider('settings.volumeEffects', 'volumeEffects', SETTING_LIMITS.volume, pct),
        this.slider('settings.volumeAmbient', 'volumeAmbient', SETTING_LIMITS.volume, pct),
        this.slider('settings.volumeMusic', 'volumeMusic', SETTING_LIMITS.volume, pct),
      );
    } else if (this.tab === 'controls') {
      rows.append(
        this.slider('settings.sensitivity', 'sensitivity', SETTING_LIMITS.sensitivity, (v) => `${v.toFixed(2)}×`),
        this.toggle('settings.invertY', 'invertY'),
        this.toggle('settings.cameraAutoReturn', 'cameraAutoReturn'),
      );
    } else if (this.tab === 'interface') {
      rows.append(this.languageRow(), this.toggle('settings.showHints', 'showHints'), this.toggle('settings.showTips', 'showTips'));
    } else {
      rows.append(this.aboutView());
    }

    const foot = el('footer', 'sheet-foot');
    foot.append(
      button(t('settings.reset'), 'ghost danger', () => s.reset()),
      el('span', 'saved', t('settings.autosaved')),
    );
    wrap.append(tabs, rows, foot);
    return wrap;
  }

  private languageRow(): HTMLElement {
    const group = el('div', 'segmented');
    group.setAttribute('role', 'radiogroup');
    for (const lang of LANGS) {
      const b = button(lang.label, lang.id === this.settings.value.language ? 'seg active' : 'seg', () => {
        if (isLang(lang.id)) this.settings.set('language', lang.id);
      });
      b.setAttribute('role', 'radio');
      b.setAttribute('aria-checked', String(lang.id === this.settings.value.language));
      group.append(b);
    }
    return this.row(t('settings.language'), t('settings.language.hint'), group);
  }

  private row(label: string, hint: string, control: HTMLElement): HTMLElement {
    const row = el('div', 'row');
    const text = el('div', 'row-text');
    text.append(el('span', 'row-label', label), el('span', 'row-hint', hint));
    row.append(text, control);
    return row;
  }

  private choice<K extends 'quality'>(
    labelKey: UiKey,
    key: K,
    options: ReadonlyArray<readonly [Settings[K], string]>,
  ): HTMLElement {
    const label = t(labelKey);
    const group = el('div', 'segmented');
    group.setAttribute('role', 'radiogroup');
    group.setAttribute('aria-label', label);
    const paint = (): void => {
      for (const node of group.querySelectorAll('button')) {
        node.classList.toggle('active', node.dataset.value === String(this.settings.value[key]));
        node.setAttribute('aria-checked', String(node.classList.contains('active')));
      }
    };
    for (const [value, text] of options) {
      const b = button(text, 'seg', () => {
        this.settings.set(key, value);
        paint();
      });
      b.dataset.value = String(value);
      b.setAttribute('role', 'radio');
      group.append(b);
    }
    paint();
    return this.row(label, t(`${labelKey}.hint` as UiKey), group);
  }

  private slider(
    labelKey: UiKey,
    key: 'renderScale' | 'fov' | 'sensitivity' | 'volumeMaster' | 'volumeEffects' | 'volumeAmbient' | 'volumeMusic',
    limits: { min: number; max: number; step: number },
    format: (v: number) => string,
  ): HTMLElement {
    const label = t(labelKey);
    const wrap = el('div', 'slider');
    const input = el('input');
    input.type = 'range';
    input.min = String(limits.min);
    input.max = String(limits.max);
    input.step = String(limits.step);
    input.value = String(this.settings.value[key]);
    input.setAttribute('aria-label', label);
    const out = el('output', undefined, format(this.settings.value[key]));
    const fill = (): void => {
      const t = (Number(input.value) - limits.min) / (limits.max - limits.min);
      input.style.setProperty('--fill', `${Math.round(t * 100)}%`);
    };
    fill();
    input.addEventListener('input', () => {
      const v = Number(input.value);
      this.settings.set(key, v);
      out.textContent = format(v);
      fill();
    });
    wrap.append(input, out);
    return this.row(label, t(`${labelKey}.hint` as UiKey), wrap);
  }

  private toggle(
    labelKey: UiKey,
    key: 'bloom' | 'filmGrain' | 'vignette' | 'chromaticAberration' | 'invertY' | 'cameraAutoReturn' | 'showHints' | 'showTips',
  ): HTMLElement {
    const label = t(labelKey);
    const b = el('button', 'switch');
    b.type = 'button';
    b.setAttribute('role', 'switch');
    b.setAttribute('aria-label', label);
    b.append(el('span', 'knob'));
    const paint = (): void => {
      const on = this.settings.value[key];
      b.classList.toggle('on', on);
      b.setAttribute('aria-checked', String(on));
    };
    b.addEventListener('click', () => {
      this.settings.set(key, !this.settings.value[key]);
      paint();
    });
    paint();
    return this.row(label, t(`${labelKey}.hint` as UiKey), b);
  }

  private controlsView(): HTMLElement {
    const wrap = el('div', 'keys');
    if (isTouchDevice()) wrap.append(el('p', 'shop-hint', t('touch.help')));
    for (const group of keyGroups()) {
      const section = el('section');
      section.append(el('h3', undefined, group.title));
      for (const [keys, action] of group.rows) {
        const row = el('div', 'key-row');
        const caps = el('span', 'caps');
        for (const k of keys) caps.append(el('kbd', k === '–' ? 'dash' : undefined, k));
        row.append(caps, el('span', undefined, action));
        section.append(row);
      }
      wrap.append(section);
    }
    return wrap;
  }

  private aboutView(): HTMLElement {
    const wrap = el('div', 'about');
    wrap.append(el('p', 'about-lede', t('about.lede')), el('p', undefined, t('about.body')));
    const maker = el('div', 'about-maker');
    const mark = el('img');
    mark.src = '/xpain-mark.svg';
    mark.alt = '';
    mark.width = 40;
    mark.height = 40;
    const text = el('div');
    const name = el('p', 'maker-line');
    name.append(`${t('title.madeBy')} `, el('b', undefined, 'Xpain'));
    text.append(name, el('p', 'dim', t('title.version', { version: VERSION })));
    maker.append(mark, text);
    wrap.append(maker);
    return wrap;
  }

  private harboursView(): HTMLElement {
    const wrap = el('div', 'harbours');
    const p = this.progress;
    const top = el('div', 'shop-top');
    top.append(
      el('div', 'shop-credits', t('credits', { n: num(p.value.credits) })),
      el('p', 'shop-hint', t('harbours.hint')),
    );
    const list = el('div', 'harbour-list');
    for (const port of PORTS) {
      const owned = p.ownsPort(port.id);
      const home = p.value.homePort === port.id;
      const card = el('article', `harbour theme-${port.theme}${home ? ' home' : ''}`);
      const art = el('div', 'harbour-art');
      art.append(el('i', 'sun'), el('i', 'peak a'), el('i', 'peak b'), el('i', 'sea'));
      const text = el('div', 'harbour-text');
      text.append(
        el('b', 'harbour-name', portName(port.id)),
        el('span', 'harbour-desc', portDescription(port.id)),
        el('span', 'harbour-perk', `${t('harbours.perk')}: ${portPerk(port.id)}`),
        el('small', undefined, t('harbours.distance', { km: num(Math.abs(port.z) / 1000, 1) })),
      );
      let action: HTMLElement;
      if (home) {
        action = el('span', 'harbour-state', t('harbours.home'));
      } else if (owned) {
        action = button(t('harbours.sailFrom'), 'buy', () => void p.setHomePort(port.id));
      } else {
        const buy = button(t('harbours.price', { price: num(port.price) }), p.value.credits >= port.price ? 'buy' : 'buy off', () => void p.buyPort(port.id));
        buy.disabled = p.value.credits < port.price;
        action = buy;
      }
      card.append(art, text, action);
      list.append(card);
    }
    wrap.append(top, list);
    return wrap;
  }
}
