
export const COMMON_UNIFORMS = /* glsl */ `
uniform float uTime;
uniform vec3 uSunDir;
uniform vec3 uSunColor;
uniform vec3 uFogColor;
uniform float uFogDensity;
uniform vec3 uCamPos;
uniform float uSunlight;
uniform float uPixelRatio;
`;

export const NOISE_GLSL = /* glsl */ `
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash12(i);
  float b = hash12(i + vec2(1.0, 0.0));
  float c = hash12(i + vec2(0.0, 1.0));
  float d = hash12(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * vnoise(p);
    p = p * 2.03 + 17.0;
    a *= 0.5;
  }
  return s;
}
`;

/** Procedural sunset sky with clouds. Needs COMMON_UNIFORMS and NOISE_GLSL. */
export const SKY_GLSL = /* glsl */ `
vec3 skyColor(vec3 dir) {
  float h = max(dir.y, 0.0);
  vec3 horizon = vec3(1.05, 0.5, 0.28);
  vec3 mid = vec3(0.26, 0.3, 0.52);
  vec3 zenith = vec3(0.02, 0.055, 0.2);
  vec3 col = mix(horizon, mid, smoothstep(0.0, 0.22, h));
  col = mix(col, zenith, smoothstep(0.12, 0.85, h));

  float sd = max(dot(dir, uSunDir), 0.0);
  col += vec3(1.0, 0.5, 0.22) * (pow(sd, 5.0) * 0.32 + pow(sd, 60.0) * 0.55);
  col += vec3(1.0, 0.82, 0.55) * pow(sd, 1800.0) * 14.0;

  if (dir.y > 0.0) {
    vec2 p = dir.xz / (dir.y + 0.18) * 1.5 + vec2(uTime * 0.012, 0.0);
    float c = smoothstep(0.52, 0.88, fbm(p));
    vec3 cloudCol = mix(vec3(0.2, 0.16, 0.26), vec3(1.0, 0.58, 0.38), clamp(pow(sd, 1.5) * 2.0 + 0.2, 0.0, 1.0));
    col = mix(col, cloudCol, c * smoothstep(0.0, 0.18, dir.y) * 0.75);
  }
  return col;
}
`;

/** Animated caustic network, used on the seabed and hull in shallow water. */
export const CAUSTICS_GLSL = /* glsl */ `
float caustics(vec2 p, float t) {
  float c = 0.0;
  vec2 q = p;
  for (int i = 0; i < 3; i++) {
    q = q * 1.45 + vec2(1.7, 9.2);
    float n = vnoise(q + vec2(t * 0.16, -t * 0.11) * (1.0 + float(i) * 0.5));
    c += pow(clamp(1.0 - abs(n * 2.0 - 1.0), 0.0, 1.0), 7.0);
  }
  return c * 0.66;
}
`;

/**
 * Guards against NaN/Inf. One bad pixel in the HDR buffer gets smeared by bloom into a large
 * black square, so every custom lit material passes its final colour through sanitize().
 */
export const SAFE_GLSL = /* glsl */ `
vec3 safeNormalize(vec3 v, vec3 fallback) {
  float l2 = dot(v, v);
  return (l2 > 1e-8 && !isnan(l2) && !isinf(l2)) ? v * inversesqrt(l2) : fallback;
}

vec3 sanitize(vec3 c, vec3 fallback) {
  if (any(isnan(c)) || any(isinf(c))) return fallback;
  return clamp(c, 0.0, 40.0);
}
`;

/**
 * Underwater lighting for solid objects: depth-dependent sun colour, ambient, and the
 * submarine headlight. Needs COMMON_UNIFORMS and the three uBeam* uniforms.
 */
export const LIGHTING_GLSL = /* glsl */ `
${SAFE_GLSL}
uniform vec3 uBeamPos;
uniform vec3 uBeamDir;
uniform vec3 uBeamParams;

vec3 shadeUnderwater(vec3 albedo, vec3 N, vec3 worldPos) {
  float depth = max(0.0, -worldPos.y);
  vec3 absorb = exp(-vec3(0.28, 0.06, 0.033) * depth);
  vec3 sun = uSunColor * max(dot(N, uSunDir), 0.0) * absorb;
  vec3 ambient = vec3(0.10, 0.16, 0.24) * absorb * (0.55 + 0.45 * N.y) + vec3(0.0015, 0.003, 0.005);

  vec3 fromLamp = worldPos - uBeamPos;
  float lampDist = length(fromLamp);
  vec3 L = fromLamp / max(lampDist, 0.001);
  float cone = smoothstep(uBeamParams.y, uBeamParams.y + 0.1, dot(L, uBeamDir));
  float reach = 1.0 - smoothstep(uBeamParams.x * 0.3, uBeamParams.x, lampDist);
  float falloff = 1.0 / (1.0 + 0.0012 * lampDist * lampDist);
  vec3 beam = vec3(0.85, 0.96, 1.0) * uBeamParams.z * cone * reach * falloff * max(dot(N, -L), 0.0);

  vec3 lit = albedo * (sun + ambient + beam);
  float dist = length(worldPos - uCamPos);
  return sanitize(mix(uFogColor, lit, exp(-uFogDensity * dist)), uFogColor);
}
`;

