import { CircleGeometry, CylinderGeometry, Euler, type BufferGeometry, BufferAttribute, Quaternion, SphereGeometry, Vector3, BoxGeometry } from 'three';
import { PropBuilder } from './props.ts';

const BONE = 0xd8d0b8;
const BONE_DARK = 0xb9b095;

const hash = (n: number): number => {
  const s = Math.sin(n * 45.164) * 43758.5453;
  return s - Math.floor(s);
};

type Ground = (x: number, z: number) => number;

function limb(b: PropBuilder, a: Vector3, c: Vector3, r0: number, r1: number, color = BONE): void {
  const dir = new Vector3().subVectors(c, a);
  const len = dir.length();
  if (len < 1e-4) return;
  const q = new Quaternion().setFromUnitVectors(new Vector3(0, 1, 0), dir.normalize());
  const e = new Euler().setFromQuaternion(q);
  const mid = new Vector3().addVectors(a, c).multiplyScalar(0.5);
  b.add(new CylinderGeometry(r1, r0, len, 7), color, { pos: [mid.x, mid.y, mid.z], rot: [e.x, e.y, e.z], jitter: 0.07 });
}

/**
 * The skeleton of a blue whale lying on the seabed, about 26 m long. Coordinates are relative to
 * (cx, cz); the Y values follow the ground so the bones rest on it, half sunk in the sediment.
 */
export function buildWhaleSkeleton(cx: number, cz: number, yaw: number, ground: Ground): BufferGeometry {
  const b = new PropBuilder();
  const dx = Math.cos(yaw);
  const dz = -Math.sin(yaw);
  const px = Math.sin(yaw);
  const pz = Math.cos(yaw);
  const at = (u: number, v: number, lift: number): Vector3 => {
    const x = dx * u + px * v;
    const z = dz * u + pz * v;
    return new Vector3(x, ground(cx + x, cz + z) + lift, z);
  };

  const N = 38;
  const spine: Vector3[] = [];
  for (let i = 0; i < N; i++) {
    const u = 9.5 - i * 0.68;
    const curl = Math.sin(i * 0.17) * 1.1 + (i > 28 ? (i - 28) * 0.16 : 0);
    const r = 0.58 - (i / N) * 0.3;
    spine.push(at(u, curl, r * 0.55));
  }
  for (let i = 0; i < N - 1; i++) {
    const a = spine[i];
    const c = spine[i + 1];
    if (!a || !c) continue;
    const r = 0.58 - (i / N) * 0.3;
    const mid = new Vector3().lerpVectors(a, c, 0.5);
    const dir = new Vector3().subVectors(c, a).normalize();
    limb(b, new Vector3().copy(mid).addScaledVector(dir, -0.27), new Vector3().copy(mid).addScaledVector(dir, 0.27), r, r, BONE);
    const top = new Vector3(mid.x, mid.y + r + 0.55 - (i / N) * 0.3, mid.z);
    limb(b, new Vector3(mid.x, mid.y + r * 0.6, mid.z), top, 0.09, 0.06, BONE_DARK);
    if (i > 8) {
      const side = new Vector3(px, 0, pz).multiplyScalar(0.7 + r);
      limb(b, mid, new Vector3().addVectors(mid, side), 0.07, 0.05, BONE_DARK);
      limb(b, mid, new Vector3().subVectors(mid, side), 0.07, 0.05, BONE_DARK);
    }
  }

  for (let i = 4; i < 17; i++) {
    const base = spine[i];
    if (!base) continue;
    const reach = 4.6 - Math.abs(i - 9) * 0.28;
    for (const side of [-1, 1]) {
      if (hash(i * 7 + side) < 0.16) continue;
      let prev = new Vector3().copy(base);
      const wobble = (hash(i * 3 + side * 5) - 0.5) * 0.7;
      const steps = 6;
      for (let s = 1; s <= steps; s++) {
        const t = s / steps;
        const v = side * reach * t;
        const u = wobble * t * t * 2;
        const lift = 0.35 + Math.sin(t * Math.PI) * 1.15 * (1 - 0.5 * hash(i + 31));
        const p = at(spineU(i) + u, spineV(i) + v, 0);
        p.y = Math.max(p.y + lift * (1 - t * 0.8), ground(cx + p.x, cz + p.z) + 0.1);
        limb(b, prev, p, 0.17 - t * 0.07, 0.15 - t * 0.07);
        prev = p;
      }
    }
  }

  const head = at(11.8, 0.2, 1.0);
  b.add(new BoxGeometry(4, 1.9, 3.1), BONE, { pos: [head.x, head.y, head.z], rot: [0, yaw, 0], jitter: 0.05 });
  b.add(new SphereGeometry(1.35, 10, 8), BONE_DARK, { pos: [head.x - dx * 1.5, head.y + 0.3, head.z - dz * 1.5], scale: [1.4, 0.8, 1.2], rot: [0, yaw, 0] });
  const snoutA = at(13.6, 0.2, 0.9);
  const snoutB = at(20.2, 0.5, 0.45);
  limb(b, snoutA, snoutB, 0.95, 0.3, BONE);
  limb(b, at(13.8, 0.2, 1.5), at(19.5, 0.5, 1.05), 0.45, 0.2, BONE_DARK);
  for (const side of [-1, 1]) {
    const jawBase = at(11.0, side * 1.6, 0.4);
    const jawMid = at(16.0, side * 2.4 + side * 0.6, 0.25);
    const jawTip = at(20.6, side * 3.0, 0.25);
    limb(b, jawBase, jawMid, 0.33, 0.26);
    limb(b, jawMid, jawTip, 0.26, 0.16);
  }

  for (const side of [-1, 1]) {
    const shoulder = at(7.4, side * 1.4, 0.35);
    const elbow = at(6.4, side * 3.4, 0.3);
    limb(b, shoulder, elbow, 0.28, 0.22);
    for (const off of [-0.25, 0.25]) {
      const wrist = at(5.0, side * 5.4 + off, 0.25);
      limb(b, elbow, wrist, 0.17, 0.14);
      for (let f = 0; f < 3; f++) {
        const tip = at(3.6 - f * 0.5, side * (6.8 + f * 0.1) + off * 2, 0.18);
        limb(b, wrist, tip, 0.1, 0.05);
      }
    }
  }

  for (const side of [-1, 1]) {
    limb(b, at(-6.8, side * 0.5, 0.3), at(-8.3, side * 1.4, 0.3), 0.14, 0.1);
  }
  return b.build();
}

function spineU(i: number): number {
  return 9.5 - i * 0.68;
}
function spineV(i: number): number {
  return Math.sin(i * 0.17) * 1.1;
}

/** The pale bacterial mat that covers the sediment around the carcass, following the ground. */
export function buildBacterialMat(cx: number, cz: number, ground: Ground): BufferGeometry {
  const g = new CircleGeometry(17, 48, 0, Math.PI * 2);
  g.rotateX(-Math.PI / 2);
  const p = g.getAttribute('position') as BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const z = p.getZ(i);
    const ang = Math.atan2(z, x);
    const k = 0.75 + 0.35 * hash(Math.round(ang * 5) + 3) + 0.15 * Math.sin(ang * 3);
    const nx = x * k;
    const nz = z * k;
    p.setXYZ(i, nx, ground(cx + nx, cz + nz) + 0.05, nz);
  }
  g.computeVertexNormals();
  const b = new PropBuilder();
  b.addRaw(g, 0x8f8a76, { jitter: 0.04 });
  return b.build();
}
