import { BALANCE } from '../data/balance.ts';

export interface SonarTarget {
  x: number;
  y: number;
  z: number;
  size: number;
  speciesId: string;
  kind: 'school' | 'animal';
}

export type ContactStatus = 'unknown' | 'new' | 'known';

export interface Contact {
  x: number;
  y: number;
  z: number;
  size: number;
  kind: SonarTarget['kind'];
  status: ContactStatus;
  speciesId: string | null;
}

export interface SonarOrigin {
  x: number;
  y: number;
  z: number;
}

/**
 * Turns the world's animals into display contacts. `analysis` 0 gives plain blips,
 * 1 marks species you have not catalogued yet, 2 also names the ones you have.
 */
export function scan(
  origin: SonarOrigin,
  range: number,
  targets: readonly SonarTarget[],
  analysis: number,
  isKnown: (speciesId: string) => boolean,
): Contact[] {
  const contacts: Contact[] = [];
  for (const t of targets) {
    const dx = t.x - origin.x;
    const dy = t.y - origin.y;
    const dz = t.z - origin.z;
    if (dx * dx + dy * dy + dz * dz > range * range) continue;
    const known = isKnown(t.speciesId);
    const status: ContactStatus = analysis < 1 ? 'unknown' : known ? 'known' : 'new';
    contacts.push({
      x: t.x,
      y: t.y,
      z: t.z,
      size: t.size,
      kind: t.kind,
      status,
      speciesId: analysis >= 2 && known ? t.speciesId : null,
    });
  }
  return contacts;
}

/** Ping timing and the last set of contacts. */
export class Sonar {
  contacts: Contact[] = [];
  lastPing = Number.NEGATIVE_INFINITY;
  static readonly HOLD = 10;
  static readonly COST = BALANCE.battery.sonarPing;

  cooldownLeft(time: number, cooldown: number): number {
    return Math.max(0, this.lastPing + cooldown - time);
  }

  ping(time: number, cooldown: number, contacts: Contact[]): boolean {
    if (this.cooldownLeft(time, cooldown) > 0) return false;
    this.lastPing = time;
    this.contacts = contacts;
    return true;
  }

  age(time: number): number {
    return time - this.lastPing;
  }

  clear(): void {
    this.contacts = [];
    this.lastPing = Number.NEGATIVE_INFINITY;
  }
}
