import { ACESFilmicToneMapping, Scene, type Texture, Vector3, WebGLRenderer } from 'three';
import { QUALITY, type QualityTier } from '../core/quality.ts';
import { forwardFromAngles } from '../core/vec3.ts';
import type { Creature } from '../domain/creature.ts';
import type { School } from '../domain/school.ts';
import type { SubState } from '../domain/submarine.ts';
import { PORT_PLACEMENTS, placementOf, type WorldQuery } from '../domain/world.ts';
import { CameraRig, type LookInput } from './camera-rig.ts';
import { createEnvironmentMap } from './env-map.ts';
import { Environment } from './environment.ts';
import { Flora } from './flora.ts';
import { Creatures } from './creatures.ts';
import { FishSchools } from './fish-school.ts';
import { LightShafts } from './light-shafts.ts';
import { MarineSnow } from './marine-snow.ts';
import { OceanSurface } from './ocean-surface.ts';
import { Harbour } from './harbour.ts';
import { ShoreMask } from './shore-mask.ts';
import { Landmarks } from './landmarks.ts';
import { Mountains } from './mountains.ts';
import { Splash } from './splash.ts';
import { SurfaceFoam } from './surface-foam.ts';
import { PostPipeline } from './post.ts';
import { Seabed } from './seabed.ts';
import { BEAM_HALF_ANGLE, LAMP_LOCAL, SubmarineView } from './submarine-view.ts';

/** Everything the renderer needs to know about one frame of the game. */
export interface RenderFrame {
  time: number;
  dt: number;
  sub: SubState;
  thrust: number;
  beamRange: number;
  lightActive: boolean;
  look: LookInput;
  mode: 'title' | 'play';
  schools: readonly School[];
  creatures: readonly Creature[];
}

export interface RenderInfo {
  underwater: boolean;
  cameraDepth: number;
}

const MSAA: Record<QualityTier, number> = { low: 0, medium: 2, high: 4, ultra: 4 };
const FLORA_RADIUS: Record<QualityTier, number> = { low: 45, medium: 65, high: 85, ultra: 110 };
const FOAM_CAPACITY: Record<QualityTier, number> = { low: 140, medium: 220, high: 320, ultra: 420 };
const SPLASH_CAPACITY: Record<QualityTier, number> = { low: 300, medium: 500, high: 800, ultra: 1200 };
const SHAFTS: Record<QualityTier, number> = { low: 5, medium: 9, high: 13, ultra: 18 };

/** Owns the WebGL renderer and every visual layer of the world, and draws one frame at a time. */
export class SceneRenderer {
  readonly canvas: HTMLCanvasElement;
  readonly rig: CameraRig;
  private readonly renderer: WebGLRenderer;
  private readonly scene = new Scene();
  private readonly environment: Environment;
  private readonly submarine = new SubmarineView();
  private readonly harbours = new Map<string, Harbour>();
  private activePort = PORT_PLACEMENTS[0]?.port.id ?? '';
  private readonly shore: ShoreMask;
  private readonly landmarks: Landmarks;
  private readonly mountains: Mountains;
  private foam: SurfaceFoam | null = null;
  private splash: Splash | null = null;
  private readonly envMap: Texture;
  private readonly world: WorldQuery;
  private ocean: OceanSurface | null = null;
  private seabed: Seabed | null = null;
  private flora: Flora | null = null;
  private fish: FishSchools | null = null;
  private creatures: Creatures | null = null;
  private snow: MarineSnow | null = null;
  private shafts: LightShafts | null = null;
  private post: PostPipeline | null = null;
  private tier: QualityTier;
  private renderScale = 1;
  private effects = { bloom: true, grain: true, vignette: true, aberration: true };
  private width = 1;
  private height = 1;
  private readonly lampWorld = new Vector3();

  constructor(canvas: HTMLCanvasElement, world: WorldQuery, tier: QualityTier) {
    this.canvas = canvas;
    this.world = world;
    this.tier = tier;
    this.renderer = new WebGLRenderer({
      canvas,
      antialias: false,
      powerPreference: 'high-performance',
    });
    this.renderer.toneMapping = ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;

    this.environment = new Environment(this.scene);
    this.envMap = createEnvironmentMap(this.renderer);
    this.scene.environment = this.envMap;
    // A Color assigned as the background is resolved at draw time, inside the (linear) HDR
    // target; renderer.setClearColor() would be converted to sRGB too early and look washed out.
    this.scene.background = this.environment.clearColor;
    this.rig = new CameraRig(1);
    this.scene.add(this.submarine.group);
    this.shore = new ShoreMask(world);
    for (const placement of PORT_PLACEMENTS) {
      const harbour = new Harbour(world, this.environment.uniforms, placement);
      this.harbours.set(placement.port.id, harbour);
      this.scene.add(harbour.group);
    }
    this.landmarks = new Landmarks(world, this.environment.uniforms);
    this.scene.add(this.landmarks.group);
    this.mountains = new Mountains(world, this.environment.uniforms);
    this.scene.add(this.mountains.mesh);
    this.buildLayers();
  }

  setActivePort(id: string): void {
    const placement = placementOf(id);
    this.activePort = placement.port.id;
    this.shore.retarget(placement.dx, placement.dz);
    this.ocean?.setHarbour(this.shore.region, this.harbours.get(this.activePort)?.piles ?? []);
  }

  get qualityTier(): QualityTier {
    return this.tier;
  }

  setQuality(tier: QualityTier): void {
    if (tier === this.tier) return;
    this.tier = tier;
    this.buildLayers();
  }

  setRenderScale(scale: number): void {
    this.renderScale = scale;
    this.resize(this.width, this.height);
  }

  setFov(degrees: number): void {
    this.rig.setFov(degrees);
  }

  setEffects(effects: { bloom: boolean; grain: boolean; vignette: boolean; aberration: boolean }): void {
    this.effects = effects;
    this.applyEffects();
  }

  private applyEffects(): void {
    this.post?.setBloomEnabled(QUALITY[this.tier].bloom && this.effects.bloom);
    this.post?.setLens(this.effects);
  }

  resize(width: number, height: number): void {
    this.width = Math.max(1, Math.floor(width));
    this.height = Math.max(1, Math.floor(height));
    const ratio = this.pixelRatio();
    this.renderer.setPixelRatio(ratio);
    this.renderer.setSize(this.width, this.height, false);
    this.environment.uniforms.uPixelRatio.value = ratio;
    this.rig.setAspect(this.width / this.height);
    this.post?.resize(this.width, this.height, ratio);
  }

  render(frame: RenderFrame): RenderInfo {
    const { sub } = frame;
    const seabedBelow = this.world.seabedY(sub.position.x, sub.position.z);
    this.rig.update(frame.dt, sub, frame.look, frame.mode, seabedBelow);

    const camera = this.rig.camera;
    camera.updateMatrixWorld();
    const env = this.environment.update(camera, frame.time);
    this.scene.environmentIntensity = 0.12 + 0.88 * (1 - env.darkness);

    this.submarine.update(
      sub,
      frame.thrust,
      frame.beamRange,
      frame.lightActive,
      env.darkness,
      frame.time,
      frame.dt,
    );
    this.updateBeamUniforms(frame);

    this.shore.update(2);
    this.landmarks.update(camera.position.x, camera.position.z);
    for (const harbour of this.harbours.values()) harbour.update(frame.time);
    this.foam?.update(frame.dt, frame.time, sub, frame.thrust, env.underwater);
    this.splash?.update(frame.dt, frame.time, sub, frame.thrust, camera.position);
    this.flora?.update(camera.position.x, camera.position.z);
    this.fish?.update(frame.schools);
    this.creatures?.update(frame.creatures);
    this.seabed?.update(camera.position.x, camera.position.z);
    this.ocean?.follow(camera.position.x, camera.position.z);
    this.shafts?.update(
      camera.position.x,
      camera.position.z,
      this.environment.uniforms.uSunDir.value,
      env.underwater,
    );

    this.post?.setBloomStrength(0.55 + 0.6 * env.darkness);
    this.post?.setGrade(env.depth, env.underwater);
    this.post?.render(frame.dt, frame.time);

    return { underwater: env.underwater, cameraDepth: env.depth };
  }

  dispose(): void {
    this.disposeLayers();
    this.submarine.dispose();
    for (const harbour of this.harbours.values()) harbour.dispose();
    this.shore.dispose();
    this.landmarks.dispose();
    this.mountains.dispose();
    this.envMap.dispose();
    this.environment.dispose();
    this.renderer.dispose();
  }

  private pixelRatio(): number {
    return Math.min(globalThis.devicePixelRatio || 1, QUALITY[this.tier].pixelRatio) * this.renderScale;
  }

  private updateBeamUniforms(frame: RenderFrame): void {
    const { sub } = frame;
    const u = this.environment.uniforms;
    const forward = forwardFromAngles(sub.yaw, sub.pitch);
    this.lampWorld.set(LAMP_LOCAL.x, LAMP_LOCAL.y, LAMP_LOCAL.z);
    this.submarine.group.localToWorld(this.lampWorld);
    u.uBeamPos.value.copy(this.lampWorld);
    u.uBeamDir.value.set(forward.x, forward.y, forward.z);
    u.uBeamParams.value.set(
      frame.beamRange,
      Math.cos(BEAM_HALF_ANGLE),
      frame.lightActive && sub.submerged ? 4 : 0,
    );
  }

  private buildLayers(): void {
    this.disposeLayers();
    const q = QUALITY[this.tier];
    const uniforms = this.environment.uniforms;

    this.ocean = new OceanSurface(uniforms, q.terrainResolution, this.shore.texture, this.harbours.get(this.activePort)?.piles ?? []);
    this.ocean.setHarbour(this.shore.region, this.harbours.get(this.activePort)?.piles ?? []);
    this.foam = new SurfaceFoam(uniforms, FOAM_CAPACITY[this.tier]);
    this.splash = new Splash(uniforms, SPLASH_CAPACITY[this.tier]);
    this.seabed = new Seabed(this.world, uniforms, q.terrainResolution);
    this.flora = new Flora(this.world, uniforms, FLORA_RADIUS[this.tier]);
    this.fish = new FishSchools(uniforms, q.creatureBudget);
    this.creatures = new Creatures(uniforms);
    this.snow = new MarineSnow(uniforms, q.particles);
    this.shafts = new LightShafts(uniforms, SHAFTS[this.tier]);
    this.scene.add(
      this.ocean.mesh,
      this.seabed.mesh,
      ...this.flora.group,
      this.foam.mesh,
      this.splash.points,
      this.fish.mesh,
      ...this.creatures.group,
      this.snow.points,
      this.shafts.group,
    );

    this.post = new PostPipeline(this.renderer, this.scene, this.rig.camera, MSAA[this.tier]);
    this.applyEffects();
    this.resize(this.width, this.height);
  }

  private disposeLayers(): void {
    if (this.ocean) this.scene.remove(this.ocean.mesh);
    if (this.seabed) this.scene.remove(this.seabed.mesh);
    if (this.flora) this.scene.remove(...this.flora.group);
    if (this.foam) this.scene.remove(this.foam.mesh);
    if (this.splash) this.scene.remove(this.splash.points);
    if (this.fish) this.scene.remove(this.fish.mesh);
    if (this.creatures) this.scene.remove(...this.creatures.group);
    if (this.snow) this.scene.remove(this.snow.points);
    if (this.shafts) this.scene.remove(this.shafts.group);
    this.ocean?.dispose();
    this.seabed?.dispose();
    this.foam?.dispose();
    this.splash?.dispose();
    this.flora?.dispose();
    this.fish?.dispose();
    this.creatures?.dispose();
    this.snow?.dispose();
    this.shafts?.dispose();
    this.post?.dispose();
    this.ocean = null;
    this.seabed = null;
    this.foam = null;
    this.splash = null;
    this.flora = null;
    this.fish = null;
    this.creatures = null;
    this.snow = null;
    this.shafts = null;
    this.post = null;
  }
}
