import {
  type Camera,
  HalfFloatType,
  type Scene,
  Vector2,
  Vector3,
  WebGLRenderTarget,
  type WebGLRenderer,
} from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { NOISE_GLSL } from './shaders/common.ts';

const finalShader = {
  name: 'LuminaraFinalPass',
  uniforms: {
    tDiffuse: { value: null },
    uTime: { value: 0 },
    uVignette: { value: 0.55 },
    uGrain: { value: 0.03 },
    uAberration: { value: 0.0022 },
    uResolution: { value: new Vector2(1, 1) },
    uSaturation: { value: 1 },
    uContrast: { value: 1 },
    uShadowTint: { value: new Vector3(0, 0, 0) },
    uHighlightTint: { value: new Vector3(1, 1, 1) },
  },
  vertexShader: /* glsl */ `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: /* glsl */ `
    uniform sampler2D tDiffuse;
    uniform float uTime;
    uniform float uVignette;
    uniform float uGrain;
    uniform float uAberration;
    uniform vec2 uResolution;
    uniform float uSaturation;
    uniform float uContrast;
    uniform vec3 uShadowTint;
    uniform vec3 uHighlightTint;
    varying vec2 vUv;
    ${NOISE_GLSL}
    void main() {
      vec2 c = vUv - 0.5;
      float r2 = dot(c, c);
      vec2 off = c * r2 * uAberration * 6.0;
      vec3 col = vec3(
        texture2D(tDiffuse, vUv + off).r,
        texture2D(tDiffuse, vUv).g,
        texture2D(tDiffuse, vUv - off).b
      );
      // Per-zone colour grade: saturation, contrast, tinted shadows and highlights.
      float luma = dot(col, vec3(0.2126, 0.7152, 0.0722));
      col = mix(vec3(luma), col, uSaturation);
      col = (col - 0.5) * uContrast + 0.5;
      col += uShadowTint * (1.0 - smoothstep(0.0, 0.35, luma));
      col *= mix(vec3(1.0), uHighlightTint, smoothstep(0.4, 0.9, luma));
      col = max(col, 0.0);
      float vig = 1.0 - smoothstep(0.25, 0.95, length(c) * 1.2);
      col *= mix(1.0, vig, uVignette);
      float g = hash12(vUv * uResolution + fract(uTime) * 91.0) - 0.5;
      col += g * uGrain;
      gl_FragColor = vec4(col, 1.0);
    }
  `,
};

interface Grade {
  readonly saturation: number;
  readonly contrast: number;
  readonly shadow: readonly [number, number, number];
  readonly highlight: readonly [number, number, number];
}

const SURFACE_GRADE: Grade = { saturation: 1.08, contrast: 1.04, shadow: [0, 0.004, 0.008], highlight: [1.03, 1.0, 0.96] };

const GRADES: ReadonlyArray<{ depth: number; grade: Grade }> = [
  { depth: 0, grade: { saturation: 1.12, contrast: 1.05, shadow: [0, 0.006, 0.01], highlight: [1.02, 1.03, 1.0] } },
  { depth: 60, grade: { saturation: 1.05, contrast: 1.05, shadow: [0, 0.006, 0.014], highlight: [0.98, 1.02, 1.04] } },
  { depth: 300, grade: { saturation: 0.92, contrast: 1.08, shadow: [0, 0.004, 0.016], highlight: [0.95, 1.0, 1.08] } },
  { depth: 1500, grade: { saturation: 0.82, contrast: 1.1, shadow: [0, 0.003, 0.014], highlight: [0.95, 1.02, 1.1] } },
  { depth: 5000, grade: { saturation: 0.72, contrast: 1.12, shadow: [0.004, 0.0, 0.016], highlight: [1.0, 0.98, 1.1] } },
  { depth: 10000, grade: { saturation: 0.66, contrast: 1.14, shadow: [0.008, 0.0, 0.02], highlight: [1.06, 0.96, 1.12] } },
];

const mix = (a: number, b: number, t: number): number => a + (b - a) * t;

function gradeAt(depth: number): Grade {
  let i = 0;
  while (i < GRADES.length - 2 && depth > (GRADES[i + 1]?.depth ?? 0)) i++;
  const a = GRADES[i];
  const b = GRADES[i + 1];
  if (!a || !b) return SURFACE_GRADE;
  const t = Math.min(1, Math.max(0, (depth - a.depth) / (b.depth - a.depth)));
  const m = (x: readonly [number, number, number], y: readonly [number, number, number]): [number, number, number] => [
    mix(x[0], y[0], t),
    mix(x[1], y[1], t),
    mix(x[2], y[2], t),
  ];
  return {
    saturation: mix(a.grade.saturation, b.grade.saturation, t),
    contrast: mix(a.grade.contrast, b.grade.contrast, t),
    shadow: m(a.grade.shadow, b.grade.shadow),
    highlight: m(a.grade.highlight, b.grade.highlight),
  };
}

/** HDR render → bloom → tone mapping → vignette, grain and chromatic aberration. */
export class PostPipeline {
  private readonly composer: EffectComposer;
  private readonly bloom: UnrealBloomPass;
  private readonly finalPass: ShaderPass;

  constructor(renderer: WebGLRenderer, scene: Scene, camera: Camera, samples: number) {
    const size = renderer.getDrawingBufferSize(new Vector2());
    const target = new WebGLRenderTarget(size.x, size.y, { type: HalfFloatType, samples });
    this.composer = new EffectComposer(renderer, target);
    this.composer.addPass(new RenderPass(scene, camera));
    this.bloom = new UnrealBloomPass(new Vector2(size.x, size.y), 0.65, 0.7, 0.9);
    this.composer.addPass(this.bloom);
    this.composer.addPass(new OutputPass());
    this.finalPass = new ShaderPass(finalShader);
    this.composer.addPass(this.finalPass);
  }

  setBloomEnabled(enabled: boolean): void {
    this.bloom.enabled = enabled;
  }

  setLens(options: { grain: boolean; vignette: boolean; aberration: boolean }): void {
    const u = this.finalPass.uniforms;
    if (u.uGrain) u.uGrain.value = options.grain ? 0.03 : 0;
    if (u.uVignette) u.uVignette.value = options.vignette ? 0.55 : 0;
    if (u.uAberration) u.uAberration.value = options.aberration ? 0.0022 : 0;
  }

  setGrade(depth: number, underwater: boolean): void {
    const u = this.finalPass.uniforms;
    const k = underwater ? gradeAt(depth) : SURFACE_GRADE;
    if (u.uSaturation) u.uSaturation.value = k.saturation;
    if (u.uContrast) u.uContrast.value = k.contrast;
    (u.uShadowTint?.value as Vector3 | undefined)?.set(...k.shadow);
    (u.uHighlightTint?.value as Vector3 | undefined)?.set(...k.highlight);
  }

  setBloomStrength(strength: number): void {
    this.bloom.strength = strength;
  }

  resize(width: number, height: number, pixelRatio: number): void {
    this.composer.setPixelRatio(pixelRatio);
    this.composer.setSize(width, height);
    const resolution = this.finalPass.uniforms.uResolution;
    if (resolution) resolution.value.set(width * pixelRatio, height * pixelRatio);
  }

  render(dt: number, time: number): void {
    const t = this.finalPass.uniforms.uTime;
    if (t) t.value = time;
    this.composer.render(dt);
  }

  dispose(): void {
    this.composer.dispose();
  }
}
