import { clamp } from '../core/math.ts';
import { createRng, type Rng } from '../core/random.ts';
import { BALANCE } from '../data/balance.ts';
import { SPECIES, type SpeciesDef } from '../data/species.ts';
import { Creature } from './creature.ts';
import { type Point3, School, type SchoolEnv } from './school.ts';

const DESPAWN_DISTANCE = 190;
const SPAWN_DISTANCE: readonly [number, number] = [18, 70];
const SPAWN_INTERVAL = 0.4;
const MAX_SCHOOLS = 6;
const FULL_BUDGET = 360;

const SOLITARY: readonly SpeciesDef[] = (SPECIES as readonly SpeciesDef[]).filter((s) => s.school === undefined);
const CREATURE_DESPAWN = 260;
const CREATURE_SPAWN: readonly [number, number] = [40, 120];
const CREATURE_INTERVAL = 0.8;

const SCHOOLING: readonly SpeciesDef[] = (SPECIES as readonly SpeciesDef[]).filter(
  (s) => s.school !== undefined && s.archetype === 'fish' && s.habitat === 'pelagic',
);

/** Keeps a handful of schools alive around the submarine, spawning and retiring them as it moves. */
export class Population {
  private readonly rng: Rng;
  private readonly active: School[] = [];
  private readonly animals: Creature[] = [];
  private budget: number;
  private spawnTimer = 0;
  private creatureTimer = 0;

  constructor(seed: number, fishBudget: number) {
    this.rng = createRng(seed);
    this.budget = fishBudget;
  }

  get schools(): readonly School[] {
    return this.active;
  }

  get creatures(): readonly Creature[] {
    return this.animals;
  }

  placeCreature(id: string, position: Point3): Creature | null {
    const species = SOLITARY.find((s) => s.id === id);
    if (!species) return null;
    const animal = new Creature(species, position, this.rng);
    this.animals.push(animal);
    return animal;
  }

  private maxCreatures(): number {
    return clamp(Math.round(this.budget / 45), 3, 12);
  }

  setBudget(fishBudget: number): void {
    this.budget = fishBudget;
  }

  prefill(subPos: Point3, env: SchoolEnv): void {
    this.active.length = 0;
    this.animals.length = 0;
    for (let i = 0; i < 30 && this.animals.length < this.maxCreatures(); i++) this.trySpawnCreature(subPos, env);
    for (let i = 0; i < MAX_SCHOOLS * 3 && this.active.length < MAX_SCHOOLS; i++) {
      this.trySpawn(subPos, env);
    }
  }

  update(dt: number, time: number, subPos: Point3, env: SchoolEnv): void {
    for (let i = this.active.length - 1; i >= 0; i--) {
      const school = this.active[i];
      if (!school) continue;
      if (Math.hypot(school.centre.x - subPos.x, school.centre.z - subPos.z) > DESPAWN_DISTANCE) {
        this.active.splice(i, 1);
      }
    }

    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0 && this.active.length < MAX_SCHOOLS) {
      this.spawnTimer = SPAWN_INTERVAL;
      this.trySpawn(subPos, env);
    }

    for (const school of this.active) school.update(dt, time, env, subPos);

    for (let i = this.animals.length - 1; i >= 0; i--) {
      const a = this.animals[i];
      if (!a) continue;
      if (Math.hypot(a.position.x - subPos.x, a.position.z - subPos.z) > CREATURE_DESPAWN) {
        this.animals.splice(i, 1);
      } else {
        a.update(dt, time, env, subPos);
      }
    }
    this.creatureTimer -= dt;
    if (this.creatureTimer <= 0 && this.animals.length < this.maxCreatures()) {
      this.creatureTimer = CREATURE_INTERVAL;
      this.trySpawnCreature(subPos, env);
    }
  }

  private trySpawnCreature(subPos: Point3, env: SchoolEnv): boolean {
    const depth = Math.max(0, -subPos.y);
    const candidates = SOLITARY.filter(
      (s) =>
        depth >= s.depth[0] - 30 &&
        depth <= s.depth[1] + 30 &&
        !this.animals.some((a) => a.speciesId === s.id),
    );
    if (candidates.length === 0) return false;
    let total = 0;
    for (const s of candidates) total += BALANCE.rarityWeight[s.rarity];
    let roll = this.rng.next() * total;
    let species = candidates[0];
    for (const s of candidates) {
      roll -= BALANCE.rarityWeight[s.rarity];
      if (roll <= 0) {
        species = s;
        break;
      }
    }
    if (!species) return false;

    const angle = this.rng.range(0, Math.PI * 2);
    const distance = this.rng.range(CREATURE_SPAWN[0], CREATURE_SPAWN[1]) + species.sizeM * 2;
    const x = subPos.x + Math.cos(angle) * distance;
    const z = subPos.z + Math.sin(angle) * distance;
    const floor = env.seabedY(x, z);
    let y: number;
    if (species.habitat === 'benthic') {
      y = floor + 0.4 + species.sizeM * 0.4;
    } else {
      const lowest = Math.max(-species.depth[1], floor + 3 + species.sizeM * 0.6);
      const highest = -Math.max(3, species.depth[0]);
      if (lowest >= highest) return false;
      y = clamp(-depth + this.rng.range(-25, 25), lowest, highest);
    }
    if (y <= floor) return false;
    this.animals.push(new Creature(species, { x, y, z }, this.rng));
    return true;
  }

  private totalFish(): number {
    let n = 0;
    for (const s of this.active) n += s.count;
    return n;
  }

  private trySpawn(subPos: Point3, env: SchoolEnv): boolean {
    const depth = Math.max(0, -subPos.y);
    const candidates = SCHOOLING.filter((s) => depth >= s.depth[0] - 40 && depth <= s.depth[1] + 40);
    if (candidates.length === 0) return false;

    let total = 0;
    for (const s of candidates) total += BALANCE.rarityWeight[s.rarity];
    let roll = this.rng.next() * total;
    let species = candidates[0];
    for (const s of candidates) {
      roll -= BALANCE.rarityWeight[s.rarity];
      if (roll <= 0) {
        species = s;
        break;
      }
    }
    if (!species?.school) return false;

    const scale = clamp(this.budget / FULL_BUDGET, 0.3, 1);
    const count = Math.max(6, Math.round(this.rng.range(species.school.min, species.school.max) * scale));
    if (this.totalFish() + count > this.budget) return false;

    const angle = this.rng.range(0, Math.PI * 2);
    const distance = this.rng.range(SPAWN_DISTANCE[0], SPAWN_DISTANCE[1]);
    const x = subPos.x + Math.cos(angle) * distance;
    const z = subPos.z + Math.sin(angle) * distance;

    const floor = env.seabedY(x, z) + 5;
    const lowest = Math.max(-species.depth[1], floor);
    const highest = -Math.max(3, species.depth[0]);
    if (lowest >= highest) return false;
    const wanted = Math.min(-depth + this.rng.range(-20, 20), -species.prefer * 0.5);
    const y = clamp(this.rng.range(0, 1) < 0.5 ? wanted : -depth + this.rng.range(-12, 12), lowest, highest);

    this.active.push(new School(species, count, { x, y, z }, this.rng));
    return true;
  }
}
