import { isTouchDevice } from '../core/device.ts';
import { TouchControls } from '../ui/touch-controls.ts';
import { Tutorial, type TipId } from '../domain/tutorial.ts';
import { onLangChange, t } from '../i18n/index.ts';
import { missionTitle, poiName, siteDescription, siteName, speciesName, zoneName } from '../i18n/names.ts';
import { AudioEngine } from '../audio/engine.ts';
import { Input } from '../core/input.ts';
import { clamp, damp } from '../core/math.ts';
import { FpsGovernor, QUALITY, type QualityTier } from '../core/quality.ts';
import type { Settings, SettingsStore } from '../core/settings.ts';
import { getPort } from '../data/ports.ts';
import { DIVE_SITES, PORT, POIS } from '../data/sites.ts';
import { getSpecies } from '../data/species.ts';
import { Vector3 } from 'three';
import { forwardFromAngles } from '../core/vec3.ts';
import { BALANCE, SUB } from '../data/balance.ts';
import type { SpeciesDef } from '../data/species.ts';
import type { PhotoAlbum } from '../domain/photo-album.ts';
import { ratingText, scorePhoto } from '../domain/photo.ts';
import { visualSize } from '../domain/creature.ts';
import { Population } from '../domain/population.ts';
import { scan, Sonar, type SonarTarget } from '../domain/sonar.ts';
import type { ProgressStore } from '../domain/progress.ts';
import { deriveSubSpec } from '../domain/spec.ts';
import {
  IDLE_CONTROLS,
  type SubControls,
  type SubEnvironment,
  type SubEvent,
  Submarine,
} from '../domain/submarine.ts';
import { waveHeight } from '../domain/waves.ts';
import { placementOf, world } from '../domain/world.ts';
import { SceneRenderer } from '../render/scene-renderer.ts';
import { Hud } from '../ui/hud.ts';
import { SonarDisplay } from '../ui/sonar-display.ts';

export type AppMode = 'title' | 'play' | 'paused';

export interface GameAppOptions {
  canvas: HTMLCanvasElement;
  hudRoot: HTMLElement;
  tier: QualityTier;
  settings: SettingsStore;
  progress: ProgressStore;
  album: PhotoAlbum;
  autoQuality: boolean;
  onModeChange?: (mode: AppMode) => void;
}

/** Species are catalogued only in daylight above this depth, otherwise they must be lit. */
const DAYLIGHT_DEPTH = 150;
const SCHOOL_REACH = 12;
/** How long a species must stay in view to be catalogued, seconds. */
const SIGHTING_SECONDS = 0.7;

const EMERGENCY_HOLD_SECONDS = 0.8;

/** Wires input, simulation, rendering and the HUD together and runs the frame loop. */
export class GameApp {
  readonly sub: Submarine;
  readonly view: SceneRenderer;
  private readonly input: Input;
  private readonly hud: Hud;
  private readonly governor: FpsGovernor;
  private readonly environment: SubEnvironment;
  private readonly population: Population;
  private readonly settings: SettingsStore;
  private readonly progress: ProgressStore;
  private readonly album: PhotoAlbum;
  private readonly canvas: HTMLCanvasElement;
  private pendingShot: { id: string; score: number } | null = null;
  private readonly sonar = new Sonar();
  private readonly sighting = new Map<string, number>();
  private readonly camDir = new Vector3();
  private lastBump = -10;
  private lastPhoto = -10;
  private readonly ndc = new Vector3();
  private readonly sonarDisplay = new SonarDisplay();
  private readonly onModeChange: ((mode: AppMode) => void) | undefined;
  private autoQuality: boolean;
  private readonly audio = new AudioEngine();
  private homePort = '';
  private readonly tutorial: Tutorial;
  private readonly touch = isTouchDevice();
  private readonly touchControls: TouchControls | null;
  private mode: AppMode = 'title';
  private time = 0;
  private lastFrame = 0;
  private frameId = 0;
  private maxDepth = 0;
  private emergencyHold = 0;
  private thrustShown = 0;
  private running = false;

  constructor(options: GameAppOptions) {
    this.onModeChange = options.onModeChange;
    this.settings = options.settings;
    this.progress = options.progress;
    this.album = options.album;
    this.canvas = options.canvas;
    this.autoQuality = options.autoQuality;
    this.view = new SceneRenderer(options.canvas, world, options.tier);
    this.input = new Input(options.canvas);
    this.hud = new Hud(options.hudRoot);
    this.tutorial = new Tutorial(tipStorage());
    this.touchControls = this.touch ? new TouchControls(this.input, () => this.togglePause()) : null;
    if (this.touchControls) {
      document.body.classList.add('is-touch');
      this.touchControls.mount(document.body);
      onLangChange(() => this.touchControls?.retranslate());
    }
    onLangChange(() => this.hud.retranslate());
    this.hud.setVisible(false);
    options.hudRoot.append(this.sonarDisplay.root);
    this.governor = new FpsGovernor(options.tier);

    this.environment = {
      seabedY: (x, z) => world.seabedY(x, z),
      surfaceY: (x, z) => waveHeight(x, z, this.time),
    };
    this.sub = new Submarine(deriveSubSpec(this.progress.levels), this.spawn());
    this.sub.placeAtSurface(this.spawn(), this.environment);
    this.applyHomePort();
    this.population = new Population(20261018, QUALITY[options.tier].creatureBudget);
    this.population.prefill(this.sub.state.position, this.environment);

    this.progress.subscribe((data) => {
      this.sub.setSpec(deriveSubSpec(data.levels));
      if (data.homePort !== this.homePort) this.applyHomePort(true);
    });
    this.progress.onDiscover((r) => {
      const text = r.zoneCompleted
        ? t('game.zoneDone', { name: zoneName(r.zoneCompleted.id), bonus: r.zoneCompleted.bonus })
        : t('game.newSpecies', { name: speciesName(r.species.id), credits: r.credits });
      this.hud.toast(text, 'good', 6000);
    });
    this.progress.onDiscover(() => this.audio.chime('discovery'));
    this.progress.onMission((m) => {
      this.audio.chime('mission');
      this.hud.toast(t('missions.done', { title: missionTitle(m.id), reward: m.reward }), 'good', 6000);
    });

    this.applySettings(this.settings.value, null, true);
    this.settings.subscribe((value, changed) => this.applySettings(value, changed));

    this.fitToWindow();
    window.addEventListener('resize', this.fitToWindow);
    document.addEventListener('visibilitychange', this.onVisibility);
    options.canvas.addEventListener('webglcontextlost', (e) => {
      e.preventDefault();
      this.hud.toast(t('game.contextLost'), 'danger', 6000);
      window.setTimeout(() => location.reload(), 2500);
    });
  }

  /** Leaving the tab pauses the dive instead of letting the boat drift on its own. */
  private readonly onVisibility = (): void => {
    if (document.visibilityState === 'hidden' && this.mode === 'play') this.togglePause();
  };

  get currentMode(): AppMode {
    return this.mode;
  }

  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastFrame = performance.now();
    this.frameId = requestAnimationFrame(this.frame);
  }

  private spawn(): { x: number; z: number; yaw: number } {
    const p = placementOf(this.progress.value.homePort);
    return { x: PORT.x + p.dx, z: PORT.z + p.dz, yaw: PORT.yaw };
  }

  private applyHomePort(move = false): void {
    this.homePort = this.progress.value.homePort;
    this.sub.setService(getPort(this.homePort).service);
    this.view.setActivePort(this.homePort);
    if (move && this.mode === 'title') {
      this.sub.placeAtSurface(this.spawn(), this.environment);
      this.population.prefill(this.sub.state.position, this.environment);
      this.view.rig.snap();
    }
  }

  begin(): void {
    this.audio.unlock();
    this.setMode('play');
    this.hud.setVisible(true);
    this.sonarDisplay.setVisible(true);
    this.view.rig.resetBehind();
    this.hud.toast(t('game.start'), 'info', 7000);
  }

  exitToTitle(): void {
    this.sub.placeAtSurface(this.spawn(), this.environment);
    this.sub.rescue();
    this.population.prefill(this.sub.state.position, this.environment);
    this.maxDepth = 0;
    this.emergencyHold = 0;
    this.hud.setVisible(false);
    this.sonarDisplay.setVisible(false);
    this.sonar.clear();
    this.view.rig.snap();
    this.setMode('title');
  }

  togglePause(): void {
    if (this.mode === 'play') this.setMode('paused');
    else if (this.mode === 'paused') this.setMode('play');
  }

  setQualityChoice(choice: QualityTier | 'auto'): void {
    if (choice === 'auto') {
      this.autoQuality = true;
      return;
    }
    this.autoQuality = false;
    this.governor.reset(choice);
    this.view.setQuality(choice);
    this.population.setBudget(QUALITY[choice].creatureBudget);
    this.fitToWindow();
  }

  dispose(): void {
    this.running = false;
    cancelAnimationFrame(this.frameId);
    window.removeEventListener('resize', this.fitToWindow);
    document.removeEventListener('visibilitychange', this.onVisibility);
    this.input.dispose();
    this.view.dispose();
  }

  private applySettings(value: Readonly<Settings>, changed: keyof Settings | null, keepTier = false): void {
    const all = changed === null;
    if ((all && !keepTier) || changed === 'quality') this.setQualityChoice(value.quality);
    if (all || changed === 'renderScale') this.view.setRenderScale(value.renderScale);
    if (all || changed === 'fov') this.view.setFov(value.fov);
    if (all || changed === 'cameraAutoReturn') this.view.rig.autoReturn = value.cameraAutoReturn;
    if (changed === 'showTips' && value.showTips) this.tutorial.reset();
    if (all || changed === 'showHints') this.hud.setHints(value.showHints);
    if (all || changed === 'volumeMaster' || changed === 'volumeEffects' || changed === 'volumeAmbient' || changed === 'volumeMusic') {
      this.audio.setVolumes(value);
    }
    if (
      all ||
      changed === 'bloom' ||
      changed === 'filmGrain' ||
      changed === 'vignette' ||
      changed === 'chromaticAberration'
    ) {
      this.view.setEffects({
        bloom: value.bloom,
        grain: value.filmGrain,
        vignette: value.vignette,
        aberration: value.chromaticAberration,
      });
    }
  }

  private setMode(mode: AppMode): void {
    this.mode = mode;
    this.audio.setPaused(mode !== 'play');
    this.touchControls?.setVisible(mode === 'play');
    this.onModeChange?.(mode);
  }

  private readonly fitToWindow = (): void => {
    this.view.resize(window.innerWidth, window.innerHeight);
  };

  private readonly frame = (now: number): void => {
    if (!this.running) return;
    const dt = clamp((now - this.lastFrame) / 1000, 0.0001, 0.05);
    this.lastFrame = now;
    const live = this.mode !== 'paused';
    if (live) this.time += dt;

    const playing = this.mode === 'play';
    if (playing && this.input.wasPressed('Escape')) this.togglePause();

    const controls = playing ? this.readControls(dt) : IDLE_CONTROLS;
    if (live) {
      this.handleEvents(this.sub.update(dt, controls, this.environment));
      if (playing) this.handleHotkeys();
      this.population.update(dt, this.time, this.sub.state.position, this.environment);
      this.collide();
      if (playing) this.observe(dt);
      if (playing) this.checkPois();
    }

    const state = this.sub.state;
    if (playing) {
      this.audio.update(
        {
          depth: this.sub.depth,
          speed: Math.hypot(state.velocity.x, state.velocity.y, state.velocity.z),
          maxSpeed: this.sub.currentSpec.maxSpeed,
          thrust: controls.thrust,
          submerged: state.submerged,
        },
        dt,
      );
    }
    this.maxDepth = Math.max(this.maxDepth, this.sub.depth);
    this.thrustShown = damp(this.thrustShown, controls.thrust, 6, dt);

    const raw = this.input.consumeLook();
    const { sensitivity, invertY } = this.settings.value;
    const look = playing
      ? { dx: raw.dx * sensitivity, dy: raw.dy * sensitivity * (invertY ? -1 : 1), zoom: raw.zoom }
      : { dx: 0, dy: 0, zoom: 0 };
    const spec = this.sub.currentSpec;
    this.view.render({
      time: this.time,
      dt: live ? dt : 0,
      sub: state,
      thrust: this.thrustShown,
      beamRange: spec.beamRange,
      lightActive: this.sub.lightActive,
      look,
      mode: this.mode === 'title' ? 'title' : 'play',
      schools: this.population.schools,
      creatures: this.population.creatures,
    });

    if (this.pendingShot) this.keepPhoto(this.pendingShot);

    if (this.mode !== 'title') {
      this.sonarDisplay.draw(
        this.time,
        this.sonar,
        { x: state.position.x, y: state.position.y, z: state.position.z, yaw: state.yaw },
        spec.sonarRange,
        spec.sonarCooldown,
      );
      this.hud.setTip(this.currentTip());
      this.hud.update({
        depth: this.sub.depth,
        maxDepth: this.maxDepth,
        crushDepth: spec.crushDepth,
        speed: Math.hypot(state.velocity.x, state.velocity.y, state.velocity.z),
        heading: (((-state.yaw * 180) / Math.PI) % 360 + 360) % 360,
        oxygen: state.oxygen / spec.oxygenCapacity,
        battery: state.battery / spec.batteryCapacity,
        hull: state.hull / 100,
        submerged: state.submerged,
        lightOn: this.sub.lightActive,
        emergency: state.emergency !== null,
        emergencyHold: this.emergencyHold,
      });
    }

    if (this.autoQuality && live && this.time > 4) {
      const next = this.governor.update(dt);
      if (next) {
        this.view.setQuality(next);
        this.population.setBudget(QUALITY[next].creatureBudget);
        this.fitToWindow();
      }
    }

    this.input.endFrame();
    this.frameId = requestAnimationFrame(this.frame);
  };

  private readControls(dt: number): SubControls {
    const i = this.input;
    const axis = (plus: string[], minus: string[]): number =>
      (i.isDown(...plus) ? 1 : 0) - (i.isDown(...minus) ? 1 : 0);

    if (i.isDown('KeyX')) this.emergencyHold += dt / EMERGENCY_HOLD_SECONDS;
    else this.emergencyHold = Math.max(0, this.emergencyHold - dt * 2);
    const emergency = this.emergencyHold >= 1;
    if (emergency) this.emergencyHold = 1;

    return {
      thrust: axis(['KeyW', 'ArrowUp'], ['KeyS', 'ArrowDown']),
      turn: axis(['KeyA', 'ArrowLeft'], ['KeyD', 'ArrowRight']),
      lift: axis(['Space'], ['ShiftLeft', 'ShiftRight']),
      emergency,
    };
  }

  private observe(dt: number): void {
    const camera = this.view.rig.camera;
    const camPos = camera.position;
    camera.getWorldDirection(this.camDir);
    const pos = this.sub.state.position;
    const seen = new Set<string>();

    const check = (id: string, x: number, y: number, z: number, size: number, glows: boolean, reach: number): void => {
      const dx = x - pos.x;
      const dy = y - pos.y;
      const dz = z - pos.z;
      const dist = Math.hypot(dx, dy, dz);
      if (dist - size * 0.5 > reach) return;

      const cx = x - camPos.x;
      const cy = y - camPos.y;
      const cz = z - camPos.z;
      const camDist = Math.hypot(cx, cy, cz) || 1;
      const slack = Math.min(0.5, (size * 0.5) / camDist);
      const inView = (cx * this.camDir.x + cy * this.camDir.y + cz * this.camDir.z) / camDist > Math.cos(0.62 + slack);
      if (!inView) return;

      const lit = this.isLit(dx, dy, dz, dist, slack, glows && dist < reach);
      if (lit) seen.add(id);
    };

    for (const school of this.population.schools) {
      const species = getSpecies(school.speciesId);
      const c = school.centre;
      check(species.id, c.x, c.y, c.z, school.radius * 2, species.glow !== undefined, school.radius + SCHOOL_REACH);
    }
    for (const a of this.population.creatures) {
      const size = visualSize(a.species);
      check(a.speciesId, a.position.x, a.position.y, a.position.z, size, a.species.glow !== undefined, Math.min(45, 10 + size * 1.2));
    }

    for (const [id, t] of this.sighting) {
      if (!seen.has(id)) {
        const left = t - dt * 2;
        if (left <= 0) this.sighting.delete(id);
        else this.sighting.set(id, left);
      }
    }
    for (const id of seen) {
      const t = (this.sighting.get(id) ?? 0) + dt;
      this.sighting.set(id, t);
      if (t >= SIGHTING_SECONDS && !this.progress.isDiscovered(id)) this.progress.discover(getSpecies(id));
    }

    if (this.sub.state.submerged) {
      const earned = this.progress.recordDepth(this.sub.depth);
      if (earned > 0) this.hud.toast(t('game.depthRecord', { depth: Math.floor(this.progress.value.maxDepth), earned }), 'good', 3500);
    }
  }

  private keepPhoto(shot: { id: string; score: number }): void {
    this.pendingShot = null;
    try {
      const w = 288;
      const h = 162;
      const out = document.createElement('canvas');
      out.width = w;
      out.height = h;
      const ctx = out.getContext('2d');
      if (!ctx) return;
      const cw = this.canvas.width;
      const ch = this.canvas.height;
      const sh = Math.min(ch, (cw * 9) / 16);
      const sw = (sh * 16) / 9;
      ctx.drawImage(this.canvas, (cw - sw) / 2, (ch - sh) / 2, sw, sh, 0, 0, w, h);
      this.album.save(shot.id, shot.score, out.toDataURL('image/jpeg', 0.72));
    } catch {
    }
  }

  private isLit(dx: number, dy: number, dz: number, dist: number, slack: number, glows: boolean): boolean {
    if (glows || this.sub.depth < DAYLIGHT_DEPTH) return true;
    if (!this.sub.lightActive || dist > this.sub.currentSpec.beamRange * 0.85) return false;
    const beam = forwardFromAngles(this.sub.state.yaw, this.sub.state.pitch);
    return (dx * beam.x + dy * beam.y + dz * beam.z) / (dist || 1) > Math.cos(0.5 + slack);
  }

  private takePhoto(): void {
    if (this.time - this.lastPhoto < BALANCE.photo.cooldown) return;
    if (!this.sub.spendBattery(BALANCE.battery.photo)) {
      this.hud.toast(t('game.photoNoPower'), 'warn', 2500);
      return;
    }
    this.lastPhoto = this.time;
    this.audio.shutter();
    this.hud.flash();

    const camera = this.view.rig.camera;
    const pos = this.sub.state.position;
    const spec = this.sub.currentSpec;
    const fov = (camera.fov * Math.PI) / 180;
    let best: { species: SpeciesDef; score: number } | null = null;
    const consider = (species: SpeciesDef, x: number, y: number, z: number, size: number): void => {
      const dx = x - pos.x;
      const dy = y - pos.y;
      const dz = z - pos.z;
      const dist = Math.hypot(dx, dy, dz);
      const camDist = Math.hypot(x - camera.position.x, y - camera.position.y, z - camera.position.z);
      if (camDist > 80) return;
      this.ndc.set(x, y, z).project(camera);
      if (this.ndc.z > 1 || Math.abs(this.ndc.x) > 1 || Math.abs(this.ndc.y) > 1) return;
      if (!this.isLit(dx, dy, dz, dist, Math.min(0.5, size / 2 / (camDist || 1)), species.glow !== undefined)) return;
      const score = scorePhoto({ species, distance: camDist, size, x: this.ndc.x, y: this.ndc.y, fov }, spec.photoBonus);
      if (!best || score > best.score) best = { species, score };
    };
    for (const school of this.population.schools) {
      consider(getSpecies(school.speciesId), school.centre.x, school.centre.y, school.centre.z, school.radius * 2);
    }
    for (const a of this.population.creatures) {
      consider(a.species, a.position.x, a.position.y, a.position.z, visualSize(a.species));
    }

    const shot = best as { species: SpeciesDef; score: number } | null;
    if (!shot) {
      this.hud.toast(t('game.photoEmpty'), 'info', 2200);
      return;
    }
    if (shot.score < BALANCE.photo.minScore) {
      this.hud.toast(t('game.photoPoor', { rating: ratingText(shot.score), name: speciesName(shot.species.id) }), 'info', 3500);
      return;
    }
    const isNew = !this.progress.isDiscovered(shot.species.id);
    if (isNew) this.progress.discover(shot.species);
    const result = this.progress.recordPhoto(shot.species, shot.score, this.sub.depth);
    if (result.newBest) this.pendingShot = { id: shot.species.id, score: shot.score };
    const extra = result.newBest && !result.first ? t('game.photoRecord') : '';
    this.hud.toast(t('game.photoDone', { rating: ratingText(shot.score), name: speciesName(shot.species.id), score: shot.score, reward: result.reward, extra }), 'good', 4500);
  }

  private collide(): void {
    for (const a of this.population.creatures) {
      const hit = a.bodyHit(this.sub.state.position, SUB.radius);
      if (!hit) continue;
      const mass = clamp(visualSize(a.species) / 4, 0.5, 3);
      const damage = this.sub.bump(hit.nx, hit.ny, hit.nz, hit.overlap, a.velocity(), mass);
      a.alarm = 1;
      a.heading += 0.9 * (hit.nx * -Math.sin(a.heading) + hit.nz * Math.cos(a.heading) > 0 ? 1 : -1);
      if (damage >= 0.5 && this.time - this.lastBump > 1) {
        this.lastBump = this.time;
        this.audio.bump(damage / 6);
        this.hud.toast(t('game.collision', { name: speciesName(a.species.id), damage: Math.round(damage) }), 'warn', 3500);
      }
    }
  }

  private pingSonar(): void {
    const spec = this.sub.currentSpec;
    if (this.sonar.cooldownLeft(this.time, spec.sonarCooldown) > 0) return;
    if (!this.sub.spendBattery(Sonar.COST)) {
      this.hud.toast(t('game.sonarNoPower'), 'warn', 2500);
      return;
    }
    this.audio.ping();
    const targets: SonarTarget[] = [];
    for (const school of this.population.schools) {
      targets.push({ ...school.centre, size: school.radius, speciesId: school.speciesId, kind: 'school' });
    }
    for (const a of this.population.creatures) {
      targets.push({ ...a.position, size: a.species.sizeM, speciesId: a.speciesId, kind: 'animal' });
    }
    const p = this.sub.state.position;
    const contacts = scan({ x: p.x, y: p.y, z: p.z }, spec.sonarRange, targets, spec.sonarAnalysis, (id) =>
      this.progress.isDiscovered(id),
    );
    this.sonar.ping(this.time, spec.sonarCooldown, contacts);
    this.hud.toast(contacts.length > 0 ? t('game.sonarContacts', { n: contacts.length }) : t('game.sonarClear'), 'info', 2200);
  }

  private currentTip(): string | null {
    if (this.mode !== 'play' || !this.settings.value.showTips) return null;
    const id = this.tutorial.update({
      depth: this.sub.depth,
      lightOn: this.sub.lightActive,
      photos: Object.keys(this.progress.value.photos).length,
    });
    if (id === null) return null;
    const keys: Record<TipId, string> = { dive: 'Shift', light: 'L', photo: 'P' };
    return this.touch ? t(`tip.${id}.touch` as const) : t(`tip.${id}` as const, { key: keys[id] });
  }

  private handleHotkeys(): void {
    if (this.input.wasPressed('KeyF')) this.pingSonar();
    if (this.input.wasPressed('KeyP')) this.takePhoto();
    if (this.input.wasPressed('KeyL')) {
      const on = this.sub.toggleLight();
      this.hud.toast(on ? t('game.lightOn') : t('game.lightOff'));
    }
    DIVE_SITES.forEach((site, index) => {
      if (!this.input.wasPressed(`Digit${index + 1}`)) return;
      if (this.progress.levels.hull < site.minHull) {
        this.hud.toast(t('game.needHull', { name: siteName(site.id), level: site.minHull }), 'warn', 5000);
        return;
      }
      this.sub.placeAtSurface({ x: site.x, z: site.z, yaw: -Math.PI / 2 }, this.environment);
      this.view.rig.snap();
      this.population.prefill(this.sub.state.position, this.environment);
      this.hud.toast(`${siteName(site.id)}. ${siteDescription(site.id)}`, 'info', 6000);
    });
  }

  private checkPois(): void {
    if (!this.sub.state.submerged) return;
    const p = this.sub.state.position;
    for (const poi of POIS) {
      if (this.progress.isPoiFound(poi.id)) continue;
      if (Math.hypot(p.x - poi.x, p.z - poi.z) > poi.radius) continue;
      if (p.y - world.seabedY(poi.x, poi.z) > 80) continue;
      const found = this.progress.discoverPoi(poi.id);
      if (found) {
        this.audio.chime('mission');
        this.hud.toast(t('game.poiFound', { name: poiName(found.id), reward: found.reward }), 'good', 7000);
      }
    }
  }

  private handleEvents(events: SubEvent[]): void {
    for (const event of events) {
      switch (event.type) {
        case 'submerged':
          this.hud.toast(t('game.diveBegan'), 'info', 2500);
          break;
        case 'surfaced':
          this.hud.toast(t('game.surfaced'), 'good');
          break;
        case 'emergency':
          this.hud.toast(t(`game.emergency.${event.reason}`), 'danger', 6000);
          this.emergencyHold = 1;
          break;
        case 'rescued':
          this.emergencyHold = 0;
          if (event.reason !== 'manual') {
            this.sub.rescue();
            this.hud.toast(t('game.rescued'), 'good', 6000);
          }
          break;
        case 'impact':
          this.audio.bump(event.damage / 10);
          this.hud.toast(t('game.impact', { damage: Math.round(event.damage) }), 'warn');
          break;
        case 'warning':
          this.audio.warning();
          this.hud.toast(t(`game.warn.${event.kind}`), 'warn', 5000);
          break;
        case 'boundary':
          this.hud.toast(t('game.edge'), 'info', 2000);
          break;
      }
    }
  }
}

function tipStorage(): Storage | null {
  try {
    return localStorage;
  } catch {
    return null;
  }
}
