import {
  BufferAttribute,
  BufferGeometry,
  CylinderGeometry,
  Euler,
  Points,
  Quaternion,
  ShaderMaterial,
  SphereGeometry,
  Vector3,
} from 'three';
import { COMMON_UNIFORMS, LIGHTING_GLSL, NOISE_GLSL } from './shaders/common.ts';
import { PropBuilder } from './props.ts';
import type { SceneUniforms } from './uniforms.ts';

const hash = (n: number): number => {
  const s = Math.sin(n * 63.7264) * 43758.5453;
  return s - Math.floor(s);
};

type Ground = (x: number, z: number) => number;

export interface VentField {
  geometry: BufferGeometry;
  mouths: Vector3[];
}

function chimney(b: PropBuilder, x: number, y: number, z: number, height: number, radius: number, seed: number): void {
  const g = new CylinderGeometry(radius * 0.55, radius, height, 9, 8, true);
  const p = g.getAttribute('position') as BufferAttribute;
  const bendX = (hash(seed) - 0.5) * 0.35 * height;
  const bendZ = (hash(seed + 1) - 0.5) * 0.35 * height;
  for (let i = 0; i < p.count; i++) {
    const t = (p.getY(i) + height / 2) / height;
    const rough = 0.82 + 0.36 * hash(seed + i * 0.37);
    const ring = Math.floor(t * 8);
    const lump = 1 + 0.18 * Math.sin(ring * 2.1 + seed);
    p.setXYZ(i, p.getX(i) * rough * lump + bendX * t * t, p.getY(i) + height / 2, p.getZ(i) * rough * lump + bendZ * t * t);
  }
  g.computeVertexNormals();
  b.add(g, 0x4a382c, { pos: [x, y, z], jitter: 0.25 });
  b.add(new CylinderGeometry(radius * 1.2, radius * 3.4, height * 0.22, 10, 1, true), 0x5a4332, { pos: [x, y + height * 0.1, z], jitter: 0.2 });
  b.add(new SphereGeometry(radius * 0.6, 8, 6), 0x6a3a1c, { pos: [x + bendX, y + height - 0.05, z + bendZ], scale: [1, 0.35, 1], emit: 0.55 });
}

function tubeWorm(b: PropBuilder, x: number, y: number, z: number, len: number, seed: number): void {
  const tilt = (hash(seed) - 0.5) * 0.7;
  const dir = new Vector3(Math.sin(tilt), 1, (hash(seed + 2) - 0.5) * 0.6).normalize();
  const q = new Quaternion().setFromUnitVectors(new Vector3(0, 1, 0), dir);
  const e = new Euler().setFromQuaternion(q);
  const mid = new Vector3(x, y, z).addScaledVector(dir, len / 2);
  b.add(new CylinderGeometry(0.05, 0.07, len, 5), 0xe6dccb, { pos: [mid.x, mid.y, mid.z], rot: [e.x, e.y, e.z], jitter: 0.08 });
  const tip = new Vector3(x, y, z).addScaledVector(dir, len);
  b.add(new SphereGeometry(0.1, 5, 4), 0xd02a22, { pos: [tip.x, tip.y, tip.z], scale: [1, 1.5, 1], emit: 0.35 });
}

/** A field of black smokers around (cx, cz) with tube-worm colonies at their feet. */
export function buildVentField(cx: number, cz: number, ground: Ground): VentField {
  const b = new PropBuilder();
  const mouths: Vector3[] = [];
  const count = 9;
  for (let i = 0; i < count; i++) {
    const a = hash(i + 10) * Math.PI * 2;
    const r = 4 + hash(i + 30) * 38;
    const x = cx + Math.cos(a) * r;
    const z = cz + Math.sin(a) * r;
    const y = ground(x, z) - 0.4;
    const height = 4 + hash(i + 50) * 13;
    const radius = 0.7 + hash(i + 70) * 0.7;
    chimney(b, x - cx, y, z - cz, height, radius, i * 11.3);
    mouths.push(new Vector3(x, y + height, z));
    for (let w = 0; w < 10; w++) {
      const wa = hash(i * 7 + w) * Math.PI * 2;
      const wr = radius * 2.2 + hash(i * 13 + w) * 2.6;
      const wx = x + Math.cos(wa) * wr;
      const wz = z + Math.sin(wa) * wr;
      tubeWorm(b, wx - cx, ground(wx, wz) - 0.1, wz - cz, 0.7 + hash(i + w * 3) * 1.1, i * 31 + w);
    }
  }
  return { geometry: b.build(), mouths };
}

const smokeVertex = /* glsl */ `
uniform float uTime;
attribute vec4 aData; // x = mouth index seed, y = phase offset, z = speed, w = size seed
varying vec3 vWorldPos;
varying float vAlpha;

void main() {
  float age = fract(uTime * aData.z + aData.y);
  vec3 p = position;
  float rise = age * (22.0 + 10.0 * aData.w);
  p.y += rise;
  // The plume bends with the bottom current and billows.
  p.x += age * age * 18.0 + sin(uTime * 0.5 + aData.x * 17.0 + age * 5.0) * (0.5 + 3.0 * age);
  p.z += age * age * 5.0 + cos(uTime * 0.4 + aData.x * 11.0 + age * 4.0) * (0.5 + 3.0 * age);
  vWorldPos = p;
  vec4 mv = viewMatrix * vec4(p, 1.0);
  gl_Position = projectionMatrix * mv;
  float size = 2.0 + age * 15.0 * (0.7 + 0.6 * aData.w);
  gl_PointSize = clamp(size * 520.0 / max(-mv.z, 1.0), 2.0, 240.0);
  vAlpha = smoothstep(0.0, 0.07, age) * (1.0 - age) * 0.55;
}
`;

const smokeFragment = /* glsl */ `
${COMMON_UNIFORMS}
${NOISE_GLSL}
${LIGHTING_GLSL}
varying vec3 vWorldPos;
varying float vAlpha;

void main() {
  vec2 q = gl_PointCoord - 0.5;
  float d = length(q) * 2.0;
  if (d > 1.0) discard;
  float n = vnoise(q * 5.0 + vWorldPos.xz * 0.3 + vWorldPos.y * 0.2);
  float a = (1.0 - smoothstep(0.2, 1.0, d)) * vAlpha * (0.55 + 0.9 * n);
  // Dark mineral smoke: visible against lit water, picks up the headlight.
  vec3 col = shadeUnderwater(vec3(0.16, 0.14, 0.13), vec3(0.0, 1.0, 0.0), vWorldPos);
  col = max(col, uFogColor * 0.15);
  if (!(a >= 0.0) || a > 100.0) discard;
  gl_FragColor = vec4(col, min(a, 1.0));
}
`;

/** Plumes of dark smoke rising from every chimney mouth, animated entirely on the GPU. */
export class VentSmoke {
  readonly points: Points;

  constructor(uniforms: SceneUniforms, mouths: readonly Vector3[], perMouth: number) {
    const total = mouths.length * perMouth;
    const positions = new Float32Array(total * 3);
    const data = new Float32Array(total * 4);
    let k = 0;
    mouths.forEach((m, mi) => {
      for (let i = 0; i < perMouth; i++, k++) {
        positions.set([m.x, m.y, m.z], k * 3);
        data.set([mi + 1, hash(k + 5), 0.035 + hash(k + 9) * 0.02, hash(k + 21)], k * 4);
      }
    });
    const geometry = new BufferGeometry();
    geometry.setAttribute('position', new BufferAttribute(positions, 3));
    geometry.setAttribute('aData', new BufferAttribute(data, 4));
    const material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
        uBeamPos: uniforms.uBeamPos,
        uBeamDir: uniforms.uBeamDir,
        uBeamParams: uniforms.uBeamParams,
      },
      vertexShader: smokeVertex,
      fragmentShader: smokeFragment,
      transparent: true,
      depthWrite: false,
      fog: false,
    });
    this.points = new Points(geometry, material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 4;
  }

  dispose(): void {
    this.points.geometry.dispose();
    (this.points.material as ShaderMaterial).dispose();
  }
}
