import { BufferAttribute, BufferGeometry, Points, ShaderMaterial } from 'three';
import { createRng } from '../core/random.ts';
import type { Vec3 } from '../core/vec3.ts';
import type { SubState } from '../domain/submarine.ts';
import { waveHeight } from '../domain/waves.ts';
import { COMMON_UNIFORMS } from './shaders/common.ts';
import type { SceneUniforms } from './uniforms.ts';

const SPRAY = 0;
const BUBBLE = 1;
const GRAVITY = 9.81;

interface Particle {
  kind: number;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  age: number;
  life: number;
  size: number;
  phase: number;
}

const vertexShader = /* glsl */ `
uniform float uPixelRatio;
attribute vec3 aData; // size (metres), kind, alpha
varying float vKind;
varying float vAlpha;
varying float vDist;

void main() {
  vec4 mv = viewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  float d = max(-mv.z, 0.4);
  vDist = d;
  vKind = aData.y;
  vAlpha = aData.z;
  gl_PointSize = clamp(aData.x * 1700.0 / d, 2.5, 64.0) * uPixelRatio;
}
`;

const fragmentShader = /* glsl */ `
${COMMON_UNIFORMS}
varying float vKind;
varying float vAlpha;
varying float vDist;

void main() {
  vec2 q = gl_PointCoord - 0.5;
  float d = length(q) * 2.0;
  if (d > 1.0) discard;
  float a;
  vec3 col;
  if (vKind < 0.5) {
    // Spray droplet: a soft white blob.
    a = (1.0 - smoothstep(0.35, 1.0, d)) * 0.85;
    col = vec3(0.95, 0.98, 1.0) * (0.6 + 0.4 * uSunlight);
  } else {
    // Bubble: a faint rim and a bright specular dot.
    float rim = smoothstep(0.55, 0.92, d) * (1.0 - smoothstep(0.92, 1.0, d));
    float spec = 1.0 - smoothstep(0.0, 0.28, length(q - vec2(-0.16, -0.16)) * 2.0);
    a = rim * 0.55 + spec * 0.9 + 0.06;
    col = mix(vec3(0.6, 0.85, 0.95), vec3(1.0), spec) * (0.35 + 0.65 * uSunlight) + vec3(0.0, 0.05, 0.05);
  }
  a *= vAlpha;
  col = mix(uFogColor, col, exp(-uFogDensity * vDist));
  if (!(a >= 0.0) || a > 100.0) discard;
  gl_FragColor = vec4(col, min(a, 1.0));
}
`;

/**
 * Water spray when the hull breaks the surface, bubbles that stream off it after diving, the
 * propeller's bubble trail and a burst of bubbles when the camera itself crosses the surface.
 */
export class Splash {
  readonly points: Points;
  private readonly capacity: number;
  private readonly list: Particle[] = [];
  private readonly positions: Float32Array;
  private readonly data: Float32Array;
  private readonly geometry: BufferGeometry;
  private readonly material: ShaderMaterial;
  private readonly posAttr: BufferAttribute;
  private readonly dataAttr: BufferAttribute;
  private readonly rng = createRng(777);
  private prevSubSide: number | null = null;
  private prevCamSide: number | null = null;
  private trailDebt = 0;
  private propDebt = 0;
  private shedTime = 0;

  constructor(uniforms: SceneUniforms, capacity: number) {
    this.capacity = capacity;
    this.positions = new Float32Array(capacity * 3);
    this.data = new Float32Array(capacity * 3);
    this.geometry = new BufferGeometry();
    this.posAttr = new BufferAttribute(this.positions, 3);
    this.dataAttr = new BufferAttribute(this.data, 3);
    this.posAttr.setUsage(35048);
    this.dataAttr.setUsage(35048);
    this.geometry.setAttribute('position', this.posAttr);
    this.geometry.setAttribute('aData', this.dataAttr);
    this.geometry.setDrawRange(0, 0);

    this.material = new ShaderMaterial({
      uniforms: {
        uTime: uniforms.uTime,
        uSunDir: uniforms.uSunDir,
        uSunColor: uniforms.uSunColor,
        uFogColor: uniforms.uFogColor,
        uFogDensity: uniforms.uFogDensity,
        uCamPos: uniforms.uCamPos,
        uSunlight: uniforms.uSunlight,
        uPixelRatio: uniforms.uPixelRatio,
      },
      vertexShader,
      fragmentShader,
      transparent: true,
      depthWrite: false,
      fog: false,
    });
    this.points = new Points(this.geometry, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 3;
  }

  update(dt: number, time: number, sub: SubState, thrust: number, camera: Vec3): void {
    if (dt <= 0) {
      this.upload(time);
      return;
    }
    this.detectCrossings(time, sub, camera);
    this.emitContinuous(dt, time, sub, thrust);
    this.simulate(dt, time);
    this.upload(time);
  }

  dispose(): void {
    this.geometry.dispose();
    this.material.dispose();
  }

  private detectCrossings(time: number, sub: SubState, camera: Vec3): void {
    const subSide = Math.sign(sub.position.y + 0.2 - waveHeight(sub.position.x, sub.position.z, time));
    if (this.prevSubSide !== null && subSide !== this.prevSubSide && subSide !== 0) {
      const speed = Math.min(8, Math.hypot(sub.velocity.x, sub.velocity.y, sub.velocity.z));
      if (subSide < 0) {
        this.diveSplash(sub, time, 0.5 + speed * 0.15);
        this.shedTime = 3.5;
      } else {
        this.surfaceBurst(sub, time, 0.6 + speed * 0.15);
      }
    }
    this.prevSubSide = subSide || this.prevSubSide || 1;

    const camSide = Math.sign(camera.y - waveHeight(camera.x, camera.z, time));
    if (this.prevCamSide !== null && camSide !== this.prevCamSide && camSide !== 0) {
      this.cameraBubbles(camera, time, camSide < 0);
    }
    this.prevCamSide = camSide || this.prevCamSide || 1;
  }

  private diveSplash(sub: SubState, time: number, power: number): void {
    const n = Math.round(26 + power * 26);
    for (let i = 0; i < n; i++) {
      const a = this.rng.next() * Math.PI * 2;
      const r = this.rng.range(0.4, 2.0);
      const out = this.rng.range(0.8, 3.2) * power;
      this.push({
        kind: SPRAY,
        x: sub.position.x + Math.cos(a) * r,
        y: waveHeight(sub.position.x, sub.position.z, time) + 0.1,
        z: sub.position.z + Math.sin(a) * r,
        vx: Math.cos(a) * out,
        vy: this.rng.range(2.4, 6.0) * (0.6 + power * 0.5),
        vz: Math.sin(a) * out,
        age: 0,
        life: 2,
        size: this.rng.range(0.035, 0.09),
        phase: this.rng.next() * 6.28,
      });
    }
    this.bubbleCloud(sub.position.x, sub.position.y, sub.position.z, 2.2, Math.round(28 + power * 24));
  }

  private surfaceBurst(sub: SubState, time: number, power: number): void {
    const n = Math.round(34 + power * 30);
    for (let i = 0; i < n; i++) {
      const a = this.rng.next() * Math.PI * 2;
      const r = this.rng.range(0.8, 2.4);
      const out = this.rng.range(0.6, 2.4) * power;
      this.push({
        kind: SPRAY,
        x: sub.position.x + Math.cos(a) * r,
        y: waveHeight(sub.position.x, sub.position.z, time) + this.rng.range(0.1, 0.9),
        z: sub.position.z + Math.sin(a) * r,
        vx: Math.cos(a) * out,
        vy: this.rng.range(1.6, 4.4) * (0.6 + power * 0.5),
        vz: Math.sin(a) * out,
        age: 0,
        life: 2,
        size: this.rng.range(0.03, 0.08),
        phase: this.rng.next() * 6.28,
      });
    }
  }

  private cameraBubbles(camera: Vec3, time: number, goingUnder: boolean): void {
    const n = goingUnder ? 70 : 40;
    const surfaceY = waveHeight(camera.x, camera.z, time);
    for (let i = 0; i < n; i++) {
      const a = this.rng.next() * Math.PI * 2;
      const r = this.rng.range(0.4, 4.5);
      this.push({
        kind: BUBBLE,
        x: camera.x + Math.cos(a) * r,
        y: surfaceY - this.rng.range(0.1, goingUnder ? 3.2 : 1.2),
        z: camera.z + Math.sin(a) * r,
        vx: this.rng.range(-0.2, 0.2),
        vy: this.rng.range(0.6, 1.4),
        vz: this.rng.range(-0.2, 0.2),
        age: 0,
        life: this.rng.range(1.2, 3.2),
        size: this.rng.range(0.012, 0.05),
        phase: this.rng.next() * 6.28,
      });
    }
  }

  private bubbleCloud(x: number, y: number, z: number, radius: number, count: number): void {
    for (let i = 0; i < count; i++) {
      const a = this.rng.next() * Math.PI * 2;
      const r = this.rng.next() * radius;
      this.push({
        kind: BUBBLE,
        x: x + Math.cos(a) * r,
        y: y + this.rng.range(-0.6, 1.0),
        z: z + Math.sin(a) * r,
        vx: this.rng.range(-0.3, 0.3),
        vy: this.rng.range(0.5, 1.6),
        vz: this.rng.range(-0.3, 0.3),
        age: 0,
        life: this.rng.range(1.4, 3.6),
        size: this.rng.range(0.015, 0.07),
        phase: this.rng.next() * 6.28,
      });
    }
  }

  private emitContinuous(dt: number, time: number, sub: SubState, thrust: number): void {
    const surfaceY = waveHeight(sub.position.x, sub.position.z, time);
    const underSurface = sub.position.y < surfaceY - 0.5;
    if (!underSurface) return;

    if (this.shedTime > 0) {
      this.shedTime -= dt;
      this.trailDebt += dt * 28 * Math.min(1, this.shedTime);
      while (this.trailDebt >= 1) {
        this.trailDebt -= 1;
        this.bubbleCloud(sub.position.x, sub.position.y + 0.7, sub.position.z, 1.3, 1);
      }
    }

    const speed = Math.hypot(sub.velocity.x, sub.velocity.z);
    const effort = Math.abs(thrust) + speed * 0.12;
    if (effort > 0.15) {
      this.propDebt += dt * Math.min(60, effort * 38);
      const fx = -Math.sin(sub.yaw);
      const fz = -Math.cos(sub.yaw);
      while (this.propDebt >= 1) {
        this.propDebt -= 1;
        this.push({
          kind: BUBBLE,
          x: sub.position.x - fx * 3.9 + this.rng.range(-0.35, 0.35),
          y: sub.position.y + this.rng.range(-0.35, 0.35),
          z: sub.position.z - fz * 3.9 + this.rng.range(-0.35, 0.35),
          vx: -fx * (1 + speed * 0.3) * this.rng.range(0.4, 1.0),
          vy: this.rng.range(0.1, 0.5),
          vz: -fz * (1 + speed * 0.3) * this.rng.range(0.4, 1.0),
          age: 0,
          life: this.rng.range(1.2, 2.6),
          size: this.rng.range(0.012, 0.045),
          phase: this.rng.next() * 6.28,
        });
      }
    }
  }

  private simulate(dt: number, time: number): void {
    for (let i = this.list.length - 1; i >= 0; i--) {
      const p = this.list[i];
      if (!p) continue;
      p.age += dt / p.life;
      const surfaceY = waveHeight(p.x, p.z, time);
      if (p.kind === SPRAY) {
        p.vy -= GRAVITY * dt;
        p.vx *= 1 - 0.4 * dt;
        p.vz *= 1 - 0.4 * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;
        if (p.y < surfaceY) p.age = 1;
      } else {
        p.vy += (0.9 - p.vy) * Math.min(1, 1.5 * dt);
        p.x += (p.vx + Math.sin(time * 5 + p.phase) * 0.12) * dt;
        p.y += p.vy * dt;
        p.z += (p.vz + Math.cos(time * 4.3 + p.phase) * 0.12) * dt;
        p.vx *= 1 - 0.8 * dt;
        p.vz *= 1 - 0.8 * dt;
        if (p.y >= surfaceY - 0.02) p.age = 1;
      }
      if (p.age >= 1) {
        this.list[i] = this.list[this.list.length - 1] as Particle;
        this.list.pop();
      }
    }
  }

  private push(p: Particle): void {
    if (this.list.length >= this.capacity) this.list.shift();
    this.list.push(p);
  }

  private upload(_time: number): void {
    const n = this.list.length;
    for (let i = 0; i < n; i++) {
      const p = this.list[i];
      if (!p) continue;
      this.positions[i * 3] = p.x;
      this.positions[i * 3 + 1] = p.y;
      this.positions[i * 3 + 2] = p.z;
      this.data[i * 3] = p.size;
      this.data[i * 3 + 1] = p.kind;
      const fade = p.kind === SPRAY ? 1 - p.age * p.age : Math.min(1, p.age * 8) * (1 - p.age ** 3);
      this.data[i * 3 + 2] = fade;
    }
    this.geometry.setDrawRange(0, n);
    this.posAttr.needsUpdate = true;
    this.dataAttr.needsUpdate = true;
  }
}
