import { clamp, TAU, wrapPi } from '../core/math.ts';
import type { Rng } from '../core/random.ts';
import type { SpeciesDef } from '../data/species.ts';

export interface Point3 {
  x: number;
  y: number;
  z: number;
}

export interface SchoolEnv {
  seabedY(x: number, z: number): number;
}

/** Distance at which a school notices the submarine and bolts, metres. */
export const FLEE_RADIUS = 16;
const TOP_DEPTH = 2.5;
const SEABED_CLEARANCE = 3.5;
const LOOK_AHEAD = 26;

/**
 * One school of small fish. The whole group follows an invisible leader that wanders,
 * avoids land and the seabed, and runs from the submarine; every fish chases its own
 * slot around the leader, so the cost is linear in the number of fish.
 */
export class School {
  readonly speciesId: string;
  readonly count: number;
  readonly position: Float32Array;
  readonly velocity: Float32Array;
  readonly phase: Float32Array;
  readonly centre: Point3;
  readonly radius: number;
  private readonly offsets: Float32Array;
  private readonly speed: number;
  private readonly minDepth: number;
  private readonly maxDepth: number;
  private readonly seed: number;
  private readonly turnSign: number;
  private heading: number;
  private baseY: number;
  private alarm = 0;

  constructor(species: SpeciesDef, count: number, centre: Point3, rng: Rng) {
    this.speciesId = species.id;
    this.count = count;
    this.centre = { ...centre };
    this.speed = species.speed;
    this.minDepth = species.depth[0];
    this.maxDepth = species.depth[1];
    this.seed = rng.next() * 100;
    this.turnSign = rng.chance(0.5) ? 1 : -1;
    this.heading = rng.next() * TAU;
    this.baseY = centre.y;
    this.radius = 2.5 + Math.sqrt(count) * 0.9;

    this.position = new Float32Array(count * 3);
    this.velocity = new Float32Array(count * 3);
    this.phase = new Float32Array(count);
    this.offsets = new Float32Array(count * 3);

    for (let i = 0; i < count; i++) {
      let x = 0;
      let y = 0;
      let z = 0;
      do {
        x = rng.range(-1, 1);
        y = rng.range(-1, 1);
        z = rng.range(-1, 1);
      } while (x * x + y * y + z * z > 1);
      y *= 0.45;
      this.offsets[i * 3] = x;
      this.offsets[i * 3 + 1] = y;
      this.offsets[i * 3 + 2] = z;
      this.phase[i] = rng.next();
      this.position[i * 3] = centre.x + x * this.radius;
      this.position[i * 3 + 1] = centre.y + y * this.radius;
      this.position[i * 3 + 2] = centre.z + z * this.radius;
      this.velocity[i * 3] = Math.cos(this.heading) * this.speed * 0.5;
      this.velocity[i * 3 + 2] = Math.sin(this.heading) * this.speed * 0.5;
    }
  }

  get panic(): number {
    return this.alarm;
  }

  update(dt: number, time: number, env: SchoolEnv, threat: Point3 | null): void {
    this.moveLeader(dt, time, env, threat);
    this.moveFish(dt, time, env);
  }

  private moveLeader(dt: number, time: number, env: SchoolEnv, threat: Point3 | null): void {
    const c = this.centre;
    this.alarm = Math.max(0, this.alarm - dt * 0.4);

    this.heading +=
      (0.35 * Math.sin(time * 0.17 + this.seed) + 0.2 * Math.sin(time * 0.41 + this.seed * 3)) * dt;

    if (threat) {
      const dx = c.x - threat.x;
      const dy = c.y - threat.y;
      const dz = c.z - threat.z;
      if (Math.hypot(dx, dy, dz) < FLEE_RADIUS + this.radius) {
        this.alarm = 1;
        const away = Math.atan2(dz, dx);
        this.heading += clamp(wrapPi(away - this.heading), -1, 1) * 4 * dt;
      }
    }

    const ahead = env.seabedY(
      c.x + Math.cos(this.heading) * LOOK_AHEAD,
      c.z + Math.sin(this.heading) * LOOK_AHEAD,
    );
    if (ahead > c.y - SEABED_CLEARANCE) this.heading += this.turnSign * 1.8 * dt;

    const speed = this.speed * 0.6 * (1 + 1.2 * this.alarm);
    c.x += Math.cos(this.heading) * speed * dt;
    c.z += Math.sin(this.heading) * speed * dt;

    const floor = env.seabedY(c.x, c.z) + SEABED_CLEARANCE;
    const lowest = Math.max(-this.maxDepth, floor);
    const highest = -Math.max(TOP_DEPTH, this.minDepth);
    const wanted = this.baseY + Math.sin(time * 0.13 + this.seed) * 4;
    const targetY = lowest > highest ? highest : clamp(wanted, lowest, highest);
    c.y += clamp(targetY - c.y, -3, 3) * Math.min(1, dt * 0.8);
  }

  private moveFish(dt: number, time: number, env: SchoolEnv): void {
    const c = this.centre;
    const spread = this.radius * (1 - 0.45 * this.alarm);
    const leaderSpeed = this.speed * 0.6 * (1 + 1.2 * this.alarm);
    const lx = Math.cos(this.heading) * leaderSpeed;
    const lz = Math.sin(this.heading) * leaderSpeed;
    const maxSpeed = this.speed * (1.35 + 0.9 * this.alarm);
    const blend = Math.min(1, dt * 3.5);

    for (let i = 0; i < this.count; i++) {
      const k = i * 3;
      const ph = this.phase[i] ?? 0;
      const tx =
        c.x + (this.offsets[k] ?? 0) * spread + Math.sin(time * 0.9 + ph * 6.28) * 0.7;
      const ty =
        c.y + (this.offsets[k + 1] ?? 0) * spread + Math.sin(time * 0.7 + ph * 9.4) * 0.35;
      const tz =
        c.z + (this.offsets[k + 2] ?? 0) * spread + Math.cos(time * 0.8 + ph * 5.1) * 0.7;

      const px = this.position[k] ?? 0;
      const py = this.position[k + 1] ?? 0;
      const pz = this.position[k + 2] ?? 0;

      let dx = lx + (tx - px) * 1.4;
      let dy = (ty - py) * 1.4;
      let dz = lz + (tz - pz) * 1.4;
      const len = Math.hypot(dx, dy, dz);
      if (len > maxSpeed) {
        const s = maxSpeed / len;
        dx *= s;
        dy *= s;
        dz *= s;
      }

      const vx = (this.velocity[k] ?? 0) + (dx - (this.velocity[k] ?? 0)) * blend;
      const vy = (this.velocity[k + 1] ?? 0) + (dy - (this.velocity[k + 1] ?? 0)) * blend;
      const vz = (this.velocity[k + 2] ?? 0) + (dz - (this.velocity[k + 2] ?? 0)) * blend;
      this.velocity[k] = vx;
      this.velocity[k + 1] = vy;
      this.velocity[k + 2] = vz;

      const nx = px + vx * dt;
      const nz = pz + vz * dt;
      const floor = env.seabedY(nx, nz) + 0.5;
      this.position[k] = nx;
      this.position[k + 1] = clamp(py + vy * dt, floor, -1);
      this.position[k + 2] = nz;
    }
  }
}
