import { BufferAttribute, BufferGeometry, Mesh, type ShaderMaterial } from 'three';
import { smoothstep } from '../core/math.ts';
import { fbm2 } from '../core/noise.ts';
import type { WorldQuery } from '../domain/world.ts';
import { createPropMaterial } from './props.ts';
import type { SceneUniforms } from './uniforms.ts';

const X_NEAR = -760;
const X_FAR = -7200;
const Z_HALF = 7600;
const COLS = 170;
const ROWS = 230;
const SEED = 9137;

const mix = (a: readonly number[], b: readonly number[], t: number): number[] =>
  [0, 1, 2].map((i) => (a[i] ?? 0) + ((b[i] ?? 0) - (a[i] ?? 0)) * t);

const GRASS = [0.22, 0.36, 0.17];
const FOREST = [0.1, 0.22, 0.13];
const ROCK = [0.26, 0.29, 0.34];
const DARK = [0.14, 0.15, 0.18];
const SNOW = [0.95, 0.97, 1.0];

function ridgeHeight(x: number, z: number, edge: number): number {
  const rise = smoothstep(-800, -2400, x);
  const fade = 1 - smoothstep(Z_HALF - 1800, Z_HALF, Math.abs(z));
  const broad = fbm2(x * 0.00045, z * 0.00045, 4, SEED);
  const ridge = 1 - Math.abs(fbm2(x * 0.0011 + 40, z * 0.0011, 5, SEED + 7) * 2 - 1);
  const crags = fbm2(x * 0.006, z * 0.006, 3, SEED + 13);
  const peaks = (0.25 + 1.5 * broad) * ridge ** 2.2 * 1400 + crags * 80;
  const foothill = smoothstep(-760, -1500, x) * (60 + fbm2(x * 0.002, z * 0.002, 3, SEED + 3) * 160);
  return edge + (foothill + peaks * rise) * fade;
}

/** A backdrop of snow-capped mountains far inland, behind the port; pure scenery, never reachable. */
export class Mountains {
  readonly mesh: Mesh;
  private readonly material: ShaderMaterial;

  constructor(world: WorldQuery, uniforms: SceneUniforms) {
    this.material = createPropMaterial(uniforms, 0);
    this.material.uniforms.uFogDensity = { value: 0.00007 };
    const cols = COLS + 1;
    const rows = ROWS + 1;
    const total = cols * rows;
    const positions = new Float32Array(total * 3);
    const colors = new Float32Array(total * 3);
    const emit = new Float32Array(total);
    const slime = new Float32Array(total);
    const heights = new Float32Array(total);
    const edge = Math.max(2, world.seabedY(X_NEAR, 0));

    const xs: number[] = [];
    for (let i = 0; i < cols; i++) xs.push(X_NEAR + (X_FAR - X_NEAR) * (i / COLS) ** 1.7);
    const zs: number[] = [];
    for (let j = 0; j < rows; j++) zs.push(-Z_HALF + (2 * Z_HALF * j) / ROWS);

    for (let j = 0; j < rows; j++) {
      for (let i = 0; i < cols; i++) {
        const x = xs[i] ?? 0;
        const z = zs[j] ?? 0;
        const k = j * cols + i;
        const h = ridgeHeight(x, z, edge);
        heights[k] = h;
        positions.set([x, h, z], k * 3);
      }
    }

    const geometry = new BufferGeometry();
    const index: number[] = [];
    for (let j = 0; j < ROWS; j++) {
      for (let i = 0; i < COLS; i++) {
        const a = j * cols + i;
        index.push(a, a + 1, a + cols, a + 1, a + cols + 1, a + cols);
      }
    }
    geometry.setIndex(index);
    geometry.setAttribute('position', new BufferAttribute(positions, 3));
    geometry.computeVertexNormals();
    const normals = geometry.getAttribute('normal');

    for (let j = 0; j < rows; j++) {
      for (let i = 0; i < cols; i++) {
        const k = j * cols + i;
        const h = heights[k] ?? 0;
        const z = zs[j] ?? 0;
        const ny = normals.getY(k);
        const grain = fbm2((xs[i] ?? 0) * 0.01, z * 0.01, 3, SEED + 21);
        const snowLine = 600 + 320 * smoothstep(-2200, 1800, z) + (grain - 0.5) * 260;
        let c = mix(FOREST, GRASS, smoothstep(10, 120, h) * (0.5 + grain * 0.5));
        c = mix(c, ROCK, smoothstep(160, 420, h));
        c = mix(c, DARK, smoothstep(0.82, 0.5, ny) * 0.8);
        const snowAmount = smoothstep(snowLine - 60, snowLine + 120, h) * smoothstep(0.4, 0.72, ny + (grain - 0.5) * 0.2);
        c = mix(c, SNOW, snowAmount);
        colors.set(c, k * 3);
        emit[k] = 0.14 + snowAmount * 0.22;
      }
    }
    geometry.setAttribute('color', new BufferAttribute(colors, 3));
    geometry.setAttribute('emit', new BufferAttribute(emit, 1));
    geometry.setAttribute('slime', new BufferAttribute(slime, 1));
    geometry.computeBoundingSphere();

    this.mesh = new Mesh(geometry, this.material);
    this.mesh.frustumCulled = false;
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    this.material.dispose();
  }
}
