import { Color, DirectionalLight, HemisphereLight, type PerspectiveCamera, type Scene } from 'three';
import { clamp, lerp } from '../core/math.ts';
import { sunlightAt } from '../domain/ocean.ts';
import { waveHeight } from '../domain/waves.ts';
import { SkyDome } from './sky.ts';
import { createSceneUniforms, type SceneUniforms } from './uniforms.ts';

const smooth = (t: number): number => t * t * (3 - 2 * t);

export interface EnvironmentState {
  underwater: boolean;
  depth: number;
  darkness: number;
}

const WATER_ZONES: readonly { depth: number; color: Color; density: number }[] = [
  { depth: 0, color: new Color(0.03, 0.36, 0.5), density: 0.03 },
  { depth: 40, color: new Color(0.02, 0.26, 0.44), density: 0.028 },
  { depth: 200, color: new Color(0.008, 0.09, 0.2), density: 0.024 },
  { depth: 1000, color: new Color(0.004, 0.025, 0.07), density: 0.02 },
  { depth: 4000, color: new Color(0.004, 0.012, 0.035), density: 0.018 },
  { depth: 9000, color: new Color(0.012, 0.008, 0.03), density: 0.016 },
];
const AIR_HAZE = new Color(0.75, 0.42, 0.3);
const SUN_AIR = new Color(1.0, 0.62, 0.34);
const SUN_WATER = new Color(0.35, 0.75, 1.0);

/** Owns the sky, the sun and the global look of the scene: fog colour and density follow depth. */
export class Environment {
  readonly uniforms: SceneUniforms = createSceneUniforms();
  readonly sky: SkyDome;
  private readonly sun = new DirectionalLight(0xffffff, 2.6);
  private readonly hemisphere = new HemisphereLight(0x8fa6d8, 0x1a2230, 0.9);
  private readonly tint = new Color();

  constructor(scene: Scene) {
    this.sky = new SkyDome(this.uniforms);
    this.sun.position.copy(this.uniforms.uSunDir.value).multiplyScalar(200);
    scene.add(this.sky.mesh, this.sun, this.hemisphere);
  }

  update(camera: PerspectiveCamera, time: number): EnvironmentState {
    const u = this.uniforms;
    const p = camera.position;
    const surface = waveHeight(p.x, p.z, time);
    const underwater = p.y < surface;
    const depth = Math.max(0, surface - p.y);
    const sunlight = underwater ? sunlightAt(depth) : 1;

    u.uTime.value = time;
    u.uCamPos.value.copy(p);
    u.uSunlight.value = sunlight;

    if (underwater) {
      this.zoneWater(depth);

      const absorbed = 1 - Math.exp(-depth / 14);
      this.sun.color.copy(SUN_AIR).lerp(SUN_WATER, absorbed);
      this.sun.intensity = 2.6 * sunlight;
      this.hemisphere.color.copy(u.uFogColor.value).multiplyScalar(2.5).addScalar(0.02);
      this.hemisphere.groundColor.copy(u.uFogColor.value).multiplyScalar(0.8);
      this.hemisphere.intensity = 0.05 + 0.75 * sunlight;
    } else {
      u.uFogColor.value.copy(AIR_HAZE);
      u.uFogDensity.value = 0.00045;
      this.sun.color.copy(SUN_AIR);
      this.sun.intensity = 2.6;
      this.hemisphere.color.setRGB(0.55, 0.62, 0.85);
      this.hemisphere.groundColor.setRGB(0.12, 0.16, 0.2);
      this.hemisphere.intensity = 0.9;
    }

    this.tint.copy(u.uFogColor.value);
    this.sky.mesh.visible = !underwater;
    this.sky.follow(p.x, p.y, p.z);

    return { underwater, depth, darkness: clamp(1 - sunlight) };
  }

  /** Blends the fog colour and density between the depth keyframes. */
  private zoneWater(depth: number): void {
    const u = this.uniforms;
    let i = 0;
    while (i < WATER_ZONES.length - 2 && depth > (WATER_ZONES[i + 1]?.depth ?? 0)) i++;
    const a = WATER_ZONES[i];
    const b = WATER_ZONES[i + 1];
    if (!a || !b) return;
    const t = smooth(clamp((depth - a.depth) / (b.depth - a.depth)));
    u.uFogColor.value.copy(a.color).lerp(b.color, t);
    u.uFogDensity.value = lerp(a.density, b.density, t);
  }

  get clearColor(): Color {
    return this.tint;
  }

  dispose(): void {
    this.sky.mesh.geometry.dispose();
    this.sky.mesh.material.dispose();
    this.sun.dispose();
  }
}
