import { type BufferGeometry, Euler, Group, Mesh, type ShaderMaterial } from 'three';
import { POIS } from '../data/sites.ts';
import type { WorldQuery } from '../domain/world.ts';
import { createPropMaterial } from './props.ts';
import type { SceneUniforms } from './uniforms.ts';
import { buildTrees } from './trees.ts';
import { buildFormations } from './rock-formations.ts';
import { buildVentField, VentSmoke } from './vents.ts';
import { buildBacterialMat, buildWhaleSkeleton } from './whale-fall.ts';
import { buildSpilledContainers, buildWreck } from './wreck.ts';

const SHOW_RANGE = 650;

interface Entry {
  readonly root: Group;
  readonly x: number;
  readonly z: number;
}

/** The hand-built places of the world: the wreck, vents, the whale fall... one mesh each. */
export class Landmarks {
  readonly group = new Group();
  private readonly entries: Entry[] = [];
  private readonly geometries: BufferGeometry[] = [];
  private readonly material: ShaderMaterial;
  private readonly treeMaterial: ShaderMaterial;
  private readonly smokes: VentSmoke[] = [];
  private readonly uniforms: SceneUniforms;

  constructor(world: WorldQuery, uniforms: SceneUniforms) {
    this.uniforms = uniforms;
    this.material = createPropMaterial(uniforms);
    this.treeMaterial = createPropMaterial(uniforms, 0);
    this.group.add(this.mesh(buildFormations(world)));
    const trees = new Mesh(buildTrees(world), this.treeMaterial);
    this.geometries.push(trees.geometry);
    this.group.add(trees);
    for (const poi of POIS) {
      if (poi.kind === 'wreck') this.buildWreck(poi.x, poi.z, world);
      if (poi.kind === 'vents') this.buildVents(poi.x, poi.z, world);
      if (poi.kind === 'whalefall') this.buildWhaleFall(poi.x, poi.z, world);
    }
  }

  update(camX: number, camZ: number): void {
    for (const e of this.entries) {
      e.root.visible = Math.hypot(e.x - camX, e.z - camZ) < SHOW_RANGE;
    }
  }

  dispose(): void {
    for (const g of this.geometries) g.dispose();
    for (const smoke of this.smokes) smoke.dispose();
    this.material.dispose();
    this.treeMaterial.dispose();
  }

  private mesh(geometry: BufferGeometry): Mesh {
    this.geometries.push(geometry);
    const mesh = new Mesh(geometry, this.material);
    return mesh;
  }

  private register(root: Group, x: number, z: number): void {
    this.group.add(root);
    this.entries.push({ root, x, z });
  }

  private buildVents(cx: number, cz: number, world: WorldQuery): void {
    const root = new Group();
    const field = buildVentField(cx, cz, (x, z) => world.seabedY(x, z));
    const mesh = this.mesh(field.geometry);
    mesh.position.set(cx, 0, cz);
    const smoke = new VentSmoke(this.uniforms, field.mouths, 70);
    this.smokes.push(smoke);
    root.add(mesh, smoke.points);
    this.register(root, cx, cz);
  }

  private buildWhaleFall(cx: number, cz: number, world: WorldQuery): void {
    const root = new Group();
    const ground = (x: number, z: number): number => world.seabedY(x, z);
    const bones = this.mesh(buildWhaleSkeleton(cx, cz, 0.35, ground));
    bones.position.set(cx, 0, cz);
    const mat = this.mesh(buildBacterialMat(cx, cz, ground));
    mat.position.set(cx, 0, cz);
    root.add(mat, bones);
    this.register(root, cx, cz);
  }

  private buildWreck(cx: number, cz: number, world: WorldQuery): void {
    const yaw = 0.6;
    const dx = Math.cos(yaw);
    const dz = -Math.sin(yaw);
    const at = (along: number): number => world.seabedY(cx + dx * along, cz + dz * along);
    const { stern, bow } = buildWreck();

    const root = new Group();
    const sternMesh = this.mesh(stern);
    sternMesh.position.set(cx, at(-20) - 1.6, cz);
    sternMesh.rotation.copy(new Euler(0.28, yaw, 0.04, 'YXZ'));

    const bowMesh = this.mesh(bow);
    bowMesh.position.set(cx + dx * 9 + dz * 5, at(30) - 2.4, cz + dz * 9 - dx * 5);
    bowMesh.rotation.copy(new Euler(0.7, yaw + 0.32, -0.08, 'YXZ'));

    const spill = this.mesh(buildSpilledContainers(cx, cz, (x, z) => world.seabedY(x, z)));
    spill.position.set(cx, 0, cz);
    root.add(sternMesh, bowMesh, spill);
    this.register(root, cx, cz);
  }
}
