export type QualityTier = 'low' | 'medium' | 'high' | 'ultra';

export interface QualitySettings {
  pixelRatio: number;
  bloom: boolean;
  particles: number;
  terrainResolution: number;
  creatureBudget: number;
}

export const QUALITY_TIERS: readonly QualityTier[] = ['low', 'medium', 'high', 'ultra'];

export const QUALITY: Readonly<Record<QualityTier, QualitySettings>> = {
  low: { pixelRatio: 1, bloom: false, particles: 1200, terrainResolution: 64, creatureBudget: 120 },
  medium: {
    pixelRatio: 1.25,
    bloom: true,
    particles: 2500,
    terrainResolution: 96,
    creatureBudget: 240,
  },
  high: { pixelRatio: 1.75, bloom: true, particles: 4500, terrainResolution: 128, creatureBudget: 400 },
  ultra: { pixelRatio: 2, bloom: true, particles: 8000, terrainResolution: 160, creatureBudget: 600 },
};

export interface GovernorOptions {
  lowerBelow: number;
  raiseAbove: number;
  windowSeconds: number;
  cooldownSeconds: number;
}

const DEFAULTS: GovernorOptions = {
  lowerBelow: 42,
  raiseAbove: 58,
  windowSeconds: 3,
  cooldownSeconds: 6,
};

/**
 * Watches frame times and suggests a quality tier. Pure state machine:
 * feed it `dt` each frame; it returns a new tier only when it wants a change.
 */
export class FpsGovernor {
  private tierIndex: number;
  private elapsed = 0;
  private frames = 0;
  private sinceChange = Number.POSITIVE_INFINITY;
  private readonly options: GovernorOptions;

  constructor(initial: QualityTier, options: Partial<GovernorOptions> = {}) {
    this.tierIndex = QUALITY_TIERS.indexOf(initial);
    this.options = { ...DEFAULTS, ...options };
  }

  get tier(): QualityTier {
    return QUALITY_TIERS[this.tierIndex] ?? 'medium';
  }

  reset(tier: QualityTier): void {
    this.tierIndex = QUALITY_TIERS.indexOf(tier);
    this.elapsed = 0;
    this.frames = 0;
    this.sinceChange = 0;
  }

  update(dt: number): QualityTier | null {
    if (!(dt > 0) || dt > 1) return null;
    this.elapsed += dt;
    this.frames += 1;
    this.sinceChange += dt;
    if (this.elapsed < this.options.windowSeconds) return null;

    const fps = this.frames / this.elapsed;
    this.elapsed = 0;
    this.frames = 0;
    if (this.sinceChange < this.options.cooldownSeconds) return null;

    let next = this.tierIndex;
    if (fps < this.options.lowerBelow) next -= 1;
    else if (fps > this.options.raiseAbove) next += 1;
    next = Math.max(0, Math.min(QUALITY_TIERS.length - 1, next));
    if (next === this.tierIndex) return null;

    this.tierIndex = next;
    this.sinceChange = 0;
    return this.tier;
  }
}
