import { PerspectiveCamera, Vector3 } from 'three';
import { clamp, damp, dampAngle } from '../core/math.ts';
import type { Vec3 } from '../core/vec3.ts';

export interface LookInput {
  /** Pixels dragged since the last frame. */
  dx: number;
  dy: number;
  /** Wheel delta since the last frame. */
  zoom: number;
}

const MIN_DISTANCE = 7;
const MAX_DISTANCE = 40;

/**
 * Third-person chase camera. Dragging orbits around the submarine; after a moment of
 * inactivity the view eases back behind it. In title mode it slowly circles the boat.
 */
export class CameraRig {
  readonly camera: PerspectiveCamera;
  private yawOffset = Math.PI * 0.85;
  private pitch = 0.28;
  private distance = 17;
  private idle = 0;
  private readonly target = new Vector3();
  private readonly desired = new Vector3();
  private initialised = false;
  autoReturn = true;

  constructor(aspect: number) {
    this.camera = new PerspectiveCamera(62, aspect, 0.3, 16000);
  }

  setFov(degrees: number): void {
    this.camera.fov = degrees;
    this.camera.updateProjectionMatrix();
  }

  setAspect(aspect: number): void {
    this.camera.aspect = aspect;
    this.camera.updateProjectionMatrix();
  }

  update(
    dt: number,
    sub: { position: Vec3; yaw: number },
    look: LookInput,
    mode: 'title' | 'play',
    seabedY: number,
  ): void {
    if (look.dx !== 0 || look.dy !== 0) this.idle = 0;
    else this.idle += dt;

    this.distance = clamp(this.distance * (1 + look.zoom * 0.0012), MIN_DISTANCE, MAX_DISTANCE);

    if (mode === 'title') {
      this.yawOffset += dt * 0.12;
      this.pitch = damp(this.pitch, 0.16, 1.5, dt);
      this.distance = damp(this.distance, 22, 1, dt);
    } else {
      this.yawOffset -= look.dx * 0.0055;
      this.pitch = clamp(this.pitch + look.dy * 0.0045, -0.5, 1.2);
      if (this.autoReturn && this.idle > 2.2) {
        this.yawOffset = dampAngle(this.yawOffset, 0, 1.4, dt);
        this.pitch = damp(this.pitch, 0.24, 1.2, dt);
      }
    }

    const yaw = sub.yaw + this.yawOffset;
    const cp = Math.cos(this.pitch);
    this.desired.set(
      sub.position.x + Math.sin(yaw) * cp * this.distance,
      sub.position.y + 1.2 + Math.sin(this.pitch) * this.distance,
      sub.position.z + Math.cos(yaw) * cp * this.distance,
    );
    this.desired.y = Math.max(this.desired.y, seabedY + 1.5);

    this.target.set(sub.position.x, sub.position.y + 0.7, sub.position.z);

    if (!this.initialised) {
      this.camera.position.copy(this.desired);
      this.initialised = true;
    } else {
      const k = 1 - Math.exp(-7 * dt);
      this.camera.position.lerp(this.desired, k);
    }
    this.camera.lookAt(this.target);
  }

  resetBehind(): void {
    this.yawOffset = 0;
    this.pitch = 0.24;
    this.distance = 17;
    this.idle = 0;
  }

  snap(): void {
    this.initialised = false;
  }
}
