import { BoxGeometry, BufferAttribute, type BufferGeometry, CylinderGeometry } from 'three';
import { PropBuilder } from './props.ts';

const hash = (n: number): number => {
  const s = Math.sin(n * 78.233) * 43758.5453;
  return s - Math.floor(s);
};

const LENGTH = 92;
const HEIGHT = 14;
const WIDTH = 17;

function hullSection(x0: number, x1: number, tornStart: boolean, tornEnd: boolean, seed: number): BufferGeometry {
  const len = x1 - x0;
  const g = new BoxGeometry(len, HEIGHT, WIDTH, Math.max(4, Math.round(len / 4)), 3, 5);
  const p = g.getAttribute('position') as BufferAttribute;
  const cx = (x0 + x1) / 2;
  for (let i = 0; i < p.count; i++) {
    const lx = p.getX(i);
    const x = lx + cx;
    const yn = (p.getY(i) + HEIGHT / 2) / HEIGHT;
    const t = (x + LENGTH / 2) / LENGTH;
    let widthScale = 0.58 + 0.42 * Math.min(1, yn * 1.6);
    if (t > 0.7) widthScale *= 1 - ((t - 0.7) / 0.3) ** 1.7 * 0.97;
    if (t < 0.08) widthScale *= 0.7 + 0.3 * (t / 0.08);
    let y = p.getY(i) + HEIGHT / 2;
    y += t ** 3 * 3.2 * yn;
    let z = p.getZ(i) * widthScale;
    let vx = x;
    const nearStart = tornStart && lx < -len / 2 + 0.01;
    const nearEnd = tornEnd && lx > len / 2 - 0.01;
    if (nearStart || nearEnd) {
      const k = seed + i * 3.1;
      vx += (hash(k) - 0.5) * 5;
      y += (hash(k + 1) - 0.5) * 4.5;
      z += (hash(k + 2) - 0.5) * 3;
    }
    p.setXYZ(i, vx, y, z);
  }
  g.computeVertexNormals();
  return g;
}

/**
 * The cargo ship "Orion", split in two by the storm. Local origin: keel line at y = 0, centre of the
 * ship at x = 0; the bow points to +X. The stern section carries the superstructure.
 */
export function buildWreck(): { stern: BufferGeometry; bow: BufferGeometry } {
  const stern = new PropBuilder();
  const hullRed = 0x6a2c22;
  const hullTop = 0x232b31;
  const sternHull = hullSection(-46, 6, false, true, 1);
  stern.addRaw(sternHull, hullRed, { jitter: 0.05 });
  stern.add(new BoxGeometry(52, 0.5, 14), hullTop, { pos: [-20, HEIGHT + 0.4, 0] });

  const white = 0xb9beba;
  stern.add(new BoxGeometry(13, 8, 14), white, { pos: [-35, HEIGHT + 4.5, 0] });
  stern.add(new BoxGeometry(10, 6, 13), white, { pos: [-34, HEIGHT + 11.5, 0], jitter: 0.08 });
  stern.add(new BoxGeometry(7, 3.2, 17), 0xa9aeaa, { pos: [-33, HEIGHT + 15.7, 0] });
  stern.add(new BoxGeometry(7.2, 1.1, 17.2), 0x2a3238, { pos: [-33, HEIGHT + 15.9, 0], emit: 0 });
  for (let row = 0; row < 2; row++) {
    stern.add(new BoxGeometry(0.2, 1.0, 11.4), 0x10181d, { pos: [-28.5, HEIGHT + 9.4 + row * 3, 0] });
  }
  stern.add(new CylinderGeometry(2.3, 2.8, 8, 14), 0x8a2a22, { pos: [-39, HEIGHT + 21.5, 0], rot: [0, 0, 0.18] });
  stern.add(new CylinderGeometry(2.35, 2.35, 1.4, 14), 0x14181b, { pos: [-39.8, HEIGHT + 25.4, 0], rot: [0, 0, 0.18] });
  stern.add(new CylinderGeometry(0.22, 0.3, 16, 6), 0x70767a, { pos: [-30, HEIGHT + 24, 0], rot: [0, 0, -0.07] });
  stern.add(new BoxGeometry(0.3, 0.3, 7), 0x70767a, { pos: [-30.5, HEIGHT + 28, 0] });

  for (let i = 0; i < 3; i++) {
    stern.add(new BoxGeometry(9, 1.3, 11.5), 0x5a625f, { pos: [-18 + i * 11, HEIGHT + 1.2, 0], jitter: 0.1 });
  }
  stern.add(new CylinderGeometry(0.5, 0.6, 9, 8), 0x7a7f74, { pos: [-8, HEIGHT + 4.5, 5.5] });
  stern.add(new CylinderGeometry(0.28, 0.38, 14, 6), 0x7a7f74, { pos: [-1, HEIGHT + 11.5, 5.5], rot: [0, 0, 1.05] });

  const colours = [0x8c2f23, 0x2a4f7a, 0xb8651f, 0x4d5e50, 0x8a8f95, 0x6b3b6e];
  for (let i = 0; i < 9; i++) {
    const col = i % 3;
    const row = Math.floor(i / 3);
    const c = colours[Math.floor(hash(i + 4) * colours.length)] ?? 0x8c2f23;
    stern.add(new BoxGeometry(6.2, 2.6, 2.4), c, {
      pos: [-18 + col * 8 + (hash(i) - 0.5) * 1.2, HEIGHT + 2.4 + row * 0, -3.8 + row * 3.8],
      rot: [(hash(i + 9) - 0.5) * 0.35, (hash(i + 13) - 0.5) * 0.25, (hash(i + 21) - 0.5) * 0.4],
    });
  }
  stern.add(new CylinderGeometry(0.5, 0.5, 8, 8), 0x3a3f42, { pos: [-48, 3.2, 0], rot: [0, 0, 1.45] });
  stern.add(new BoxGeometry(0.8, 7, 4.5), 0x4a4f50, { pos: [-47.5, 3.4, 0] });

  const bow = new PropBuilder();
  bow.addRaw(hullSection(14, 46, true, false, 40), hullRed, { jitter: 0.05 });
  bow.add(new BoxGeometry(30, 0.5, 12), hullTop, { pos: [27, HEIGHT + 0.5, 0] });
  bow.add(new BoxGeometry(9, 1.3, 9), 0x5a625f, { pos: [24, HEIGHT + 1.2, 0] });
  bow.add(new CylinderGeometry(0.3, 0.4, 12, 6), 0x70767a, { pos: [38, HEIGHT + 6, 0], rot: [0, 0, 0.05] });
  bow.add(new CylinderGeometry(0.6, 0.6, 1.2, 10), 0x30383c, { pos: [41, HEIGHT + 1.2, 0] });
  for (let i = 0; i < 3; i++) {
    const c = colours[Math.floor(hash(i + 70) * colours.length)] ?? 0x8c2f23;
    bow.add(new BoxGeometry(6.2, 2.6, 2.4), c, { pos: [22 + i * 6.5, HEIGHT + 2.4, 0], rot: [0.1, hash(i) * 0.3, hash(i + 3) * 0.3] });
  }
  return { stern: stern.build(), bow: bow.build() };
}

/** Containers that spilled onto the seabed around the wreck; `seabedAt` gives the ground height. */
export function buildSpilledContainers(
  cx: number,
  cz: number,
  seabedAt: (x: number, z: number) => number,
): BufferGeometry {
  const b = new PropBuilder();
  const colours = [0x8c2f23, 0x2a4f7a, 0xb8651f, 0x4d5e50, 0x6b3b6e];
  for (let i = 0; i < 11; i++) {
    const a = hash(i + 100) * Math.PI * 2;
    const r = 24 + hash(i + 120) * 40;
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    b.add(new BoxGeometry(6.2, 2.6, 2.4), colours[i % colours.length] ?? 0x8c2f23, {
      pos: [x, seabedAt(cx + x, cz + z) + 0.7, z],
      rot: [(hash(i + 3) - 0.5) * 0.4, hash(i + 5) * 6.28, (hash(i + 7) - 0.5) * 0.4],
    });
  }
  return b.build();
}
