import { clamp } from '../core/math.ts';

export interface SoundInput {
  depth: number;
  speed: number;
  maxSpeed: number;
  thrust: number;
  submerged: boolean;
}

export interface SoundParams {
  waveGain: number;
  waveCutoff: number;
  deepGain: number;
  deepFreq: number;
  engineGain: number;
  engineFreq: number;
  flowGain: number;
  flowCutoff: number;
}

const smooth = (t: number): number => t * t * (3 - 2 * t);

/** Turns the state of the dive into the loudness and pitch of the continuous sounds. Pure, so it can be tested. */
export function soundParams(i: SoundInput): SoundParams {
  const depth = Math.max(0, i.depth);
  const shallow = 1 - smooth(clamp(depth / 150));
  const deep = smooth(clamp((depth - 100) / 4000));
  const speedShare = clamp(i.speed / Math.max(1, i.maxSpeed));
  const push = clamp(Math.abs(i.thrust));
  return {
    waveGain: (i.submerged ? 0.05 + 0.25 * shallow : 0.45) * (i.submerged ? 1 : 1),
    waveCutoff: i.submerged ? 220 + 900 * shallow : 1400,
    deepGain: i.submerged ? 0.12 + 0.5 * deep : 0,
    deepFreq: 52 - 22 * deep,
    engineGain: 0.05 + 0.2 * Math.max(push, speedShare * 0.6),
    engineFreq: 62 + 90 * speedShare + 25 * push,
    flowGain: i.submerged ? 0.5 * speedShare ** 1.5 : 0,
    flowCutoff: 300 + 1400 * speedShare,
  };
}

export interface VolumeSettings {
  volumeMaster: number;
  volumeEffects: number;
  volumeAmbient: number;
  volumeMusic: number;
}

/** Final gain of a bus: master times the bus slider, squared so the slider feels even. */
export const busGain = (master: number, bus: number): number => clamp(master) ** 2 * clamp(bus) ** 2;
