export const TAU = Math.PI * 2;

export const clamp = (value: number, min = 0, max = 1): number =>
  Math.min(max, Math.max(min, value));

export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

export const inverseLerp = (a: number, b: number, value: number): number =>
  a === b ? 0 : (value - a) / (b - a);

export const remap = (
  value: number,
  inMin: number,
  inMax: number,
  outMin: number,
  outMax: number,
): number => lerp(outMin, outMax, clamp(inverseLerp(inMin, inMax, value)));

export const smoothstep = (edge0: number, edge1: number, x: number): number => {
  const t = clamp(inverseLerp(edge0, edge1, x));
  return t * t * (3 - 2 * t);
};

/** Frame-rate independent exponential smoothing toward `target`. */
export const damp = (current: number, target: number, lambda: number, dt: number): number =>
  lerp(current, target, 1 - Math.exp(-lambda * dt));

/** Wraps an angle to the range [-PI, PI]. */
export const wrapPi = (angle: number): number => {
  const a = (angle + Math.PI) % TAU;
  return (a < 0 ? a + TAU : a) - Math.PI;
};

/** Like `damp`, but takes the shortest way around the circle. */
export const dampAngle = (current: number, target: number, lambda: number, dt: number): number =>
  current + wrapPi(target - current) * (1 - Math.exp(-lambda * dt));

/** Returns `value` if it is a finite number, otherwise `fallback`. */
export const finiteOr = (value: unknown, fallback: number): number =>
  typeof value === 'number' && Number.isFinite(value) ? value : fallback;
