import { Color, type IUniform, Vector3 } from 'three';

/**
 * Uniforms shared by every custom shader. Materials reference these very objects,
 * so updating `.value` once per frame updates the whole scene.
 */
export interface SceneUniforms {
  uTime: IUniform<number>;
  uSunDir: IUniform<Vector3>;
  uSunColor: IUniform<Color>;
  uFogColor: IUniform<Color>;
  uFogDensity: IUniform<number>;
  uCamPos: IUniform<Vector3>;
  uSunlight: IUniform<number>;
  uPixelRatio: IUniform<number>;
  uBeamPos: IUniform<Vector3>;
  uBeamDir: IUniform<Vector3>;
  uBeamParams: IUniform<Vector3>;
}

export function createSceneUniforms(): SceneUniforms {
  return {
    uTime: { value: 0 },
    uSunDir: { value: new Vector3(0.9, 0.2, 0.25).normalize() },
    uSunColor: { value: new Color(1.0, 0.62, 0.34) },
    uFogColor: { value: new Color(0.03, 0.36, 0.5) },
    uFogDensity: { value: 0.03 },
    uCamPos: { value: new Vector3() },
    uSunlight: { value: 1 },
    uPixelRatio: { value: 1 },
    uBeamPos: { value: new Vector3() },
    uBeamDir: { value: new Vector3(0, 0, -1) },
    uBeamParams: { value: new Vector3(60, Math.cos((28 * Math.PI) / 180), 0) },
  };
}
